/* ==========================================
   STEP 9 - UNIVERSAL BORDER RECONSTRUCTION
   ========================================== */

console.log("");
console.log("=================================");
console.log("STEP 9 - UNIVERSAL BORDER RECONSTRUCTION");
console.log("=================================");

const step9Analysis =
    window.pdfLayoutAnalysis;

const step9Page =
    step9Analysis.pages[0];

const step9Graphics =
    step9Page.graphics || [];

const STEP9_TOLERANCE = 1.5;


/* ------------------------------------------
   STEP 9.1 - COLLECT RECTANGLE EDGES
   ------------------------------------------ */

const step9VerticalEdges = [];
const step9HorizontalEdges = [];

step9Graphics.forEach(graphic => {

    if (
        graphic.type !== "path" ||
        !graphic.args ||
        !graphic.args[2]
    ) {
        return;
    }

    const bbox =
        graphic.args[2];

    if (
        !Array.isArray(bbox) ||
        bbox.length < 4
    ) {
        return;
    }

    const minX =
        Math.min(
            bbox[0],
            bbox[2]
        );

    const minY =
        Math.min(
            bbox[1],
            bbox[3]
        );

    const maxX =
        Math.max(
            bbox[0],
            bbox[2]
        );

    const maxY =
        Math.max(
            bbox[1],
            bbox[3]
        );

    const width =
        maxX - minX;

    const height =
        maxY - minY;


    /* Vertical edges */

    if (
        height >= 15 &&
        height > width * 2
    ) {

        step9VerticalEdges.push({

            x: minX,
            y: minY,
            bottom: maxY,
            height: height

        });

        step9VerticalEdges.push({

            x: maxX,
            y: minY,
            bottom: maxY,
            height: height

        });

    }


    /* Horizontal edges */

    if (
        width >= 20 &&
        width > height * 2
    ) {

        step9HorizontalEdges.push({

            y: minY,
            x: minX,
            right: maxX,
            width: width

        });

        step9HorizontalEdges.push({

            y: maxY,
            x: minX,
            right: maxX,
            width: width

        });

    }

});


/* ------------------------------------------
   STEP 9.2 - CLUSTER VERTICAL X POSITIONS
   ------------------------------------------ */

function step9ClusterVerticalEdges(
    edges
) {

    const sorted =
        [...edges].sort(
            (a, b) =>
                a.x - b.x
        );

    const clusters = [];

    sorted.forEach(edge => {

        let cluster = null;

        for (
            const current
            of clusters
        ) {

            if (
                Math.abs(
                    current.center -
                    edge.x
                ) <=
                STEP9_TOLERANCE
            ) {

                cluster =
                    current;

                break;

            }

        }

        if (!cluster) {

            clusters.push({

                center:
                    edge.x,

                count:
                    1,

                edges:
                    [edge]

            });

        } else {

            cluster.edges.push(
                edge
            );

            cluster.count++;

            cluster.center =
                cluster.edges.reduce(
                    (
                        sum,
                        current
                    ) =>
                        sum +
                        current.x,
                    0
                ) /
                cluster.edges.length;

        }

    });

    return clusters;

}


/* ------------------------------------------
   STEP 9.3 - CLUSTER HORIZONTAL Y POSITIONS
   ------------------------------------------ */

function step9ClusterHorizontalEdges(
    edges
) {

    const sorted =
        [...edges].sort(
            (a, b) =>
                a.y - b.y
        );

    const clusters = [];

    sorted.forEach(edge => {

        let cluster = null;

        for (
            const current
            of clusters
        ) {

            if (
                Math.abs(
                    current.center -
                    edge.y
                ) <=
                STEP9_TOLERANCE
            ) {

                cluster =
                    current;

                break;

            }

        }

        if (!cluster) {

            clusters.push({

                center:
                    edge.y,

                count:
                    1,

                edges:
                    [edge]

            });

        } else {

            cluster.edges.push(
                edge
            );

            cluster.count++;

            cluster.center =
                cluster.edges.reduce(
                    (
                        sum,
                        current
                    ) =>
                        sum +
                        current.y,
                    0
                ) /
                cluster.edges.length;

        }

    });

    return clusters;

}


const step9VerticalClusters =
    step9ClusterVerticalEdges(
        step9VerticalEdges
    );

const step9HorizontalClusters =
    step9ClusterHorizontalEdges(
        step9HorizontalEdges
    );


/* ------------------------------------------
   STEP 9.4 - FILTER REAL VERTICAL BORDERS
   ------------------------------------------ */

const step9VerticalBorders =
    step9VerticalClusters
        .filter(
            cluster =>
                cluster.count >= 2
        )
        .map(
            cluster => ({
                x: Number(
                    cluster.center.toFixed(2)
                ),
                count:
                    cluster.count
            })
        )
        .sort(
            (a, b) =>
                a.x - b.x
        );


/* ------------------------------------------
   STEP 9.5 - FILTER REAL HORIZONTAL BORDERS
   ------------------------------------------ */

const step9HorizontalBorders =
    step9HorizontalClusters
        .filter(
            cluster =>
                cluster.count >= 2
        )
        .map(
            cluster => ({
                y: Number(
                    cluster.center.toFixed(2)
                ),
                count:
                    cluster.count
            })
        )
        .sort(
            (a, b) =>
                a.y - b.y
        );


/* ------------------------------------------
   STEP 9.6 - CREATE BORDER MODEL
   ------------------------------------------ */

const step9BorderModel = {

    version:
        "9.0",

    page: {

        pageNumber:
            step9Page.pageNumber,

        width:
            step9Page.width,

        height:
            step9Page.height

    },

    vertical: {

        positions:
            step9VerticalBorders

    },

    horizontal: {

        positions:
            step9HorizontalBorders

    },

    statistics: {

        vertical:
            step9VerticalBorders.length,

        horizontal:
            step9HorizontalBorders.length,

        rawVerticalEdges:
            step9VerticalEdges.length,

        rawHorizontalEdges:
            step9HorizontalEdges.length

    }

};


window.pdfReconstructedBorders =
    step9BorderModel;


