/* ==========================================
   STEP 10 - UNIVERSAL CELL BORDER MAPPING
   ========================================== */

console.log("");
console.log("=================================");
console.log("STEP 10 - UNIVERSAL CELL BORDER MAPPING");
console.log("=================================");

const step10CellModel =
    window.pdfUniversalCells;

const step10BorderModel =
    window.pdfReconstructedBorders;

if (!step10CellModel) {

    console.error(
        "STEP 10 ERROR: Cell model not found."
    );

} else if (!step10BorderModel) {

    console.error(
        "STEP 10 ERROR: Reconstructed border model not found."
    );

} else {

    const step10Cells =
        step10CellModel.cells;

    const step10VerticalBorders =
        step10BorderModel.vertical.positions;

    const step10HorizontalBorders =
        step10BorderModel.horizontal.positions;


    const STEP10_TOLERANCE = 5;


    /* ------------------------------------------
       FIND NEAREST BORDER
       ------------------------------------------ */

    function step10NearestBorder(
        value,
        borders,
        property
    ) {

        let nearest = null;
        let distance = Infinity;

        borders.forEach(border => {

            const borderValue =
                border[property];

            const currentDistance =
                Math.abs(
                    borderValue - value
                );

            if (
                currentDistance <
                distance
            ) {

                distance =
                    currentDistance;

                nearest =
                    border;

            }

        });

        if (
            nearest &&
            distance <=
            STEP10_TOLERANCE
        ) {

            return nearest;

        }

        return null;

    }


    /* ------------------------------------------
       NORMALIZE DOUBLE EDGES
       ------------------------------------------ */

    function step10NormalizeVertical(
        borders
    ) {

        const result = [];

        borders.forEach(border => {

            const x =
                border.x;

            const existing =
                result.find(
                    current =>
                        Math.abs(
                            current.x - x
                        ) <= 3
                );

            if (!existing) {

                result.push({

                    x: x,

                    count:
                        border.count

                });

            } else {

                existing.count +=
                    border.count;

            }

        });

        return result;

    }


    const step10NormalizedVertical =
        step10NormalizeVertical(
            step10VerticalBorders
        );


    /* ------------------------------------------
       MAP BORDERS TO CELLS
       ------------------------------------------ */

    const step10MappedCells =
        step10Cells.map(cell => {

            const left =
                cell.x;

            const right =
                cell.x +
                cell.width;

            const top =
                cell.y;

            const bottom =
                cell.y +
                cell.height;


            const nearestLeft =
                step10NearestBorder(
                    left,
                    step10NormalizedVertical,
                    "x"
                );

            const nearestRight =
                step10NearestBorder(
                    right,
                    step10NormalizedVertical,
                    "x"
                );

            const nearestTop =
                step10NearestBorder(
                    top,
                    step10HorizontalBorders,
                    "y"
                );

            const nearestBottom =
                step10NearestBorder(
                    bottom,
                    step10HorizontalBorders,
                    "y"
                );


            const borders = {

                left:
                    !!nearestLeft,

                right:
                    !!nearestRight,

                top:
                    !!nearestTop,

                bottom:
                    !!nearestBottom

            };


            const borderCount =
                Object.values(
                    borders
                ).filter(
                    Boolean
                ).length;


            return {

                ...cell,

                borders:
                    borders,

                borderCount:
                    borderCount,

                hasBorder:
                    borderCount > 0

            };

        });


    /* ------------------------------------------
       STATISTICS
       ------------------------------------------ */

    const step10Statistics = {

        totalCells:
            step10MappedCells.length,

        cellsWithBorders:
            step10MappedCells.filter(
                cell =>
                    cell.hasBorder
            ).length,

        leftBorders:
            step10MappedCells.filter(
                cell =>
                    cell.borders.left
            ).length,

        rightBorders:
            step10MappedCells.filter(
                cell =>
                    cell.borders.right
            ).length,

        topBorders:
            step10MappedCells.filter(
                cell =>
                    cell.borders.top
            ).length,

        bottomBorders:
            step10MappedCells.filter(
                cell =>
                    cell.borders.bottom
            ).length,

        normalizedVerticalBorders:
            step10NormalizedVertical.length,

        horizontalBorders:
            step10HorizontalBorders.length

    };


    /* ------------------------------------------
       FINAL MODEL
       ------------------------------------------ */

    const step10Model = {

        version:
            "10.0",

        page:
            step10CellModel.page,

        columns:
            step10CellModel.columns,

        cells:
            step10MappedCells,

        borders: {

            vertical:
                step10NormalizedVertical,

            horizontal:
                step10HorizontalBorders

        },

        statistics:
            step10Statistics

    };


    window.pdfUniversalBorderMap =
        step10Model;


    /* ------------------------------------------
       OUTPUT
       ------------------------------------------ */

    console.log("");
    console.log("=================================");
    console.log("STEP 10 RESULT");
    console.log("=================================");

    console.log(
        "Total Cells:",
        step10Statistics.totalCells
    );

    console.log(
        "Cells With Borders:",
        step10Statistics.cellsWithBorders
    );

    console.log(
        "Left Borders:",
        step10Statistics.leftBorders
    );

    console.log(
        "Right Borders:",
        step10Statistics.rightBorders
    );

    console.log(
        "Top Borders:",
        step10Statistics.topBorders
    );

    console.log(
        "Bottom Borders:",
        step10Statistics.bottomBorders
    );

    console.log(
        "Normalized Vertical Borders:",
        step10Statistics.normalizedVerticalBorders
    );

    console.log(
        "Horizontal Borders:",
        step10Statistics.horizontalBorders
    );

    console.log("");
    console.log(
        "UNIVERSAL BORDER MAP:",
        step10Model
    );

    console.log("");
    console.log("=================================");
    console.log("STEP 10 COMPLETE");
    console.log("=================================");

}




/* ==========================================
   STEP 11 - UNIVERSAL CELL BOUNDARY RECONSTRUCTION
   ========================================== */

console.log("");
console.log("=================================");
console.log("STEP 11 - UNIVERSAL CELL BOUNDARY RECONSTRUCTION");
console.log("=================================");

const step11CellModel =
    window.pdfUniversalCells;

const step11BorderModel =
    window.pdfReconstructedBorders;

if (!step11CellModel) {

    console.error(
        "STEP 11 ERROR: Universal cell model not found."
    );

} else if (!step11BorderModel) {

    console.error(
        "STEP 11 ERROR: Reconstructed border model not found."
    );

} else {

    const step11Cells =
        step11CellModel.cells;

    const step11Vertical =
        step11BorderModel.vertical.positions;

    const step11Horizontal =
        step11BorderModel.horizontal.positions;


    /*
     * ------------------------------------------
     * 1. Normalize vertical borders
     * ------------------------------------------
     */

    function step11NormalizeVerticalBorders(
        borders
    ) {

        const sorted =
            [...borders].sort(
                (a, b) =>
                    a.x - b.x
            );

        const groups = [];

        sorted.forEach(border => {

            const last =
                groups[groups.length - 1];

            if (
                !last ||
                Math.abs(
                    last.x -
                    border.x
                ) > 3
            ) {

                groups.push({

                    x:
                        border.x,

                    count:
                        border.count,

                    members:
                        [border]

                });

            } else {

                last.members.push(
                    border
                );

                last.count +=
                    border.count;

            }

        });


        return groups.map(
            group => {

                const totalWeight =
                    group.members.reduce(
                        (sum, item) =>
                            sum +
                            item.count,
                        0
                    );

                const weightedX =
                    group.members.reduce(
                        (sum, item) =>
                            sum +
                            (
                                item.x *
                                item.count
                            ),
                        0
                    ) /
                    totalWeight;

                return {

                    x:
                        weightedX,

                    count:
                        group.count,

                    edges:
                        group.members

                };

            }
        );

    }


    const step11LogicalVertical =
        step11NormalizeVerticalBorders(
            step11Vertical
        );


    /*
     * ------------------------------------------
     * 2. Sort horizontal borders
     * ------------------------------------------
     */

    const step11LogicalHorizontal =
        [...step11Horizontal]
            .sort(
                (a, b) =>
                    b.y - a.y
            );


    /*
     * ------------------------------------------
     * 3. Find nearest border
     * ------------------------------------------
     */

    function step11NearestVertical(
        x
    ) {

        let nearest =
            null;

        let distance =
            Infinity;

        step11LogicalVertical.forEach(
            border => {

                const d =
                    Math.abs(
                        border.x - x
                    );

                if (
                    d < distance
                ) {

                    distance =
                        d;

                    nearest =
                        border;

                }

            }
        );

        return {

            border:
                nearest,

            distance:
                distance

        };

    }


    function step11NearestHorizontal(
        y
    ) {

        let nearest =
            null;

        let distance =
            Infinity;

        step11LogicalHorizontal.forEach(
            border => {

                const d =
                    Math.abs(
                        border.y - y
                    );

                if (
                    d < distance
                ) {

                    distance =
                        d;

                    nearest =
                        border;

                }

            }
        );

        return {

            border:
                nearest,

            distance:
                distance

        };

    }


    /*
     * ------------------------------------------
     * 4. Determine actual table boundaries
     * ------------------------------------------
     */

    const step11XPositions =
        step11LogicalVertical
            .map(
                border =>
                    border.x
            )
            .sort(
                (a, b) =>
                    a - b
            );


    const step11YPositions =
        step11LogicalHorizontal
            .map(
                border =>
                    border.y
            )
            .sort(
                (a, b) =>
                    b - a
            );


    console.log(
        "Logical Vertical Borders:",
        step11XPositions
    );

    console.log(
        "Logical Horizontal Borders:",
        step11YPositions
    );


    /*
     * ------------------------------------------
     * 5. Rebuild cell boundaries
     * ------------------------------------------
     */

    const STEP11_TOLERANCE = 8;


    const step11RebuiltCells =
        step11Cells.map(
            (cell, index) => {

                const originalLeft =
                    cell.x;

                const originalRight =
                    cell.x +
                    cell.width;

                const originalTop =
                    cell.y;

                const originalBottom =
                    cell.y +
                    cell.height;


                const leftMatch =
                    step11NearestVertical(
                        originalLeft
                    );

                const rightMatch =
                    step11NearestVertical(
                        originalRight
                    );

                const topMatch =
                    step11NearestHorizontal(
                        originalTop
                    );

                const bottomMatch =
                    step11NearestHorizontal(
                        originalBottom
                    );


                let newLeft =
                    originalLeft;

                let newRight =
                    originalRight;

                let newTop =
                    originalTop;

                let newBottom =
                    originalBottom;


                /*
                 * Only replace the boundary
                 * when a real PDF border is
                 * reasonably close.
                 */

                if (
                    leftMatch.border &&
                    leftMatch.distance <=
                    STEP11_TOLERANCE
                ) {

                    newLeft =
                        leftMatch.border.x;

                }


                if (
                    rightMatch.border &&
                    rightMatch.distance <=
                    STEP11_TOLERANCE
                ) {

                    newRight =
                        rightMatch.border.x;

                }


                if (
                    topMatch.border &&
                    topMatch.distance <=
                    STEP11_TOLERANCE
                ) {

                    newTop =
                        topMatch.border.y;

                }


                if (
                    bottomMatch.border &&
                    bottomMatch.distance <=
                    STEP11_TOLERANCE
                ) {

                    newBottom =
                        bottomMatch.border.y;

                }


                /*
                 * Safety check
                 */

                if (
                    newRight <=
                    newLeft
                ) {

                    newLeft =
                        originalLeft;

                    newRight =
                        originalRight;

                }


                if (
                    newTop <=
                    newBottom
                ) {

                    newTop =
                        originalTop;

                    newBottom =
                        originalBottom;

                }


                return {

                    ...cell,

                    originalBounds: {

                        x:
                            originalLeft,

                        y:
                            originalTop,

                        width:
                            cell.width,

                        height:
                            cell.height

                    },

                    x:
                        newLeft,

                    y:
                        newBottom,

                    width:
                        newRight -
                        newLeft,

                    height:
                        newTop -
                        newBottom,

                    right:
                        newRight,

                    bottom:
                        newBottom,

                    boundarySource: {

                        left:
                            leftMatch.distance <=
                            STEP11_TOLERANCE,

                        right:
                            rightMatch.distance <=
                            STEP11_TOLERANCE,

                        top:
                            topMatch.distance <=
                            STEP11_TOLERANCE,

                        bottom:
                            bottomMatch.distance <=
                            STEP11_TOLERANCE

                    }

                };

            }
        );


    /*
     * ------------------------------------------
     * 6. Statistics
     * ------------------------------------------
     */

    const step11Statistics = {

        totalCells:
            step11RebuiltCells.length,

        realLeftBoundaries:
            step11RebuiltCells.filter(
                cell =>
                    cell.boundarySource.left
            ).length,

        realRightBoundaries:
            step11RebuiltCells.filter(
                cell =>
                    cell.boundarySource.right
            ).length,

        realTopBoundaries:
            step11RebuiltCells.filter(
                cell =>
                    cell.boundarySource.top
            ).length,

        realBottomBoundaries:
            step11RebuiltCells.filter(
                cell =>
                    cell.boundarySource.bottom
            ).length,

        logicalVerticalBorders:
            step11XPositions.length,

        logicalHorizontalBorders:
            step11YPositions.length

    };


    /*
     * ------------------------------------------
     * 7. Final Step 11 model
     * ------------------------------------------
     */

    const step11Model = {

        version:
            "11.0",

        page:
            step11CellModel.page,

        columns:
            step11CellModel.columns,

        cells:
            step11RebuiltCells,

        boundaries: {

            vertical:
                step11XPositions,

            horizontal:
                step11YPositions

        },

        statistics:
            step11Statistics

    };


    window.pdfUniversalCellBoundaries =
        step11Model;


    /*
     * ------------------------------------------
     * 8. Console output
     * ------------------------------------------
     */

    console.log("");
    console.log("=================================");
    console.log("STEP 11 RESULT");
    console.log("=================================");

    console.log(
        "Total Cells:",
        step11Statistics.totalCells
    );

    console.log(
        "Real Left Boundaries:",
        step11Statistics.realLeftBoundaries
    );

    console.log(
        "Real Right Boundaries:",
        step11Statistics.realRightBoundaries
    );

    console.log(
        "Real Top Boundaries:",
        step11Statistics.realTopBoundaries
    );

    console.log(
        "Real Bottom Boundaries:",
        step11Statistics.realBottomBoundaries
    );

    console.log(
        "Logical Vertical Borders:",
        step11Statistics.logicalVerticalBorders
    );

    console.log(
        "Logical Horizontal Borders:",
        step11Statistics.logicalHorizontalBorders
    );

    console.log("");
    console.log(
        "UNIVERSAL CELL BOUNDARIES:",
        step11Model
    );

    console.log("");
    console.log("=================================");
    console.log("STEP 11 COMPLETE");
    console.log("=================================");

}




/* ==========================================
   STEP 12 - UNIVERSAL TABLE GEOMETRY RECONSTRUCTION
   ========================================== */

console.log("");
console.log("=================================");
console.log("STEP 12 - UNIVERSAL TABLE GEOMETRY RECONSTRUCTION");
console.log("=================================");


const step12BoundaryModel =
    window.pdfUniversalCellBoundaries;

const step12CellModel =
    window.pdfUniversalCells;

const step12Rows =
    window.pdfUniversalRows;

const step12Columns =
    window.pdfLogicalColumnModel;


if (!step12BoundaryModel) {

    console.error(
        "STEP 12 ERROR: Cell boundary model not found."
    );

} else {

    /*
     * ------------------------------------------
     * 1. Read reconstructed boundaries
     * ------------------------------------------
     */

    const verticalBorders =
        [
            ...step12BoundaryModel
                .boundaries
                .vertical
        ]
        .sort(
            (a, b) =>
                a - b
        );


    const horizontalBorders =
        [
            ...step12BoundaryModel
                .boundaries
                .horizontal
        ]
        .sort(
            (a, b) =>
                b - a
        );


    console.log(
        "Vertical Borders:",
        verticalBorders
    );

    console.log(
        "Horizontal Borders:",
        horizontalBorders
    );


    /*
     * ------------------------------------------
     * 2. Remove duplicate / near duplicate
     * ------------------------------------------
     */

    function step12UniqueNumbers(
        values,
        tolerance
    ) {

        const result = [];

        values.forEach(
            value => {

                const exists =
                    result.some(
                        existing =>
                            Math.abs(
                                existing -
                                value
                            ) <=
                            tolerance
                    );

                if (!exists) {

                    result.push(
                        value
                    );

                }

            }
        );

        return result;

    }


    const uniqueVerticalBorders =
        step12UniqueNumbers(
            verticalBorders,
            1
        );


    const uniqueHorizontalBorders =
        step12UniqueNumbers(
            horizontalBorders,
            1
        );


    /*
     * ------------------------------------------
     * 3. Build column geometry
     * ------------------------------------------
     */

    const geometryColumns = [];


    for (
        let i = 0;
        i <
        uniqueVerticalBorders.length - 1;
        i++
    ) {

        const left =
            uniqueVerticalBorders[i];

        const right =
            uniqueVerticalBorders[i + 1];


        if (
            right <= left
        ) {

            continue;

        }


        geometryColumns.push({

            index:
                geometryColumns.length,

            left:
                left,

            right:
                right,

            width:
                right - left

        });

    }


    /*
     * ------------------------------------------
     * 4. Build row geometry
     * ------------------------------------------
     */

    const geometryRows = [];


    for (
        let i = 0;
        i <
        uniqueHorizontalBorders.length - 1;
        i++
    ) {

        const top =
            uniqueHorizontalBorders[i];

        const bottom =
            uniqueHorizontalBorders[i + 1];


        if (
            top <= bottom
        ) {

            continue;

        }


        geometryRows.push({

            index:
                geometryRows.length,

            top:
                top,

            bottom:
                bottom,

            height:
                top - bottom

        });

    }


    /*
     * ------------------------------------------
     * 5. Find which PDF row belongs to
     * which geometry band
     * ------------------------------------------
     */

    function step12FindRow(
        y
    ) {

        let best =
            null;

        let bestDistance =
            Infinity;


        geometryRows.forEach(
            row => {

                const center =
                    (
                        row.top +
                        row.bottom
                    ) / 2;


                const distance =
                    Math.abs(
                        center -
                        y
                    );


                if (
                    distance <
                    bestDistance
                ) {

                    bestDistance =
                        distance;

                    best =
                        row;

                }

            }
        );


        return best;

    }


    /*
     * ------------------------------------------
     * 6. Find which geometry column belongs
     * to a cell
     * ------------------------------------------
     */

    function step12FindColumn(
        x
    ) {

        let best =
            null;

        let bestDistance =
            Infinity;


        geometryColumns.forEach(
            column => {

                const center =
                    (
                        column.left +
                        column.right
                    ) / 2;


                const distance =
                    Math.abs(
                        center -
                        x
                    );


                if (
                    distance <
                    bestDistance
                ) {

                    bestDistance =
                        distance;

                    best =
                        column;

                }

            }
        );


        return best;

    }


    /*
     * ------------------------------------------
     * 7. Reconstruct cells
     * ------------------------------------------
     */

    const geometryCells = [];


    const sourceCells =
        step12BoundaryModel.cells ||
        [];


    sourceCells.forEach(
        (cell, index) => {

            const centerX =
                cell.x +
                (
                    cell.width /
                    2
                );


            const centerY =
                cell.y +
                (
                    cell.height /
                    2
                );


            const column =
                step12FindColumn(
                    centerX
                );


            const row =
                step12FindRow(
                    centerY
                );


            geometryCells.push({

                index:
                    index,

                row:
                    row
                        ? row.index
                        : null,

                column:
                    column
                        ? column.index
                        : null,

                x:
                    cell.x,

                y:
                    cell.y,

                width:
                    cell.width,

                height:
                    cell.height,

                right:
                    cell.x +
                    cell.width,

                bottom:
                    cell.y +
                    cell.height,

                text:
                    cell.text ||
                    "",

                hasText:
                    !!(
                        cell.text &&
                        cell.text.trim()
                    ),

                boundarySource:
                    cell.boundarySource ||
                    {}

            });

        }
    );


    /*
     * ------------------------------------------
     * 8. Attach text from meaningful regions
     * ------------------------------------------
     */

    const meaningfulRegions =
        window.pdfMergedTextRegions ||
        [];


    function step12Distance(
        a,
        b
    ) {

        return Math.sqrt(

            Math.pow(
                a.x - b.x,
                2
            ) +

            Math.pow(
                a.y - b.y,
                2
            )

        );

    }


    meaningfulRegions.forEach(
        region => {

            const regionX =
                region.x ??
                region.left ??
                0;

            const regionY =
                region.y ??
                region.top ??
                0;


            let bestCell =
                null;

            let bestDistance =
                Infinity;


            geometryCells.forEach(
                cell => {

                    const cellCenter = {

                        x:
                            cell.x +
                            cell.width /
                            2,

                        y:
                            cell.y +
                            cell.height /
                            2

                    };


                    const distance =
                        step12Distance(
                            {
                                x:
                                    regionX,

                                y:
                                    regionY
                            },
                            cellCenter
                        );


                    if (
                        distance <
                        bestDistance
                    ) {

                        bestDistance =
                            distance;

                        bestCell =
                            cell;

                    }

                }
            );


            if (
                bestCell &&
                bestDistance <
                100
            ) {

                if (
                    !bestCell.text
                ) {

                    bestCell.text =
                        region.text ||
                        "";

                } else if (
                    region.text &&
                    !bestCell.text
                        .includes(
                            region.text
                        )
                ) {

                    bestCell.text +=
                        " " +
                        region.text;

                }

                bestCell.hasText =
                    !!(
                        bestCell.text &&
                        bestCell.text.trim()
                    );

            }

        }
    );


    /*
     * ------------------------------------------
     * 9. Group cells by row
     * ------------------------------------------
     */

    const geometryRowMap =
        new Map();


    geometryCells.forEach(
        cell => {

            if (
                cell.row === null
            ) {

                return;

            }


            if (
                !geometryRowMap.has(
                    cell.row
                )
            ) {

                geometryRowMap.set(
                    cell.row,
                    []
                );

            }


            geometryRowMap
                .get(cell.row)
                .push(cell);

        }
    );


    const geometryTableRows =
        [];


    geometryRowMap.forEach(
        (cells, rowIndex) => {

            cells.sort(
                (a, b) =>
                    a.x - b.x
            );


            geometryTableRows.push({

                row:
                    rowIndex,

                cells:
                    cells

            });

        }
    );


    geometryTableRows.sort(
        (a, b) =>
            a.row - b.row
    );


    /*
     * ------------------------------------------
     * 10. Determine occupied columns
     * ------------------------------------------
     */

    const occupiedColumns =
        new Set();


    geometryCells.forEach(
        cell => {

            if (
                cell.column !== null
            ) {

                occupiedColumns.add(
                    cell.column
                );

            }

        }
    );


    /*
     * ------------------------------------------
     * 11. Build final geometry model
     * ------------------------------------------
     */

    const step12GeometryModel = {

        version:
            "12.0",

        page:
            step12CellModel
                ? step12CellModel.page
                : 1,

        verticalBorders:
            uniqueVerticalBorders,

        horizontalBorders:
            uniqueHorizontalBorders,

        columns:
            geometryColumns,

        rows:
            geometryRows,

        cells:
            geometryCells,

        tableRows:
            geometryTableRows,

        occupiedColumns:
            [
                ...occupiedColumns
            ],

        statistics: {

            verticalBorders:
                uniqueVerticalBorders.length,

            horizontalBorders:
                uniqueHorizontalBorders.length,

            columns:
                geometryColumns.length,

            rows:
                geometryRows.length,

            cells:
                geometryCells.length,

            textCells:
                geometryCells.filter(
                    cell =>
                        cell.hasText
                ).length,

            emptyCells:
                geometryCells.filter(
                    cell =>
                        !cell.hasText
                ).length

        }

    };


    /*
     * ------------------------------------------
     * 12. Store globally
     * ------------------------------------------
     */

    window.pdfUniversalTableGeometry =
        step12GeometryModel;


    /*
     * ------------------------------------------
     * 13. Console summary
     * ------------------------------------------
     */

    console.log("");
    console.log("=================================");
    console.log("STEP 12 RESULT");
    console.log("=================================");

    console.log(
        "Vertical Borders:",
        step12GeometryModel
            .statistics
            .verticalBorders
    );

    console.log(
        "Horizontal Borders:",
        step12GeometryModel
            .statistics
            .horizontalBorders
    );

    console.log(
        "Columns:",
        step12GeometryModel
            .statistics
            .columns
    );

    console.log(
        "Rows:",
        step12GeometryModel
            .statistics
            .rows
    );

    console.log(
        "Cells:",
        step12GeometryModel
            .statistics
            .cells
    );

    console.log(
        "Text Cells:",
        step12GeometryModel
            .statistics
            .textCells
    );

    console.log(
        "Empty Cells:",
        step12GeometryModel
            .statistics
            .emptyCells
    );


    console.log("");
    console.log(
        "UNIVERSAL TABLE GEOMETRY:",
        step12GeometryModel
    );

    console.log("");
    console.log("=================================");
    console.log("STEP 12 COMPLETE");
    console.log("=================================");

}




 /* ==========================================
    STEP 12.5 - UNIVERSAL LOGICAL GRID ALIGNMENT
    ========================================== */

console.log("");
console.log("=================================");
console.log("STEP 12.5 - UNIVERSAL LOGICAL GRID ALIGNMENT");
console.log("=================================");


const step125Rows =
    window.pdfUniversalRows;

const step125Columns =
    window.pdfLogicalColumnModel;

const step125Boundaries =
    window.pdfUniversalCellBoundaries;

const step125Regions =
    window.pdfMergedTextRegions;


if (!step125Rows) {

    console.error(
        "STEP 12.5 ERROR: Universal row model not found."
    );

} else if (!step125Columns) {

    console.error(
        "STEP 12.5 ERROR: Logical column model not found."
    );

} else if (!step125Boundaries) {

    console.error(
        "STEP 12.5 ERROR: Cell boundary model not found."
    );

} else {

    /*
     * ------------------------------------------
     * 1. Extract logical rows
     * ------------------------------------------
     */

    const logicalRows =
        Array.isArray(step125Rows)
            ? step125Rows
            : (
                step125Rows.rows ||
                step125Rows.tableRows ||
                []
            );


    /*
     * ------------------------------------------
     * 2. Extract logical columns
     * ------------------------------------------
     */

    let logicalColumns =
        step125Columns.columns ||
        step125Columns ||
        [];


    if (
        !Array.isArray(logicalColumns)
    ) {

        logicalColumns = [];

    }


    /*
     * ------------------------------------------
     * 3. Use actual vertical PDF boundaries
     *
     * Outer borders may have two edges.
     * Therefore 42.52 / 44.77 and
     * 575.98 / 578.23 are treated as
     * one logical boundary.
     * ------------------------------------------
     */

    const rawVertical =
        [
            ...(
                step125Boundaries
                    .boundaries
                    .vertical ||
                []
            )
        ]
        .sort(
            (a, b) =>
                a - b
        );


    function normalizeVertical(
        values
    ) {

        const groups = [];


        values.forEach(
            value => {

                const last =
                    groups[
                        groups.length - 1
                    ];


                if (
                    !last ||
                    Math.abs(
                        last.center -
                        value
                    ) > 3
                ) {

                    groups.push({

                        values:
                            [value],

                        center:
                            value

                    });

                } else {

                    last.values.push(
                        value
                    );

                    last.center =
                        last.values
                            .reduce(
                                (
                                    sum,
                                    current
                                ) =>
                                    sum +
                                    current,
                                0
                            ) /
                        last.values.length;

                }

            }
        );


        return groups.map(
            group =>
                group.center
        );

    }


    const verticalBorders =
        normalizeVertical(
            rawVertical
        );


    /*
     * ------------------------------------------
     * 4. Determine logical column boundaries
     * ------------------------------------------
     *
     * For this stage we use the
     * detected logical columns to decide
     * which real border belongs to each side.
     * ------------------------------------------
     */

    const gridColumns = [];


    logicalColumns.forEach(
        (column, index) => {

            const columnX =
                column.x ??
                column.left ??
                column.start ??
                0;


            const columnRight =
                column.right ??
                (
                    column.x +
                    column.width
                );


            let nearestLeft =
                verticalBorders[0];

            let nearestRight =
                verticalBorders[
                    verticalBorders.length - 1
                ];


            let leftDistance =
                Infinity;

            let rightDistance =
                Infinity;


            verticalBorders.forEach(
                border => {

                    const leftDiff =
                        Math.abs(
                            border -
                            columnX
                        );


                    const rightDiff =
                        Math.abs(
                            border -
                            columnRight
                        );


                    if (
                        leftDiff <
                        leftDistance
                    ) {

                        leftDistance =
                            leftDiff;

                        nearestLeft =
                            border;

                    }


                    if (
                        rightDiff <
                        rightDistance
                    ) {

                        rightDistance =
                            rightDiff;

                        nearestRight =
                            border;

                    }

                }
            );


            gridColumns.push({

                index:
                    index,

                source:
                    column,

                left:
                    nearestLeft,

                right:
                    nearestRight,

                width:
                    nearestRight -
                    nearestLeft

            });

        }
    );


    /*
     * ------------------------------------------
     * 5. If logical columns are not available,
     * create columns directly from borders.
     * ------------------------------------------
     */

    if (
        gridColumns.length === 0 &&
        verticalBorders.length >= 2
    ) {

        for (
            let i = 0;
            i <
            verticalBorders.length - 1;
            i++
        ) {

            gridColumns.push({

                index:
                    i,

                source:
                    null,

                left:
                    verticalBorders[i],

                right:
                    verticalBorders[i + 1],

                width:
                    verticalBorders[i + 1] -
                    verticalBorders[i]

            });

        }

    }


    /*
     * ------------------------------------------
     * 6. Build logical row model
     *
     * IMPORTANT:
     * We do NOT use every horizontal
     * border as a row.
     *
     * We preserve Step 5's logical rows.
     * ------------------------------------------
     */

    const gridRows = [];


    logicalRows.forEach(
        (row, index) => {

            const rowRegions =
                row.regions ||
                row.items ||
                row.cells ||
                [];


            let top =
                null;

            let bottom =
                null;


            /*
             * Find row boundaries from
             * its regions.
             */

            rowRegions.forEach(
                region => {

                    const regionTop =
                        region.y ??
                        region.top;

                    const regionBottom =
                        region.bottom ??
                        (
                            region.y +
                            region.height
                        );


                    if (
                        Number.isFinite(
                            regionTop
                        )
                    ) {

                        if (
                            top === null ||
                            regionTop >
                            top
                        ) {

                            top =
                                regionTop;

                        }

                    }


                    if (
                        Number.isFinite(
                            regionBottom
                        )
                    ) {

                        if (
                            bottom === null ||
                            regionBottom <
                            bottom
                        ) {

                            bottom =
                                regionBottom;

                        }

                    }

                }
            );


            /*
             * Some row models may store
             * geometry directly.
             */

            if (
                top === null
            ) {

                top =
                    row.top ??
                    row.y ??
                    null;

            }


            if (
                bottom === null
            ) {

                bottom =
                    row.bottom ??
                    (
                        row.y +
                        row.height
                    ) ??
                    null;

            }


            gridRows.push({

                index:
                    index,

                source:
                    row,

                top:
                    top,

                bottom:
                    bottom,

                height:
                    (
                        top !== null &&
                        bottom !== null
                    )
                        ? top - bottom
                        : null

            });

        }
    );


    /*
     * ------------------------------------------
     * 7. Assign regions to logical grid
     * ------------------------------------------
     */

    function regionCenterX(
        region
    ) {

        return (
            (
                region.x ??
                0
            ) +
            (
                region.width ??
                0
            ) /
            2
        );

    }


    function regionCenterY(
        region
    ) {

        return (
            (
                region.y ??
                0
            ) +
            (
                region.height ??
                0
            ) /
            2
        );

    }


    function findBestColumn(
        region
    ) {

        const center =
            regionCenterX(
                region
            );


        let best =
            null;

        let bestDistance =
            Infinity;


        gridColumns.forEach(
            column => {

                const inside =
                    center >=
                    column.left - 5 &&
                    center <=
                    column.right + 5;


                if (
                    inside
                ) {

                    best =
                        column;

                    bestDistance =
                        0;

                } else {

                    const columnCenter =
                        (
                            column.left +
                            column.right
                        ) /
                        2;


                    const distance =
                        Math.abs(
                            center -
                            columnCenter
                        );


                    if (
                        distance <
                        bestDistance
                    ) {

                        bestDistance =
                            distance;

                        best =
                            column;

                    }

                }

            }
        );


        return best;

    }


    function findBestRow(
        region
    ) {

        const center =
            regionCenterY(
                region
            );


        let best =
            null;

        let bestDistance =
            Infinity;


        gridRows.forEach(
            row => {

                if (
                    row.top === null ||
                    row.bottom === null
                ) {

                    return;

                }


                const inside =
                    center <=
                    row.top + 8 &&
                    center >=
                    row.bottom - 8;


                if (
                    inside
                ) {

                    best =
                        row;

                    bestDistance =
                        0;

                } else {

                    const rowCenter =
                        (
                            row.top +
                            row.bottom
                        ) /
                        2;


                    const distance =
                        Math.abs(
                            center -
                            rowCenter
                        );


                    if (
                        distance <
                        bestDistance
                    ) {

                        bestDistance =
                            distance;

                        best =
                            row;

                    }

                }

            }
        );


        return best;

    }


    /*
     * ------------------------------------------
     * 8. Create grid cells
     * ------------------------------------------
     */

    const gridCells = [];


    gridRows.forEach(
        row => {

            gridColumns.forEach(
                column => {

                    gridCells.push({

                        row:
                            row.index,

                        column:
                            column.index,

                        x:
                            column.left,

                        y:
                            row.bottom,

                        width:
                            column.width,

                        height:
                            row.height,

                        right:
                            column.right,

                        bottom:
                            row.bottom,

                        top:
                            row.top,

                        text:
                            "",

                        textRegions:
                            [],

                        border: {

                            left:
                                true,

                            right:
                                true,

                            top:
                                true,

                            bottom:
                                true

                        }

                    });

                }
            );

        }
    );


    /*
     * ------------------------------------------
     * 9. Put text regions into grid cells
     * ------------------------------------------
     */

    const sourceRegions =
        Array.isArray(
            step125Regions
        )
            ? step125Regions
            : [];


    sourceRegions.forEach(
        region => {

            const row =
                findBestRow(
                    region
                );

            const column =
                findBestColumn(
                    region
                );


            if (
                !row ||
                !column
            ) {

                return;

            }


            const target =
                gridCells.find(
                    cell =>
                        cell.row ===
                        row.index &&
                        cell.column ===
                        column.index
                );


            if (!target) {

                return;

            }


            target.textRegions.push(
                region
            );


            if (
                region.text
            ) {

                if (
                    !target.text
                ) {

                    target.text =
                        region.text;

                } else if (
                    !target.text
                        .includes(
                            region.text
                        )
                ) {

                    target.text +=
                        " " +
                        region.text;

                }

            }

        }
    );


    /*
     * ------------------------------------------
     * 10. Determine occupied cells
     * ------------------------------------------
     */

    gridCells.forEach(
        cell => {

            cell.hasText =
                !!(
                    cell.text &&
                    cell.text.trim()
                );


            cell.textCount =
                cell.textRegions.length;

        }
    );


    /*
     * ------------------------------------------
     * 11. Detect merged rows
     *
     * A row is considered merged when
     * its content occupies the complete
     * logical width.
     * ------------------------------------------
     */

    gridRows.forEach(
        row => {

            const rowCells =
                gridCells.filter(
                    cell =>
                        cell.row ===
                        row.index
                );


            const occupied =
                rowCells.filter(
                    cell =>
                        cell.hasText
                );


            if (
                occupied.length === 1 &&
                gridColumns.length > 1
            ) {

                const onlyCell =
                    occupied[0];


                const firstColumn =
                    gridColumns[0];

                const lastColumn =
                    gridColumns[
                        gridColumns.length - 1
                    ];


                /*
                 * Only mark as merged if
                 * the text is actually located
                 * across the row rather than
                 * being a normal single-column
                 * field.
                 */

                const region =
                    onlyCell.textRegions[0];


                if (
                    region
                ) {

                    const regionLeft =
                        region.x;

                    const regionRight =
                        region.x +
                        region.width;


                    const totalLeft =
                        firstColumn.left;

                    const totalRight =
                        lastColumn.right;


                    const occupiedWidth =
                        regionRight -
                        regionLeft;

                    const totalWidth =
                        totalRight -
                        totalLeft;


                    if (
                        occupiedWidth >=
                        totalWidth * 0.55
                    ) {

                        onlyCell.columnSpan =
                            gridColumns.length;

                        onlyCell.isMerged =
                            true;

                    }

                }

            }

        }
    );


    /*
     * ------------------------------------------
     * 12. Build final logical grid model
     * ------------------------------------------
     */

    const step125Model = {

        version:
            "12.5",

        columns:
            gridColumns,

        rows:
            gridRows,

        cells:
            gridCells,

        verticalBorders:
            verticalBorders,

        statistics: {

            rows:
                gridRows.length,

            columns:
                gridColumns.length,

            cells:
                gridCells.length,

            textCells:
                gridCells.filter(
                    cell =>
                        cell.hasText
                ).length,

            emptyCells:
                gridCells.filter(
                    cell =>
                        !cell.hasText
                ).length,

            mergedCells:
                gridCells.filter(
                    cell =>
                        cell.isMerged
                ).length

        }

    };


    /*
     * ------------------------------------------
     * 13. Save model
     * ------------------------------------------
     */

    window.pdfUniversalLogicalGrid =
        step125Model;


    /*
     * ------------------------------------------
     * 14. Console output
     * ------------------------------------------
     */

    console.log("");
    console.log("=================================");
    console.log("STEP 12.5 RESULT");
    console.log("=================================");

    console.log(
        "Rows:",
        step125Model.statistics.rows
    );

    console.log(
        "Columns:",
        step125Model.statistics.columns
    );

    console.log(
        "Cells:",
        step125Model.statistics.cells
    );

    console.log(
        "Text Cells:",
        step125Model.statistics.textCells
    );

    console.log(
        "Empty Cells:",
        step125Model.statistics.emptyCells
    );

    console.log(
        "Merged Cells:",
        step125Model.statistics.mergedCells
    );

    console.log(
        "Vertical Borders:",
        step125Model.verticalBorders
    );

    console.log("");
    console.log(
        "UNIVERSAL LOGICAL GRID:",
        step125Model
    );

    console.log("");
    console.log("=================================");
    console.log("STEP 12.5 COMPLETE");
    console.log("=================================");

}





/* ==========================================
   STEP 13 - UNIVERSAL TEXT TO CELL MAPPING
   & MERGE DETECTION
   ========================================== */

console.log("");
console.log("=================================");
console.log("STEP 13 - UNIVERSAL TEXT TO CELL MAPPING");
console.log("=================================");


const step13Grid =
    window.pdfUniversalLogicalGrid;

const step13Regions =
    window.pdfMergedTextRegions;


if (!step13Grid) {

    console.error(
        "STEP 13 ERROR: Logical grid not found."
    );

} else if (
    !Array.isArray(step13Regions)
) {

    console.error(
        "STEP 13 ERROR: Text regions not found."
    );

} else {

    /*
     * ------------------------------------------
     * 1. Clone grid cells
     * ------------------------------------------
     */

    const step13Cells =
        step13Grid.cells.map(
            cell => ({

                ...cell,

                text:
                    "",

                textRegions:
                    [],

                hasText:
                    false,

                columnSpan:
                    1,

                isMerged:
                    false

            })
        );


    /*
     * ------------------------------------------
     * 2. Geometry helpers
     * ------------------------------------------
     */

    function step13Overlap(
        aStart,
        aEnd,
        bStart,
        bEnd
    ) {

        const start =
            Math.max(
                aStart,
                bStart
            );

        const end =
            Math.min(
                aEnd,
                bEnd
            );

        return Math.max(
            0,
            end - start
        );

    }


    function step13OverlapRatio(
        aStart,
        aEnd,
        bStart,
        bEnd
    ) {

        const overlap =
            step13Overlap(
                aStart,
                aEnd,
                bStart,
                bEnd
            );

        const length =
            Math.max(
                0,
                aEnd - aStart
            );

        if (
            length === 0
        ) {

            return 0;

        }

        return (
            overlap /
            length
        );

    }


    /*
     * ------------------------------------------
     * 3. Find best row
     * ------------------------------------------
     */

    function step13FindRow(
        region
    ) {

        const regionTop =
            region.y;

        const regionBottom =
            region.y +
            region.height;

        const regionCenter =
            (
                regionTop +
                regionBottom
            ) / 2;


        let best =
            null;

        let bestScore =
            -Infinity;


        step13Grid.rows.forEach(
            row => {

                if (
                    row.top === null ||
                    row.bottom === null
                ) {

                    return;

                }


                const overlap =
                    step13Overlap(
                        regionBottom,
                        regionTop,
                        row.bottom,
                        row.top
                    );


                const regionHeight =
                    Math.max(
                        1,
                        regionBottom -
                        regionTop
                    );


                const overlapRatio =
                    overlap /
                    regionHeight;


                const rowCenter =
                    (
                        row.top +
                        row.bottom
                    ) / 2;


                const centerDistance =
                    Math.abs(
                        regionCenter -
                        rowCenter
                    );


                let score =
                    overlapRatio *
                    100;


                /*
                 * Strong preference for
                 * actual row overlap.
                 */

                if (
                    overlapRatio > 0.4
                ) {

                    score += 100;

                }


                /*
                 * Small distance bonus.
                 */

                score -=
                    centerDistance *
                    0.5;


                if (
                    score >
                    bestScore
                ) {

                    bestScore =
                        score;

                    best =
                        row;

                }

            }
        );


        return best;

    }


    /*
     * ------------------------------------------
     * 4. Find best column
     * ------------------------------------------
     */

    function step13FindColumn(
        region
    ) {

        const regionLeft =
            region.x;

        const regionRight =
            region.x +
            region.width;

        const regionCenter =
            (
                regionLeft +
                regionRight
            ) / 2;


        let best =
            null;

        let bestScore =
            -Infinity;


        step13Grid.columns.forEach(
            column => {

                const overlap =
                    step13Overlap(
                        regionLeft,
                        regionRight,
                        column.left,
                        column.right
                    );


                const regionWidth =
                    Math.max(
                        1,
                        regionRight -
                        regionLeft
                    );


                const overlapRatio =
                    overlap /
                    regionWidth;


                const columnCenter =
                    (
                        column.left +
                        column.right
                    ) / 2;


                const centerDistance =
                    Math.abs(
                        regionCenter -
                        columnCenter
                    );


                let score =
                    overlapRatio *
                    100;


                if (
                    overlapRatio > 0.4
                ) {

                    score += 100;

                }


                score -=
                    centerDistance *
                    0.2;


                if (
                    score >
                    bestScore
                ) {

                    bestScore =
                        score;

                    best =
                        column;

                }

            }
        );


        return best;

    }


    /*
     * ------------------------------------------
     * 5. Assign every text region
     * ------------------------------------------
     */

    const step13Assignments = [];


    step13Regions.forEach(
        (region, regionIndex) => {

            if (
                !region.text ||
                !region.text.trim()
            ) {

                return;

            }


            const row =
                step13FindRow(
                    region
                );

            const column =
                step13FindColumn(
                    region
                );


            if (
                !row ||
                !column
            ) {

                console.warn(
                    "STEP 13: Region could not be mapped:",
                    region.text
                );

                return;

            }


            const target =
                step13Cells.find(
                    cell =>
                        cell.row ===
                        row.index &&
                        cell.column ===
                        column.index
                );


            if (!target) {

                return;

            }


            target.textRegions.push({

                regionIndex:
                    regionIndex,

                text:
                    region.text,

                x:
                    region.x,

                y:
                    region.y,

                width:
                    region.width,

                height:
                    region.height

            });


            if (
                !target.text
            ) {

                target.text =
                    region.text;

            } else {

                target.text +=
                    " " +
                    region.text;

            }


            target.hasText =
                true;


            step13Assignments.push({

                regionIndex:
                    regionIndex,

                text:
                    region.text,

                row:
                    row.index,

                column:
                    column.index

            });

        }
    );


    /*
     * ------------------------------------------
     * 6. Detect horizontal spanning text
     * ------------------------------------------
     */

    const step13MergeCandidates = [];


    step13Regions.forEach(
        (region, regionIndex) => {

            if (
                !region.text ||
                !region.text.trim()
            ) {

                return;

            }


            const regionLeft =
                region.x;

            const regionRight =
                region.x +
                region.width;


            const intersectingColumns =
                step13Grid.columns.filter(
                    column => {

                        const overlap =
                            step13Overlap(
                                regionLeft,
                                regionRight,
                                column.left,
                                column.right
                            );


                        return (
                            overlap > 5
                        );

                    }
                );


            if (
                intersectingColumns.length >
                1
            ) {

                const firstColumn =
                    intersectingColumns[0];

                const lastColumn =
                    intersectingColumns[
                        intersectingColumns.length - 1
                    ];


                const coveredWidth =
                    step13Overlap(
                        regionLeft,
                        regionRight,
                        firstColumn.left,
                        lastColumn.right
                    );


                const regionWidth =
                    Math.max(
                        1,
                        regionRight -
                        regionLeft
                    );


                const coverage =
                    coveredWidth /
                    regionWidth;


                if (
                    coverage >= 0.75
                ) {

                    const row =
                        step13FindRow(
                            region
                        );


                    if (row) {

                        step13MergeCandidates.push({

                            regionIndex:
                                regionIndex,

                            text:
                                region.text,

                            row:
                                row.index,

                            startColumn:
                                firstColumn.index,

                            endColumn:
                                lastColumn.index,

                            columnSpan:
                                lastColumn.index -
                                firstColumn.index +
                                1,

                            coverage:
                                coverage

                        });

                    }

                }

            }

        }
    );


    /*
     * ------------------------------------------
     * 7. Apply merge candidates carefully
     * ------------------------------------------
     */

    step13MergeCandidates.forEach(
        candidate => {

            const rowCells =
                step13Cells.filter(
                    cell =>
                        cell.row ===
                        candidate.row
                );


            const occupiedCells =
                rowCells.filter(
                    cell =>
                        cell.hasText
                );


            /*
             * Only merge when the row has
             * one logical text region.
             */

            const matchingCells =
                rowCells.filter(
                    cell =>
                        cell.column >=
                        candidate.startColumn &&
                        cell.column <=
                        candidate.endColumn
                );


            const textCellsInRange =
                matchingCells.filter(
                    cell =>
                        cell.hasText
                );


            if (
                textCellsInRange.length <= 1
            ) {

                const firstCell =
                    rowCells.find(
                        cell =>
                            cell.column ===
                            candidate.startColumn
                    );


                if (
                    firstCell
                ) {

                    firstCell.columnSpan =
                        candidate.columnSpan;

                    firstCell.isMerged =
                        true;

                    firstCell.mergeStartColumn =
                        candidate.startColumn;

                    firstCell.mergeEndColumn =
                        candidate.endColumn;

                    firstCell.mergeText =
                        candidate.text;


                    /*
                     * Mark the remaining
                     * cells as merged children.
                     */

                    matchingCells.forEach(
                        cell => {

                            if (
                                cell !==
                                firstCell
                            ) {

                                cell.isMergedChild =
                                    true;

                            }

                        }
                    );

                }

            }

        }
    );


    /*
     * ------------------------------------------
     * 8. Calculate statistics
     * ------------------------------------------
     */

    const step13Statistics = {

        sourceRegions:
            step13Regions.length,

        mappedRegions:
            step13Assignments.length,

        unmappedRegions:
            step13Regions.length -
            step13Assignments.length,

        totalCells:
            step13Cells.length,

        textCells:
            step13Cells.filter(
                cell =>
                    cell.hasText &&
                    !cell.isMergedChild
            ).length,

        emptyCells:
            step13Cells.filter(
                cell =>
                    !cell.hasText &&
                    !cell.isMergedChild
            ).length,

        mergeCandidates:
            step13MergeCandidates.length,

        mergedCells:
            step13Cells.filter(
                cell =>
                    cell.isMerged
            ).length

    };


    /*
     * ------------------------------------------
     * 9. Create final model
     * ------------------------------------------
     */

    const step13Model = {

        version:
            "13.0",

        rows:
            step13Grid.rows,

        columns:
            step13Grid.columns,

        cells:
            step13Cells,

        assignments:
            step13Assignments,

        mergeCandidates:
            step13MergeCandidates,

        statistics:
            step13Statistics

    };


    /*
     * ------------------------------------------
     * 10. Store globally
     * ------------------------------------------
     */

    window.pdfUniversalTextCellModel =
        step13Model;


    /*
     * ------------------------------------------
     * 11. Console output
     * ------------------------------------------
     */

    console.log("");
    console.log("=================================");
    console.log("STEP 13 RESULT");
    console.log("=================================");

    console.log(
        "Source Text Regions:",
        step13Statistics.sourceRegions
    );

    console.log(
        "Mapped Regions:",
        step13Statistics.mappedRegions
    );

    console.log(
        "Unmapped Regions:",
        step13Statistics.unmappedRegions
    );

    console.log(
        "Total Cells:",
        step13Statistics.totalCells
    );

    console.log(
        "Text Cells:",
        step13Statistics.textCells
    );

    console.log(
        "Empty Cells:",
        step13Statistics.emptyCells
    );

    console.log(
        "Merge Candidates:",
        step13Statistics.mergeCandidates
    );

    console.log(
        "Merged Cells:",
        step13Statistics.mergedCells
    );


    console.log("");
    console.log(
        "UNIVERSAL TEXT CELL MODEL:",
        step13Model
    );

    console.log("");
    console.log("=================================");
    console.log("STEP 13 COMPLETE");
    console.log("=================================");

}





/* =========================================================
   STEP 13.5
   UNIVERSAL TEXT POSITION BASED COLUMN CORRECTION
   ========================================================= */

console.log("");
console.log("=================================");
console.log("STEP 13.5 - TEXT POSITION COLUMN CORRECTION");
console.log("=================================");


const step135Regions =
    window.pdfMergedTextRegions;

const step135Grid =
    window.pdfUniversalLogicalGrid;


if (
    !Array.isArray(step135Regions) ||
    !step135Grid
) {

    console.error(
        "STEP 13.5 ERROR: Required data not found."
    );

} else {

    /*
     * -----------------------------------------------------
     * 1. Create fresh cells
     * -----------------------------------------------------
     */

    const step135Cells = [];


    step135Grid.rows.forEach(
        row => {

            step135Grid.columns.forEach(
                column => {

                    step135Cells.push({

                        row:
                            row.index,

                        column:
                            column.index,

                        left:
                            column.left,

                        right:
                            column.right,

                        top:
                            row.top,

                        bottom:
                            row.bottom,

                        text:
                            "",

                        textRegions:
                            [],

                        hasText:
                            false,

                        columnSpan:
                            1,

                        isMerged:
                            false,

                        isMergedChild:
                            false

                    });

                }
            );

        }
    );


    /*
     * -----------------------------------------------------
     * 2. Helper: overlap
     * -----------------------------------------------------
     */

    function step135Overlap(
        start1,
        end1,
        start2,
        end2
    ) {

        return Math.max(
            0,
            Math.min(end1, end2) -
            Math.max(start1, start2)
        );

    }


    /*
     * -----------------------------------------------------
     * 3. Helper: calculate horizontal position
     * -----------------------------------------------------
     */

    function step135GetColumnScore(
        region,
        column
    ) {

        const regionLeft =
            region.x;

        const regionRight =
            region.x +
            region.width;

        const regionCenter =
            (
                regionLeft +
                regionRight
            ) / 2;


        const columnCenter =
            (
                column.left +
                column.right
            ) / 2;


        const overlap =
            step135Overlap(
                regionLeft,
                regionRight,
                column.left,
                column.right
            );


        const regionWidth =
            Math.max(
                1,
                region.width
            );


        const overlapRatio =
            overlap /
            regionWidth;


        const centerDistance =
            Math.abs(
                regionCenter -
                columnCenter
            );


        /*
         * Position of the LEFT edge is very
         * important for PDF reconstruction.
         */

        const leftDistance =
            Math.abs(
                regionLeft -
                column.left
            );


        let score = 0;


        /*
         * Strong overlap score
         */

        score +=
            overlapRatio *
            100;


        /*
         * Center proximity
         */

        score +=
            Math.max(
                0,
                40 -
                centerDistance
            );


        /*
         * Left edge proximity
         */

        score +=
            Math.max(
                0,
                30 -
                leftDistance
            );


        /*
         * If region starts inside column,
         * give extra confidence.
         */

        if (
            regionLeft >=
            column.left - 5 &&
            regionLeft <=
            column.right + 5
        ) {

            score += 25;

        }


        return score;

    }


    /*
     * -----------------------------------------------------
     * 4. Find best logical row
     * -----------------------------------------------------
     */

    function step135FindRow(
        region
    ) {

        const regionTop =
            region.y;

        const regionBottom =
            region.y +
            region.height;

        const regionCenter =
            (
                regionTop +
                regionBottom
            ) / 2;


        let bestRow =
            null;

        let bestScore =
            -Infinity;


        step135Grid.rows.forEach(
            row => {

                if (
                    row.top === null ||
                    row.bottom === null
                ) {

                    return;

                }


                const overlap =
                    step135Overlap(
                        regionTop,
                        regionBottom,
                        row.bottom,
                        row.top
                    );


                const regionHeight =
                    Math.max(
                        1,
                        region.height
                    );


                const overlapRatio =
                    overlap /
                    regionHeight;


                const rowCenter =
                    (
                        row.top +
                        row.bottom
                    ) / 2;


                const centerDistance =
                    Math.abs(
                        regionCenter -
                        rowCenter
                    );


                let score =
                    overlapRatio *
                    100;


                score +=
                    Math.max(
                        0,
                        50 -
                        centerDistance
                    );


                if (
                    overlapRatio > 0.25
                ) {

                    score += 100;

                }


                if (
                    score >
                    bestScore
                ) {

                    bestScore =
                        score;

                    bestRow =
                        row;

                }

            }
        );


        return bestRow;

    }


    /*
     * -----------------------------------------------------
     * 5. Determine column using REAL text position
     * -----------------------------------------------------
     */

    function step135FindColumn(
        region
    ) {

        let bestColumn =
            null;

        let bestScore =
            -Infinity;


        step135Grid.columns.forEach(
            column => {

                const score =
                    step135GetColumnScore(
                        region,
                        column
                    );


                if (
                    score >
                    bestScore
                ) {

                    bestScore =
                        score;

                    bestColumn =
                        column;

                }

            }
        );


        return {

            column:
                bestColumn,

            score:
                bestScore

        };

    }


    /*
     * -----------------------------------------------------
     * 6. First-pass mapping
     * -----------------------------------------------------
     */

    const step135Assignments = [];


    step135Regions.forEach(
        (region, index) => {

            if (
                !region.text ||
                !region.text.trim()
            ) {

                return;

            }


            const row =
                step135FindRow(
                    region
                );


            const columnResult =
                step135FindColumn(
                    region
                );


            if (
                !row ||
                !columnResult.column
            ) {

                return;

            }


            const column =
                columnResult.column;


            const cell =
                step135Cells.find(
                    item =>
                        item.row ===
                        row.index &&
                        item.column ===
                        column.index
                );


            if (!cell) {

                return;

            }


            cell.textRegions.push({

                regionIndex:
                    index,

                text:
                    region.text,

                x:
                    region.x,

                y:
                    region.y,

                width:
                    region.width,

                height:
                    region.height

            });


            if (
                !cell.text
            ) {

                cell.text =
                    region.text;

            } else {

                cell.text +=
                    " " +
                    region.text;

            }


            cell.hasText =
                true;


            step135Assignments.push({

                regionIndex:
                    index,

                text:
                    region.text,

                row:
                    row.index,

                column:
                    column.index,

                score:
                    Math.round(
                        columnResult.score *
                        100
                    ) / 100

            });

        }
    );


    /*
     * -----------------------------------------------------
     * 7. Detect actual horizontal span
     * -----------------------------------------------------
     */

    const step135MergeCandidates = [];


    step135Regions.forEach(
        (region, regionIndex) => {

            if (
                !region.text ||
                !region.text.trim()
            ) {

                return;

            }


            const regionLeft =
                region.x;

            const regionRight =
                region.x +
                region.width;


            const touchedColumns =
                step135Grid.columns.filter(
                    column => {

                        const overlap =
                            step135Overlap(
                                regionLeft,
                                regionRight,
                                column.left,
                                column.right
                            );


                        return (
                            overlap >
                            Math.min(
                                5,
                                region.width *
                                0.1
                            )
                        );

                    }
                );


            if (
                touchedColumns.length < 2
            ) {

                return;

            }


            const row =
                step135FindRow(
                    region
                );


            if (!row) {

                return;

            }


            const firstColumn =
                touchedColumns[0];

            const lastColumn =
                touchedColumns[
                    touchedColumns.length - 1
                ];


            const totalSpan =
                lastColumn.right -
                firstColumn.left;


            const regionCoverage =
                step135Overlap(
                    regionLeft,
                    regionRight,
                    firstColumn.left,
                    lastColumn.right
                ) /
                Math.max(
                    1,
                    region.width
                );


            /*
             * A region spanning multiple logical
             * columns is considered a merge candidate.
             */

            if (
                regionCoverage >= 0.75
            ) {

                step135MergeCandidates.push({

                    regionIndex:
                        regionIndex,

                    text:
                        region.text,

                    row:
                        row.index,

                    startColumn:
                        firstColumn.index,

                    endColumn:
                        lastColumn.index,

                    columnSpan:
                        lastColumn.index -
                        firstColumn.index +
                        1,

                    coverage:
                        Math.round(
                            regionCoverage *
                            100
                        ) / 100,

                    spanWidth:
                        totalSpan

                });

            }

        }
    );


    /*
     * -----------------------------------------------------
     * 8. Apply merge only when safe
     * -----------------------------------------------------
     */

    step135MergeCandidates.forEach(
        candidate => {

            const rowCells =
                step135Cells.filter(
                    cell =>
                        cell.row ===
                        candidate.row
                );


            const cellsInSpan =
                rowCells.filter(
                    cell =>
                        cell.column >=
                        candidate.startColumn &&
                        cell.column <=
                        candidate.endColumn
                );


            /*
             * Count independent text regions
             * in the candidate range.
             */

            const textRegionCount =
                cellsInSpan.reduce(
                    (
                        total,
                        cell
                    ) =>
                        total +
                        cell.textRegions.length,
                    0
                );


            /*
             * Merge only when the range is
             * represented by one text region.
             */

            if (
                textRegionCount === 1
            ) {

                const firstCell =
                    cellsInSpan[0];


                if (
                    firstCell
                ) {

                    firstCell.isMerged =
                        true;

                    firstCell.columnSpan =
                        candidate.columnSpan;

                    firstCell.mergeStartColumn =
                        candidate.startColumn;

                    firstCell.mergeEndColumn =
                        candidate.endColumn;


                    for (
                        let i = 1;
                        i < cellsInSpan.length;
                        i++
                    ) {

                        cellsInSpan[i]
                            .isMergedChild =
                            true;

                    }

                }

            }

        }
    );


    /*
     * -----------------------------------------------------
     * 9. Statistics
     * -----------------------------------------------------
     */

    const mappedRegions =
        step135Assignments.length;


    const textCells =
        step135Cells.filter(
            cell =>
                cell.hasText &&
                !cell.isMergedChild
        );


    const emptyCells =
        step135Cells.filter(
            cell =>
                !cell.hasText &&
                !cell.isMergedChild
        );


    const mergedCells =
        step135Cells.filter(
            cell =>
                cell.isMerged
        );


    const step135Statistics = {

        sourceRegions:
            step135Regions.length,

        mappedRegions:
            mappedRegions,

        unmappedRegions:
            step135Regions.length -
            mappedRegions,

        totalCells:
            step135Cells.length,

        textCells:
            textCells.length,

        emptyCells:
            emptyCells.length,

        mergeCandidates:
            step135MergeCandidates.length,

        mergedCells:
            mergedCells.length

    };


    /*
     * -----------------------------------------------------
     * 10. Create corrected model
     * -----------------------------------------------------
     */

    const step135Model = {

        version:
            "13.5",

        rows:
            step135Grid.rows,

        columns:
            step135Grid.columns,

        cells:
            step135Cells,

        assignments:
            step135Assignments,

        mergeCandidates:
            step135MergeCandidates,

        statistics:
            step135Statistics

    };


    /*
     * -----------------------------------------------------
     * 11. Store result
     * -----------------------------------------------------
     */

    window.pdfUniversalCorrectedTextCellModel =
        step135Model;


    /*
     * -----------------------------------------------------
     * 12. Console result
     * -----------------------------------------------------
     */

    console.log("");
    console.log("=================================");
    console.log("STEP 13.5 RESULT");
    console.log("=================================");

    console.log(
        "Source Text Regions:",
        step135Statistics.sourceRegions
    );

    console.log(
        "Mapped Regions:",
        step135Statistics.mappedRegions
    );

    console.log(
        "Unmapped Regions:",
        step135Statistics.unmappedRegions
    );

    console.log(
        "Total Cells:",
        step135Statistics.totalCells
    );

    console.log(
        "Text Cells:",
        step135Statistics.textCells
    );

    console.log(
        "Empty Cells:",
        step135Statistics.emptyCells
    );

    console.log(
        "Merge Candidates:",
        step135Statistics.mergeCandidates
    );

    console.log(
        "Merged Cells:",
        step135Statistics.mergedCells
    );


    console.log("");
    console.log(
        "STEP 13.5 ASSIGNMENTS:"
    );

    console.table(
        step135Assignments
    );


    console.log("");
    console.log(
        "STEP 13.5 COMPLETE"
    );

}





/* =========================================================
   STEP 14
   UNIVERSAL TEXT COLUMN GEOMETRY DETECTION
   ========================================================= */

console.log("");
console.log("=================================");
console.log("STEP 14 - UNIVERSAL TEXT COLUMN GEOMETRY");
console.log("=================================");


const step14Regions =
    window.pdfMergedTextRegions;


if (
    !Array.isArray(step14Regions) ||
    step14Regions.length === 0
) {

    console.error(
        "STEP 14 ERROR: Text regions not available."
    );

} else {

    /*
     * -----------------------------------------------------
     * 1. Collect X positions
     * -----------------------------------------------------
     */

    const step14XPoints = [];


    step14Regions.forEach(
        region => {

            if (
                !region.text ||
                !region.text.trim()
            ) {

                return;

            }


            const left =
                region.x;

            const right =
                region.x +
                region.width;


            const center =
                (
                    left +
                    right
                ) / 2;


            step14XPoints.push({

                type:
                    "left",

                x:
                    left,

                width:
                    region.width,

                text:
                    region.text

            });


            step14XPoints.push({

                type:
                    "right",

                x:
                    right,

                width:
                    region.width,

                text:
                    region.text

            });


            step14XPoints.push({

                type:
                    "center",

                x:
                    center,

                width:
                    region.width,

                text:
                    region.text

            });

        }
    );


    /*
     * -----------------------------------------------------
     * 2. Cluster nearby X positions
     * -----------------------------------------------------
     */

    const step14Tolerance =
        3;


    const step14Sorted =
        [...step14XPoints]
            .sort(
                (a, b) =>
                    a.x - b.x
            );


    const step14Clusters = [];


    step14Sorted.forEach(
        point => {

            let target =
                null;


            for (
                let i = step14Clusters.length - 1;
                i >= 0;
                i--
            ) {

                const cluster =
                    step14Clusters[i];


                if (
                    Math.abs(
                        point.x -
                        cluster.mean
                    ) <=
                    step14Tolerance
                ) {

                    target =
                        cluster;

                    break;

                }


                if (
                    point.x -
                    cluster.mean >
                    step14Tolerance
                ) {

                    break;

                }

            }


            if (!target) {

                step14Clusters.push({

                    points:
                        [point],

                    mean:
                        point.x,

                    count:
                        1

                });

            } else {

                target.points.push(
                    point
                );

                target.count =
                    target.points.length;


                target.mean =
                    target.points.reduce(
                        (
                            sum,
                            item
                        ) =>
                            sum +
                            item.x,
                        0
                    ) /
                    target.count;

            }

        }
    );


    /*
     * -----------------------------------------------------
     * 3. Calculate cluster statistics
     * -----------------------------------------------------
     */

    const step14ClusterStats =
        step14Clusters.map(
            cluster => {

                const leftCount =
                    cluster.points.filter(
                        point =>
                            point.type ===
                            "left"
                    ).length;


                const rightCount =
                    cluster.points.filter(
                        point =>
                            point.type ===
                            "right"
                    ).length;


                const centerCount =
                    cluster.points.filter(
                        point =>
                            point.type ===
                            "center"
                    ).length;


                const averageWidth =
                    cluster.points.reduce(
                        (
                            sum,
                            point
                        ) =>
                            sum +
                            point.width,
                        0
                    ) /
                    Math.max(
                        1,
                        cluster.points.length
                    );


                return {

                    x:
                        Math.round(
                            cluster.mean *
                            100
                        ) / 100,

                    count:
                        cluster.count,

                    leftCount:
                        leftCount,

                    rightCount:
                        rightCount,

                    centerCount:
                        centerCount,

                    averageWidth:
                        Math.round(
                            averageWidth *
                            100
                        ) / 100

                };

            }
        );


    /*
     * -----------------------------------------------------
     * 4. Detect strong text anchors
     * -----------------------------------------------------
     */

    const step14Anchors =
        step14ClusterStats.filter(
            cluster => {

                /*
                 * A useful text anchor is normally
                 * repeated by several regions.
                 */

                return (
                    cluster.count >= 2
                );

            }
        );


    /*
     * -----------------------------------------------------
     * 5. Detect left-edge alignment groups
     * -----------------------------------------------------
     */

    const step14LeftAnchors =
        step14Anchors
            .filter(
                cluster =>
                    cluster.leftCount >= 2
            )
            .sort(
                (
                    a,
                    b
                ) =>
                    a.x - b.x
            );


    /*
     * -----------------------------------------------------
     * 6. Detect right-edge alignment groups
     * -----------------------------------------------------
     */

    const step14RightAnchors =
        step14Anchors
            .filter(
                cluster =>
                    cluster.rightCount >= 2
            )
            .sort(
                (
                    a,
                    b
                ) =>
                    a.x - b.x
            );


    /*
     * -----------------------------------------------------
     * 7. Detect text starts
     * -----------------------------------------------------
     */

    const step14TextStarts =
        step14Regions
            .map(
                region =>
                    region.x
            )
            .sort(
                (
                    a,
                    b
                ) =>
                    a - b
            );


    /*
     * -----------------------------------------------------
     * 8. Cluster actual text starts
     * -----------------------------------------------------
     */

    const step14StartClusters = [];


    step14TextStarts.forEach(
        x => {

            let target =
                null;


            for (
                let i =
                    step14StartClusters.length - 1;
                i >= 0;
                i--
            ) {

                const cluster =
                    step14StartClusters[i];


                if (
                    Math.abs(
                        x -
                        cluster.mean
                    ) <=
                    step14Tolerance
                ) {

                    target =
                        cluster;

                    break;

                }


                if (
                    x -
                    cluster.mean >
                    step14Tolerance
                ) {

                    break;

                }

            }


            if (!target) {

                step14StartClusters.push({

                    values:
                        [x],

                    mean:
                        x,

                    count:
                        1

                });

            } else {

                target.values.push(
                    x
                );

                target.count =
                    target.values.length;


                target.mean =
                    target.values.reduce(
                        (
                            sum,
                            value
                        ) =>
                            sum +
                            value,
                        0
                    ) /
                    target.count;

            }

        }
    );


    /*
     * -----------------------------------------------------
     * 9. Keep meaningful text-start columns
     * -----------------------------------------------------
     */

    const step14TextColumns =
        step14StartClusters
            .filter(
                cluster =>
                    cluster.count >= 2
            )
            .map(
                (
                    cluster,
                    index
                ) => ({

                    index:
                        index,

                    x:
                        Math.round(
                            cluster.mean *
                            100
                        ) / 100,

                    count:
                        cluster.count

                })
            );


    /*
     * -----------------------------------------------------
     * 10. Add singleton starts when they create
     *     a meaningful gap between strong columns
     * -----------------------------------------------------
     */

    const step14StrongX =
        step14TextColumns.map(
            column =>
                column.x
        );


    const step14AllStarts =
        step14StartClusters.map(
            cluster =>
                cluster.mean
        );


    step14AllStarts.forEach(
        x => {

            const alreadyExists =
                step14StrongX.some(
                    strongX =>
                        Math.abs(
                            strongX -
                            x
                        ) <=
                        step14Tolerance
                );


            if (
                alreadyExists
            ) {

                return;

            }


            /*
             * Find nearest strong columns.
             */

            const distances =
                step14StrongX.map(
                    strongX =>
                        Math.abs(
                            strongX -
                            x
                        )
                );


            const nearest =
                distances.length
                    ? Math.min(
                        ...distances
                    )
                    : Infinity;


            /*
             * Only keep a singleton when it
             * is reasonably separated.
             */

            if (
                nearest >
                25
            ) {

                step14TextColumns.push({

                    index:
                        step14TextColumns.length,

                    x:
                        Math.round(
                            x *
                            100
                        ) / 100,

                    count:
                        1

                });

            }

        }
    );


    /*
     * -----------------------------------------------------
     * 11. Sort final text columns
     * -----------------------------------------------------
     */

    step14TextColumns.sort(
        (
            a,
            b
        ) =>
            a.x - b.x
    );


    /*
     * Re-number columns
     */

    step14TextColumns.forEach(
        (
            column,
            index
        ) => {

            column.index =
                index;

        }
    );


    /*
     * -----------------------------------------------------
     * 12. Build column boundaries
     * -----------------------------------------------------
     */

    const step14Columns = [];


    step14TextColumns.forEach(
        (
            column,
            index
        ) => {

            const previous =
                step14TextColumns[
                    index - 1
                ];


            const next =
                step14TextColumns[
                    index + 1
                ];


            let left =
                column.x;


            let right;


            if (next) {

                right =
                    (
                        column.x +
                        next.x
                    ) / 2;

            } else {

                /*
                 * Last text column:
                 * use furthest text right.
                 */

                const columnRegions =
                    step14Regions.filter(
                        region =>
                            Math.abs(
                                region.x -
                                column.x
                            ) <=
                            step14Tolerance
                    );


                const maxRight =
                    columnRegions.reduce(
                        (
                            max,
                            region
                        ) =>
                            Math.max(
                                max,
                                region.x +
                                region.width
                            ),
                        column.x
                    );


                right =
                    maxRight;

            }


            /*
             * First column should not start
             * at an arbitrary text center.
             */

            if (
                previous
            ) {

                left =
                    (
                        previous.x +
                        column.x
                    ) / 2;

            }


            step14Columns.push({

                index:
                    index,

                left:
                    Math.round(
                        left *
                        100
                    ) / 100,

                right:
                    Math.round(
                        right *
                        100
                    ) / 100,

                width:
                    Math.round(
                        (
                            right -
                            left
                        ) *
                        100
                    ) / 100,

                anchorX:
                    column.x,

                sampleCount:
                    column.count

            });

        }
    );


    /*
     * -----------------------------------------------------
     * 13. Remove extremely narrow columns
     * -----------------------------------------------------
     */

    const step14FilteredColumns =
        step14Columns.filter(
            column =>
                column.width >
                15
        );


    step14FilteredColumns.forEach(
        (
            column,
            index
        ) => {

            column.index =
                index;

        }
    );


    /*
     * -----------------------------------------------------
     * 14. Final model
     * -----------------------------------------------------
     */

    const step14Model = {

        version:
            "14.0",

        tolerance:
            step14Tolerance,

        xClusters:
            step14ClusterStats,

        leftAnchors:
            step14LeftAnchors,

        rightAnchors:
            step14RightAnchors,

        textStartClusters:
            step14StartClusters,

        textColumns:
            step14FilteredColumns

    };


    /*
     * -----------------------------------------------------
     * 15. Store globally
     * -----------------------------------------------------
     */

    window.pdfUniversalTextColumns =
        step14Model;


    /*
     * -----------------------------------------------------
     * 16. Console output
     * -----------------------------------------------------
     */

    console.log("");
    console.log("=================================");
    console.log("STEP 14 RESULT");
    console.log("=================================");

    console.log(
        "Source Text Regions:",
        step14Regions.length
    );

    console.log(
        "X Position Clusters:",
        step14ClusterStats.length
    );

    console.log(
        "Strong Left Anchors:",
        step14LeftAnchors.length
    );

    console.log(
        "Strong Right Anchors:",
        step14RightAnchors.length
    );

    console.log(
        "Detected Text Columns:",
        step14FilteredColumns.length
    );


    console.log("");
    console.log(
        "TEXT COLUMNS:"
    );

    console.table(
        step14FilteredColumns
    );


    console.log("");
    console.log(
        "LEFT ANCHORS:"
    );

    console.table(
        step14LeftAnchors
    );


    console.log("");
    console.log(
        "RIGHT ANCHORS:"
    );

    console.table(
        step14RightAnchors
    );


    console.log("");
    console.log(
        "STEP 14 COMPLETE"
    );

}





/* =========================================================
   STEP 14.5
   UNIVERSAL TEXT ANCHOR CLASSIFICATION
   & LOGICAL COLUMN DETECTION
   ========================================================= */

console.log("");
console.log("=================================");
console.log("STEP 14.5 - TEXT ANCHOR CLASSIFICATION");
console.log("=================================");


const step145Regions =
    window.pdfMergedTextRegions;


if (
    !Array.isArray(step145Regions) ||
    step145Regions.length === 0
) {

    console.error(
        "STEP 14.5 ERROR: Text regions not found."
    );

} else {

    /*
     * -----------------------------------------------------
     * 1. Basic configuration
     * -----------------------------------------------------
     */

    const STEP145_TOLERANCE = 4;

    const STEP145_MIN_REPEAT = 2;

    const STEP145_MIN_COLUMN_GAP = 30;


    /*
     * -----------------------------------------------------
     * 2. Collect actual text starts
     * -----------------------------------------------------
     */

    const step145Starts =
        step145Regions
            .filter(
                region =>
                    region.text &&
                    region.text.trim()
            )
            .map(
                region => ({

                    x:
                        region.x,

                    right:
                        region.x +
                        region.width,

                    center:
                        region.x +
                        (
                            region.width /
                            2
                        ),

                    width:
                        region.width,

                    y:
                        region.y,

                    text:
                        region.text

                })
            );


    /*
     * -----------------------------------------------------
     * 3. Cluster text START positions
     * -----------------------------------------------------
     */

    const step145Clusters = [];


    step145Starts
        .sort(
            (
                a,
                b
            ) =>
                a.x - b.x
        )
        .forEach(
            point => {

                let target =
                    null;


                for (
                    let i =
                        step145Clusters.length - 1;
                    i >= 0;
                    i--
                ) {

                    const cluster =
                        step145Clusters[i];


                    if (
                        Math.abs(
                            point.x -
                            cluster.mean
                        ) <=
                        STEP145_TOLERANCE
                    ) {

                        target =
                            cluster;

                        break;

                    }


                    if (
                        point.x -
                        cluster.mean >
                        STEP145_TOLERANCE
                    ) {

                        break;

                    }

                }


                if (!target) {

                    step145Clusters.push({

                        points:
                            [point],

                        mean:
                            point.x

                    });

                } else {

                    target.points.push(
                        point
                    );


                    target.mean =
                        target.points.reduce(
                            (
                                sum,
                                item
                            ) =>
                                sum +
                                item.x,
                            0
                        ) /
                        target.points.length;

                }

            }
        );


    /*
     * -----------------------------------------------------
     * 4. Calculate cluster information
     * -----------------------------------------------------
     */

    const step145ClusterInfo =
        step145Clusters.map(
            (
                cluster,
                index
            ) => {

                const count =
                    cluster.points.length;


                const totalWidth =
                    cluster.points.reduce(
                        (
                            sum,
                            item
                        ) =>
                            sum +
                            item.width,
                        0
                    );


                const averageWidth =
                    totalWidth /
                    Math.max(
                        1,
                        count
                    );


                const minY =
                    Math.min(
                        ...cluster.points.map(
                            item =>
                                item.y
                        )
                    );


                const maxY =
                    Math.max(
                        ...cluster.points.map(
                            item =>
                                item.y
                        )
                    );


                const texts =
                    cluster.points.map(
                        item =>
                            item.text
                    );


                return {

                    rawIndex:
                        index,

                    x:
                        Math.round(
                            cluster.mean *
                            100
                        ) / 100,

                    count:
                        count,

                    averageWidth:
                        Math.round(
                            averageWidth *
                            100
                        ) / 100,

                    yRange:
                        Math.round(
                            (
                                maxY -
                                minY
                            ) *
                            100
                        ) / 100,

                    texts:
                        texts

                };

            }
        );


    /*
     * -----------------------------------------------------
     * 5. Strong anchors
     * -----------------------------------------------------
     */

    const step145StrongAnchors =
        step145ClusterInfo
            .filter(
                cluster =>
                    cluster.count >=
                    STEP145_MIN_REPEAT
            )
            .sort(
                (
                    a,
                    b
                ) =>
                    a.x - b.x
            );


    /*
     * -----------------------------------------------------
     * 6. Classify isolated positions
     * -----------------------------------------------------
     */

    const step145Classified =
        step145ClusterInfo.map(
            cluster => {

                let type =
                    "isolated";


                if (
                    cluster.count >=
                    STEP145_MIN_REPEAT
                ) {

                    type =
                        "repeated-anchor";

                }


                /*
                 * Detect likely title / isolated
                 * centered text.
                 */

                if (
                    cluster.count === 1 &&
                    cluster.averageWidth > 100
                ) {

                    type =
                        "isolated-wide";

                }


                /*
                 * Detect likely right-side isolated
                 * content.
                 */

                if (
                    cluster.count === 1 &&
                    cluster.x > 0
                ) {

                    const nearRepeated =
                        step145StrongAnchors.some(
                            anchor =>
                                Math.abs(
                                    anchor.x -
                                    cluster.x
                                ) <=
                                25
                        );


                    if (
                        !nearRepeated
                    ) {

                        type =
                            "isolated";

                    }

                }


                return {

                    ...cluster,

                    type:

                        type

                };

            }
        );


    /*
     * -----------------------------------------------------
     * 7. Build candidate logical columns
     * -----------------------------------------------------
     */

    const step145Candidates =
        step145StrongAnchors
            .map(
                anchor => ({

                    x:
                        anchor.x,

                    count:
                        anchor.count,

                    averageWidth:
                        anchor.averageWidth,

                    confidence:
                        Math.min(
                            100,
                            anchor.count *
                            10
                        )

                })
            );


    /*
     * -----------------------------------------------------
     * 8. Remove anchors that are too close
     * -----------------------------------------------------
     */

    const step145LogicalAnchors = [];


    step145Candidates
        .sort(
            (
                a,
                b
            ) =>
                a.x - b.x
        )
        .forEach(
            candidate => {

                if (
                    step145LogicalAnchors.length ===
                    0
                ) {

                    step145LogicalAnchors.push(
                        candidate
                    );

                    return;

                }


                const previous =
                    step145LogicalAnchors[
                        step145LogicalAnchors.length - 1
                    ];


                const gap =
                    candidate.x -
                    previous.x;


                if (
                    gap >=
                    STEP145_MIN_COLUMN_GAP
                ) {

                    step145LogicalAnchors.push(
                        candidate
                    );

                } else {

                    /*
                     * Keep the stronger repeated
                     * anchor.
                     */

                    if (
                        candidate.count >
                        previous.count
                    ) {

                        step145LogicalAnchors[
                            step145LogicalAnchors.length - 1
                        ] =
                            candidate;

                    }

                }

            }
        );


    /*
     * -----------------------------------------------------
     * 9. Add useful wide text anchor only when
     *    there are not enough repeated columns
     * -----------------------------------------------------
     */

    if (
        step145LogicalAnchors.length <
        2
    ) {

        const usefulIsolated =
            step145Classified
                .filter(
                    cluster =>
                        cluster.type ===
                        "isolated-wide"
                )
                .sort(
                    (
                        a,
                        b
                    ) =>
                        b.averageWidth -
                        a.averageWidth
                );


        usefulIsolated
            .slice(
                0,
                1
            )
            .forEach(
                cluster => {

                    step145LogicalAnchors.push({

                        x:
                            cluster.x,

                        count:
                            cluster.count,

                        averageWidth:
                            cluster.averageWidth,

                        confidence:
                            20

                    });

                }
            );

    }


    /*
     * -----------------------------------------------------
     * 10. Sort logical anchors
     * -----------------------------------------------------
     */

    step145LogicalAnchors.sort(
        (
            a,
            b
        ) =>
            a.x - b.x
    );


    /*
     * -----------------------------------------------------
     * 11. Create logical text columns
     * -----------------------------------------------------
     */

    const step145Columns = [];


    step145LogicalAnchors.forEach(
        (
            anchor,
            index
        ) => {

            const previous =
                step145LogicalAnchors[
                    index - 1
                ];


            const next =
                step145LogicalAnchors[
                    index + 1
                ];


            let left =
                anchor.x;


            let right;


            /*
             * Boundary between this anchor
             * and next anchor.
             */

            if (next) {

                right =
                    (
                        anchor.x +
                        next.x
                    ) / 2;

            } else {

                /*
                 * Last column:
                 * determine maximum text right
                 * belonging to this anchor.
                 */

                const relatedRegions =
                    step145Regions.filter(
                        region =>
                            Math.abs(
                                region.x -
                                anchor.x
                            ) <=
                            STEP145_TOLERANCE
                    );


                const maxRight =
                    relatedRegions.reduce(
                        (
                            max,
                            region
                        ) =>
                            Math.max(
                                max,
                                region.x +
                                region.width
                            ),
                        anchor.x
                    );


                right =
                    maxRight;

            }


            if (previous) {

                left =
                    (
                        previous.x +
                        anchor.x
                    ) / 2;

            }


            step145Columns.push({

                index:
                    index,

                left:
                    Math.round(
                        left *
                        100
                    ) / 100,

                right:
                    Math.round(
                        right *
                        100
                    ) / 100,

                width:
                    Math.round(
                        (
                            right -
                            left
                        ) *
                        100
                    ) / 100,

                anchorX:
                    Math.round(
                        anchor.x *
                        100
                    ) / 100,

                sampleCount:
                    anchor.count,

                confidence:
                    anchor.confidence

            });

        }
    );


    /*
     * -----------------------------------------------------
     * 12. Remove invalid/narrow columns
     * -----------------------------------------------------
     */

    const step145FinalColumns =
        step145Columns.filter(
            column =>
                column.width >
                20
        );


    step145FinalColumns.forEach(
        (
            column,
            index
        ) => {

            column.index =
                index;

        }
    );


    /*
     * -----------------------------------------------------
     * 13. Model
     * -----------------------------------------------------
     */

    const step145Model = {

        version:
            "14.5",

        tolerance:
            STEP145_TOLERANCE,

        minRepeat:
            STEP145_MIN_REPEAT,

        minColumnGap:
            STEP145_MIN_COLUMN_GAP,

        clusters:
            step145Classified,

        strongAnchors:
            step145StrongAnchors,

        logicalAnchors:
            step145LogicalAnchors,

        columns:
            step145FinalColumns

    };


    /*
     * -----------------------------------------------------
     * 14. Store
     * -----------------------------------------------------
     */

    window.pdfUniversalLogicalTextColumns =
        step145Model;


    /*
     * -----------------------------------------------------
     * 15. Console output
     * -----------------------------------------------------
 */

    console.log("");
    console.log("=================================");
    console.log("STEP 14.5 RESULT");
    console.log("=================================");

    console.log(
        "Source Text Regions:",
        step145Regions.length
    );

    console.log(
        "X Clusters:",
        step145ClusterInfo.length
    );

    console.log(
        "Strong Anchors:",
        step145StrongAnchors.length
    );

    console.log(
        "Logical Anchors:",
        step145LogicalAnchors.length
    );

    console.log(
        "Detected Logical Columns:",
        step145FinalColumns.length
    );


    console.log("");
    console.log(
        "LOGICAL TEXT COLUMNS:"
    );

    console.table(
        step145FinalColumns
    );


    console.log("");
    console.log(
        "LOGICAL ANCHORS:"
    );

    console.table(
        step145LogicalAnchors
    );


    console.log("");
    console.log(
        "CLASSIFIED X CLUSTERS:"
    );

    console.table(
        step145Classified
    );


    console.log("");
    console.log(
        "STEP 14.5 COMPLETE"
    );

}





// ============================================================
// STEP 15
// UNIVERSAL TEXT-TO-LOGICAL-COLUMN REMAPPING
// ============================================================

console.log("=================================");
console.log("STEP 15 START");
console.log("=================================");

const sourceRegions15 =
    window.pdfMergedTextRegions || [];

const logicalColumns15 =
    window.pdfUniversalLogicalTextColumns?.columns || [];

if (
    !sourceRegions15.length ||
    !logicalColumns15.length
) {
    console.error(
        "Step 15: Required Step 14.5 data not found."
    );
} else {

    // --------------------------------------------------------
    // Helper: calculate horizontal overlap
    // --------------------------------------------------------

    function horizontalOverlap15(a, b) {

        const left =
            Math.max(a.x, b.left);

        const right =
            Math.min(
                a.x + a.width,
                b.right
            );

        return Math.max(
            0,
            right - left
        );
    }


    // --------------------------------------------------------
    // Helper: calculate overlap ratio
    // --------------------------------------------------------

    function overlapRatio15(region, column) {

        const overlap =
            horizontalOverlap15(
                region,
                column
            );

        if (region.width <= 0) {
            return 0;
        }

        return overlap / region.width;
    }


    // --------------------------------------------------------
    // Helper: distance between text start and anchor
    // --------------------------------------------------------

    function anchorDistance15(
        region,
        column
    ) {

        return Math.abs(
            region.x - column.anchorX
        );
    }


    // --------------------------------------------------------
    // Helper: distance from region center
    // --------------------------------------------------------

    function centerDistance15(
        region,
        column
    ) {

        const regionCenter =
            region.x +
            (region.width / 2);

        const columnCenter =
            (column.left + column.right) / 2;

        return Math.abs(
            regionCenter - columnCenter
        );
    }


    // --------------------------------------------------------
    // Score each region against each logical column
    // --------------------------------------------------------

    function scoreColumn15(
        region,
        column
    ) {

        const overlap =
            overlapRatio15(
                region,
                column
            );

        const anchorDistance =
            anchorDistance15(
                region,
                column
            );

        const centerDistance =
            centerDistance15(
                region,
                column
            );

        let score = 0;


        // Strong horizontal overlap
        score += overlap * 100;


        // Text starting close to column anchor
        score += Math.max(
            0,
            50 - anchorDistance
        );


        // Center proximity
        score += Math.max(
            0,
            30 - centerDistance
        );


        // ----------------------------------------------------
        // Strong bonus when text starts near anchor
        // ----------------------------------------------------

        if (anchorDistance <= 3) {

            score += 80;

        } else if (anchorDistance <= 8) {

            score += 40;

        } else if (anchorDistance <= 15) {

            score += 15;
        }


        return score;
    }


    // --------------------------------------------------------
    // Map every text region
    // --------------------------------------------------------

    const assignments15 = [];

    sourceRegions15.forEach(
        (region, regionIndex) => {

            let bestColumn = -1;
            let bestScore = -Infinity;

            const candidateScores = [];


            logicalColumns15.forEach(
                (column, columnIndex) => {

                    const score =
                        scoreColumn15(
                            region,
                            column
                        );

                    candidateScores.push({
                        column: columnIndex,
                        score: score
                    });


                    if (
                        score >
                        bestScore
                    ) {

                        bestScore =
                            score;

                        bestColumn =
                            columnIndex;
                    }
                }
            );


            // ------------------------------------------------
            // Sort candidates for diagnostics
            // ------------------------------------------------

            candidateScores.sort(
                (a, b) =>
                    b.score - a.score
            );


            const secondBest =
                candidateScores.length > 1
                    ? candidateScores[1].score
                    : 0;


            const confidenceGap =
                bestScore -
                secondBest;


            assignments15.push({

                regionIndex:
                    regionIndex,

                text:
                    region.text,

                x:
                    region.x,

                width:
                    region.width,

                column:
                    bestColumn,

                score:
                    Number(
                        bestScore.toFixed(2)
                    ),

                confidenceGap:
                    Number(
                        confidenceGap.toFixed(2)
                    )
            });

        }
    );


    // --------------------------------------------------------
    // Build column groups
    // --------------------------------------------------------

    const columnGroups15 =
        logicalColumns15.map(
            (_, columnIndex) => {

                return assignments15
                    .filter(
                        item =>
                            item.column ===
                            columnIndex
                    );
            }
        );


    // --------------------------------------------------------
    // Calculate column statistics
    // --------------------------------------------------------

    const columnStatistics15 =
        columnGroups15.map(
            (
                group,
                columnIndex
            ) => {

                if (!group.length) {

                    return {

                        column:
                            columnIndex,

                        regionCount:
                            0,

                        minX:
                            null,

                        maxX:
                            null,

                        averageX:
                            null,

                        averageConfidence:
                            0
                    };
                }


                const minX =
                    Math.min(
                        ...group.map(
                            item => item.x
                        )
                    );


                const maxX =
                    Math.max(
                        ...group.map(
                            item =>
                                item.x +
                                item.width
                        )
                    );


                const averageX =
                    group.reduce(
                        (
                            sum,
                            item
                        ) =>
                            sum +
                            item.x,
                        0
                    ) /
                    group.length;


                const averageConfidence =
                    group.reduce(
                        (
                            sum,
                            item
                        ) =>
                            sum +
                            item.confidenceGap,
                        0
                    ) /
                    group.length;


                return {

                    column:
                        columnIndex,

                    regionCount:
                        group.length,

                    minX:
                        Number(
                            minX.toFixed(2)
                        ),

                    maxX:
                        Number(
                            maxX.toFixed(2)
                        ),

                    averageX:
                        Number(
                            averageX.toFixed(2)
                        ),

                    averageConfidence:
                        Number(
                            averageConfidence.toFixed(2)
                        )
                };
            }
        );


    // --------------------------------------------------------
    // Save final Step 15 model
    // --------------------------------------------------------

    window.pdfUniversalTextColumnMapping = {

        sourceRegions:
            sourceRegions15,

        logicalColumns:
            logicalColumns15,

        assignments:
            assignments15,

        columnGroups:
            columnGroups15,

        columnStatistics:
            columnStatistics15
    };


    // --------------------------------------------------------
    // Console output
    // --------------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 15 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Text Regions:",
        sourceRegions15.length
    );

    console.log(
        "Logical Columns:",
        logicalColumns15.length
    );

    console.log(
        "Mapped Regions:",
        assignments15.length
    );

    console.log(
        "Column Statistics:"
    );

    console.table(
        columnStatistics15
    );

    console.log(
        "================================="
    );

    console.log(
        "STEP 15 COMPLETE"
    );

    console.log(
        "================================="
    );
}





// ============================================================
// STEP 16
// UNIVERSAL LOGICAL ROW + COLUMN STRUCTURE
// ============================================================

console.log("=================================");
console.log("STEP 16 START");
console.log("=================================");

const mapping16 =
    window.pdfUniversalTextColumnMapping;

const regions16 =
    window.pdfMergedTextRegions || [];

const logicalColumns16 =
    mapping16?.logicalColumns || [];

const assignments16 =
    mapping16?.assignments || [];

if (
    !mapping16 ||
    !regions16.length ||
    !assignments16.length
) {

    console.error(
        "Step 16: Step 15 data not found."
    );

} else {

    // --------------------------------------------------------
    // Build region lookup
    // --------------------------------------------------------

    const assignmentMap16 =
        new Map();

    assignments16.forEach(
        assignment => {

            assignmentMap16.set(
                assignment.regionIndex,
                assignment
            );

        }
    );


    // --------------------------------------------------------
    // Sort regions vertically
    // --------------------------------------------------------

    const sortedRegions16 =
        regions16
            .map(
                (region, index) => ({
                    region,
                    index
                })
            )
            .sort(
                (a, b) => {

                    if (
                        a.region.pageNumber !==
                        b.region.pageNumber
                    ) {

                        return (
                            a.region.pageNumber -
                            b.region.pageNumber
                        );
                    }

                    return (
                        b.region.y -
                        a.region.y
                    );

                }
            );


    // --------------------------------------------------------
    // Universal row detection
    // --------------------------------------------------------

    const rows16 = [];

    const ROW_Y_TOLERANCE = 7;


    sortedRegions16.forEach(
        item => {

            const region =
                item.region;

            let bestRow = null;

            let bestDistance =
                Infinity;


            // ----------------------------------------------
            // Find closest existing row
            // ----------------------------------------------

            for (
                const row of rows16
            ) {

                if (
                    row.pageNumber !==
                    region.pageNumber
                ) {
                    continue;
                }


                const distance =
                    Math.abs(
                        row.anchorY -
                        region.y
                    );


                if (
                    distance <=
                    ROW_Y_TOLERANCE &&
                    distance <
                    bestDistance
                ) {

                    bestDistance =
                        distance;

                    bestRow =
                        row;
                }

            }


            // ----------------------------------------------
            // Create new row
            // ----------------------------------------------

            if (!bestRow) {

                bestRow = {

                    rowIndex:
                        rows16.length,

                    pageNumber:
                        region.pageNumber,

                    anchorY:
                        region.y,

                    top:
                        region.y,

                    bottom:
                        region.y +
                        region.height,

                    regions: [],

                    columns: {},

                    regionCount: 0
                };


                rows16.push(
                    bestRow
                );
            }


            // ----------------------------------------------
            // Add region to row
            // ----------------------------------------------

            bestRow.regions.push(
                item.index
            );

            bestRow.regionCount++;


            bestRow.top =
                Math.max(
                    bestRow.top,
                    region.y
                );


            bestRow.bottom =
                Math.min(
                    bestRow.bottom,
                    region.y +
                    region.height
                );


            // Keep highest Y as row anchor
            bestRow.anchorY =
                Math.max(
                    bestRow.anchorY,
                    region.y
                );

        }
    );


    // --------------------------------------------------------
    // Sort rows top to bottom
    // --------------------------------------------------------

    rows16.sort(
        (a, b) =>
            b.anchorY -
            a.anchorY
    );


    rows16.forEach(
        (row, newIndex) => {

            row.rowIndex =
                newIndex;

        }
    );


    // --------------------------------------------------------
    // Assign regions to logical columns
    // --------------------------------------------------------

    rows16.forEach(
        row => {

            row.columns = {};


            row.regions.forEach(
                regionIndex => {

                    const assignment =
                        assignmentMap16.get(
                            regionIndex
                        );

                    if (!assignment) {
                        return;
                    }


                    const column =
                        assignment.column;


                    if (
                        !row.columns[column]
                    ) {

                        row.columns[column] = [];

                    }


                    row.columns[column]
                        .push(
                            regionIndex
                        );

                }
            );

        }
    );


    // --------------------------------------------------------
    // Calculate row geometry
    // --------------------------------------------------------

    rows16.forEach(
        row => {

            const allRegions =
                row.regions.map(
                    index =>
                        regions16[index]
                );


            const minY =
                Math.min(
                    ...allRegions.map(
                        r => r.y
                    )
                );


            const maxY =
                Math.max(
                    ...allRegions.map(
                        r =>
                            r.y +
                            r.height
                    )
                );


            row.top =
                minY;

            row.bottom =
                maxY;

            row.height =
                maxY -
                minY;


            row.columnCount =
                Object.keys(
                    row.columns
                ).length;

        }
    );


    // --------------------------------------------------------
    // Detect centered / spanning text
    // --------------------------------------------------------

    rows16.forEach(
        row => {

            row.spanningCandidates = [];


            row.regions.forEach(
                regionIndex => {

                    const region =
                        regions16[
                            regionIndex
                        ];

                    const assignment =
                        assignmentMap16.get(
                            regionIndex
                        );


                    if (!assignment) {
                        return;
                    }


                    const textCenter =
                        region.x +
                        (
                            region.width /
                            2
                        );


                    const firstColumn =
                        logicalColumns16[0];

                    const lastColumn =
                        logicalColumns16[
                            logicalColumns16.length - 1
                        ];


                    if (
                        !firstColumn ||
                        !lastColumn
                    ) {
                        return;
                    }


                    const totalLeft =
                        firstColumn.left;


                    const totalRight =
                        lastColumn.right;


                    const totalWidth =
                        totalRight -
                        totalLeft;


                    const distanceFromCenter =
                        Math.abs(
                            textCenter -
                            (
                                (
                                    totalLeft +
                                    totalRight
                                ) / 2
                            )
                        );


                    const centered =
                        distanceFromCenter <=
                        (
                            totalWidth *
                            0.15
                        );


                    const wideEnough =
                        region.width >=
                        (
                            totalWidth *
                            0.25
                        );


                    if (
                        centered &&
                        wideEnough
                    ) {

                        row.spanningCandidates
                            .push(
                                regionIndex
                            );

                    }

                }
            );

        }
    );


    // --------------------------------------------------------
    // Build readable row summary
    // --------------------------------------------------------

    const rowSummary16 =
        rows16.map(
            row => {

                const columnTexts = [];


                for (
                    let columnIndex = 0;
                    columnIndex <
                    logicalColumns16.length;
                    columnIndex++
                ) {

                    const indexes =
                        row.columns[
                            columnIndex
                        ] || [];


                    const text =
                        indexes
                            .map(
                                index =>
                                    regions16[
                                        index
                                    ].text
                            )
                            .join(" | ");


                    columnTexts.push(
                        text
                    );

                }


                return {

                    row:
                        row.rowIndex,

                    y:
                        Number(
                            row.anchorY.toFixed(2)
                        ),

                    height:
                        Number(
                            row.height.toFixed(2)
                        ),

                    columns:
                        row.columnCount,

                    col0:
                        columnTexts[0] || "",

                    col1:
                        columnTexts[1] || "",

                    col2:
                        columnTexts[2] || "",

                    spanning:
                        row.spanningCandidates.length

                };

            }
        );


    // --------------------------------------------------------
    // Save Step 16 model
    // --------------------------------------------------------

    window.pdfUniversalLogicalRows = {

        rows:
            rows16,

        rowSummary:
            rowSummary16,

        logicalColumns:
            logicalColumns16,

        assignments:
            assignments16,

        regionLookup:
            assignmentMap16
    };


    // --------------------------------------------------------
    // Console output
    // --------------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 16 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Regions:",
        regions16.length
    );

    console.log(
        "Logical Columns:",
        logicalColumns16.length
    );

    console.log(
        "Logical Rows:",
        rows16.length
    );

    console.log(
        "Row Summary:"
    );

    console.table(
        rowSummary16
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 16 COMPLETE"
    );

    console.log(
        "================================="
    );
}






// ============================================================
// STEP 17
// UNIVERSAL SMART ROW CONSOLIDATION
// ============================================================

console.log("=================================");
console.log("STEP 17 START");
console.log("=================================");

const model17 =
    window.pdfUniversalLogicalRows;

const regions17 =
    window.pdfMergedTextRegions || [];

const assignments17 =
    model17?.assignments || [];

const logicalColumns17 =
    model17?.logicalColumns || [];

if (
    !model17 ||
    !regions17.length ||
    !assignments17.length
) {

    console.error(
        "Step 17: Step 16 data not found."
    );

} else {

    // --------------------------------------------------------
    // Configuration
    // --------------------------------------------------------

    const MAX_VERTICAL_GAP = 18;
    const SAME_ROW_GAP = 14;
    const COLUMN_SEPARATION = 25;


    // --------------------------------------------------------
    // Assignment lookup
    // --------------------------------------------------------

    const assignmentMap17 =
        new Map();

    assignments17.forEach(
        item => {

            assignmentMap17.set(
                item.regionIndex,
                item
            );

        }
    );


    // --------------------------------------------------------
    // Sort source regions top -> bottom
    // --------------------------------------------------------

    const sorted17 =
        regions17
            .map(
                (region, index) => ({
                    region,
                    index
                })
            )
            .sort(
                (a, b) => {

                    if (
                        a.region.pageNumber !==
                        b.region.pageNumber
                    ) {

                        return (
                            a.region.pageNumber -
                            b.region.pageNumber
                        );
                    }

                    return (
                        b.region.y -
                        a.region.y
                    );

                }
            );


    // --------------------------------------------------------
    // Initial rows
    // --------------------------------------------------------

    const initialRows17 = [];


    sorted17.forEach(
        item => {

            const region =
                item.region;

            const assignment =
                assignmentMap17.get(
                    item.index
                );

            const column =
                assignment
                    ? assignment.column
                    : -1;


            let bestRow = null;
            let bestScore = -Infinity;


            // ------------------------------------------------
            // Compare with existing rows
            // ------------------------------------------------

            initialRows17.forEach(
                row => {

                    if (
                        row.pageNumber !==
                        region.pageNumber
                    ) {
                        return;
                    }


                    const rowBottom =
                        Math.min(
                            ...row.regions.map(
                                index =>
                                    regions17[
                                        index
                                    ].y +
                                    regions17[
                                        index
                                    ].height
                            )
                        );


                    const verticalGap =
                        row.anchorY -
                        region.y;


                    if (
                        verticalGap < 0 ||
                        verticalGap >
                        MAX_VERTICAL_GAP
                    ) {
                        return;
                    }


                    let score = 0;


                    // ----------------------------------------
                    // Strong same-column continuation
                    // ----------------------------------------

                    if (
                        row.columns.includes(
                            column
                        )
                    ) {

                        score += 45;

                    }


                    // ----------------------------------------
                    // Different column can still be same row
                    // ----------------------------------------

                    if (
                        !row.columns.includes(
                            column
                        )
                    ) {

                        score += 20;

                    }


                    // ----------------------------------------
                    // Vertical proximity
                    // ----------------------------------------

                    if (
                        verticalGap <= 5
                    ) {

                        score += 50;

                    } else if (
                        verticalGap <= 9
                    ) {

                        score += 40;

                    } else if (
                        verticalGap <= 14
                    ) {

                        score += 25;

                    } else {

                        score += 10;

                    }


                    // ----------------------------------------
                    // Check horizontal relationship
                    // ----------------------------------------

                    const regionLeft =
                        region.x;

                    const regionRight =
                        region.x +
                        region.width;


                    const horizontalMatch =
                        row.regions.some(
                            existingIndex => {

                                const existing =
                                    regions17[
                                        existingIndex
                                    ];

                                const existingLeft =
                                    existing.x;

                                const existingRight =
                                    existing.x +
                                    existing.width;


                                const overlap =
                                    Math.max(
                                        0,
                                        Math.min(
                                            regionRight,
                                            existingRight
                                        ) -
                                        Math.max(
                                            regionLeft,
                                            existingLeft
                                        )
                                    );


                                return (
                                    overlap > 0
                                );

                            }
                        );


                    if (
                        horizontalMatch
                    ) {

                        score += 15;

                    }


                    // ----------------------------------------
                    // Prefer closest row
                    // ----------------------------------------

                    score -=
                        verticalGap;


                    if (
                        score >
                        bestScore
                    ) {

                        bestScore =
                            score;

                        bestRow =
                            row;
                    }

                }
            );


            // ------------------------------------------------
            // Create new row if no suitable row
            // ------------------------------------------------

            if (
                !bestRow ||
                bestScore < 20
            ) {

                bestRow = {

                    pageNumber:
                        region.pageNumber,

                    anchorY:
                        region.y,

                    regions: [],

                    columns: [],

                    minY:
                        region.y,

                    maxY:
                        region.y +
                        region.height

                };


                initialRows17.push(
                    bestRow
                );

            }


            // ------------------------------------------------
            // Add region
            // ------------------------------------------------

            bestRow.regions.push(
                item.index
            );


            if (
                !bestRow.columns.includes(
                    column
                )
            ) {

                bestRow.columns.push(
                    column
                );

            }


            bestRow.anchorY =
                Math.max(
                    bestRow.anchorY,
                    region.y
                );


            bestRow.minY =
                Math.min(
                    bestRow.minY,
                    region.y
                );


            bestRow.maxY =
                Math.max(
                    bestRow.maxY,
                    region.y +
                    region.height
                );

        }
    );


    // --------------------------------------------------------
    // Sort rows
    // --------------------------------------------------------

    initialRows17.sort(
        (a, b) =>
            b.anchorY -
            a.anchorY
    );


    // --------------------------------------------------------
    // Build final rows
    // --------------------------------------------------------

    const finalRows17 =
        initialRows17.map(
            (row, index) => {

                const columns = {};


                row.regions.forEach(
                    regionIndex => {

                        const assignment =
                            assignmentMap17.get(
                                regionIndex
                            );

                        if (!assignment) {
                            return;
                        }


                        const column =
                            assignment.column;


                        if (
                            !columns[column]
                        ) {

                            columns[column] = [];

                        }


                        columns[column]
                            .push(
                                regionIndex
                            );

                    }
                );


                const texts = [];


                for (
                    let columnIndex = 0;
                    columnIndex <
                    logicalColumns17.length;
                    columnIndex++
                ) {

                    const indexes =
                        columns[
                            columnIndex
                        ] || [];


                    // Sort text inside column
                    indexes.sort(
                        (a, b) =>
                            regions17[b].y -
                            regions17[a].y
                    );


                    texts.push(
                        indexes
                            .map(
                                regionIndex =>
                                    regions17[
                                        regionIndex
                                    ].text
                            )
                            .join(" ")
                    );

                }


                return {

                    rowIndex:
                        index,

                    pageNumber:
                        row.pageNumber,

                    y:
                        Number(
                            row.anchorY.toFixed(2)
                        ),

                    top:
                        Number(
                            row.minY.toFixed(2)
                        ),

                    bottom:
                        Number(
                            row.maxY.toFixed(2)
                        ),

                    height:
                        Number(
                            (
                                row.maxY -
                                row.minY
                            ).toFixed(2)
                        ),

                    regionCount:
                        row.regions.length,

                    columnCount:
                        row.columns.length,

                    col0:
                        texts[0] || "",

                    col1:
                        texts[1] || "",

                    col2:
                        texts[2] || "",

                    regionIndexes:
                        [...row.regions]

                };

            }
        );


    // --------------------------------------------------------
    // Detect spanning candidates
    // --------------------------------------------------------

    finalRows17.forEach(
        row => {

            row.spanningCandidates = [];


            row.regionIndexes.forEach(
                regionIndex => {

                    const region =
                        regions17[
                            regionIndex
                        ];


                    const center =
                        region.x +
                        (
                            region.width /
                            2
                        );


                    const firstColumn =
                        logicalColumns17[0];

                    const lastColumn =
                        logicalColumns17[
                            logicalColumns17.length - 1
                        ];


                    if (
                        !firstColumn ||
                        !lastColumn
                    ) {
                        return;
                    }


                    const pageLeft =
                        firstColumn.left;


                    const pageRight =
                        lastColumn.right;


                    const pageWidth =
                        pageRight -
                        pageLeft;


                    const pageCenter =
                        (
                            pageLeft +
                            pageRight
                        ) / 2;


                    const centerDistance =
                        Math.abs(
                            center -
                            pageCenter
                        );


                    const centered =
                        centerDistance <=
                        pageWidth * 0.15;


                    const wide =
                        region.width >=
                        pageWidth * 0.25;


                    if (
                        centered &&
                        wide
                    ) {

                        row.spanningCandidates
                            .push(
                                regionIndex
                            );

                    }

                }
            );

        }
    );


    // --------------------------------------------------------
    // Final readable summary
    // --------------------------------------------------------

    const summary17 =
        finalRows17.map(
            row => ({

                row:
                    row.rowIndex + 1,

                y:
                    row.y,

                height:
                    row.height,

                regions:
                    row.regionCount,

                columns:
                    row.columnCount,

                col0:
                    row.col0,

                col1:
                    row.col1,

                col2:
                    row.col2,

                spanning:
                    row.spanningCandidates.length

            })
        );


    // --------------------------------------------------------
    // Save model
    // --------------------------------------------------------

    window.pdfUniversalSmartRows = {

        rows:
            finalRows17,

        summary:
            summary17,

        logicalColumns:
            logicalColumns17,

        assignments:
            assignments17,

        regions:
            regions17

    };


    // --------------------------------------------------------
    // Output
    // --------------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 17 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Regions:",
        regions17.length
    );

    console.log(
        "Logical Columns:",
        logicalColumns17.length
    );

    console.log(
        "Smart Logical Rows:",
        finalRows17.length
    );

    console.log(
        "Row Summary:"
    );

    console.table(
        summary17
    );

    console.log(
        "================================="
    );

    console.log(
        "STEP 17 COMPLETE"
    );

    console.log(
        "================================="
    );
}





// ============================================================
// STEP 18
// UNIVERSAL ROW REFINEMENT
