console.log("=================================");
console.log("STEP 18 START");
console.log("=================================");

const smartRows18 =
    window.pdfUniversalSmartRows;

const regions18 =
    window.pdfMergedTextRegions || [];

const assignments18 =
    smartRows18?.assignments || [];

const columns18 =
    smartRows18?.logicalColumns || [];

if (
    !smartRows18 ||
    !regions18.length ||
    !assignments18.length
) {

    console.error(
        "Step 18: Step 17 data not found."
    );

} else {

    // --------------------------------------------------------
    // Configuration
    // --------------------------------------------------------

    const SAME_BASELINE_TOLERANCE = 5;

    const CONTINUATION_GAP_MIN = 5;

    const CONTINUATION_GAP_MAX = 18;


    // --------------------------------------------------------
    // Assignment lookup
    // --------------------------------------------------------

    const assignmentMap18 =
        new Map();

    assignments18.forEach(
        item => {

            assignmentMap18.set(
                item.regionIndex,
                item
            );

        }
    );


    // --------------------------------------------------------
    // Sort source regions
    // --------------------------------------------------------

    const sorted18 =
        regions18
            .map(
                (region, index) => ({
                    region,
                    index
                })
            )
            .sort(
                (a, b) => {

                    if (
                        a.region.pageNumber !==
                        b.region.pageNumber
                    ) {

                        return (
                            a.region.pageNumber -
                            b.region.pageNumber
                        );

                    }

                    return (
                        b.region.y -
                        a.region.y
                    );

                }
            );


    // --------------------------------------------------------
    // Initial independent rows
    // --------------------------------------------------------

    const rows18 = [];


    sorted18.forEach(
        item => {

            const region =
                item.region;

            const assignment =
                assignmentMap18.get(
                    item.index
                );


            rows18.push({

                pageNumber:
                    region.pageNumber,

                anchorY:
                    region.y,

                regions: [
                    item.index
                ],

                columns: [
                    assignment
                        ? assignment.column
                        : -1
                ]

            });

        }
    );


    // --------------------------------------------------------
    // Determine whether two regions belong to same row
    // --------------------------------------------------------

    function sameLogicalRow18(
        regionA,
        regionB,
        columnA,
        columnB
    ) {

        // ----------------------------------------------------
        // Same baseline
        // ----------------------------------------------------

        const baselineDifference =
            Math.abs(
                regionA.y -
                regionB.y
            );


        if (
            baselineDifference <=
            SAME_BASELINE_TOLERANCE
        ) {

            return true;

        }


        // ----------------------------------------------------
        // Different vertical position
        // ----------------------------------------------------

        const upper =
            regionA.y >
            regionB.y
                ? regionA
                : regionB;

        const lower =
            regionA.y >
            regionB.y
                ? regionB
                : regionA;


        const gap =
            upper.y -
            (
                lower.y +
                lower.height
            );


        // ----------------------------------------------------
        // Same column continuation
        // ----------------------------------------------------

        if (
            columnA === columnB &&
            gap >= CONTINUATION_GAP_MIN &&
            gap <= CONTINUATION_GAP_MAX
        ) {

            return true;

        }


        // ----------------------------------------------------
        // Never combine different columns merely because
        // their Y positions are close.
        // ----------------------------------------------------

        if (
            columnA !== columnB
        ) {

            return false;

        }


        return false;

    }


    // --------------------------------------------------------
    // Merge only genuinely same logical rows
    // --------------------------------------------------------

    let changed = true;


    while (changed) {

        changed = false;


        outerLoop:

        for (
            let i = 0;
            i < rows18.length;
            i++
        ) {

            for (
                let j = i + 1;
                j < rows18.length;
                j++
            ) {

                const rowA =
                    rows18[i];

                const rowB =
                    rows18[j];


                if (
                    rowA.pageNumber !==
                    rowB.pageNumber
                ) {

                    continue;

                }


                let canMerge = false;


                // ------------------------------------------------
                // Compare every region pair
                // ------------------------------------------------

                for (
                    const indexA
                    of rowA.regions
                ) {

                    for (
                        const indexB
                        of rowB.regions
                    ) {

                        const regionA =
                            regions18[
                                indexA
                            ];

                        const regionB =
                            regions18[
                                indexB
                            ];


                        const assignmentA =
                            assignmentMap18.get(
                                indexA
                            );

                        const assignmentB =
                            assignmentMap18.get(
                                indexB
                            );


                        const columnA =
                            assignmentA
                                ? assignmentA.column
                                : -1;

                        const columnB =
                            assignmentB
                                ? assignmentB.column
                                : -1;


                        if (
                            sameLogicalRow18(
                                regionA,
                                regionB,
                                columnA,
                                columnB
                            )
                        ) {

                            canMerge = true;

                            break;

                        }

                    }


                    if (canMerge) {
                        break;
                    }

                }


                if (!canMerge) {
                    continue;
                }


                // ------------------------------------------------
                // Merge row B into row A
                // ------------------------------------------------

                rowA.regions.push(
                    ...rowB.regions
                );


                rowA.columns.push(
                    ...rowB.columns
                );


                rowA.columns =
                    [
                        ...new Set(
                            rowA.columns
                        )
                    ];


                rowA.anchorY =
                    Math.max(
                        rowA.anchorY,
                        rowB.anchorY
                    );


                rows18.splice(
                    j,
                    1
                );


                changed = true;

                break outerLoop;

            }

        }

    }


    // --------------------------------------------------------
    // Sort final rows top -> bottom
    // --------------------------------------------------------

    rows18.sort(
        (a, b) =>
            b.anchorY -
            a.anchorY
    );


    // --------------------------------------------------------
    // Build final row objects
    // --------------------------------------------------------

    const finalRows18 =
        rows18.map(
            (row, index) => {

                const columns = {};


                row.regions.forEach(
                    regionIndex => {

                        const assignment =
                            assignmentMap18.get(
                                regionIndex
                            );


                        if (!assignment) {
                            return;
                        }


                        const column =
                            assignment.column;


                        if (
                            !columns[column]
                        ) {

                            columns[column] = [];

                        }


                        columns[column]
                            .push(
                                regionIndex
                            );

                    }
                );


                // --------------------------------------------
                // Sort regions inside each column
                // --------------------------------------------

                Object.keys(
                    columns
                ).forEach(
                    column => {

                        columns[column]
                            .sort(
                                (a, b) =>
                                    regions18[b].y -
                                    regions18[a].y
                            );

                    }
                );


                const texts = [];


                for (
                    let c = 0;
                    c < columns18.length;
                    c++
                ) {

                    const indexes =
                        columns[c] || [];


                    texts.push(
                        indexes
                            .map(
                                regionIndex =>
                                    regions18[
                                        regionIndex
                                    ].text
                            )
                            .join(" ")
                    );

                }


                const allRegions =
                    row.regions.map(
                        index =>
                            regions18[index]
                    );


                const top =
                    Math.min(
                        ...allRegions.map(
                            r => r.y
                        )
                    );


                const bottom =
                    Math.max(
                        ...allRegions.map(
                            r =>
                                r.y +
                                r.height
                        )
                    );


                return {

                    rowIndex:
                        index,

                    pageNumber:
                        row.pageNumber,

                    y:
                        Number(
                            row.anchorY.toFixed(2)
                        ),

                    top:
                        Number(
                            top.toFixed(2)
                        ),

                    bottom:
                        Number(
                            bottom.toFixed(2)
                        ),

                    height:
                        Number(
                            (
                                bottom -
                                top
                            ).toFixed(2)
                        ),

                    regionCount:
                        row.regions.length,

                    columnCount:
                        Object.keys(
                            columns
                        ).length,

                    col0:
                        texts[0] || "",

                    col1:
                        texts[1] || "",

                    col2:
                        texts[2] || "",

                    regionIndexes:
                        [...row.regions]

                };

            }
        );


    // --------------------------------------------------------
    // Save model
    // --------------------------------------------------------

    window.pdfUniversalRefinedRows = {

        rows:
            finalRows18,

        logicalColumns:
            columns18,

        assignments:
            assignments18,

        regions:
            regions18

    };


    // --------------------------------------------------------
    // Console output
    // --------------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 18 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Regions:",
        regions18.length
    );

    console.log(
        "Logical Columns:",
        columns18.length
    );

    console.log(
        "Refined Logical Rows:",
        finalRows18.length
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 18 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 18.1 START");
console.log("=================================");

const sourceRows181 =
    window.pdfUniversalRefinedRows?.rows || [];

const sourceRegions181 =
    window.pdfMergedTextRegions || [];

const assignments181 =
    window.pdfUniversalRefinedRows?.assignments || [];

const logicalColumns181 =
    window.pdfUniversalRefinedRows?.logicalColumns || [];

console.log("Input Rows:", sourceRows181.length);
console.log("Source Regions:", sourceRegions181.length);
console.log("Logical Columns:", logicalColumns181.length);


// --------------------------------------------------
// STEP 18.1A
// Build region information
// --------------------------------------------------

const regionMap181 = new Map();

sourceRegions181.forEach((region, index) => {

    const assignment =
        assignments181.find(a =>
            a.regionIndex === index
        );

    const column =
        assignment?.column ?? 0;

    regionMap181.set(index, {
        ...region,
        regionIndex: index,
        column: column
    });

});


// --------------------------------------------------
// STEP 18.1B
// Flatten all regions from current rows
// --------------------------------------------------

const allRegions181 = [];

sourceRows181.forEach(row => {

    if (!row.regionIndices) return;

    row.regionIndices.forEach(index => {

        const region =
            regionMap181.get(index);

        if (region) {
            allRegions181.push(region);
        }

    });

});


// Fallback if regionIndices are unavailable
if (allRegions181.length === 0) {

    sourceRegions181.forEach((region, index) => {

        const assignment =
            assignments181.find(a =>
                a.regionIndex === index
            );

        allRegions181.push({
            ...region,
            regionIndex: index,
            column: assignment?.column ?? 0
        });

    });

}


// --------------------------------------------------
// STEP 18.1C
// Sort by vertical position
// --------------------------------------------------

allRegions181.sort((a, b) => {

    if (a.pageNumber !== b.pageNumber) {
        return a.pageNumber - b.pageNumber;
    }

    if (Math.abs(a.y - b.y) <= 3) {
        return a.x - b.x;
    }

    return b.y - a.y;

});


// --------------------------------------------------
// STEP 18.1D
// Precision row rules
// --------------------------------------------------

const BASELINE_TOLERANCE_181 = 5;

const ADDRESS_GAP_MAX_181 = 16;

const MAX_VERTICAL_MERGE_181 = 18;


// --------------------------------------------------
// Helper: same baseline
// --------------------------------------------------

function sameBaseline181(a, b) {

    return Math.abs(a.y - b.y)
        <= BASELINE_TOLERANCE_181;

}


// --------------------------------------------------
// Helper: vertical continuation
// --------------------------------------------------

function verticalGap181(upper, lower) {

    return Math.abs(
        upper.y - (lower.y + lower.height)
    );

}


// --------------------------------------------------
// Helper: horizontal overlap
// --------------------------------------------------

function horizontalOverlap181(a, b) {

    const left =
        Math.max(a.x, b.x);

    const right =
        Math.min(
            a.x + a.width,
            b.x + b.width
        );

    return Math.max(0, right - left);

}


// --------------------------------------------------
// Helper: should merge two regions?
// --------------------------------------------------

function shouldMerge181(currentRow, region) {

    if (!currentRow.regions.length) {
        return false;
    }


    // ----------------------------------------------
    // Rule 1:
    // Same baseline = same logical row
    // ----------------------------------------------

    for (const existing of currentRow.regions) {

        if (
            existing.pageNumber === region.pageNumber &&
            sameBaseline181(existing, region)
        ) {

            return true;

        }

    }


    // ----------------------------------------------
    // Rule 2:
    // Same column continuation
    // ----------------------------------------------

    for (const existing of currentRow.regions) {

        if (
            existing.pageNumber !== region.pageNumber
        ) {
            continue;
        }

        if (
            existing.column !== region.column
        ) {
            continue;
        }


        const upper =
            existing.y > region.y
                ? existing
                : region;

        const lower =
            existing.y > region.y
                ? region
                : existing;


        const gap =
            verticalGap181(upper, lower);


        if (
            gap >= 0 &&
            gap <= ADDRESS_GAP_MAX_181
        ) {

            // Only merge if there is reasonable
            // horizontal relationship.

            const overlap =
                horizontalOverlap181(
                    existing,
                    region
                );

            const centerExisting =
                existing.x +
                existing.width / 2;

            const centerRegion =
                region.x +
                region.width / 2;

            const centerDistance =
                Math.abs(
                    centerExisting -
                    centerRegion
                );


            if (
                overlap > 0 ||
                centerDistance < 120
            ) {

                return true;

            }

        }

    }


    // ----------------------------------------------
    // Rule 3:
    // Different columns + different baseline
    // NEVER merge automatically.
    // ----------------------------------------------

    return false;

}


// --------------------------------------------------
// STEP 18.1E
// Build precise rows
// --------------------------------------------------

const refinedRows181 = [];

allRegions181.forEach(region => {

    let targetRow = null;


    // Search only recent rows.
    // This prevents distant content from merging.

    for (
        let i = refinedRows181.length - 1;
        i >= Math.max(0, refinedRows181.length - 3);
        i--
    ) {

        const row =
            refinedRows181[i];


        if (
            row.pageNumber !== region.pageNumber
        ) {
            continue;
        }


        if (
            shouldMerge181(row, region)
        ) {

            targetRow = row;
            break;

        }

    }


    // ----------------------------------------------
    // Create new row
    // ----------------------------------------------

    if (!targetRow) {

        targetRow = {

            rowIndex:
                refinedRows181.length,

            pageNumber:
                region.pageNumber,

            y:
                region.y,

            regions: [],

            regionIndices: [],

            col0: "",
            col1: "",
            col2: "",

            span: false

        };

        refinedRows181.push(targetRow);

    }


    targetRow.regions.push(region);

    targetRow.regionIndices.push(
        region.regionIndex
    );

});


// --------------------------------------------------
// STEP 18.1F
// Sort regions inside each row by column / X
// --------------------------------------------------

refinedRows181.forEach(row => {

    row.regions.sort((a, b) => {

        if (a.column !== b.column) {
            return a.column - b.column;
        }

        return a.x - b.x;

    });


    // Reset columns

    row.col0 = "";
    row.col1 = "";
    row.col2 = "";


    row.regions.forEach(region => {

        const column =
            Math.max(
                0,
                Math.min(2, region.column)
            );

        if (row["col" + column]) {

            row["col" + column] +=
                " " + region.text;

        } else {

            row["col" + column] =
                region.text;

        }

    });


    row.regionCount =
        row.regions.length;


    // ----------------------------------------------
    // Span detection
    // ----------------------------------------------

    const usedColumns =
        new Set(
            row.regions.map(
                r => r.column
            )
        );


    row.span =
        usedColumns.size >= 2 &&
        row.regions.length === 1;

});


// --------------------------------------------------
// STEP 18.1G
// Re-index rows
// --------------------------------------------------

refinedRows181.forEach((row, index) => {

    row.rowIndex = index;

});


// --------------------------------------------------
// STEP 18.1H
// Save result
// --------------------------------------------------

window.pdfUniversalPrecisionRows = {

    rows: refinedRows181,

    logicalColumns:
        logicalColumns181,

    assignments:
        assignments181,

    regions:
        sourceRegions181

};


