console.log("=================================");
console.log("STEP 18.2 START");
console.log("=================================");

const regions182 =
    window.pdfMergedTextRegions || [];

const mapping182 =
    window.pdfUniversalTextColumnMapping || {};

const logicalColumns182 =
    window.pdfUniversalLogicalTextColumns?.columns || [];

console.log(
    "Source Regions:",
    regions182.length
);

console.log(
    "Logical Columns:",
    logicalColumns182.length
);


// --------------------------------------------------
// Get column assignment
// --------------------------------------------------

function getColumn182(region, index) {

    const assignment =
        mapping182.assignments?.find(
            a => a.regionIndex === index
        );

    if (
        assignment &&
        Number.isFinite(assignment.column)
    ) {
        return assignment.column;
    }

    return 0;
}


// --------------------------------------------------
// Prepare regions
// --------------------------------------------------

const prepared182 =
    regions182.map((region, index) => {

        return {
            ...region,
            regionIndex: index,
            column: getColumn182(region, index),
            centerX:
                region.x +
                region.width / 2,
            centerY:
                region.y +
                region.height / 2
        };

    });


// --------------------------------------------------
// Sort top → bottom
// --------------------------------------------------

prepared182.sort((a, b) => {

    if (
        a.pageNumber !==
        b.pageNumber
    ) {
        return a.pageNumber -
            b.pageNumber;
    }

    if (
        Math.abs(a.y - b.y) <= 3
    ) {
        return a.x - b.x;
    }

    return b.y - a.y;

});


// --------------------------------------------------
// Configuration
// --------------------------------------------------

// Text on exactly the same baseline
const BASELINE_TOLERANCE_182 = 4;

// Maximum gap for a genuine
// same-column continuation line
const CONTINUATION_MAX_GAP_182 = 14;

// Minimum horizontal similarity
// required for continuation
const CENTER_DISTANCE_LIMIT_182 = 45;


// --------------------------------------------------
// Same baseline
// --------------------------------------------------

function isSameBaseline182(a, b) {

    return Math.abs(
        a.y - b.y
    ) <= BASELINE_TOLERANCE_182;

}


// --------------------------------------------------
// Vertical gap
// --------------------------------------------------

function getVerticalGap182(a, b) {

    const upper =
        a.y >= b.y
            ? a
            : b;

    const lower =
        a.y >= b.y
            ? b
            : a;

    return Math.max(
        0,
        upper.y -
        (
            lower.y +
            lower.height
        )
    );

}


// --------------------------------------------------
// Same-column continuation
// --------------------------------------------------

function isContinuation182(a, b) {

    if (
        a.column !== b.column
    ) {
        return false;
    }


    if (
        isSameBaseline182(a, b)
    ) {
        return false;
    }


    const gap =
        getVerticalGap182(a, b);


    if (
        gap > CONTINUATION_MAX_GAP_182
    ) {
        return false;
    }


    const centerDistance =
        Math.abs(
            a.centerX -
            b.centerX
        );


    if (
        centerDistance <=
        CENTER_DISTANCE_LIMIT_182
    ) {
        return true;
    }


    // If the second line starts
    // inside the first text region
    const horizontalOverlap =
        Math.max(
            0,
            Math.min(
                a.x + a.width,
                b.x + b.width
            ) -
            Math.max(
                a.x,
                b.x
            )
        );


    return horizontalOverlap > 10;

}


// --------------------------------------------------
// Build initial rows
// --------------------------------------------------

const rows182 = [];

prepared182.forEach(region => {

    let target = null;


    // ----------------------------------------------
    // First priority:
    // same baseline
    // ----------------------------------------------

    for (
        let i = rows182.length - 1;
        i >= Math.max(
            0,
            rows182.length - 5
        );
        i--
    ) {

        const row =
            rows182[i];


        const sameBaseline =
            row.regions.some(
                existing =>
                    isSameBaseline182(
                        existing,
                        region
                    )
            );


        if (sameBaseline) {

            target = row;
            break;

        }

    }


    // ----------------------------------------------
    // Second priority:
    // continuation line
    // ----------------------------------------------

    if (!target) {

        for (
            let i = rows182.length - 1;
            i >= Math.max(
                0,
                rows182.length - 3
            );
            i--
        ) {

            const row =
                rows182[i];


            const continuation =
                row.regions.some(
                    existing =>
                        isContinuation182(
                            existing,
                            region
                        )
                );


            if (continuation) {

                target = row;
                break;

            }

        }

    }


    // ----------------------------------------------
    // New row
    // ----------------------------------------------

    if (!target) {

        target = {

            pageNumber:
                region.pageNumber,

            y:
                region.y,

            regions: [],

            regionIndices: []

        };

        rows182.push(target);

    }


    target.regions.push(region);

    target.regionIndices.push(
        region.regionIndex
    );

});


// --------------------------------------------------
// Sort regions inside rows
// --------------------------------------------------

rows182.forEach(row => {

    row.regions.sort((a, b) => {

        if (
            a.column !== b.column
        ) {
            return a.column -
                b.column;
        }

        return a.x - b.x;

    });

});


// --------------------------------------------------
// Build final logical rows
// --------------------------------------------------

const finalRows182 =
    rows182.map(
        (row, rowIndex) => {

            const result = {

                rowIndex,

                pageNumber:
                    row.pageNumber,

                y:
                    row.y,

                col0: "",
                col1: "",
                col2: "",

                regions:
                    row.regions,

                regionIndices:
                    row.regionIndices,

                regionCount:
                    row.regions.length,

                span: false

            };


            // --------------------------------------
            // Put text into logical columns
            // --------------------------------------

            row.regions.forEach(region => {

                const column =
                    Math.max(
                        0,
                        Math.min(
                            2,
                            region.column
                        )
                    );

                const key =
                    "col" + column;


                if (
                    result[key]
                ) {

                    result[key] +=
                        " " +
                        region.text;

                } else {

                    result[key] =
                        region.text;

                }

            });


            // --------------------------------------
            // Span candidate
            // --------------------------------------

            const usedColumns =
                new Set(
                    row.regions.map(
                        r => r.column
                    )
                );


            result.span =
                usedColumns.size >= 2 &&
                row.regions.length === 1;


            return result;

        }
    );


// --------------------------------------------------
// Save
// --------------------------------------------------

window.pdfUniversalBaselineRows = {

    rows:
        finalRows182,

    logicalColumns:
        logicalColumns182,

    regions:
        regions182

};


// --------------------------------------------------
// Result
// --------------------------------------------------

console.log("=================================");
console.log("STEP 18.2 RESULT");
console.log("=================================");

console.log(
    "Source Regions:",
    regions182.length
);

console.log(
    "Logical Columns:",
    logicalColumns182.length
);

console.log(
    "Baseline Logical Rows:",
    finalRows182.length
);

console.log("=================================");
console.log("STEP 18.2 COMPLETE");
