console.log("=================================");
console.log("STEP 18.5 START");
console.log("=================================");

const borders185 =
    window.pdfReconstructedBorders;

if (!borders185?.horizontal?.positions) {

    console.error(
        "Horizontal border data not found."
    );

} else {

    const raw185 =
        borders185.horizontal.positions;


    // ----------------------------------------------
    // Extract Y positions
    // ----------------------------------------------

    const yValues185 =
        raw185
            .map(item => {

                if (
                    typeof item === "number"
                ) {
                    return item;
                }

                return (
                    item.y ??
                    item.position ??
                    item.value ??
                    item.minY ??
                    item.maxY
                );

            })
            .filter(
                y => Number.isFinite(
                    Number(y)
                )
            )
            .map(
                y => Number(y)
            )
            .sort(
                (a, b) => a - b
            );


    console.log(
        "Raw Horizontal Positions:",
        yValues185.length
    );


    // ----------------------------------------------
    // Pair nearby lines
    // ----------------------------------------------

    const PAIR_TOLERANCE_185 = 3;


    const logicalBoundaries185 = [];

    let i = 0;


    while (
        i < yValues185.length
    ) {

        const current =
            yValues185[i];

        const next =
            yValues185[i + 1];


        // ------------------------------------------
        // Two close lines = one real border
        // ------------------------------------------

        if (
            next !== undefined &&
            Math.abs(
                next - current
            ) <= PAIR_TOLERANCE_185
        ) {

            logicalBoundaries185.push({

                y:
                    Number(
                        (
                            current +
                            next
                        ) / 2
                    ),

                top:
                    current,

                bottom:
                    next,

                thickness:
                    Number(
                        (
                            next -
                            current
                        ).toFixed(2)
                    ),

                sourceCount: 2,

                type: "paired"

            });


            i += 2;

        } else {

            // --------------------------------------
            // Single legitimate boundary
            // --------------------------------------

            logicalBoundaries185.push({

                y:
                    Number(
                        current.toFixed(2)
                    ),

                top:
                    current,

                bottom:
                    current,

                thickness: 0,

                sourceCount: 1,

                type: "single"

            });


            i++;

        }

    }


    // ----------------------------------------------
    // Remove accidental duplicate logical
    // boundaries
    // ----------------------------------------------

    const FINAL_TOLERANCE_185 = 1.5;

    const cleaned185 = [];


    logicalBoundaries185.forEach(
        boundary => {

            const last =
                cleaned185[
                    cleaned185.length - 1
                ];


            if (
                !last ||
                Math.abs(
                    last.y -
                    boundary.y
                ) > FINAL_TOLERANCE_185
            ) {

                cleaned185.push(
                    boundary
                );

            } else {

                // Keep the stronger boundary

                if (
                    boundary.sourceCount >
                    last.sourceCount
                ) {

                    cleaned185[
                        cleaned185.length - 1
                    ] = boundary;

                }

            }

        }
    );


    // ----------------------------------------------
    // Save
    // ----------------------------------------------

    window.pdfUniversalHorizontalBoundaries = {

        rawPositions:
            yValues185,

        boundaries:
            cleaned185

    };


    // ----------------------------------------------
    // Result
    // ----------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 18.5 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Raw Positions:",
        yValues185.length
    );

    console.log(
        "Logical Boundaries:",
        cleaned185.length
    );

    console.log(
        "================================="
    );


    console.table(
        cleaned185.map(
            (b, index) => ({

                index: index,

                y: b.y,

                type: b.type,

                sourceCount:
                    b.sourceCount,

                thickness:
                    b.thickness

            })
        )
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 18.5 COMPLETE"
    );

    console.log(
        "================================="
    );

}




console.log("=================================");
console.log("STEP 19 START");
console.log("=================================");

const horizontal19 =
    window.pdfUniversalHorizontalBoundaries;

const textRegions19 =
    window.pdfMergedTextRegions;

if (
    !horizontal19?.boundaries ||
    !textRegions19
) {

    console.error(
        "Step 18.5 data or text regions not found."
    );

} else {

    const boundaries19 =
        horizontal19.boundaries;

    const regions19 =
        [...textRegions19].sort(
            (a, b) => {

                if (
                    a.pageNumber !==
                    b.pageNumber
                ) {
                    return (
                        a.pageNumber -
                        b.pageNumber
                    );
                }

                return b.y - a.y;

            }
        );


    // ------------------------------------------------
    // PDF coordinate system:
    // Higher Y = higher on page
    // ------------------------------------------------

    const alignedRegions19 =
        regions19.map(
            region => {

                let nearestBoundary = null;

                let nearestDistance =
                    Infinity;


                boundaries19.forEach(
                    boundary => {

                        const distance =
                            Math.min(

                                Math.abs(
                                    region.y -
                                    boundary.y
                                ),

                                Math.abs(
                                    region.bottom -
                                    boundary.y
                                ),

                                Math.abs(
                                    region.y +
                                    region.height / 2 -
                                    boundary.y
                                )

                            );


                        if (
                            distance <
                            nearestDistance
                        ) {

                            nearestDistance =
                                distance;

                            nearestBoundary =
                                boundary;

                        }

                    }
                );


                return {

                    ...region,

                    nearestBoundaryY:
                        nearestBoundary
                            ? nearestBoundary.y
                            : null,

                    boundaryDistance:
                        nearestDistance,

                    boundaryType:
                        nearestBoundary
                            ? nearestBoundary.type
                            : null

                };

            }
        );


    // ------------------------------------------------
    // Build vertical intervals between boundaries
    // ------------------------------------------------

    const intervals19 = [];


    for (
        let i = 0;
        i < boundaries19.length - 1;
        i++
    ) {

        const upper =
            boundaries19[i + 1];

        const lower =
            boundaries19[i];


        intervals19.push({

            index: i,

            top:
                lower.y,

            bottom:
                upper.y,

            height:
                upper.y -
                lower.y,

            textRegions: []

        });

    }


    // ------------------------------------------------
    // Assign text to nearest logical interval
    // ------------------------------------------------

    alignedRegions19.forEach(
        region => {

            let bestInterval = null;

            let bestDistance =
                Infinity;


            intervals19.forEach(
                interval => {

                    const regionCenter =
                        region.y +
                        region.height / 2;


                    const intervalCenter =
                        (
                            interval.top +
                            interval.bottom
                        ) / 2;


                    const inside =
                        regionCenter >=
                        interval.top &&
                        regionCenter <=
                        interval.bottom;


                    let distance;


                    if (inside) {

                        distance = 0;

                    } else {

                        distance =
                            Math.min(

                                Math.abs(
                                    regionCenter -
                                    interval.top
                                ),

                                Math.abs(
                                    regionCenter -
                                    interval.bottom
                                )

                            );

                    }


                    if (
                        distance <
                        bestDistance
                    ) {

                        bestDistance =
                            distance;

                        bestInterval =
                            interval;

                    }

                }
            );


            if (bestInterval) {

                bestInterval.textRegions.push(
                    region
                );

            }

        }
    );


    // ------------------------------------------------
    // Remove completely empty intervals
    // ------------------------------------------------

    const logicalRows19 =
        intervals19.map(
            (interval, index) => ({

                index:

                    index + 1,

                top:
                    interval.top,

                bottom:
                    interval.bottom,

                height:
                    interval.height,

                textCount:
                    interval.textRegions.length,

                texts:
                    interval.textRegions
                        .map(
                            r => r.text
                        )

            })
        );


    // ------------------------------------------------
    // Save model
    // ------------------------------------------------

    window.pdfUniversalTextBoundaryAlignment = {

        boundaries:
            boundaries19,

        intervals:
            intervals19,

        rows:
            logicalRows19,

        alignedRegions:
            alignedRegions19

    };


    // ------------------------------------------------
    // Output
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 19 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Logical Boundaries:",
        boundaries19.length
    );

    console.log(
        "Logical Intervals:",
        intervals19.length
    );

    console.log(
        "Text Regions:",
        regions19.length
    );

    console.log(
        "================================="
    );


    console.table(
        logicalRows19
            .filter(
                row =>
                    row.textCount > 0
            )
            .map(
                row => ({

                    Row:
                        row.index,

                    Top:
                        Number(
                            row.top
                        ).toFixed(2),

                    Bottom:
                        Number(
                            row.bottom
                        ).toFixed(2),

                    Height:
                        Number(
                            row.height
                        ).toFixed(2),

                    TextCount:
                        row.textCount,

                    Text:
                        row.texts.join(
                            " | "
                        )

                })
            )
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 19 COMPLETE"
    );

    console.log(
        "================================="
    );

}





