console.log("=================================");
console.log("STEP 21 START");
console.log("UNIVERSAL PRECISION TEXT ROWS");
console.log("=================================");

const source21 =
    window.pdfMergedTextRegions;

if (!source21 || !source21.length) {

    console.error(
        "pdfMergedTextRegions not found."
    );

} else {

    const regions21 =
        [...source21].sort((a, b) => {

            if (
                a.pageNumber !==
                b.pageNumber
            ) {
                return (
                    a.pageNumber -
                    b.pageNumber
                );
            }

            return b.y - a.y;

        });


    // ------------------------------------------------
    // Row detection settings
    // ------------------------------------------------

    const BASELINE_TOLERANCE_21 = 4;

    const LABEL_VALUE_TOLERANCE_21 = 10;

    const CONTINUATION_MAX_GAP_21 = 18;


    const rows21 = [];


    // ------------------------------------------------
    // Helper
    // ------------------------------------------------

    function centerY21(region) {

        return (
            region.y +
            region.height / 2
        );

    }


    function horizontalOverlap21(a, b) {

        const left =
            Math.max(
                a.x,
                b.x
            );

        const right =
            Math.min(
                a.right,
                b.right
            );

        return Math.max(
            0,
            right - left
        );

    }


    function overlapRatio21(a, b) {

        const overlap =
            horizontalOverlap21(
                a,
                b
            );

        const smallerWidth =
            Math.min(
                a.width,
                b.width
            );

        if (
            smallerWidth <= 0
        ) {
            return 0;
        }

        return (
            overlap /
            smallerWidth
        );

    }


    // ------------------------------------------------
    // Detect rows
    // ------------------------------------------------

    regions21.forEach(region => {

        let bestRow = null;

        let bestScore = -Infinity;


        rows21.forEach(row => {

            if (
                row.pageNumber !==
                region.pageNumber
            ) {
                return;
            }


            const rowRegions =
                row.regions;


            // ----------------------------------------
            // Row vertical range
            // ----------------------------------------

            const rowTop =
                Math.min(
                    ...rowRegions.map(
                        r => r.y
                    )
                );

            const rowBottom =
                Math.max(
                    ...rowRegions.map(
                        r =>
                            r.y +
                            r.height
                    )
                );


            const rowCenter =
                (
                    rowTop +
                    rowBottom
                ) / 2;


            const regionCenter =
                centerY21(region);


            const centerDistance =
                Math.abs(
                    regionCenter -
                    rowCenter
                );


            // ----------------------------------------
            // Same baseline
            // ----------------------------------------

            const sameBaseline =
                rowRegions.some(
                    r =>
                        Math.abs(
                            centerY21(r) -
                            regionCenter
                        ) <=
                        BASELINE_TOLERANCE_21
                );


            // ----------------------------------------
            // Vertical relationship
            // ----------------------------------------

            const gap =
                region.y -
                rowBottom;


            const aboveGap =
                rowTop -
                (
                    region.y +
                    region.height
                );


            const verticalClose =
                (
                    gap >= 0 &&
                    gap <=
                    CONTINUATION_MAX_GAP_21
                ) ||
                (
                    aboveGap >= 0 &&
                    aboveGap <=
                    CONTINUATION_MAX_GAP_21
                );


            // ----------------------------------------
            // Horizontal relationship
            // ----------------------------------------

            let maxOverlap = 0;

            rowRegions.forEach(
                existing => {

                    maxOverlap =
                        Math.max(
                            maxOverlap,
                            overlapRatio21(
                                existing,
                                region
                            )
                        );

                }
            );


            // ----------------------------------------
            // Score
            // ----------------------------------------

            let score = 0;


            if (sameBaseline) {

                score += 100;

            }


            if (
                centerDistance <=
                LABEL_VALUE_TOLERANCE_21
            ) {

                score += 20;

            }


            if (verticalClose) {

                score += 10;

            }


            if (
                maxOverlap > 0
            ) {

                score +=
                    maxOverlap * 20;

            }


            // ----------------------------------------
            // Important protection:
            //
            // Two vertically separated regions
            // should NOT merge merely because they
            // are in the same column.
            // ----------------------------------------

            const strongBaseline =
                centerDistance <=
                BASELINE_TOLERANCE_21;


            const strongHorizontal =
                maxOverlap >= 0.45;


            if (
                !strongBaseline &&
                !strongHorizontal
            ) {

                score -= 100;

            }


            if (
                score >
                bestScore
            ) {

                bestScore = score;

                bestRow = row;

            }

        });


        // ------------------------------------------------
        // Create new row if no reliable match
        // ------------------------------------------------

        if (
            !bestRow ||
            bestScore < 20
        ) {

            rows21.push({

                pageNumber:
                    region.pageNumber,

                regions: [
                    region
                ]

            });

        } else {

            bestRow.regions.push(
                region
            );

        }

    });


    // ------------------------------------------------
    // Sort rows top to bottom
    // ------------------------------------------------

    rows21.sort(
        (a, b) => {

            if (
                a.pageNumber !==
                b.pageNumber
            ) {
                return (
                    a.pageNumber -
                    b.pageNumber
                );
            }

            const ay =
                Math.max(
                    ...a.regions.map(
                        r => r.y
                    )
                );

            const by =
                Math.max(
                    ...b.regions.map(
                        r => r.y
                    )
                );

            return by - ay;

        }
    );


    // ------------------------------------------------
    // Build final row model
    // ------------------------------------------------

    const finalRows21 =
        rows21.map(
            (row, index) => {

                const sortedRegions =
                    [...row.regions].sort(
                        (a, b) =>
                            a.x - b.x
                    );


                const top =
                    Math.min(
                        ...sortedRegions.map(
                            r => r.y
                        )
                    );


                const bottom =
                    Math.max(
                        ...sortedRegions.map(
                            r =>
                                r.y +
                                r.height
                        )
                    );


                return {

                    index:
                        index + 1,

                    pageNumber:
                        row.pageNumber,

                    top:
                        top,

                    bottom:
                        bottom,

                    height:
                        bottom - top,

                    regions:
                        sortedRegions,

                    text:
                        sortedRegions
                            .map(
                                r =>
                                    r.text
                            )
                            .join(" | "),

                    regionCount:
                        sortedRegions.length

                };

            }
        );


    // ------------------------------------------------
    // Save
    // ------------------------------------------------

    window.pdfUniversalPrecisionTextRows = {

        sourceRegions:
            regions21,

        rows:
            finalRows21

    };


    // ------------------------------------------------
    // Result
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 21 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Regions:",
        regions21.length
    );

    console.log(
        "Precision Text Rows:",
        finalRows21.length
    );

    console.log(
        "================================="
    );


    finalRows21.forEach(
        row => {

            console.log(
                `ROW ${row.index} | ` +
                `Y: ${row.top.toFixed(2)} | ` +
                `REGIONS: ${row.regionCount} | ` +
                `TEXT: ${row.text}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 21 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 22 START");
console.log("PURE GEOMETRY ROW CLUSTERING");
console.log("=================================");

const source22 =
    window.pdfMergedTextRegions;

if (!source22 || !source22.length) {

    console.error(
        "pdfMergedTextRegions not found."
    );

} else {

    const regions22 =
        [...source22].sort((a, b) => {

            if (
                a.pageNumber !==
                b.pageNumber
            ) {
                return (
                    a.pageNumber -
                    b.pageNumber
                );
            }

            return b.y - a.y;

        });


    // ------------------------------------------------
    // Geometry settings
    // ------------------------------------------------

    const BASELINE_TOLERANCE_22 = 4;

    const LABEL_VALUE_GAP_22 = 14;

    const MULTILINE_GAP_22 = 18;


    // ------------------------------------------------
    // Helpers
    // ------------------------------------------------

    function centerY22(r) {

        return (
            r.y +
            r.height / 2
        );

    }


    function centerX22(r) {

        return (
            r.x +
            r.width / 2
        );

    }


    function horizontalGap22(a, b) {

        if (
            a.right < b.x
        ) {

            return b.x - a.right;

        }

        if (
            b.right < a.x
        ) {

            return a.x - b.right;

        }

        return 0;

    }


    function verticalOverlap22(a, b) {

        const top =
            Math.max(
                a.y,
                b.y
            );

        const bottom =
            Math.min(
                a.y + a.height,
                b.y + b.height
            );

        return Math.max(
            0,
            bottom - top
        );

    }


    // ------------------------------------------------
    // STEP A
    // First create strict baseline groups
    // ------------------------------------------------

    const baselineGroups22 = [];


    regions22.forEach(region => {

        let target = null;


        for (
            const group of
            baselineGroups22
        ) {

            if (
                group.pageNumber !==
                region.pageNumber
            ) {
                continue;
            }


            const groupCenter =
                group.centerY;


            const distance =
                Math.abs(
                    centerY22(region) -
                    groupCenter
                );


            if (
                distance <=
                BASELINE_TOLERANCE_22
            ) {

                target = group;
                break;

            }

        }


        if (!target) {

            baselineGroups22.push({

                pageNumber:
                    region.pageNumber,

                centerY:
                    centerY22(region),

                regions: [
                    region
                ]

            });

        } else {

            target.regions.push(
                region
            );


            // Recalculate center

            target.centerY =
                target.regions.reduce(
                    (
                        sum,
                        r
                    ) =>
                        sum +
                        centerY22(r),
                    0
                ) /
                target.regions.length;

        }

    });


    // ------------------------------------------------
    // STEP B
    // Sort baseline groups
    // ------------------------------------------------

    baselineGroups22.sort(
        (a, b) => {

            if (
                a.pageNumber !==
                b.pageNumber
            ) {
                return (
                    a.pageNumber -
                    b.pageNumber
                );
            }

            return (
                b.centerY -
                a.centerY
            );

        }
    );


    // ------------------------------------------------
    // STEP C
    // Combine nearby baseline groups ONLY when
    // they clearly represent label/value text
    // on the same horizontal line.
    // ------------------------------------------------

    const logicalRows22 = [];


    baselineGroups22.forEach(
        group => {

            const groupRegions =
                group.regions;


            // ----------------------------------------
            // Try existing logical rows
            // ----------------------------------------

            let matchedRow = null;


            for (
                const row of
                logicalRows22
            ) {

                if (
                    row.pageNumber !==
                    group.pageNumber
                ) {
                    continue;
                }


                const rowRegions =
                    row.regions;


                // ------------------------------------
                // Row Y center
                // ------------------------------------

                const rowCenter =
                    row.centerY;


                const yDistance =
                    Math.abs(
                        group.centerY -
                        rowCenter
                    );


                if (
                    yDistance <=
                    BASELINE_TOLERANCE_22
                ) {

                    matchedRow = row;
                    break;

                }


                // ------------------------------------
                // Check horizontal label/value pair
                // ------------------------------------

                if (
                    yDistance >
                    LABEL_VALUE_GAP_22
                ) {
                    continue;
                }


                let horizontalPair =
                    false;


                for (
                    const a of rowRegions
                ) {

                    for (
                        const b of groupRegions
                    ) {

                        const gap =
                            horizontalGap22(
                                a,
                                b
                            );


                        const verticalOverlap =
                            verticalOverlap22(
                                a,
                                b
                            );


                        // Text blocks on same
                        // horizontal structure

                        if (
                            gap <= 120 &&
                            verticalOverlap >= 2
                        ) {

                            horizontalPair =
                                true;

                        }

                    }

                }


                if (
                    horizontalPair
                ) {

                    matchedRow = row;
                    break;

                }

            }


            // ----------------------------------------
            // Create new logical row
            // ----------------------------------------

            if (!matchedRow) {

                logicalRows22.push({

                    pageNumber:
                        group.pageNumber,

                    centerY:
                        group.centerY,

                    regions:
                        [...groupRegions]

                });

            } else {

                matchedRow.regions.push(
                    ...groupRegions
                );


                matchedRow.centerY =
                    matchedRow.regions.reduce(
                        (
                            sum,
                            r
                        ) =>
                            sum +
                            centerY22(r),
                        0
                    ) /
                    matchedRow.regions.length;

            }

        }
    );


    // ------------------------------------------------
    // STEP D
    // Sort regions inside every row
    // ------------------------------------------------

    logicalRows22.forEach(row => {

        row.regions.sort(
            (a, b) =>
                a.x - b.x
        );

    });


    // ------------------------------------------------
    // STEP E
    // Final model
    // ------------------------------------------------

    const finalRows22 =
        logicalRows22.map(
            (row, index) => {

                const top =
                    Math.min(
                        ...row.regions.map(
                            r => r.y
                        )
                    );


                const bottom =
                    Math.max(
                        ...row.regions.map(
                            r =>
                                r.y +
                                r.height
                        )
                    );


                return {

                    index:
                        index + 1,

                    pageNumber:
                        row.pageNumber,

                    top:
                        top,

                    bottom:
                        bottom,

                    centerY:
                        row.centerY,

                    height:
                        bottom - top,

                    regionCount:
                        row.regions.length,

                    regions:
                        row.regions,

                    text:
                        row.regions
                            .map(
                                r =>
                                    r.text
                            )
                            .join(
                                " | "
                            )

                };

            }
        );


    // ------------------------------------------------
    // Save
    // ------------------------------------------------

    window.pdfUniversalPureGeometryRows = {

        sourceRegions:
            regions22,

        baselineGroups:
            baselineGroups22,

        rows:
            finalRows22

    };


    // ------------------------------------------------
    // Result
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 22 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Regions:",
        regions22.length
    );

    console.log(
        "Baseline Groups:",
        baselineGroups22.length
    );

    console.log(
        "Logical Rows:",
        finalRows22.length
    );

    console.log(
        "================================="
    );


    finalRows22.forEach(
        row => {

            console.log(
                `ROW ${row.index} | ` +
                `Y: ${row.top.toFixed(2)} | ` +
                `REGIONS: ${row.regionCount} | ` +
                `TEXT: ${row.text}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 22 COMPLETE"
    );

    console.log(
        "================================="
    );

}






console.log("=================================");
console.log("STEP 22.5 START");
console.log("LABEL / VALUE ROW CORRECTION");
console.log("=================================");

const input225 =
    window.pdfUniversalPureGeometryRows;

if (!input225?.rows) {

    console.error(
        "Step 22 rows not found."
    );

} else {

    const rows225 =
        input225.rows.map(row => ({

            ...row,

            regions:
                [...row.regions]

        }));


    // ---------------------------------------------
    // Settings
    // ---------------------------------------------

    const MAX_Y_DIFFERENCE_225 = 11;

    const MAX_HORIZONTAL_GAP_225 = 140;

    const MAX_LABEL_WIDTH_225 = 120;


    // ---------------------------------------------
    // Helpers
    // ---------------------------------------------

    function gap225(a, b) {

        if (a.right <= b.x) {

            return b.x - a.right;

        }

        if (b.right <= a.x) {

            return a.x - b.right;

        }

        return 0;

    }


    function centerY225(r) {

        return (
            r.y +
            r.height / 2
        );

    }


    // ---------------------------------------------
    // Find candidate row pairs
    // ---------------------------------------------

    let changed225 = true;


    while (changed225) {

        changed225 = false;


        for (
            let i = 0;
            i < rows225.length;
            i++
        ) {

            const rowA =
                rows225[i];


            if (
                rowA.regions.length === 0
            ) {
                continue;
            }


            // Only inspect rows that are
            // vertically close.

            for (
                let j = i + 1;
                j < rows225.length;
                j++
            ) {

                const rowB =
                    rows225[j];


                if (
                    rowB.pageNumber !==
                    rowA.pageNumber
                ) {
                    continue;
                }


                const yA =
                    rowA.centerY;

                const yB =
                    rowB.centerY;


                const yDifference =
                    Math.abs(
                        yA - yB
                    );


                if (
                    yDifference >
                    MAX_Y_DIFFERENCE_225
                ) {
                    continue;
                }


                let validPair = false;


                // ---------------------------------
                // Look for label -> value relation
                // ---------------------------------

                for (
                    const a of rowA.regions
                ) {

                    for (
                        const b of rowB.regions
                    ) {

                        let left =
                            a;

                        let right =
                            b;


                        if (
                            b.x < a.x
                        ) {

                            left = b;
                            right = a;

                        }


                        const horizontalGap =
                            gap225(
                                left,
                                right
                            );


                        // Left block should look
                        // like a label.

                        const looksLikeLabel =
                            left.width <=
                            MAX_LABEL_WIDTH_225;


                        const text =
                            left.text
                                .trim();


                        const hasLabelMarker =
                            /[:\-]/.test(
                                text
                            );


                        if (
                            looksLikeLabel &&
                            horizontalGap <=
                                MAX_HORIZONTAL_GAP_225 &&
                            (
                                hasLabelMarker ||
                                left.width < 90
                            )
                        ) {

                            validPair = true;

                        }

                    }

                }


                if (!validPair) {
                    continue;
                }


                // ---------------------------------
                // Merge rows
                // ---------------------------------

                rowA.regions.push(
                    ...rowB.regions
                );


                rowA.regions.sort(
                    (a, b) =>
                        a.x - b.x
                );


                const top =
                    Math.min(
                        ...rowA.regions.map(
                            r => r.y
                        )
                    );


                const bottom =
                    Math.max(
                        ...rowA.regions.map(
                            r =>
                                r.y +
                                r.height
                        )
                    );


                rowA.centerY =
                    rowA.regions.reduce(
                        (
                            sum,
                            r
                        ) =>
                            sum +
                            centerY225(r),
                        0
                    ) /
                    rowA.regions.length;


                rowA.top =
                    top;

                rowA.bottom =
                    bottom;

                rowA.height =
                    bottom - top;

                rowA.regionCount =
                    rowA.regions.length;

                rowA.text =
                    rowA.regions
                        .map(
                            r =>
                                r.text
                        )
                        .join(
                            " | "
                        );


                // Remove merged row

                rows225.splice(
                    j,
                    1
                );


                changed225 = true;

                break;

            }


            if (changed225) {
                break;
            }

        }

    }


    // ---------------------------------------------
    // Final sorting
    // ---------------------------------------------

    rows225.sort(
        (a, b) => {

            if (
                a.pageNumber !==
                b.pageNumber
            ) {

                return (
                    a.pageNumber -
                    b.pageNumber
                );

            }

            return (
                b.top -
                a.top
            );

        }
    );


    // ---------------------------------------------
    // Re-index
    // ---------------------------------------------

    const final225 =
        rows225.map(
            (row, index) => ({

                ...row,

                index:
                    index + 1,

                text:
                    row.regions
                        .sort(
                            (a, b) =>
                                a.x - b.x
                        )
                        .map(
                            r =>
                                r.text
                        )
                        .join(
                            " | "
                        ),

                regionCount:
                    row.regions.length

            })
        );


    // ---------------------------------------------
    // Save
    // ---------------------------------------------

    window.pdfUniversalLabelValueRows = {

        sourceRows:
            input225.rows,

        rows:
            final225

    };


    // ---------------------------------------------
    // Result
    // ---------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 22.5 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Input Rows:",
        input225.rows.length
    );

    console.log(
        "Final Rows:",
        final225.length
    );

    console.log(
        "================================="
    );


    final225.forEach(
        row => {

            console.log(
                `ROW ${row.index} | ` +
                `Y: ${row.top.toFixed(2)} | ` +
                `REGIONS: ${row.regionCount} | ` +
                `TEXT: ${row.text}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 22.5 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 23 START");
console.log("ROW + COLUMN + BORDER INTEGRATION");
console.log("=================================");

const rows23 =
    window.pdfUniversalLabelValueRows?.rows;

const columns23 =
    window.pdfUniversalLogicalTextColumns?.columns;

const borders23 =
    window.pdfUniversalHorizontalBoundaries?.boundaries;

if (!rows23 || !columns23 || !borders23) {

    console.error(
        "Required Step 22.5 / Step 14.5 / Step 18.5 data not found."
    );

} else {

    // ------------------------------------------------
    // Sort boundaries from bottom -> top
    // ------------------------------------------------

    const sortedBorders23 =
        [...borders23].sort(
            (a, b) => a.y - b.y
        );


    // ------------------------------------------------
    // Helpers
    // ------------------------------------------------

    function nearestBoundary23(
        value
    ) {

        let best = null;

        let distance =
            Infinity;


        sortedBorders23.forEach(
            boundary => {

                const d =
                    Math.abs(
                        boundary.y -
                        value
                    );


                if (
                    d < distance
                ) {

                    distance = d;

                    best = boundary;

                }

            }
        );


        return {

            boundary: best,

            distance: distance

        };

    }


    function regionColumn23(
        region
    ) {

        const center =
            region.x +
            region.width / 2;


        let best =
            null;

        let bestDistance =
            Infinity;


        columns23.forEach(
            column => {

                const left =
                    column.left;

                const right =
                    column.right;

                let distance;


                if (
                    center >= left &&
                    center <= right
                ) {

                    distance = 0;

                } else {

                    distance =
                        Math.min(
                            Math.abs(
                                center -
                                left
                            ),
                            Math.abs(
                                center -
                                right
                            )
                        );

                }


                if (
                    distance <
                    bestDistance
                ) {

                    bestDistance =
                        distance;

                    best =
                        column;

                }

            }
        );


        return best;

    }


    // ------------------------------------------------
    // Build integrated rows
    // ------------------------------------------------

    const integratedRows23 =
        rows23.map(
            (row, index) => {

                const rowTop =
                    Math.min(
                        ...row.regions.map(
                            r => r.y
                        )
                    );


                const rowBottom =
                    Math.max(
                        ...row.regions.map(
                            r =>
                                r.y +
                                r.height
                        )
                    );


                // ------------------------------------
                // Find surrounding borders
                // ------------------------------------

                const topCandidate =
                    nearestBoundary23(
                        rowBottom
                    );


                const bottomCandidate =
                    nearestBoundary23(
                        rowTop
                    );


                // ------------------------------------
                // Use actual border when reasonably
                // close, otherwise text geometry.
                // ------------------------------------

                const BORDER_ATTACH_TOLERANCE_23 =
                    12;


                let visualTop =
                    rowBottom;


                let visualBottom =
                    rowTop;


                if (
                    topCandidate.boundary &&
                    topCandidate.distance <=
                        BORDER_ATTACH_TOLERANCE_23
                ) {

                    visualTop =
                        topCandidate.boundary.y;

                }


                if (
                    bottomCandidate.boundary &&
                    bottomCandidate.distance <=
                        BORDER_ATTACH_TOLERANCE_23
                ) {

                    visualBottom =
                        bottomCandidate.boundary.y;

                }


                // ------------------------------------
                // Keep correct coordinate order
                // ------------------------------------

                const highY =
                    Math.max(
                        visualTop,
                        visualBottom
                    );

                const lowY =
                    Math.min(
                        visualTop,
                        visualBottom
                    );


                // ------------------------------------
                // Build cells for 3 logical columns
                // ------------------------------------

                const cells23 =
                    columns23.map(
                        (
                            column,
                            columnIndex
                        ) => {

                            const cellRegions =
                                row.regions.filter(
                                    region => {

                                        const mapped =
                                            regionColumn23(
                                                region
                                            );

                                        return (
                                            mapped &&
                                            mapped.index ===
                                            column.index
                                        );

                                    }
                                );


                            return {

                                rowIndex:
                                    index + 1,

                                columnIndex:
                                    columnIndex,

                                left:
                                    column.left,

                                right:
                                    column.right,

                                top:
                                    highY,

                                bottom:
                                    lowY,

                                width:
                                    column.right -
                                    column.left,

                                height:
                                    highY -
                                    lowY,

                                text:
                                    cellRegions
                                        .map(
                                            r =>
                                                r.text
                                        )
                                        .join(
                                            " "
                                        ),

                                regions:
                                    cellRegions,

                                textCount:
                                    cellRegions.length,

                                border: {

                                    top:
                                        !!(
                                            topCandidate.boundary
                                        ),

                                    bottom:
                                        !!(
                                            bottomCandidate.boundary
                                        ),

                                    left:
                                        false,

                                    right:
                                        false

                                }

                            };

                        }
                    );


                return {

                    index:
                        index + 1,

                    pageNumber:
                        row.pageNumber,

                    textTop:
                        rowTop,

                    textBottom:
                        rowBottom,

                    top:
                        highY,

                    bottom:
                        lowY,

                    height:
                        highY -
                        lowY,

                    text:
                        row.text,

                    regionCount:
                        row.regionCount,

                    regions:
                        row.regions,

                    cells:
                        cells23

                };

            }
        );


    // ------------------------------------------------
    // Save integrated model
    // ------------------------------------------------

    window.pdfUniversalIntegratedRows = {

        rows:
            integratedRows23,

        columns:
            columns23,

        borders:
            sortedBorders23

    };


    // ------------------------------------------------
    // Result
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 23 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Text Rows:",
        rows23.length
    );

    console.log(
        "Logical Columns:",
        columns23.length
    );

    console.log(
        "Horizontal Boundaries:",
        sortedBorders23.length
    );

    console.log(
        "Integrated Rows:",
        integratedRows23.length
    );

    console.log(
        "================================="
    );


    integratedRows23.forEach(
        row => {

            console.log(
                `ROW ${row.index} | ` +
                `TOP: ${row.top.toFixed(2)} | ` +
                `BOTTOM: ${row.bottom.toFixed(2)} | ` +
                `HEIGHT: ${row.height.toFixed(2)} | ` +
                `CELLS: ${row.cells.length} | ` +
                `TEXT: ${row.text}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 23 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 24 START");
console.log("UNIVERSAL TABLE REGION DETECTION");
console.log("=================================");

const integrated24 =
    window.pdfUniversalIntegratedRows;

const reconstructed24 =
    window.pdfReconstructedBorders;

if (
    !integrated24 ||
    !integrated24.rows ||
    !integrated24.columns ||
    !reconstructed24
) {

    console.error(
        "Step 23 data or border data not found."
    );

} else {

    const rows24 =
        integrated24.rows;

    const columns24 =
        integrated24.columns;


    // ------------------------------------------------
    // Get real horizontal border positions
    // ------------------------------------------------

    const horizontal24 =
        reconstructed24.horizontal?.positions ||
        [];


    const borderYs24 =
        horizontal24
            .map(item => item.y)
            .filter(
                y => Number.isFinite(y)
            )
            .sort(
                (a, b) => b - a
            );


    // ------------------------------------------------
    // Find repeated / strong horizontal boundaries
    // ------------------------------------------------

    const boundaryGroups24 = [];

    const Y_TOLERANCE_24 = 3;


    borderYs24.forEach(y => {

        let group =
            boundaryGroups24.find(
                g =>
                    Math.abs(
                        g.center - y
                    ) <= Y_TOLERANCE_24
            );


        if (!group) {

            group = {

                center: y,

                values: []

            };

            boundaryGroups24.push(
                group
            );

        }


        group.values.push(y);


        group.center =
            group.values.reduce(
                (sum, value) =>
                    sum + value,
                0
            ) /
            group.values.length;

    });


    // ------------------------------------------------
    // Calculate border strength
    // ------------------------------------------------

    const strongBoundaries24 =
        boundaryGroups24
            .map(
                group => ({

                    y:
                        group.center,

                    count:
                        group.values.length

                })
            )
            .sort(
                (a, b) =>
                    b.y - a.y
            );


    // ------------------------------------------------
    // Determine row text center
    // ------------------------------------------------

    const rowInfo24 =
        rows24.map(
            row => {

                const textCenter =
                    (
                        row.textTop +
                        row.textBottom
                    ) / 2;


                return {

                    rowIndex:
                        row.index,

                    textCenter:
                        textCenter,

                    top:
                        row.top,

                    bottom:
                        row.bottom,

                    regionCount:
                        row.regionCount,

                    text:
                        row.text

                };

            }
        );


    // ------------------------------------------------
    // Find border support around each row
    // ------------------------------------------------

    const rowSupport24 =
        rowInfo24.map(
            row => {

                const above =
                    strongBoundaries24
                        .filter(
                            boundary =>
                                boundary.y >
                                row.textCenter
                        )
                        .sort(
                            (a, b) =>
                                Math.abs(
                                    a.y -
                                    row.textCenter
                                ) -
                                Math.abs(
                                    b.y -
                                    row.textCenter
                                )
                        )[0];


                const below =
                    strongBoundaries24
                        .filter(
                            boundary =>
                                boundary.y <
                                row.textCenter
                        )
                        .sort(
                            (a, b) =>
                                Math.abs(
                                    a.y -
                                    row.textCenter
                                ) -
                                Math.abs(
                                    b.y -
                                    row.textCenter
                                )
                        )[0];


                const aboveDistance =
                    above
                        ? Math.abs(
                            above.y -
                            row.textCenter
                        )
                        : Infinity;


                const belowDistance =
                    below
                        ? Math.abs(
                            below.y -
                            row.textCenter
                        )
                        : Infinity;


                return {

                    ...row,

                    above:
                        above || null,

                    below:
                        below || null,

                    aboveDistance:
                        aboveDistance,

                    belowDistance:
                        belowDistance

                };

            }
        );


    // ------------------------------------------------
    // Detect table-like continuous row sequence
    // ------------------------------------------------

    const TABLE_DISTANCE_LIMIT_24 = 45;

    const tableCandidates24 = [];

    let currentCandidate24 = [];


    rowSupport24.forEach(
        row => {

            const hasNearbyBorder =
                row.aboveDistance <=
                    TABLE_DISTANCE_LIMIT_24 ||
                row.belowDistance <=
                    TABLE_DISTANCE_LIMIT_24;


            if (hasNearbyBorder) {

                currentCandidate24.push(
                    row
                );

            } else {

                if (
                    currentCandidate24.length >=
                    2
                ) {

                    tableCandidates24.push(
                        currentCandidate24
                    );

                }

                currentCandidate24 = [];

            }

        }
    );


    if (
        currentCandidate24.length >=
        2
    ) {

        tableCandidates24.push(
            currentCandidate24
        );

    }


    // ------------------------------------------------
    // Score each candidate
    // ------------------------------------------------

    const scoredCandidates24 =
        tableCandidates24.map(
            candidate => {

                const multiRegionRows =
                    candidate.filter(
                        row =>
                            row.regionCount >=
                            2
                    ).length;


                const borderRows =
                    candidate.filter(
                        row =>
                            row.above ||
                            row.below
                    ).length;


                const score =
                    (
                        candidate.length * 2
                    ) +
                    (
                        multiRegionRows * 3
                    ) +
                    (
                        borderRows * 2
                    );


                return {

                    rows:
                        candidate,

                    startRow:
                        Math.min(
                            ...candidate.map(
                                r =>
                                    r.rowIndex
                            )
                        ),

                    endRow:
                        Math.max(
                            ...candidate.map(
                                r =>
                                    r.rowIndex
                            )
                        ),

                    rowCount:
                        candidate.length,

                    multiRegionRows:
                        multiRegionRows,

                    borderRows:
                        borderRows,

                    score:
                        score

                };

            }
        )
        .sort(
            (a, b) =>
                b.score -
                a.score
        );


    // ------------------------------------------------
    // Select strongest table region
    // ------------------------------------------------

    let selectedTable24 =
        scoredCandidates24[0] ||
        null;


    // ------------------------------------------------
    // Safety validation
    // ------------------------------------------------

    if (selectedTable24) {

        const selectedRows24 =
            selectedTable24.rows;


        const minRow24 =
            Math.min(
                ...selectedRows24.map(
                    r =>
                        r.rowIndex
                )
            );


        const maxRow24 =
            Math.max(
                ...selectedRows24.map(
                    r =>
                        r.rowIndex
                )
            );


        selectedTable24 =
            {

                ...selectedTable24,

                minRow:
                    minRow24,

                maxRow:
                    maxRow24,

                columnCount:
                    columns24.length,

                tableTop:
                    Math.max(
                        ...selectedRows24.map(
                            r =>
                                r.top
                        )
                    ),

                tableBottom:
                    Math.min(
                        ...selectedRows24.map(
                            r =>
                                r.bottom
                        )
                    )

            };

    }


    // ------------------------------------------------
    // Save result
    // ------------------------------------------------

    window.pdfUniversalTableRegion = {

        detected:
            !!selectedTable24,

        candidates:
            scoredCandidates24,

        selected:
            selectedTable24,

        boundaries:
            strongBoundaries24,

        columns:
            columns24,

        rows:
            rows24

    };


    // ------------------------------------------------
    // Console output
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 24 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Logical Rows:",
        rows24.length
    );

    console.log(
        "Logical Columns:",
        columns24.length
    );

    console.log(
        "Raw Horizontal Borders:",
        borderYs24.length
    );

    console.log(
        "Strong Boundaries:",
        strongBoundaries24.length
    );

    console.log(
        "Table Candidates:",
        scoredCandidates24.length
    );


    if (selectedTable24) {

        console.log(
            "---------------------------------"
        );

        console.log(
            "SELECTED TABLE REGION"
        );

        console.log(
            "---------------------------------"
        );

        console.log(
            "Start Row:",
            selectedTable24.startRow
        );

        console.log(
            "End Row:",
            selectedTable24.endRow
        );

        console.log(
            "Row Count:",
            selectedTable24.rowCount
        );

        console.log(
            "Column Count:",
            selectedTable24.columnCount
        );

        console.log(
            "Score:",
            selectedTable24.score
        );

        console.log(
            "Table Top:",
            selectedTable24.tableTop
        );

        console.log(
            "Table Bottom:",
            selectedTable24.tableBottom
        );

    } else {

        console.log(
            "NO TABLE REGION DETECTED"
        );

    }


    console.log(
        "================================="
    );

    console.log(
        "TABLE CANDIDATES"
    );

    console.log(
        "================================="
    );


    scoredCandidates24.forEach(
        candidate => {

            console.log(
                `Rows ${candidate.startRow}-${candidate.endRow} | ` +
                `Count: ${candidate.rowCount} | ` +
                `Multi-region: ${candidate.multiRegionRows} | ` +
                `Borders: ${candidate.borderRows} | ` +
                `Score: ${candidate.score}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 24 COMPLETE"
    );

    console.log(
        "================================="
    );

}





