console.log("STEP 24.5 START");
console.log("HORIZONTAL BORDER GEOMETRY CHECK");
console.log("=================================");

const pages245 =
    window.pdfLayoutAnalysis?.pages || [];

const horizontal245 = [];

pages245.forEach(page => {

    const graphics =
        page.graphics || [];

    graphics.forEach(graphic => {

        if (
            graphic.type !== "path" ||
            !graphic.args
        ) {
            return;
        }

        const args =
            graphic.args;

        const bbox =
            args[2];

        if (
            !Array.isArray(bbox) ||
            bbox.length < 4
        ) {
            return;
        }

        const x1 =
            Math.min(
                bbox[0],
                bbox[2]
            );

        const y1 =
            Math.min(
                bbox[1],
                bbox[3]
            );

        const x2 =
            Math.max(
                bbox[0],
                bbox[2]
            );

        const y2 =
            Math.max(
                bbox[1],
                bbox[3]
            );

        const width =
            x2 - x1;

        const height =
            y2 - y1;


        // Horizontal geometry
        if (
            width >= 20 &&
            width > height * 4
        ) {

            horizontal245.push({

                pageNumber:
                    page.pageNumber,

                x1:
                    x1,

                x2:
                    x2,

                y:
                    (y1 + y2) / 2,

                width:
                    width,

                height:
                    height

            });

        }

    });

});


// ------------------------------------------------
// Group horizontal lines by Y
// ------------------------------------------------

const groups245 = [];

const Y_TOLERANCE_245 = 3;

horizontal245.forEach(line => {

    let group =
        groups245.find(
            g =>
                Math.abs(
                    g.y -
                    line.y
                ) <=
                Y_TOLERANCE_245
        );


    if (!group) {

        group = {

            y:
                line.y,

            lines: []

        };

        groups245.push(
            group
        );

    }


    group.lines.push(
        line
    );

});


// ------------------------------------------------
// Calculate combined geometry
// ------------------------------------------------

const borderGeometry245 =
    groups245
        .map(group => {

            const minX =
                Math.min(
                    ...group.lines.map(
                        line =>
                            line.x1
                    )
                );

            const maxX =
                Math.max(
                    ...group.lines.map(
                        line =>
                            line.x2
                    )
                );

            const totalWidth =
                maxX - minX;


            return {

                y:
                    group.y,

                minX:
                    minX,

                maxX:
                    maxX,

                width:
                    totalWidth,

                segments:
                    group.lines.length

            };

        })
        .sort(
            (a, b) =>
                b.y - a.y
        );


// ------------------------------------------------
// Save
// ------------------------------------------------

window.pdfUniversalHorizontalGeometry =
    borderGeometry245;


// ------------------------------------------------
// Output
// ------------------------------------------------

