console.log("=================================");
console.log("STEP 25 START");
console.log("UNIVERSAL TABLE GEOMETRY DETECTION");
console.log("=================================");

const geometry25 =
    window.pdfUniversalHorizontalGeometry || [];

const rows25 =
    window.pdfUniversalIntegratedRows?.rows || [];

const columns25 =
    window.pdfUniversalIntegratedRows?.columns || [];

if (
    !geometry25.length ||
    !rows25.length
) {

    console.error(
        "Step 23 / Step 24.5 geometry data not found."
    );

} else {

    // ---------------------------------------------
    // PDF geometry statistics
    // ---------------------------------------------

    const widths25 =
        geometry25.map(
            line => line.width
        );


    const maxWidth25 =
        Math.max(
            ...widths25
        );


    // ---------------------------------------------
    // Classify horizontal lines
    // ---------------------------------------------

    const classified25 =
        geometry25.map(
            (line, index) => {

                const widthRatio =
                    line.width /
                    maxWidth25;


                let type =
                    "short";


                if (
                    widthRatio >=
                    0.90
                ) {

                    type =
                        "full";

                } else if (
                    widthRatio >=
                    0.60
                ) {

                    type =
                        "medium";

                }


                return {

                    index:
                        index + 1,

                    y:
                        line.y,

                    x1:
                        line.minX,

                    x2:
                        line.maxX,

                    width:
                        line.width,

                    widthRatio:
                        widthRatio,

                    segments:
                        line.segments,

                    type:
                        type

                };

            }
        );


    // ---------------------------------------------
    // Find repeated full-width grid pattern
    // ---------------------------------------------

    const fullLines25 =
        classified25.filter(
            line =>
                line.type ===
                "full"
        );


    const innerLines25 =
        classified25.filter(
            line =>
                line.type ===
                "medium"
        );


    // ---------------------------------------------
    // Calculate Y gaps between full lines
    // ---------------------------------------------

    const fullSorted25 =
        [...fullLines25].sort(
            (a, b) =>
                b.y - a.y
        );


    const fullGaps25 = [];

    for (
        let i = 1;
        i < fullSorted25.length;
        i++
    ) {

        fullGaps25.push({

            from:
                fullSorted25[i - 1].y,

            to:
                fullSorted25[i].y,

            gap:
                fullSorted25[i - 1].y -
                fullSorted25[i].y

        });

    }


    // ---------------------------------------------
    // Detect dense grid sequence
    // ---------------------------------------------

    const GRID_GAP_MIN_25 =
        8;

    const GRID_GAP_MAX_25 =
        45;


    const gridSegments25 = [];

    let current25 = [];


    fullSorted25.forEach(
        (line, index) => {

            if (
                current25.length ===
                0
            ) {

                current25.push(
                    line
                );

                return;

            }


            const previous =
                current25[
                    current25.length - 1
                ];


            const gap =
                previous.y -
                line.y;


            if (
                gap >=
                    GRID_GAP_MIN_25 &&
                gap <=
                    GRID_GAP_MAX_25
            ) {

                current25.push(
                    line
                );

            } else {

                if (
                    current25.length >=
                    3
                ) {

                    gridSegments25.push(
                        current25
                    );

                }

                current25 = [
                    line
                ];

            }

        }
    );


    if (
        current25.length >=
        3
    ) {

        gridSegments25.push(
            current25
        );

    }


    // ---------------------------------------------
    // Score grid segments
    // ---------------------------------------------

    const scored25 =
        gridSegments25.map(
            segment => {

                const minY =
                    Math.min(
                        ...segment.map(
                            line =>
                                line.y
                        )
                    );


                const maxY =
                    Math.max(
                        ...segment.map(
                            line =>
                                line.y
                        )
                    );


                const totalHeight =
                    maxY -
                    minY;


                const rowCount =
                    segment.length -
                    1;


                const score =
                    (
                        segment.length *
                        3
                    ) +
                    (
                        rowCount *
                        2
                    );


                return {

                    startY:
                        maxY,

                    endY:
                        minY,

                    height:
                        totalHeight,

                    boundaryCount:
                        segment.length,

                    estimatedRows:
                        rowCount,

                    score:
                        score,

                    lines:
                        segment

                };

            }
        )
        .sort(
            (a, b) =>
                b.score -
                a.score
        );


    // ---------------------------------------------
    // Find strongest table geometry
    // ---------------------------------------------

    let selected25 =
        scored25[0] ||
        null;


    // ---------------------------------------------
    // Validate against text rows
    // ---------------------------------------------

    if (selected25) {

        const matchingRows25 =
            rows25.filter(
                row => {

                    const center =
                        (
                            row.textTop +
                            row.textBottom
                        ) / 2;


                    return (
                        center <=
                            selected25.startY &&
                        center >=
                            selected25.endY
                    );

                }
            );


        selected25 = {

            ...selected25,

            matchingTextRows:
                matchingRows25.length,

            matchingRowIndexes:
                matchingRows25.map(
                    row =>
                        row.index
                )

        };

    }


    // ---------------------------------------------
    // Save model
    // ---------------------------------------------

    window.pdfUniversalTableGeometryModel = {

        allLines:
            classified25,

        fullLines:
            fullLines25,

        innerLines:
            innerLines25,

        fullGaps:
            fullGaps25,

        candidates:
            scored25,

        selected:
            selected25,

        columns:
            columns25,

        textRows:
            rows25

    };


    // ---------------------------------------------
    // Output
    // ---------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 25 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Total Horizontal Lines:",
        geometry25.length
    );

    console.log(
        "Full Width Lines:",
        fullLines25.length
    );

    console.log(
        "Medium Width Lines:",
        innerLines25.length
    );

    console.log(
        "Grid Candidates:",
        scored25.length
    );


    if (selected25) {

        console.log(
            "---------------------------------"
        );

        console.log(
            "SELECTED GRID"
        );

        console.log(
            "---------------------------------"
        );

        console.log(
            "Start Y:",
            selected25.startY
        );

        console.log(
            "End Y:",
            selected25.endY
        );

        console.log(
            "Height:",
            selected25.height
        );

        console.log(
            "Boundary Count:",
            selected25.boundaryCount
        );

        console.log(
            "Estimated Rows:",
            selected25.estimatedRows
        );

        console.log(
            "Matching Text Rows:",
            selected25.matchingTextRows
        );

        console.log(
            "Matching Row Indexes:",
            selected25.matchingRowIndexes
        );

        console.log(
            "Score:",
            selected25.score
        );

    } else {

        console.log(
            "NO GRID CANDIDATE DETECTED"
        );

    }


    console.log(
        "---------------------------------"
    );

    console.log(
        "GRID CANDIDATES"
    );

    console.log(
        "---------------------------------"
    );


    scored25.forEach(
        (candidate, index) => {

            console.log(
                `CANDIDATE ${index + 1} | ` +
                `Y: ${candidate.startY.toFixed(2)} -> ${candidate.endY.toFixed(2)} | ` +
                `Boundaries: ${candidate.boundaryCount} | ` +
                `Rows: ${candidate.estimatedRows} | ` +
                `Score: ${candidate.score}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 25 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 26 START");
console.log("UNIVERSAL BORDER REGION SEGMENTATION");
console.log("=================================");

const lines26 =
    window.pdfUniversalTableGeometryModel?.allLines || [];

const rows26 =
    window.pdfUniversalIntegratedRows?.rows || [];

if (
    !lines26.length ||
    !rows26.length
) {

    console.error(
        "Step 25 geometry data not found."
    );

} else {

    // ---------------------------------------------
    // Only meaningful full/medium horizontal lines
    // ---------------------------------------------

    const usable26 =
        lines26
            .filter(
                line =>
                    line.type === "full" ||
                    line.type === "medium"
            )
            .sort(
                (a, b) =>
                    b.y - a.y
            );


    // ---------------------------------------------
    // Group nearby horizontal boundaries
    // ---------------------------------------------

    const GAP_MIN_26 = 8;
    const GAP_MAX_26 = 45;

    const regions26 = [];

    let current26 = [];


    usable26.forEach(
        line => {

            if (
                current26.length ===
                0
            ) {

                current26.push(
                    line
                );

                return;

            }


            const previous =
                current26[
                    current26.length - 1
                ];


            const gap =
                previous.y -
                line.y;


            if (
                gap >= GAP_MIN_26 &&
                gap <= GAP_MAX_26
            ) {

                current26.push(
                    line
                );

            } else {

                if (
                    current26.length >= 2
                ) {

                    regions26.push(
                        current26
                    );

                }

                current26 = [
                    line
                ];

            }

        }
    );


    if (
        current26.length >= 2
    ) {

        regions26.push(
            current26
        );

    }


    // ---------------------------------------------
    // Build region information
    // ---------------------------------------------

    const segmented26 =
        regions26.map(
            (segment, index) => {

                const top =
                    Math.max(
                        ...segment.map(
                            line =>
                                line.y
                        )
                    );


                const bottom =
                    Math.min(
                        ...segment.map(
                            line =>
                                line.y
                        )
                    );


                const width =
                    Math.max(
                        ...segment.map(
                            line =>
                                line.width
                        )
                    );


                const textRows =
                    rows26.filter(
                        row => {

                            const center =
                                (
                                    row.textTop +
                                    row.textBottom
                                ) / 2;


                            return (
                                center <= top &&
                                center >= bottom
                            );

                        }
                    );


                const fullCount =
                    segment.filter(
                        line =>
                            line.type ===
                            "full"
                    ).length;


                const mediumCount =
                    segment.filter(
                        line =>
                            line.type ===
                            "medium"
                    ).length;


                return {

                    regionIndex:
                        index + 1,

                    top:
                        top,

                    bottom:
                        bottom,

                    height:
                        top - bottom,

                    boundaryCount:
                        segment.length,

                    fullWidthLines:
                        fullCount,

                    mediumWidthLines:
                        mediumCount,

                    maxWidth:
                        width,

                    textRowCount:
                        textRows.length,

                    textRowIndexes:
                        textRows.map(
                            row =>
                                row.index
                        ),

                    lines:
                        segment

                };

            }
        );


    // ---------------------------------------------
    // Score regions by geometry only
    // ---------------------------------------------

    const scored26 =
        segmented26.map(
            region => {

                const density =
                    region.height >
                    0
                        ? region.boundaryCount /
                          region.height
                        : 0;


                const score =
                    (
                        region.boundaryCount *
                        3
                    ) +
                    (
                        region.fullWidthLines *
                        2
                    ) +
                    (
                        region.mediumWidthLines
                    ) +
                    (
                        region.textRowCount *
                        2
                    );


                return {

                    ...region,

                    density:
                        density,

                    score:
                        score

                };

            }
        )
        .sort(
            (a, b) =>
                b.score -
                a.score
        );


    // ---------------------------------------------
    // Save
    // ---------------------------------------------

    window.pdfUniversalBorderRegions = {

        regions:
            scored26,

        sourceLines:
            lines26,

        sourceRows:
            rows26

    };


    // ---------------------------------------------
    // Output
    // ---------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 26 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Usable Border Lines:",
        usable26.length
    );

    console.log(
        "Detected Border Regions:",
        scored26.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "BORDER REGIONS"
    );

    console.log(
        "---------------------------------"
    );


    scored26.forEach(
        region => {

            console.log(
                `REGION ${region.regionIndex} | ` +
                `TOP: ${region.top.toFixed(2)} | ` +
                `BOTTOM: ${region.bottom.toFixed(2)} | ` +
                `HEIGHT: ${region.height.toFixed(2)} | ` +
                `BOUNDARIES: ${region.boundaryCount} | ` +
                `FULL: ${region.fullWidthLines} | ` +
                `MEDIUM: ${region.mediumWidthLines} | ` +
                `TEXT ROWS: ${region.textRowCount} | ` +
                `SCORE: ${region.score}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 26 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 27 START");
console.log("UNIVERSAL REGION + COLUMN MAPPING");
console.log("=================================");

const regions27 =
    window.pdfUniversalBorderRegions?.regions || [];

const rows27 =
    window.pdfUniversalIntegratedRows?.rows || [];

const columns27 =
    window.pdfUniversalIntegratedRows?.columns || [];

if (
    !regions27.length ||
    !rows27.length ||
    !columns27.length
) {

    console.error(
        "Step 26 / Step 23 data not found."
    );

} else {

    // ------------------------------------------------
    // Map each logical text row to a border region
    // ------------------------------------------------

    const mappedRegions27 =
        regions27.map(
            region => {

                const regionRows =
                    rows27.filter(
                        row => {

                            const center =
                                (
                                    row.textTop +
                                    row.textBottom
                                ) / 2;


                            return (
                                center <=
                                    region.top &&
                                center >=
                                    region.bottom
                            );

                        }
                    );


                // ------------------------------------
                // Create column summary
                // ------------------------------------

                const columnSummary =
                    columns27.map(
                        column => {

                            const columnRows =
                                regionRows.filter(
                                    row => {

                                        return row.regions.some(
                                            regionItem => {

                                                const centerX =
                                                    regionItem.x +
                                                    regionItem.width /
                                                    2;


                                                return (
                                                    centerX >=
                                                        column.left &&
                                                    centerX <=
                                                        column.right
                                                );

                                            }
                                        );

                                    }
                                );


                            return {

                                columnIndex:
                                    column.index,

                                left:
                                    column.left,

                                right:
                                    column.right,

                                width:
                                    column.right -
                                    column.left,

                                rowCount:
                                    columnRows.length,

                                rowIndexes:
                                    columnRows.map(
                                        row =>
                                            row.index
                                    )

                            };

                        }
                    );


                return {

                    regionIndex:
                        region.regionIndex,

                    top:
                        region.top,

                    bottom:
                        region.bottom,

                    height:
                        region.height,

                    boundaryCount:
                        region.boundaryCount,

                    fullWidthLines:
                        region.fullWidthLines,

                    mediumWidthLines:
                        region.mediumWidthLines,

                    textRows:
                        regionRows,

                    textRowCount:
                        regionRows.length,

                    columns:
                        columnSummary

                };

            }
        );


    // ------------------------------------------------
    // Build region classification
    // ------------------------------------------------

    const classified27 =
        mappedRegions27.map(
            region => {

                const hasMultipleColumns =
                    region.columns.filter(
                        column =>
                            column.rowCount >
                            0
                    ).length >= 2;


                const hasDenseBorders =
                    region.boundaryCount >=
                    4;


                let type =
                    "bordered-section";


                if (
                    hasMultipleColumns &&
                    hasDenseBorders
                ) {

                    type =
                        "structured-grid";

                }


                return {

                    ...region,

                    type:
                        type

                };

            }
        );


    // ------------------------------------------------
    // Save
    // ------------------------------------------------

    window.pdfUniversalRegionColumnModel = {

        regions:
            classified27,

        columns:
            columns27,

        rows:
            rows27

    };


    // ------------------------------------------------
    // Output
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 27 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Regions:",
        classified27.length
    );

    console.log(
        "Logical Columns:",
        columns27.length
    );

    console.log(
        "Logical Rows:",
        rows27.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "REGION CLASSIFICATION"
    );

    console.log(
        "---------------------------------"
    );


    classified27.forEach(
        region => {

            console.log(
                `REGION ${region.regionIndex} | ` +
                `TYPE: ${region.type} | ` +
                `TOP: ${region.top.toFixed(2)} | ` +
                `BOTTOM: ${region.bottom.toFixed(2)} | ` +
                `BOUNDARIES: ${region.boundaryCount} | ` +
                `TEXT ROWS: ${region.textRowCount}`
            );


            region.columns.forEach(
                column => {

                    console.log(
                        `   COL ${column.columnIndex} | ` +
                        `ROWS: ${column.rowCount} | ` +
                        `ROW INDEXES: ${column.rowIndexes}`
                    );

                }
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 27 COMPLETE"
    );

    console.log(
        "================================="
    );

}






console.log("=================================");
console.log("STEP 28 START");
console.log("UNIVERSAL PHYSICAL COLUMN DETECTION");
console.log("=================================");

const reconstructed28 =
    window.pdfReconstructedBorders;

const logicalColumns28 =
    window.pdfUniversalLogicalTextColumns?.columns ||
    [];

if (
    !reconstructed28 ||
    !logicalColumns28.length
) {

    console.error(
        "Required border or logical column data not found."
    );

} else {

    // ------------------------------------------------
    // Get vertical border positions
    // ------------------------------------------------

    const vertical28 =
        reconstructed28.vertical?.positions ||
        [];


    const rawX28 =
        vertical28
            .map(
                item => item.x
            )
            .filter(
                x =>
                    Number.isFinite(x)
            )
            .sort(
                (a, b) =>
                    a - b
            );


    // ------------------------------------------------
    // Merge double/thick border edges
    // ------------------------------------------------

    const X_TOLERANCE_28 = 3;

    const physicalGroups28 = [];


    rawX28.forEach(x => {

        let group =
            physicalGroups28.find(
                g =>
                    Math.abs(
                        g.center -
                        x
                    ) <=
                    X_TOLERANCE_28
            );


        if (!group) {

            group = {

                center:
                    x,

                values: []

            };

            physicalGroups28.push(
                group
            );

        }


        group.values.push(x);


        group.center =
            group.values.reduce(
                (sum, value) =>
                    sum + value,
                0
            ) /
            group.values.length;

    });


    const physicalBorders28 =
        physicalGroups28
            .map(
                group => ({

                    x:
                        group.center,

                    edgeCount:
                        group.values.length

                })
            )
            .sort(
                (a, b) =>
                    a.x - b.x
            );


    // ------------------------------------------------
    // Build physical columns
    // ------------------------------------------------

    const physicalColumns28 = [];


    for (
        let i = 0;
        i <
        physicalBorders28.length - 1;
        i++
    ) {

        const left =
            physicalBorders28[i].x;

        const right =
            physicalBorders28[i + 1].x;


        if (
            right -
            left <
            10
        ) {

            continue;

        }


        physicalColumns28.push({

            index:
                physicalColumns28.length,

            left:
                left,

            right:
                right,

            width:
                right - left,

            leftEdgeCount:
                physicalBorders28[
                    i
                ].edgeCount,

            rightEdgeCount:
                physicalBorders28[
                    i + 1
                ].edgeCount

        });

    }


    // ------------------------------------------------
    // Compare logical text columns
    // ------------------------------------------------

    const columnComparison28 =
        logicalColumns28.map(
            logical => {

                let best =
                    null;

                let bestScore =
                    Infinity;


                physicalColumns28.forEach(
                    physical => {

                        const centerLogical =
                            (
                                logical.left +
                                logical.right
                            ) / 2;


                        const centerPhysical =
                            (
                                physical.left +
                                physical.right
                            ) / 2;


                        const score =
                            Math.abs(
                                centerLogical -
                                centerPhysical
                            );


                        if (
                            score <
                            bestScore
                        ) {

                            bestScore =
                                score;

                            best =
                                physical;

                        }

                    }
                );


                return {

                    logicalIndex:
                        logical.index,

                    logicalLeft:
                        logical.left,

                    logicalRight:
                        logical.right,

                    logicalWidth:
                        logical.right -
                        logical.left,

                    physicalIndex:
                        best
                            ? best.index
                            : null,

                    physicalLeft:
                        best
                            ? best.left
                            : null,

                    physicalRight:
                        best
                            ? best.right
                            : null,

                    physicalWidth:
                        best
                            ? best.width
                            : null,

                    centerDistance:
                        best
                            ? bestScore
                            : null

                };

            }
        );


    // ------------------------------------------------
    // Save
    // ------------------------------------------------

    window.pdfUniversalPhysicalColumns = {

        verticalBorders:
            physicalBorders28,

        columns:
            physicalColumns28,

        comparison:
            columnComparison28

    };


    // ------------------------------------------------
    // Output
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 28 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Raw Vertical X Positions:",
        rawX28.length
    );

    console.log(
        "Physical Vertical Borders:",
        physicalBorders28.length
    );

    console.log(
        "Physical Columns:",
        physicalColumns28.length
    );

    console.log(
        "Logical Text Columns:",
        logicalColumns28.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "PHYSICAL VERTICAL BORDERS"
    );

    console.log(
        "---------------------------------"
    );

    physicalBorders28.forEach(
        (border, index) => {

            console.log(
                `BORDER ${index + 1} | ` +
                `X: ${border.x.toFixed(2)} | ` +
                `EDGES: ${border.edgeCount}`
            );

        }
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "PHYSICAL COLUMNS"
    );

    console.log(
        "---------------------------------"
    );

    physicalColumns28.forEach(
        column => {

            console.log(
                `COL ${column.index} | ` +
                `X: ${column.left.toFixed(2)} -> ${column.right.toFixed(2)} | ` +
                `WIDTH: ${column.width.toFixed(2)}`
            );

        }
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "LOGICAL vs PHYSICAL"
    );

    console.log(
        "---------------------------------"
    );

    columnComparison28.forEach(
        item => {

            console.log(
                `LOGICAL ${item.logicalIndex} | ` +
                `X: ${item.logicalLeft.toFixed(2)} -> ${item.logicalRight.toFixed(2)} | ` +
                `PHYSICAL: ${item.physicalIndex} | ` +
                `X: ${
                    item.physicalLeft !== null
                        ? item.physicalLeft.toFixed(2)
                        : "N/A"
                } -> ${
                    item.physicalRight !== null
                        ? item.physicalRight.toFixed(2)
                        : "N/A"
                } | ` +
                `CENTER DIST: ${
                    item.centerDistance !== null
                        ? item.centerDistance.toFixed(2)
                        : "N/A"
                }`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 28 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 29 START");
console.log("UNIVERSAL PHYSICAL CELL + TEXT MAPPING");
console.log("=================================");

const physical29 =
    window.pdfUniversalPhysicalColumns;

const textRegions29 =
    window.pdfMergedTextRegions || [];

const logicalRows29 =
    window.pdfUniversalLabelValueRows?.rows || [];

if (
    !physical29?.columns?.length ||
    !textRegions29.length ||
    !logicalRows29.length
) {

    console.error(
        "Required Step 28 / text row data not found."
    );

} else {

    // ------------------------------------------------
    // Physical columns
    // ------------------------------------------------

    const physicalColumns =
        physical29.columns;


    // ------------------------------------------------
    // Map text to physical column
    // ------------------------------------------------

    const mappedText29 =
        textRegions29.map(
            region => {

                const centerX =
                    region.x +
                    region.width / 2;


                let bestColumn =
                    null;

                let bestScore =
                    Infinity;


                physicalColumns.forEach(
                    column => {

                        let score;


                        // Text center inside column
                        if (
                            centerX >= column.left &&
                            centerX <= column.right
                        ) {

                            const columnCenter =
                                (
                                    column.left +
                                    column.right
                                ) / 2;


                            score =
                                Math.abs(
                                    centerX -
                                    columnCenter
                                ) * 0.05;

                        }

                        else {

                            const distance =
                                centerX < column.left
                                    ? column.left - centerX
                                    : centerX - column.right;


                            score =
                                distance;

                        }


                        // Prefer actual text overlap
                        const overlapLeft =
                            Math.max(
                                region.x,
                                column.left
                            );


                        const overlapRight =
                            Math.min(
                                region.right,
                                column.right
                            );


                        const overlap =
                            Math.max(
                                0,
                                overlapRight -
                                overlapLeft
                            );


                        if (
                            overlap > 0
                        ) {

                            score -=
                                Math.min(
                                    overlap * 0.1,
                                    10
                                );

                        }


                        if (
                            score <
                            bestScore
                        ) {

                            bestScore =
                                score;

                            bestColumn =
                                column;

                        }

                    }
                );


                return {

                    ...region,

                    physicalColumn:
                        bestColumn
                            ? bestColumn.index
                            : null,

                    physicalColumnLeft:
                        bestColumn
                            ? bestColumn.left
                            : null,

                    physicalColumnRight:
                        bestColumn
                            ? bestColumn.right
                            : null,

                    mappingScore:
                        bestScore

                };

            }
        );


    // ------------------------------------------------
    // Group by logical text rows
    // ------------------------------------------------

    const finalRows29 =
        logicalRows29.map(
            logicalRow => {

                const rowRegions =
                    mappedText29.filter(
                        region =>
                            logicalRow.regions.some(
                                source =>
                                    source.index ===
                                    region.index
                            )
                    );


                const cells = {};


                physicalColumns.forEach(
                    column => {

                        cells[
                            column.index
                        ] = {

                            columnIndex:
                                column.index,

                            left:
                                column.left,

                            right:
                                column.right,

                            width:
                                column.width,

                            texts: []

                        };

                    }
                );


                rowRegions.forEach(
                    region => {

                        const columnIndex =
                            region.physicalColumn;


                        if (
                            columnIndex === null
                        ) {

                            return;

                        }


                        cells[
                            columnIndex
                        ].texts.push({

                            index:
                                region.index,

                            text:
                                region.text,

                            x:
                                region.x,

                            y:
                                region.y,

                            width:
                                region.width,

                            height:
                                region.height,

                            centerX:
                                region.x +
                                region.width / 2,

                            mappingScore:
                                region.mappingScore

                        });

                    }
                );


                return {

                    rowIndex:
                        logicalRow.index,

                    textTop:
                        logicalRow.textTop,

                    textBottom:
                        logicalRow.textBottom,

                    height:
                        logicalRow.height,

                    cells:
                        Object.values(
                            cells
                        )

                };

            }
        );


    // ------------------------------------------------
    // Detect text relationships
    // ------------------------------------------------

    finalRows29.forEach(
        row => {

            row.cells.forEach(
                cell => {

                    cell.texts.sort(
                        (a, b) =>
                            a.x -
                            b.x
                    );


                    cell.combinedText =
                        cell.texts
                            .map(
                                item =>
                                    item.text
                            )
                            .join(" ");

                }
            );

        }
    );


    // ------------------------------------------------
    // Save
    // ------------------------------------------------

    window.pdfUniversalPhysicalTextModel = {

        physicalColumns:
            physicalColumns,

        textRegions:
            mappedText29,

        rows:
            finalRows29

    };


    // ------------------------------------------------
    // Output
    // ------------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 29 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Physical Columns:",
        physicalColumns.length
    );

    console.log(
        "Text Regions:",
        mappedText29.length
    );

    console.log(
        "Logical Rows:",
        finalRows29.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "ROW → PHYSICAL COLUMN MAPPING"
    );

    console.log(
        "---------------------------------"
    );


    finalRows29.forEach(
        row => {

            const output =
                row.cells
                    .map(
                        cell =>
                            `COL ${cell.columnIndex}: ${
                                cell.combinedText ||
                                ""
                            }`
                    )
                    .join(" | ");


            console.log(
                `ROW ${row.rowIndex} | ${output}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 29 COMPLETE"
    );

    console.log(
        "================================="
    );

}






console.log("=================================");
console.log("STEP 29.1 START");
console.log("UNIVERSAL ROW IDENTITY FIX");
console.log("=================================");

const physical291 =
    window.pdfUniversalPhysicalColumns;

const text291 =
    window.pdfMergedTextRegions || [];

const rows291 =
    window.pdfUniversalLabelValueRows?.rows || [];

if (
    !physical291?.columns?.length ||
    !text291.length ||
    !rows291.length
) {

    console.error(
        "Required Step 28 / Step 22.5 data not found."
    );

} else {

    const columns =
        physical291.columns;


    // ---------------------------------------------
    // Create clean row boundaries from text geometry
    // ---------------------------------------------

    const cleanRows291 =
        rows291.map(
            (row, rowIndex) => {

                const sourceRegions =
                    text291.filter(
                        region => {

                            const centerY =
                                region.y +
                                region.height / 2;


                            const rowCenter =
                                row.y;


                            return Math.abs(
                                centerY -
                                (
                                    rowCenter +
                                    row.height / 2
                                )
                            ) <= 12;

                        }
                    );


                return {

                    rowIndex:
                        rowIndex + 1,

                    sourceY:
                        row.y,

                    sourceRegions:
                        sourceRegions

                };

            }
        );


    // ---------------------------------------------
    // IMPORTANT:
    // Direct nearest-row mapping
    // ---------------------------------------------

    const mappedText291 =
        text291.map(
            region => {

                const centerY =
                    region.y +
                    region.height / 2;


                let bestRow =
                    null;

                let bestDistance =
                    Infinity;


                cleanRows291.forEach(
                    row => {

                        const rowCenter =
                            row.sourceRegions.length
                                ? row.sourceRegions.reduce(
                                    (
                                        sum,
                                        item
                                    ) =>
                                        sum +
                                        item.y +
                                        item.height / 2,
                                    0
                                ) /
                                row.sourceRegions.length
                                : row.sourceY;


                        const distance =
                            Math.abs(
                                centerY -
                                rowCenter
                            );


                        if (
                            distance <
                            bestDistance
                        ) {

                            bestDistance =
                                distance;

                            bestRow =
                                row;

                        }

                    }
                );


                // ---------------------------------
                // Physical column mapping
                // ---------------------------------

                const centerX =
                    region.x +
                    region.width / 2;


                let bestColumn =
                    null;

                let bestColumnDistance =
                    Infinity;


                columns.forEach(
                    column => {

                        let distance;


                        if (
                            centerX >=
                                column.left &&
                            centerX <=
                                column.right
                        ) {

                            distance = 0;

                        } else if (
                            centerX <
                            column.left
                        ) {

                            distance =
                                column.left -
                                centerX;

                        } else {

                            distance =
                                centerX -
                                column.right;

                        }


                        if (
                            distance <
                            bestColumnDistance
                        ) {

                            bestColumnDistance =
                                distance;

                            bestColumn =
                                column;

                        }

                    }
                );


                return {

                    index:
                        region.index,

                    text:
                        region.text,

                    x:
                        region.x,

                    y:
                        region.y,

                    width:
                        region.width,

                    height:
                        region.height,

                    rowIndex:
                        bestRow
                            ? bestRow.rowIndex
                            : null,

                    physicalColumn:
                        bestColumn
                            ? bestColumn.index
                            : null

                };

            }
        );


    // ---------------------------------------------
    // Build final clean rows
    // ---------------------------------------------

    const finalRows291 =
        cleanRows291.map(
            row => {

                const rowTexts =
                    mappedText291.filter(
                        item =>
                            item.rowIndex ===
                            row.rowIndex
                    );


                const cells =
                    columns.map(
                        column => {

                            const cellTexts =
                                rowTexts
                                    .filter(
                                        item =>
                                            item.physicalColumn ===
                                            column.index
                                    )
                                    .sort(
                                        (
                                            a,
                                            b
                                        ) =>
                                            a.x -
                                            b.x
                                    );


                            return {

                                columnIndex:
                                    column.index,

                                left:
                                    column.left,

                                right:
                                    column.right,

                                width:
                                    column.width,

                                texts:
                                    cellTexts,

                                combinedText:
                                    cellTexts
                                        .map(
                                            item =>
                                                item.text
                                        )
                                        .join(" ")

                            };

                        }
                    );


                return {

                    rowIndex:
                        row.rowIndex,

                    sourceY:
                        row.sourceY,

                    cells:
                        cells

                };

            }
        );


    // ---------------------------------------------
    // Save
    // ---------------------------------------------

    window.pdfUniversalFixedPhysicalModel = {

        columns:
            columns,

        textRegions:
            mappedText291,

        rows:
            finalRows291

    };


    // ---------------------------------------------
    // Output
    // ---------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 29.1 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Physical Columns:",
        columns.length
    );

    console.log(
        "Text Regions:",
        mappedText291.length
    );

    console.log(
        "Rows:",
        finalRows291.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "CLEAN ROW MAPPING"
    );

    console.log(
        "---------------------------------"
    );


    finalRows291.forEach(
        row => {

            const output =
                row.cells
                    .map(
                        cell =>
                            `COL ${cell.columnIndex}: ${
                                cell.combinedText ||
                                ""
                            }`
                    )
                    .join(" | ");


            console.log(
                `ROW ${row.rowIndex} | ${output}`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 29.1 COMPLETE"
    );

    console.log(
        "================================="
    );

}





