console.log("=================================");
console.log("STEP 29.3 START");
console.log("UNIVERSAL MASTER ROW MAPPING");
console.log("=================================");

const sourceRegions293 =
    window.pdfMergedTextRegions || [];

const logicalRows293 =
    window.pdfUniversalLabelValueRows?.rows || [];

const physicalColumns293 =
    window.pdfUniversalPhysicalColumns?.columns || [];


if (
    !sourceRegions293.length ||
    !logicalRows293.length ||
    !physicalColumns293.length
) {

    console.error(
        "Required Step 15 / Step 22.5 / Step 28 data not found."
    );

} else {

    // ---------------------------------------------
    // Build row centers directly from their regions
    // ---------------------------------------------

    const rowModels293 =
        logicalRows293.map(
            (row, rowIndex) => {

                const regions =
                    Array.isArray(row.regions)
                        ? row.regions
                        : [];


                const validRegions =
                    regions.filter(
                        region =>
                            Number.isFinite(
                                region.y
                            )
                    );


                const centerY =
                    validRegions.length
                        ? validRegions.reduce(
                            (
                                sum,
                                region
                            ) =>
                                sum +
                                region.y +
                                region.height / 2,
                            0
                        ) /
                        validRegions.length
                        : null;


                return {

                    rowIndex:
                        rowIndex + 1,

                    centerY:
                        centerY,

                    regionCount:
                        validRegions.length

                };

            }
        );


    // ---------------------------------------------
    // Map every ORIGINAL text region to nearest row
    // ---------------------------------------------

    const mappedRegions293 =
        sourceRegions293.map(
            (region, sourceIndex) => {

                const centerY =
                    region.y +
                    region.height / 2;


                let bestRow =
                    null;

                let bestDistance =
                    Infinity;


                rowModels293.forEach(
                    row => {

                        if (
                            row.centerY === null
                        ) {

                            return;

                        }


                        const distance =
                            Math.abs(
                                centerY -
                                row.centerY
                            );


                        if (
                            distance <
                            bestDistance
                        ) {

                            bestDistance =
                                distance;

                            bestRow =
                                row;

                        }

                    }
                );


                // ---------------------------------
                // Physical column
                // ---------------------------------

                const centerX =
                    region.x +
                    region.width / 2;


                let bestColumn =
                    null;

                let bestColumnDistance =
                    Infinity;


                physicalColumns293.forEach(
                    column => {

                        let distance;


                        if (
                            centerX >=
                                column.left &&
                            centerX <=
                                column.right
                        ) {

                            distance = 0;

                        } else if (
                            centerX <
                            column.left
                        ) {

                            distance =
                                column.left -
                                centerX;

                        } else {

                            distance =
                                centerX -
                                column.right;

                        }


                        if (
                            distance <
                            bestColumnDistance
                        ) {

                            bestColumnDistance =
                                distance;

                            bestColumn =
                                column;

                        }

                    }
                );


                return {

                    sourceIndex:
                        sourceIndex,

                    text:
                        region.text,

                    x:
                        region.x,

                    y:
                        region.y,

                    width:
                        region.width,

                    height:
                        region.height,

                    centerX:
                        centerX,

                    centerY:
                        centerY,

                    rowIndex:
                        bestRow
                            ? bestRow.rowIndex
                            : null,

                    rowDistance:
                        bestDistance,

                    physicalColumn:
                        bestColumn
                            ? bestColumn.index
                            : null

                };

            }
        );


    // ---------------------------------------------
    // Build final master rows
    // ---------------------------------------------

    const masterRows293 =
        rowModels293.map(
            row => {

                const rowRegions =
                    mappedRegions293
                        .filter(
                            region =>
                                region.rowIndex ===
                                row.rowIndex
                        )
                        .sort(
                            (a, b) =>
                                a.x -
                                b.x
                        );


                return {

                    rowIndex:
                        row.rowIndex,

                    centerY:
                        row.centerY,

                    regions:
                        rowRegions,

                    text:
                        rowRegions
                            .map(
                                region =>
                                    region.text
                            )
                            .join(" | ")

                };

            }
        );


    // ---------------------------------------------
    // Save master model
    // ---------------------------------------------

    window.pdfUniversalMasterRowModel = {

        rows:
            masterRows293,

        regions:
            mappedRegions293,

        physicalColumns:
            physicalColumns293

    };


    // ---------------------------------------------
    // Output
    // ---------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 29.3 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Source Regions:",
        sourceRegions293.length
    );

    console.log(
        "Master Rows:",
        masterRows293.length
    );

    console.log(
        "Mapped Regions:",
        mappedRegions293.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "MASTER ROW MODEL"
    );

    console.log(
        "---------------------------------"
    );


    masterRows293.forEach(
        row => {

            const columns =
                row.regions
                    .map(
                        region =>
                            `COL ${
                                region.physicalColumn
                            }: ${
                                region.text
                            }`
                    )
                    .join(" | ");


            console.log(
                `ROW ${row.rowIndex} | ` +
                `${columns}`
            );

        }
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "MAPPING CHECK"
    );

    console.log(
        "---------------------------------"
    );


    mappedRegions293.forEach(
        region => {

            console.log(
                `TEXT: ${
                    region.text
                } | ` +
                `ROW: ${
                    region.rowIndex
                } | ` +
                `COL: ${
                    region.physicalColumn
                } | ` +
                `ROW DIST: ${
                    region.rowDistance.toFixed(2)
                }`
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 29.3 COMPLETE"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 30 START");
console.log("UNIVERSAL ROW COORDINATE MODEL");
console.log("=================================");

const master30 =
    window.pdfUniversalMasterRowModel;

const page30 =
    window.pdfLayoutAnalysis?.pages?.[0];

if (
    !master30?.rows?.length ||
    !master30?.regions?.length ||
    !page30
) {

    console.error(
        "Step 29.3 / page geometry data not found."
    );

} else {

    // ---------------------------------------------
    // Page geometry
    // ---------------------------------------------

    const pageWidth =
        page30.width;

    const pageHeight =
        page30.height;


    // ---------------------------------------------
    // Build coordinate rows
    // ---------------------------------------------

    const coordinateRows30 =
        master30.rows.map(
            row => {

                const regions =
                    row.regions
                        .map(
                            region => ({

                                sourceIndex:
                                    region.sourceIndex,

                                text:
                                    region.text,

                                x:
                                    region.x,

                                y:
                                    region.y,

                                width:
                                    region.width,

                                height:
                                    region.height,

                                right:
                                    region.x +
                                    region.width,

                                bottom:
                                    region.y +
                                    region.height,

                                centerX:
                                    region.x +
                                    region.width / 2,

                                centerY:
                                    region.y +
                                    region.height / 2,

                                physicalColumn:
                                    region.physicalColumn

                            })
                        )
                        .sort(
                            (a, b) =>
                                a.x -
                                b.x
                        );


                // ---------------------------------
                // Row bounding box
                // ---------------------------------

                const minX =
                    regions.length
                        ? Math.min(
                            ...regions.map(
                                item =>
                                    item.x
                            )
                        )
                        : 0;


                const maxX =
                    regions.length
                        ? Math.max(
                            ...regions.map(
                                item =>
                                    item.right
                            )
                        )
                        : 0;


                const minY =
                    regions.length
                        ? Math.min(
                            ...regions.map(
                                item =>
                                    item.y
                            )
                        )
                        : 0;


                const maxY =
                    regions.length
                        ? Math.max(
                            ...regions.map(
                                item =>
                                    item.bottom
                            )
                        )
                        : 0;


                return {

                    rowIndex:
                        row.rowIndex,

                    centerY:
                        row.centerY,

                    bounds: {

                        x:
                            minX,

                        y:
                            minY,

                        width:
                            maxX -
                            minX,

                        height:
                            maxY -
                            minY

                    },

                    regions:
                        regions

                };

            }
        );


    // ---------------------------------------------
    // Page normalized coordinates
    // ---------------------------------------------

    coordinateRows30.forEach(
        row => {

            row.regions.forEach(
                region => {

                    region.normalized = {

                        x:
                            region.x /
                            pageWidth,

                        y:
                            region.y /
                            pageHeight,

                        width:
                            region.width /
                            pageWidth,

                        height:
                            region.height /
                            pageHeight

                    };

                }
            );

        }
    );


    // ---------------------------------------------
    // Save
    // ---------------------------------------------

    window.pdfUniversalCoordinateModel = {

        page: {

            width:
                pageWidth,

            height:
                pageHeight

        },

        rows:
            coordinateRows30,

        regions:
            master30.regions

    };


    // ---------------------------------------------
    // Output
    // ---------------------------------------------

    console.log(
        "================================="
    );

    console.log(
        "STEP 30 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Page Width:",
        pageWidth
    );

    console.log(
        "Page Height:",
        pageHeight
    );

    console.log(
        "Rows:",
        coordinateRows30.length
    );

    console.log(
        "Text Regions:",
        master30.regions.length
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "ROW COORDINATE MODEL"
    );

    console.log(
        "---------------------------------"
    );


    coordinateRows30.forEach(
        row => {

            console.log(
                `ROW ${row.rowIndex} | ` +
                `REGIONS: ${row.regions.length} | ` +
                `X: ${row.bounds.x.toFixed(2)} | ` +
                `Y: ${row.bounds.y.toFixed(2)} | ` +
                `W: ${row.bounds.width.toFixed(2)} | ` +
                `H: ${row.bounds.height.toFixed(2)}`
            );


            row.regions.forEach(
                region => {

                    console.log(
                        `   TEXT: ${
                            region.text
                        } | ` +
                        `X: ${
                            region.x.toFixed(2)
                        } | ` +
                        `Y: ${
                            region.y.toFixed(2)
                        } | ` +
                        `W: ${
                            region.width.toFixed(2)
                        } | ` +
                        `H: ${
                            region.height.toFixed(2)
                        }`
                    );

                }
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 30 COMPLETE"
    );

    console.log(
        "================================="
    );

}






console.log("=================================");
console.log("STEP 31 START");
console.log("UNIVERSAL TEXT + BORDER LAYOUT MODEL");
console.log("=================================");

const coordinateModel31 =
    window.pdfUniversalCoordinateModel;

const borderModel31 =
    window.pdfUniversalBorderRegions;

if (
    !coordinateModel31?.rows?.length ||
    !borderModel31?.regions?.length
) {

    console.error(
        "Step 30 coordinate model or border region model not found."
    );

} else {

    const pageWidth31 =
        coordinateModel31.page.width;

    const pageHeight31 =
        coordinateModel31.page.height;

    const textRegions31 =
        coordinateModel31.rows.flatMap(
            row => row.regions
        );

    /*
     * ---------------------------------
     * Helper: vertical overlap
     * ---------------------------------
     */

    function verticalOverlap31(a, b) {

        const top =
            Math.max(
                a.y,
                b.y
            );

        const bottom =
            Math.min(
                a.bottom,
                b.bottom
            );

        return Math.max(
            0,
            bottom - top
        );
    }

    /*
     * ---------------------------------
     * Helper: horizontal overlap
     * ---------------------------------
     */

    function horizontalOverlap31(a, b) {

        const left =
            Math.max(
                a.x,
                b.x
            );

        const right =
            Math.min(
                a.right,
                b.right
            );

        return Math.max(
            0,
            right - left
        );
    }

    /*
     * ---------------------------------
     * Normalize border region
     * ---------------------------------
     */

    const borderRegions31 =
        borderModel31.regions.map(
            (region, index) => {

                const top =
                    Math.max(
                        region.top,
                        region.bottom
                    );

                const bottom =
                    Math.min(
                        region.top,
                        region.bottom
                    );

                const height =
                    top - bottom;

                const textInside =
                    textRegions31.filter(
                        text => {

                            const centerX =
                                text.x +
                                text.width / 2;

                            const centerY =
                                text.y +
                                text.height / 2;

                            return (
                                centerX >= region.left &&
                                centerX <= region.right &&
                                centerY <= top &&
                                centerY >= bottom
                            );

                        }
                    );

                return {

                    regionIndex:
                        index + 1,

                    top:
                        top,

                    bottom:
                        bottom,

                    left:
                        region.left,

                    right:
                        region.right,

                    width:
                        region.right -
                        region.left,

                    height:
                        height,

                    boundaryCount:
                        region.boundaries
                            ?.length || 0,

                    textCount:
                        textInside.length,

                    textRegions:
                        textInside

                };

            }
        );

    /*
     * ---------------------------------
     * Match each text region
     * to nearest border region
     * ---------------------------------
     */

    const mappedText31 =
        textRegions31.map(
            text => {

                const centerX =
                    text.x +
                    text.width / 2;

                const centerY =
                    text.y +
                    text.height / 2;

                let bestRegion =
                    null;

                let bestDistance =
                    Infinity;

                borderRegions31.forEach(
                    region => {

                        const inside =
                            centerX >= region.left &&
                            centerX <= region.right &&
                            centerY <= region.top &&
                            centerY >= region.bottom;

                        if (inside) {

                            bestRegion = region;

                            bestDistance = 0;

                            return;

                        }

                        const dx =
                            centerX < region.left
                                ? region.left - centerX
                                : centerX > region.right
                                    ? centerX - region.right
                                    : 0;

                        const dy =
                            centerY > region.top
                                ? centerY - region.top
                                : centerY < region.bottom
                                    ? region.bottom - centerY
                                    : 0;

                        const distance =
                            Math.sqrt(
                                dx * dx +
                                dy * dy
                            );

                        if (
                            distance <
                            bestDistance
                        ) {

                            bestDistance =
                                distance;

                            bestRegion =
                                region;

                        }

                    }
                );

                return {

                    ...text,

                    matchedRegion:
                        bestRegion
                            ? bestRegion.regionIndex
                            : null,

                    regionDistance:
                        bestDistance

                };

            }
        );

    /*
     * ---------------------------------
     * Build final universal rows
     * ---------------------------------
     */

    const layoutRows31 =
        coordinateModel31.rows.map(
            row => {

                const rowTexts =
                    mappedText31.filter(
                        text =>
                            text.sourceIndex !==
                            undefined &&
                            row.regions.some(
                                source =>
                                    source.sourceIndex ===
                                    text.sourceIndex
                            )
                    );

                return {

                    rowIndex:
                        row.rowIndex,

                    centerY:
                        row.centerY,

                    bounds:
                        row.bounds,

                    textCount:
                        rowTexts.length,

                    texts:
                        rowTexts

                };

            }
        );

    /*
     * ---------------------------------
     * Layout type detection
     * ---------------------------------
     */

    const detectedRegions31 =
        borderRegions31.map(
            region => {

                const regionTexts =
                    mappedText31.filter(
                        text =>
                            text.matchedRegion ===
                            region.regionIndex
                    );

                const uniqueRows =
                    new Set(
                        regionTexts.map(
                            text => {

                                const nearestRow =
                                    layoutRows31.reduce(
                                        (
                                            best,
                                            current
                                        ) => {

                                            const currentDistance =
                                                Math.abs(
                                                    current.centerY -
                                                    (
                                                        text.y +
                                                        text.height / 2
                                                    )
                                                );

                                            const bestDistance =
                                                best
                                                    ? Math.abs(
                                                        best.centerY -
                                                        (
                                                            text.y +
                                                            text.height / 2
                                                        )
                                                    )
                                                    : Infinity;

                                            return currentDistance <
                                                bestDistance
                                                ? current
                                                : best;

                                        },
                                        null
                                    );

                                return nearestRow
                                    ? nearestRow.rowIndex
                                    : null;

                            }
                        )
                    );

                let layoutType =
                    "bordered-section";

                if (
                    region.boundaryCount >= 6 &&
                    uniqueRows.size >= 3
                ) {

                    layoutType =
                        "structured-region";

                }

                return {

                    ...region,

                    detectedLayoutType:
                        layoutType,

                    detectedTextCount:
                        regionTexts.length,

                    detectedRowCount:
                        uniqueRows.size

                };

            }
        );

    /*
     * ---------------------------------
     * Final universal model
     * ---------------------------------
     */

    window.pdfUniversalLayoutModel = {

        page: {

            width:
                pageWidth31,

            height:
                pageHeight31

        },

        regions:
            detectedRegions31,

        rows:
            layoutRows31,

        textRegions:
            mappedText31

    };

    /*
     * ---------------------------------
     * Console diagnostics
     * ---------------------------------
     */

    console.log(
        "================================="
    );

    console.log(
        "STEP 31 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Page Width:",
        pageWidth31
    );

    console.log(
        "Page Height:",
        pageHeight31
    );

    console.log(
        "Border Regions:",
        detectedRegions31.length
    );

    console.log(
        "Logical Rows:",
        layoutRows31.length
    );

    console.log(
        "Text Regions:",
        mappedText31.length
    );

    console.log(
        "---------------------------------"
    );

    console.log(
        "DETECTED LAYOUT REGIONS"
    );

    console.log(
        "---------------------------------"
    );

   detectedRegions31.forEach(
    region => {

        const left =
            Number.isFinite(region.left)
                ? region.left.toFixed(2)
                : "N/A";

        const right =
            Number.isFinite(region.right)
                ? region.right.toFixed(2)
                : "N/A";

        const top =
            Number.isFinite(region.top)
                ? region.top.toFixed(2)
                : "N/A";

        const bottom =
            Number.isFinite(region.bottom)
                ? region.bottom.toFixed(2)
                : "N/A";

        const width =
            Number.isFinite(region.width)
                ? region.width.toFixed(2)
                : "N/A";

        const height =
            Number.isFinite(region.height)
                ? region.height.toFixed(2)
                : "N/A";

        console.log(
            `REGION ${region.regionIndex} | ` +
            `TYPE: ${region.detectedLayoutType} | ` +
            `X: ${left} -> ${right} | ` +
            `Y: ${bottom} -> ${top} | ` +
            `W: ${width} | ` +
            `H: ${height} | ` +
            `BORDERS: ${region.boundaryCount} | ` +
            `TEXT: ${region.detectedTextCount} | ` +
            `ROWS: ${region.detectedRowCount}`
        );

    }
);

    console.log(
        "---------------------------------"
    );

    console.log(
        "TEXT → REGION MAPPING"
    );

    console.log(
        "---------------------------------"
    );

    mappedText31.forEach(
        text => {

            console.log(
                `TEXT: ${text.text} | ` +
                `REGION: ${text.matchedRegion} | ` +
                `DIST: ${text.regionDistance.toFixed(2)}`
            );

        }
    );

    console.log(
        "================================="
    );

    console.log(
        "STEP 31 COMPLETE"
    );

    console.log(
        "================================="
    );

}




