console.log("=================================");
console.log("STEP 33 START");
console.log("UNIVERSAL ACTUAL BORDER GEOMETRY");
console.log("=================================");

const analysis33 =
    window.pdfLayoutAnalysis;

const borderRegions33 =
    window.pdfUniversalBorderRegions;

if (
    !analysis33?.pages?.length ||
    !borderRegions33?.regions?.length
) {

    console.error(
        "Required PDF geometry data not found."
    );

} else {

    const page33 =
        analysis33.pages[0];

    const allGraphics33 =
        page33.graphics || [];

    /*
     * ---------------------------------
     * Collect path geometry
     * ---------------------------------
     */

    const pathObjects33 =
        allGraphics33.filter(
            item =>
                item.type === "path"
        );

    console.log(
        "Total Path Objects:",
        pathObjects33.length
    );

    /*
     * ---------------------------------
     * Extract numeric coordinates
     * ---------------------------------
     *
     * PDF.js constructPath arguments
     * can contain operators + coordinate
     * arrays, so we recursively inspect
     * numeric values.
     */

    function collectNumbers33(
        value,
        output = []
    ) {

        if (
            typeof value ===
            "number" &&
            Number.isFinite(value)
        ) {

            output.push(value);

        } else if (
            Array.isArray(value)
        ) {

            value.forEach(
                item =>
                    collectNumbers33(
                        item,
                        output
                    )
            );

        }

        return output;

    }

    /*
     * ---------------------------------
     * Build coordinate ranges
     * ---------------------------------
     */

    const geometry33 = [];

    pathObjects33.forEach(
        (path, pathIndex) => {

            const numbers =
                collectNumbers33(
                    path.args
                );

            if (
                numbers.length < 4
            ) {
                return;
            }

            const xs = [];
            const ys = [];

            /*
             * We only use plausible PDF
             * page coordinates.
             */

            numbers.forEach(
                (value, index) => {

                    if (
                        value >= -5 &&
                        value <=
                        page33.width + 5
                    ) {

                        if (
                            index % 2 === 0
                        ) {

                            xs.push(value);

                        }

                    }

                    if (
                        value >= -5 &&
                        value <=
                        page33.height + 5
                    ) {

                        if (
                            index % 2 === 1
                        ) {

                            ys.push(value);

                        }

                    }

                }
            );

            if (
                xs.length < 2 ||
                ys.length < 2
            ) {
                return;
            }

            const minX =
                Math.min(...xs);

            const maxX =
                Math.max(...xs);

            const minY =
                Math.min(...ys);

            const maxY =
                Math.max(...ys);

            const width =
                maxX - minX;

            const height =
                maxY - minY;

            /*
             * Keep only geometry that
             * resembles a page border,
             * divider or box.
             */

            if (
                width >= 20 ||
                height >= 20
            ) {

                geometry33.push({

                    pathIndex,

                    minX,
                    maxX,
                    minY,
                    maxY,

                    width,
                    height

                });

            }

        }
    );

    /*
     * ---------------------------------
     * Find overall border bounds
     * ---------------------------------
     */

    const allX33 =
        geometry33.flatMap(
            item => [
                item.minX,
                item.maxX
            ]
        );

    const allY33 =
        geometry33.flatMap(
            item => [
                item.minY,
                item.maxY
            ]
        );

    const globalMinX33 =
        allX33.length
            ? Math.min(...allX33)
            : 0;

    const globalMaxX33 =
        allX33.length
            ? Math.max(...allX33)
            : page33.width;

    const globalMinY33 =
        allY33.length
            ? Math.min(...allY33)
            : 0;

    const globalMaxY33 =
        allY33.length
            ? Math.max(...allY33)
            : page33.height;

    /*
     * ---------------------------------
     * Match border regions using Y
     * ---------------------------------
     */

    const actualRegions33 =
        borderRegions33.regions.map(
            (region, index) => {

                const top =
                    Math.max(
                        region.top,
                        region.bottom
                    );

                const bottom =
                    Math.min(
                        region.top,
                        region.bottom
                    );

                const matchingGeometry =
                    geometry33.filter(
                        item => {

                            const centerY =
                                (
                                    item.minY +
                                    item.maxY
                                ) / 2;

                            const overlap =
                                centerY >=
                                    bottom - 5 &&
                                centerY <=
                                    top + 5;

                            return overlap;

                        }
                    );

                const regionX =
                    matchingGeometry.length
                        ? matchingGeometry.flatMap(
                            item => [
                                item.minX,
                                item.maxX
                            ]
                        )
                        : [];

                const regionY =
                    matchingGeometry.length
                        ? matchingGeometry.flatMap(
                            item => [
                                item.minY,
                                item.maxY
                            ]
                        )
                        : [];

                const left =
                    regionX.length
                        ? Math.min(
                            ...regionX
                        )
                        : globalMinX33;

                const right =
                    regionX.length
                        ? Math.max(
                            ...regionX
                        )
                        : globalMaxX33;

                const actualBottom =
                    regionY.length
                        ? Math.min(
                            ...regionY
                        )
                        : bottom;

                const actualTop =
                    regionY.length
                        ? Math.max(
                            ...regionY
                        )
                        : top;

                return {

                    regionIndex:
                        index + 1,

                    top:
                        actualTop,

                    bottom:
                        actualBottom,

                    left:
                        left,

                    right:
                        right,

                    width:
                        right - left,

                    height:
                        actualTop -
                        actualBottom,

                    geometryCount:
                        matchingGeometry.length,

                    geometry:
                        matchingGeometry

                };

            }
        );

    /*
     * ---------------------------------
     * Save model
     * ---------------------------------
     */

    window.pdfUniversalActualBorderModel = {

        page: {

            width:
                page33.width,

            height:
                page33.height

        },

        regions:
            actualRegions33,

        geometry:
            geometry33

    };

    /*
     * ---------------------------------
     * RESULT
     * ---------------------------------
     */

    console.log(
        "================================="
    );

    console.log(
        "STEP 33 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Page Width:",
        page33.width
    );

    console.log(
        "Page Height:",
        page33.height
    );

    console.log(
        "Usable Geometry:",
        geometry33.length
    );

    console.log(
        "Actual Border Regions:",
        actualRegions33.length
    );

    console.log(
        "---------------------------------"
    );

    actualRegions33.forEach(
        region => {

            console.log(
                `REGION ${region.regionIndex} | ` +
                `X: ${
                    Number.isFinite(
                        region.left
                    )
                        ? region.left.toFixed(2)
                        : "N/A"
                } -> ${
                    Number.isFinite(
                        region.right
                    )
                        ? region.right.toFixed(2)
                        : "N/A"
                } | ` +
                `Y: ${
                    Number.isFinite(
                        region.bottom
                    )
                        ? region.bottom.toFixed(2)
                        : "N/A"
                } -> ${
                    Number.isFinite(
                        region.top
                    )
                        ? region.top.toFixed(2)
                        : "N/A"
                } | ` +
                `W: ${
                    Number.isFinite(
                        region.width
                    )
                        ? region.width.toFixed(2)
                        : "N/A"
                } | ` +
                `H: ${
                    Number.isFinite(
                        region.height
                    )
                        ? region.height.toFixed(2)
                        : "N/A"
                } | ` +
                `GEOMETRY: ${
                    region.geometryCount
                }`
            );

        }
    );

    console.log(
        "================================="
    );

    console.log(
        "STEP 33 COMPLETE"
    );

    console.log(
        "================================="
    );

}






