console.log("=================================");
console.log("STEP 40 START");
console.log("UNIVERSAL STRUCTURE DETECTION");
console.log("=================================");

const model40 =
    window.pdfUniversalLayoutPrimitiveModel;

if (
    !model40 ||
    !model40.page ||
    !Array.isArray(model40.text) ||
    !Array.isArray(model40.horizontalBorders) ||
    !Array.isArray(model40.verticalBorders)
) {

    console.error(
        "Step 39 layout primitive model not found."
    );

} else {

    const page40 =
        model40.page;

    const text40 =
        model40.text;

    const horizontal40 =
        model40.horizontalBorders;

    const vertical40 =
        model40.verticalBorders;


    /*
     * =================================
     * 1. UNIQUE HORIZONTAL Y LEVELS
     * =================================
     */

    const yLevels40 = [];

    horizontal40.forEach(
        line => {

            const y =
                Number(line.y);

            if (!Number.isFinite(y)) {
                return;
            }

            const existing =
                yLevels40.find(
                    value =>
                        Math.abs(value - y) < 0.75
                );

            if (
                existing === undefined
            ) {

                yLevels40.push(y);

            }

        }
    );

    yLevels40.sort(
        (a, b) =>
            b - a
    );


    /*
     * =================================
     * 2. CREATE BORDER BANDS
     * =================================
     *
     * A border band is the area between
     * two nearby horizontal borders.
     */

    const bands40 = [];

    for (
        let i = 0;
        i < yLevels40.length - 1;
        i++
    ) {

        const top =
            yLevels40[i];

        const bottom =
            yLevels40[i + 1];

        const height =
            top - bottom;

        if (
            height <= 0 ||
            height > 150
        ) {
            continue;
        }

        const topLines =
            horizontal40.filter(
                line =>
                    Math.abs(
                        line.y - top
                    ) < 0.75
            );

        const bottomLines =
            horizontal40.filter(
                line =>
                    Math.abs(
                        line.y - bottom
                    ) < 0.75
            );

        const topLine =
            topLines.length
                ? topLines[0]
                : null;

        const bottomLine =
            bottomLines.length
                ? bottomLines[0]
                : null;

        if (
            !topLine ||
            !bottomLine
        ) {
            continue;
        }

        const left =
            Math.max(
                topLine.x1,
                bottomLine.x1
            );

        const right =
            Math.min(
                topLine.x2,
                bottomLine.x2
            );

        const width =
            right - left;

        if (width <= 0) {
            continue;
        }

        bands40.push({

            top:
                top,

            bottom:
                bottom,

            height:
                height,

            left:
                left,

            right:
                right,

            width:
                width,

            topType:
                topLine.lineType,

            bottomType:
                bottomLine.lineType

        });

    }


    /*
     * =================================
     * 3. TEXT INSIDE EACH BAND
     * =================================
     */

    bands40.forEach(
        (band, index) => {

            const insideText =
                text40.filter(
                    item => {

                        const centerY =
                            item.centerY;

                        const centerX =
                            item.centerX;

                        return (

                            centerY <
                                band.top + 0.75 &&

                            centerY >
                                band.bottom - 0.75 &&

                            centerX >=
                                band.left - 2 &&

                            centerX <=
                                band.right + 2

                        );

                    }
                );

            band.index =
                index + 1;

            band.textCount =
                insideText.length;

            band.textIndexes =
                insideText.map(
                    item =>
                        item.sourceIndex
                );

            band.texts =
                insideText.map(
                    item =>
                        item.text
                );

        }
    );


    /*
     * =================================
     * 4. VERTICAL BORDER INTERSECTIONS
     * =================================
     */

    bands40.forEach(
        band => {

            const intersections =
                vertical40.filter(
                    vertical => {

                        const x =
                            Number(
                                vertical.x
                            );

                        return (

                            x >=
                                band.left - 2 &&

                            x <=
                                band.right + 2

                        );

                    }
                );

            band.verticalBorderCount =
                intersections.length;

            band.verticalBorderXs =
                intersections.map(
                    item =>
                        item.x
                );

        }
    );


    /*
     * =================================
     * 5. STRUCTURE CLASSIFICATION
     * =================================
     */

    bands40.forEach(
        band => {

            let score = 0;

            /*
             * Horizontal boundaries
             */

            if (
                band.topType ===
                "full-width"
            ) {
                score += 2;
            }

            if (
                band.bottomType ===
                "full-width"
            ) {
                score += 2;
            }

            /*
             * Medium/value-area geometry
             */

            if (
                band.topType ===
                "medium-width"
            ) {
                score += 1;
            }

            if (
                band.bottomType ===
                "medium-width"
            ) {
                score += 1;
            }

            /*
             * Vertical structure
             */

            if (
                band.verticalBorderCount >= 2
            ) {
                score += 3;
            }

            /*
             * Text
             */

            if (
                band.textCount > 0
            ) {
                score += 2;
            }

            if (
                band.textCount >= 2
            ) {
                score += 1;
            }

            band.structureScore =
                score;

            if (
                score >= 7
            ) {

                band.structureType =
                    "structured-grid";

            } else if (
                score >= 4
            ) {

                band.structureType =
                    "structured-row";

            } else {

                band.structureType =
                    "open-layout";

            }

        }
    );


    /*
     * =================================
     * 6. GROUP CONTIGUOUS STRUCTURED BANDS
     * =================================
     */

    const structuredBands40 =
        bands40.filter(
            band =>
                band.structureType !==
                "open-layout"
        );

    const structures40 = [];

    structuredBands40.forEach(
        band => {

            const previous =
                structures40[
                    structures40.length - 1
                ];

            if (
                previous &&
                Math.abs(
                    previous.bottom -
                    band.top
                ) < 1
            ) {

                previous.bottom =
                    band.bottom;

                previous.height =
                    previous.top -
                    previous.bottom;

                previous.bandIndexes.push(
                    band.index
                );

                previous.textCount +=
                    band.textCount;

                previous.structureScore +=
                    band.structureScore;

            } else {

                structures40.push({

                    structureIndex:
                        structures40.length + 1,

                    top:
                        band.top,

                    bottom:
                        band.bottom,

                    height:
                        band.height,

                    bandIndexes:
                        [band.index],

                    textCount:
                        band.textCount,

                    structureScore:
                        band.structureScore

                });

            }

        }
    );


    /*
     * =================================
     * 7. STRUCTURE CONFIDENCE
     * =================================
     */

    structures40.forEach(
        structure => {

            const score =
                structure.structureScore;

            if (
                score >= 20
            ) {

                structure.confidence =
                    "high";

            } else if (
                score >= 10
            ) {

                structure.confidence =
                    "medium";

            } else {

                structure.confidence =
                    "low";

            }

            structure.structureType =
                "table-like-region";

        }
    );


    /*
     * =================================
     * 8. FINAL MODEL
     * =================================
     */

    window.pdfUniversalStructureModel = {

        version:
            "1.0",

        page:
            page40,

        yLevels:
            yLevels40,

        bands:
            bands40,

        structures:
            structures40,

        statistics: {

            horizontalYLevels:
                yLevels40.length,

            borderBands:
                bands40.length,

            structuredBands:
                structuredBands40.length,

            tableLikeRegions:
                structures40.length

        }

    };


    /*
     * =================================
     * RESULT
     * =================================
     */

    console.log(
        "================================="
    );

    console.log(
        "STEP 40 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Page:",
        page40.width,
        "x",
        page40.height
    );

    console.log(
        "Horizontal Y Levels:",
        yLevels40.length
    );

    console.log(
        "Border Bands:",
        bands40.length
    );

    console.log(
        "Structured Bands:",
        structuredBands40.length
    );

    console.log(
        "Table-like Regions:",
        structures40.length
    );


    /*
     * =================================
     * BAND DETAILS
     * =================================
     */

    console.log(
        "---------------------------------"
    );

    console.log(
        "BORDER BAND ANALYSIS"
    );

    console.log(
        "---------------------------------"
    );

    bands40.forEach(
        band => {

            console.log(

                `B${band.index} | ` +

                `Y:${band.bottom.toFixed(2)} -> ` +

                `${band.top.toFixed(2)} | ` +

                `H:${band.height.toFixed(2)} | ` +

                `W:${band.width.toFixed(2)} | ` +

                `TEXT:${band.textCount} | ` +

                `VERT:${band.verticalBorderCount} | ` +

                `TYPE:${band.structureType} | ` +

                `SCORE:${band.structureScore}`

            );

        }
    );


    /*
     * =================================
     * STRUCTURE DETAILS
     * =================================
     */

    console.log(
        "---------------------------------"
    );

    console.log(
        "TABLE-LIKE STRUCTURES"
    );

    console.log(
        "---------------------------------"
    );

    structures40.forEach(
        structure => {

            console.log(

                `STRUCTURE ${structure.structureIndex} | ` +

                `Y:${structure.bottom.toFixed(2)} -> ` +

                `${structure.top.toFixed(2)} | ` +

                `H:${structure.height.toFixed(2)} | ` +

                `BANDS:${structure.bandIndexes.join(",")} | ` +

                `TEXT:${structure.textCount} | ` +

                `SCORE:${structure.structureScore} | ` +

                `CONFIDENCE:${structure.confidence}`

            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 40 COMPLETE"
    );

    console.log(
        "UNIVERSAL STRUCTURE MODEL READY"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
console.log("STEP 41 START");
console.log("SMART STRUCTURE SEGMENTATION");
console.log("=================================");

const model41 =
    window.pdfUniversalStructureModel;

const primitive41 =
    window.pdfUniversalLayoutPrimitiveModel;

if (
    !model41 ||
    !primitive41 ||
    !Array.isArray(model41.bands)
) {

    console.error(
        "Required Step 40 / Step 39 models not found."
    );

} else {

    const bands41 =
        model41.bands;

    const page41 =
        model41.page;


    /*
     * =================================
     * 1. PREPARE BAND INFORMATION
     * =================================
     */

    const preparedBands41 =
        bands41
            .map(
                (band, index) => ({

                    sourceIndex:
                        index,

                    index:
                        band.index,

                    top:
                        Number(band.top),

                    bottom:
                        Number(band.bottom),

                    height:
                        Number(band.height),

                    left:
                        Number(band.left),

                    right:
                        Number(band.right),

                    width:
                        Number(band.width),

                    topType:
                        band.topType,

                    bottomType:
                        band.bottomType,

                    textCount:
                        Number(band.textCount) || 0,

                    verticalBorderCount:
                        Number(
                            band.verticalBorderCount
                        ) || 0,

                    structureType:
                        band.structureType

                })
            )
            .filter(
                band =>
                    Number.isFinite(band.top) &&
                    Number.isFinite(band.bottom) &&
                    Number.isFinite(band.height)
            );


    /*
     * =================================
     * 2. GEOMETRY TOLERANCE
     * =================================
     */

    const geometryTolerance41 =
        Math.max(
            0.75,
            page41.width * 0.001
        );


    /*
     * =================================
     * 3. DETECT STRUCTURAL BREAKS
     * =================================
     */

    const breaks41 = [];


    for (
        let i = 0;
        i < preparedBands41.length - 1;
        i++
    ) {

        const current =
            preparedBands41[i];

        const next =
            preparedBands41[i + 1];


        /*
         * A. Large vertical gap
         */

        const gap =
            current.bottom -
            next.top;

        const averageHeight =
            (
                current.height +
                next.height
            ) / 2;

        const largeGap =
            gap >
            Math.max(
                averageHeight * 1.8,
                25
            );


        /*
         * B. Width pattern change
         */

        const widthDifference =
            Math.abs(
                current.width -
                next.width
            );

        const widthChanged =
            widthDifference >
            geometryTolerance41 * 2;


        /*
         * C. Border type pattern change
         */

        const patternChanged =
            current.topType !==
            next.bottomType &&
            current.bottomType !==
            next.topType;


        /*
         * D. Full-width / medium-width transition
         */

        const fullToMedium =
            (
                current.bottomType ===
                "full-width" &&
                next.topType ===
                "medium-width"
            );

        const mediumToFull =
            (
                current.bottomType ===
                "medium-width" &&
                next.topType ===
                "full-width"
            );


        /*
         * E. Text discontinuity
         */

        const textGap =
            current.textCount === 0 &&
            next.textCount === 0;


        /*
         * F. Vertical border discontinuity
         */

        const verticalChange =
            current.verticalBorderCount !==
            next.verticalBorderCount;


        /*
         * =================================
         * BREAK SCORE
         * =================================
         */

        let breakScore = 0;

        if (largeGap) {
            breakScore += 5;
        }

        if (widthChanged) {
            breakScore += 2;
        }

        if (patternChanged) {
            breakScore += 1;
        }

        if (
            fullToMedium ||
            mediumToFull
        ) {
            breakScore += 1;
        }

        if (textGap) {
            breakScore += 1;
        }

        if (verticalChange) {
            breakScore += 1;
        }


        /*
         * Strong break
         */

        if (
            breakScore >= 5
        ) {

            breaks41.push({

                afterBand:
                    current.index,

                beforeBand:
                    next.index,

                score:
                    breakScore,

                gap:
                    gap,

                widthChanged:
                    widthChanged,

                patternChanged:
                    patternChanged,

                verticalChange:
                    verticalChange

            });

        }

    }


    /*
     * =================================
     * 4. BUILD SEGMENTS
     * =================================
     */

    const segments41 = [];

    let currentSegment41 = null;


    preparedBands41.forEach(
        band => {

            if (
                !currentSegment41
            ) {

                currentSegment41 = {

                    segmentIndex:
                        segments41.length + 1,

                    top:
                        band.top,

                    bottom:
                        band.bottom,

                    height:
                        band.height,

                    bandIndexes:
                        [band.index],

                    textCount:
                        band.textCount,

                    bandCount:
                        1,

                    minWidth:
                        band.width,

                    maxWidth:
                        band.width,

                    widthTypes:
                        [band.width],

                    structureTypes:
                        [band.structureType],

                    verticalBorderCounts:
                        [
                            band.verticalBorderCount
                        ]

                };

                return;

            }


            const previousBandIndex =
                currentSegment41
                    .bandIndexes[
                        currentSegment41
                            .bandIndexes.length - 1
                    ];


            const breakFound =
                breaks41.find(
                    item =>
                        item.afterBand ===
                        previousBandIndex
                );


            if (
                breakFound
            ) {

                segments41.push(
                    currentSegment41
                );


                currentSegment41 = {

                    segmentIndex:
                        segments41.length + 1,

                    top:
                        band.top,

                    bottom:
                        band.bottom,

                    height:
                        band.height,

                    bandIndexes:
                        [band.index],

                    textCount:
                        band.textCount,

                    bandCount:
                        1,

                    minWidth:
                        band.width,

                    maxWidth:
                        band.width,

                    widthTypes:
                        [band.width],

                    structureTypes:
                        [band.structureType],

                    verticalBorderCounts:
                        [
                            band.verticalBorderCount
                        ]

                };

            } else {

                currentSegment41.bottom =
                    band.bottom;

                currentSegment41.height =
                    currentSegment41.top -
                    currentSegment41.bottom;

                currentSegment41.bandIndexes
                    .push(
                        band.index
                    );

                currentSegment41.textCount +=
                    band.textCount;

                currentSegment41.bandCount +=
                    1;

                currentSegment41.minWidth =
                    Math.min(
                        currentSegment41.minWidth,
                        band.width
                    );

                currentSegment41.maxWidth =
                    Math.max(
                        currentSegment41.maxWidth,
                        band.width
                    );

                currentSegment41.widthTypes
                    .push(
                        band.width
                    );

                currentSegment41.structureTypes
                    .push(
                        band.structureType
                    );

                currentSegment41
                    .verticalBorderCounts
                    .push(
                        band.verticalBorderCount
                    );

            }

        }
    );


    /*
     * Add final segment
     */

    if (
        currentSegment41
    ) {

        segments41.push(
            currentSegment41
        );

    }


    /*
     * =================================
     * 5. CALCULATE SEGMENT STATISTICS
     * =================================
     */

    segments41.forEach(
        segment => {

            const averageWidth =
                segment.widthTypes.length
                    ? segment.widthTypes
                        .reduce(
                            (sum, value) =>
                                sum + value,
                            0
                        ) /
                        segment.widthTypes.length
                    : 0;


            const averageVerticalBorders =
                segment.verticalBorderCounts.length
                    ? segment.verticalBorderCounts
                        .reduce(
                            (sum, value) =>
                                sum + value,
                            0
                        ) /
                        segment.verticalBorderCounts.length
                    : 0;


            const uniqueStructureTypes =
                [
                    ...new Set(
                        segment.structureTypes
                    )
                ];


            segment.averageWidth =
                averageWidth;

            segment.averageVerticalBorders =
                averageVerticalBorders;

            segment.structureTypes =
                uniqueStructureTypes;


            /*
             * Classification
             */

            if (
                segment.bandCount >= 3 &&
                segment.textCount >= 2 &&
                averageVerticalBorders >= 2
            ) {

                segment.structureType =
                    "structured-table";

            } else if (
                segment.textCount > 0 &&
                averageVerticalBorders >= 1
            ) {

                segment.structureType =
                    "structured-section";

            } else {

                segment.structureType =
                    "border-section";

            }


            /*
             * Confidence
             */

            let confidenceScore = 0;

            if (
                segment.textCount > 0
            ) {
                confidenceScore += 2;
            }

            if (
                segment.bandCount >= 3
            ) {
                confidenceScore += 2;
            }

            if (
                averageVerticalBorders >= 2
            ) {
                confidenceScore += 3;
            }

            if (
                segment.maxWidth -
                segment.minWidth <
                page41.width * 0.20
            ) {
                confidenceScore += 1;
            }

            segment.confidenceScore =
                confidenceScore;


            if (
                confidenceScore >= 7
            ) {

                segment.confidence =
                    "high";

            } else if (
                confidenceScore >= 4
            ) {

                segment.confidence =
                    "medium";

            } else {

                segment.confidence =
                    "low";

            }

        }
    );


    /*
     * =================================
     * 6. MAP TEXT TO SEGMENTS
     * =================================
     */

    const text41 =
        Array.isArray(
            primitive41.text
        )
            ? primitive41.text
            : [];


    segments41.forEach(
        segment => {

            const segmentTexts =
                text41.filter(
                    text => {

                        const centerY =
                            Number(
                                text.centerY
                            );

                        return (

                            Number.isFinite(
                                centerY
                            ) &&

                            centerY <=
                                segment.top +
                                geometryTolerance41 &&

                            centerY >=
                                segment.bottom -
                                geometryTolerance41

                        );

                    }
                );


            segment.texts =
                segmentTexts.map(
                    text =>
                        text.text
                );

            segment.textSourceIndexes =
                segmentTexts.map(
                    text =>
                        text.sourceIndex
                );

        }
    );


    /*
     * =================================
     * 7. FINAL MODEL
     * =================================
     */

    window.pdfUniversalSegmentedStructureModel = {

        version:
            "1.0",

        page:
            page41,

        geometryTolerance:
            geometryTolerance41,

        breaks:
            breaks41,

        segments:
            segments41,

        statistics: {

            sourceBands:
                preparedBands41.length,

            structuralBreaks:
                breaks41.length,

            segments:
                segments41.length,

            structuredTables:
                segments41.filter(
                    segment =>
                        segment.structureType ===
                        "structured-table"
                ).length,

            structuredSections:
                segments41.filter(
                    segment =>
                        segment.structureType ===
                        "structured-section"
                ).length

        }

    };


    /*
     * =================================
     * RESULT
     * =================================
     */

    console.log(
        "================================="
    );

    console.log(
        "STEP 41 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Page:",
        page41.width,
        "x",
        page41.height
    );

    console.log(
        "Source Bands:",
        preparedBands41.length
    );

    console.log(
        "Structural Breaks:",
        breaks41.length
    );

    console.log(
        "Segments:",
        segments41.length
    );

    console.log(
        "Structured Tables:",
        segments41.filter(
            segment =>
                segment.structureType ===
                "structured-table"
        ).length
    );

    console.log(
        "Structured Sections:",
        segments41.filter(
            segment =>
                segment.structureType ===
                "structured-section"
        ).length
    );


    /*
     * =================================
     * BREAK DETAILS
     * =================================
     */

    console.log(
        "---------------------------------"
    );

    console.log(
        "STRUCTURAL BREAKS"
    );

    console.log(
        "---------------------------------"
    );

    breaks41.forEach(
        item => {

            console.log(

                `AFTER B${item.afterBand} -> ` +

                `BEFORE B${item.beforeBand} | ` +

                `SCORE:${item.score} | ` +

                `GAP:${item.gap.toFixed(2)} | ` +

                `WIDTH_CHANGE:${item.widthChanged} | ` +

                `PATTERN_CHANGE:${item.patternChanged} | ` +

                `VERTICAL_CHANGE:${item.verticalChange}`

            );

        }
    );


    /*
     * =================================
     * SEGMENT DETAILS
     * =================================
     */

    console.log(
        "---------------------------------"
    );

    console.log(
        "SMART STRUCTURE SEGMENTS"
    );

    console.log(
        "---------------------------------"
    );

    segments41.forEach(
        segment => {

            console.log(

                `SEGMENT ${segment.segmentIndex} | ` +

                `Y:${segment.bottom.toFixed(2)} -> ` +

                `${segment.top.toFixed(2)} | ` +

                `H:${segment.height.toFixed(2)} | ` +

                `BANDS:${segment.bandIndexes.join(",")} | ` +

                `TEXT:${segment.textCount} | ` +

                `AVG-W:${segment.averageWidth.toFixed(2)} | ` +

                `VERT:${segment.averageVerticalBorders.toFixed(2)} | ` +

                `TYPE:${segment.structureType} | ` +

                `CONFIDENCE:${segment.confidence}`

            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 41 COMPLETE"
    );

    console.log(
        "SMART STRUCTURE MODEL READY"
    );

    console.log(
        "================================="
    );

}





console.log("=================================");
