console.log("=================================");
console.log("STEP 42 START");
console.log("SEGMENT + MASTER ROW MAPPING");
console.log("=================================");

const segments42 =
    window.pdfUniversalSmartSegments;

const master42 =
    window.pdfUniversalMasterRowModel;

const coordinate42 =
    window.pdfUniversalCoordinateModel;

if (
    !segments42 ||
    !Array.isArray(segments42.segments)
) {

    console.error(
        "Step 41.3 smart segments not found."
    );

} else if (
    !master42 ||
    !Array.isArray(master42.rows)
) {

    console.error(
        "Step 29.3 master row model not found."
    );

} else {

    const rows42 =
        master42.rows;

    const segmentsList42 =
        segments42.segments;


    /*
     * =================================
     * 1. MAP MASTER ROWS TO SEGMENTS
     * =================================
     */

    const mappedSegments42 =
        segmentsList42.map(
            (segment, segmentIndex) => {

                const segmentRows =
                    [];


                rows42.forEach(
                    (row, rowIndex) => {

                        /*
                         * Master row Y
                         */

                        const rowY =
                            Number(
                                row.y
                            );

                        const rowTop =
                            Number(
                                row.top
                            );

                        const rowBottom =
                            Number(
                                row.bottom
                            );


                        /*
                         * Different versions of
                         * the row model may contain
                         * different coordinate fields.
                         */

                        let centerY =
                            Number(
                                row.centerY
                            );


                        if (
                            !Number.isFinite(
                                centerY
                            )
                        ) {

                            if (
                                Number.isFinite(
                                    rowTop
                                ) &&
                                Number.isFinite(
                                    rowBottom
                                )
                            ) {

                                centerY =
                                    (
                                        rowTop +
                                        rowBottom
                                    ) / 2;

                            } else if (
                                Number.isFinite(
                                    rowY
                                )
                            ) {

                                centerY =
                                    rowY;

                            }

                        }


                        if (
                            !Number.isFinite(
                                centerY
                            )
                        ) {
                            return;
                        }


                        /*
                         * Segment boundary
                         */

                        const insideSegment =
                            centerY <=
                                segment.top + 1 &&
                            centerY >=
                                segment.bottom - 1;


                        if (
                            insideSegment
                        ) {

                            segmentRows.push({

                                rowIndex:
                                    rowIndex,

                                masterRow:
                                    row,

                                centerY:
                                    centerY

                            });

                        }

                    }
                );


                /*
                 * Sort top → bottom
                 */

                segmentRows.sort(
                    (
                        a,
                        b
                    ) =>
                        b.centerY -
                        a.centerY
                );


                return {

                    segmentIndex:
                        segment.segmentIndex,

                    top:
                        segment.top,

                    bottom:
                        segment.bottom,

                    height:
                        segment.height,

                    type:
                        segment.type,

                    confidence:
                        segment.confidence,

                    widthTypes:
                        segment.widthTypes,

                    rows:
                        segmentRows

                };

            }
        );


    /*
     * =================================
     * 2. FALLBACK ROW MAPPING
     * =================================
     */

    /*
     * Some master rows may not contain
     * usable Y fields. In that case,
     * use the text regions from the
     * coordinate model.
     */

    if (
        coordinate42 &&
        Array.isArray(
            coordinate42.rows
        )
    ) {

        mappedSegments42.forEach(
            segment => {

                if (
                    segment.rows.length > 0
                ) {
                    return;
                }


                coordinate42.rows.forEach(
                    (
                        row,
                        rowIndex
                    ) => {

                        const centerY =
                            Number(
                                row.centerY
                            );


                        if (
                            !Number.isFinite(
                                centerY
                            )
                        ) {
                            return;
                        }


                        if (
                            centerY <=
                                segment.top + 1 &&
                            centerY >=
                                segment.bottom - 1
                        ) {

                            segment.rows.push({

                                rowIndex:
                                    rowIndex,

                                coordinateRow:
                                    row,

                                centerY:
                                    centerY

                            });

                        }

                    }
                );


                segment.rows.sort(
                    (
                        a,
                        b
                    ) =>
                        b.centerY -
                        a.centerY
                );

            }
        );

    }


    /*
     * =================================
     * 3. REMOVE DUPLICATES
     * =================================
     */

    mappedSegments42.forEach(
        segment => {

            const seen =
                new Set();

            segment.rows =
                segment.rows.filter(
                    row => {

                        const key =
                            row.rowIndex;

                        if (
                            seen.has(key)
                        ) {

                            return false;

                        }

                        seen.add(key);

                        return true;

                    }
                );

        }
    );


    /*
     * =================================
     * 4. BUILD FINAL MODEL
     * =================================
     */

    window.pdfUniversalSegmentRowModel = {

        version:
            "1.0",

        page:
            segments42.page,

        segments:
            mappedSegments42,

        statistics: {

            segments:
                mappedSegments42.length,

            masterRows:
                rows42.length,

            mappedRows:
                mappedSegments42.reduce(
                    (
                        total,
                        segment
                    ) =>
                        total +
                        segment.rows.length,
                    0
                )

        }

    };


    /*
     * =================================
     * 5. OUTPUT
     * =================================
     */

    console.log(
        "================================="
    );

    console.log(
        "STEP 42 RESULT"
    );

    console.log(
        "================================="
    );

    console.log(
        "Segments:",
        mappedSegments42.length
    );

    console.log(
        "Master Rows:",
        rows42.length
    );

    console.log(
        "Mapped Rows:",
        mappedSegments42.reduce(
            (
                total,
                segment
            ) =>
                total +
                segment.rows.length,
            0
        )
    );


    console.log(
        "---------------------------------"
    );

    console.log(
        "SEGMENT ROW MAPPING"
    );

    console.log(
        "---------------------------------"
    );


    mappedSegments42.forEach(
        segment => {

            console.log(
                `SEGMENT ${segment.segmentIndex} | ` +
                `Y:${segment.bottom.toFixed(2)} -> ` +
                `${segment.top.toFixed(2)} | ` +
                `ROWS:${segment.rows.length} | ` +
                `TYPE:${segment.type} | ` +
                `CONFIDENCE:${segment.confidence}`
            );


            segment.rows.forEach(
                (
                    row,
                    index
                ) => {

                    const masterRow =
                        row.masterRow ||
                        row.coordinateRow;


                    console.log(

                        `   ROW ${index + 1} | ` +

                        `MASTER:${row.rowIndex + 1} | ` +

                        `CENTER-Y:${row.centerY.toFixed(2)} | ` +

                        `DATA:`,

                        masterRow

                    );

                }
            );

        }
    );


    console.log(
        "================================="
    );

    console.log(
        "STEP 42 COMPLETE"
    );

    console.log(
        "SEGMENT ROW MODEL READY"
    );

    console.log(
        "================================="
    );

}





