/* ---------- TEXT ELEMENTS ---------- */

const textVerifyElements =
    textVerifyRenderLayer.elements?.text || [];


/* ---------- VERIFY COORDINATES ---------- */

const textVerifyResults =
    textVerifyElements.map((item, index) => {

        const docx = item.docx || {};

        return {

            index:
                index + 1,

            id:
                item.id,

            text:
                item.text,

            physicalColumn:
                item.physicalColumn,

            borderRegion:
                item.borderRegion,

            xTwips:
                Number(docx.xTwips || 0),

            yTwips:
                Number(docx.yTwips || 0),

            widthTwips:
                Number(docx.widthTwips || 0),

            heightTwips:
                Number(docx.heightTwips || 0)

        };

    });


/* ---------- BASIC VALIDATION ---------- */

const textVerifyInvalid =
    textVerifyResults.filter(item =>

        !Number.isFinite(item.xTwips) ||
        !Number.isFinite(item.yTwips) ||
        !Number.isFinite(item.widthTwips) ||
        !Number.isFinite(item.heightTwips) ||

        item.widthTwips <= 0 ||
        item.heightTwips <= 0

    );


const textVerifyOutOfPage =
    textVerifyResults.filter(item =>

        item.xTwips < 0 ||
        item.yTwips < 0 ||

        item.xTwips > textVerifyRenderLayer.page.widthTwips ||
        item.yTwips > textVerifyRenderLayer.page.heightTwips

    );


/* ---------- SAVE VERIFICATION MODEL ---------- */

window.pdfUniversalDocxTextVerificationModel = {

    page: {

        widthTwips:
            Number(
                textVerifyRenderLayer.page.widthTwips
            ),

        heightTwips:
            Number(
                textVerifyRenderLayer.page.heightTwips
            )

    },

    totalElements:
        textVerifyResults.length,

    invalidElements:
        textVerifyInvalid.length,

    outOfPageElements:
        textVerifyOutOfPage.length,

    elements:
        textVerifyResults

};


