if (!borderVerifyRenderLayer) {

    console.error(
        "STEP 51 ERROR: DOCX Render Layer not found."
    );

    throw new Error(
        "Step 51 cannot continue."
    );
}


/* ---------- PAGE SIZE ---------- */

const borderVerifyPageWidth =
    Number(
        borderVerifyRenderLayer.page?.widthTwips || 0
    );

const borderVerifyPageHeight =
    Number(
        borderVerifyRenderLayer.page?.heightTwips || 0
    );


/* =========================================================
   HORIZONTAL BORDERS
   ========================================================= */

const borderVerifyHorizontal =
    borderVerifyRenderLayer.elements?.horizontal || [];


const borderVerifyHorizontalResults =
    borderVerifyHorizontal.map((item, index) => {

        const docx =
            item.docx || {};

        const x1 =
            Number(docx.x1Twips || 0);

        const x2 =
            Number(docx.x2Twips || 0);

        const y =
            Number(docx.yTwips || 0);

        return {

            index:
                index + 1,

            id:
                item.id,

            x1Twips:
                x1,

            x2Twips:
                x2,

            yTwips:
                y,

            widthTwips:
                Number(docx.widthTwips || 0),

            valid:
                Number.isFinite(x1) &&
                Number.isFinite(x2) &&
                Number.isFinite(y) &&

                x1 >= 0 &&
                x2 <= borderVerifyPageWidth &&

                y >= 0 &&
                y <= borderVerifyPageHeight &&

                x2 > x1

        };

    });


/* =========================================================
   VERTICAL BORDERS
   ========================================================= */

const borderVerifyVertical =
    borderVerifyRenderLayer.elements?.vertical || [];


const borderVerifyVerticalResults =
    borderVerifyVertical.map((item, index) => {

        const docx =
            item.docx || {};

        const x =
            Number(docx.xTwips || 0);

        const y1 =
            Number(docx.y1Twips || 0);

        const y2 =
            Number(docx.y2Twips || 0);

        return {

            index:
                index + 1,

            id:
                item.id,

            xTwips:
                x,

            y1Twips:
                y1,

            y2Twips:
                y2,

            heightTwips:
                Number(docx.heightTwips || 0),

            valid:
                Number.isFinite(x) &&
                Number.isFinite(y1) &&
                Number.isFinite(y2) &&

                x >= 0 &&
                x <= borderVerifyPageWidth &&

                y1 >= 0 &&
                y2 <= borderVerifyPageHeight &&

                y2 > y1

        };

    });


/* =========================================================
   INVALID ELEMENTS
   ========================================================= */

const invalidHorizontalBorders =
    borderVerifyHorizontalResults
        .filter(item => !item.valid);


const invalidVerticalBorders =
    borderVerifyVerticalResults
        .filter(item => !item.valid);


