/* =========================================================
   STEP 52 — UNIVERSAL DOCX GRID MODEL
   ========================================================= */

const gridRenderLayer =
    window.pdfUniversalDocxRenderLayer;

const gridBorderVerification =
    window.pdfUniversalDocxBorderVerificationModel;

const gridTextVerification =
    window.pdfUniversalDocxTextVerificationModel;

const gridPageModel =
    window.pdfUniversalDocxPageModel;


/* =========================================================
   SAFETY CHECK
   ========================================================= */

if (
    !gridRenderLayer ||
    !gridBorderVerification ||
    !gridTextVerification ||
    !gridPageModel
) {

    console.error(
        "STEP 52 ERROR: Required models are missing."
    );

    throw new Error(
        "Step 52 cannot continue."
    );
}


/* =========================================================
   PAGE
   ========================================================= */

const gridPage = {

    widthTwips:
        Number(
            gridPageModel.page?.widthTwips || 0
        ),

    heightTwips:
        Number(
            gridPageModel.page?.heightTwips || 0
        ),

    orientation:
        gridPageModel.page?.orientation ||
        "portrait"

};


/* =========================================================
   COLLECT ALL X POSITIONS
   ========================================================= */

const gridXPositions = new Set();

gridXPositions.add(0);
gridXPositions.add(gridPage.widthTwips);


/* ---------- TEXT X POSITIONS ---------- */

(
    gridTextVerification.elements || []
).forEach(item => {

    const x =
        Number(item.xTwips || 0);

    const right =
        x +
        Number(item.widthTwips || 0);

    if (x >= 0 && x <= gridPage.widthTwips) {
        gridXPositions.add(x);
    }

    if (
        right >= 0 &&
        right <= gridPage.widthTwips
    ) {
        gridXPositions.add(right);
    }

});


/* ---------- HORIZONTAL BORDER X POSITIONS ---------- */

(
    gridBorderVerification.horizontal.elements || []
).forEach(item => {

    const x1 =
        Number(item.x1Twips || 0);

    const x2 =
        Number(item.x2Twips || 0);

    if (
        x1 >= 0 &&
        x1 <= gridPage.widthTwips
    ) {
        gridXPositions.add(x1);
    }

    if (
        x2 >= 0 &&
        x2 <= gridPage.widthTwips
    ) {
        gridXPositions.add(x2);
    }

});


/* ---------- VERTICAL BORDER X POSITIONS ---------- */

(
    gridBorderVerification.vertical.elements || []
).forEach(item => {

    const x =
        Number(item.xTwips || 0);

    if (
        x >= 0 &&
        x <= gridPage.widthTwips
    ) {
        gridXPositions.add(x);
    }

});


/* =========================================================
   SORT X POSITIONS
   ========================================================= */

const gridSortedX =
    Array.from(gridXPositions)
        .sort((a, b) => a - b);


/* =========================================================
   COLLECT ALL Y POSITIONS
   ========================================================= */

const gridYPositions = new Set();

gridYPositions.add(0);
gridYPositions.add(gridPage.heightTwips);


/* ---------- TEXT Y POSITIONS ---------- */

(
    gridTextVerification.elements || []
).forEach(item => {

    const y =
        Number(item.yTwips || 0);

    const bottom =
        y +
        Number(item.heightTwips || 0);

    if (
        y >= 0 &&
        y <= gridPage.heightTwips
    ) {
        gridYPositions.add(y);
    }

    if (
        bottom >= 0 &&
        bottom <= gridPage.heightTwips
    ) {
        gridYPositions.add(bottom);
    }

});


/* ---------- HORIZONTAL BORDER Y POSITIONS ---------- */

(
    gridBorderVerification.horizontal.elements || []
).forEach(item => {

    const y =
        Number(item.yTwips || 0);

    if (
        y >= 0 &&
        y <= gridPage.heightTwips
    ) {
        gridYPositions.add(y);
    }

});


/* ---------- VERTICAL BORDER Y POSITIONS ---------- */

(
    gridBorderVerification.vertical.elements || []
).forEach(item => {

    const y1 =
        Number(item.y1Twips || 0);

    const y2 =
        Number(item.y2Twips || 0);

    if (
        y1 >= 0 &&
        y1 <= gridPage.heightTwips
    ) {
        gridYPositions.add(y1);
    }

    if (
        y2 >= 0 &&
        y2 <= gridPage.heightTwips
    ) {
        gridYPositions.add(y2);
    }

});


/* =========================================================
   SORT Y POSITIONS
   ========================================================= */

const gridSortedY =
    Array.from(gridYPositions)
        .sort((a, b) => a - b);


/* =========================================================
   BUILD GRID COLUMNS
   ========================================================= */

const gridColumns = [];

for (
    let i = 0;
    i < gridSortedX.length - 1;
    i++
) {

    const left =
        gridSortedX[i];

    const right =
        gridSortedX[i + 1];

    if (right <= left) {
        continue;
    }

    gridColumns.push({

        index:
            gridColumns.length + 1,

        leftTwips:
            left,

        rightTwips:
            right,

        widthTwips:
            right - left

    });

}


/* =========================================================
   BUILD GRID ROWS
   ========================================================= */

const gridRows = [];

for (
    let i = 0;
    i < gridSortedY.length - 1;
    i++
) {

    const top =
        gridSortedY[i];

    const bottom =
        gridSortedY[i + 1];

    if (bottom <= top) {
        continue;
    }

    gridRows.push({

        index:
            gridRows.length + 1,

        topTwips:
            top,

        bottomTwips:
            bottom,

        heightTwips:
            bottom - top

    });

}


/* =========================================================
   FINAL GRID MODEL
   ========================================================= */

const pdfUniversalDocxGridModel = {

    version:
        "1.0",

    coordinateUnit:
        "twips",

    page:
        gridPage,

    columns:
        gridColumns,

    rows:
        gridRows,

    source:

        {

            textElements:
                gridTextVerification.elements.length,

            horizontalBorders:
                gridBorderVerification.horizontal.elements.length,

            verticalBorders:
                gridBorderVerification.vertical.elements.length

        }

};


/* =========================================================
   SAVE GLOBAL MODEL
   ========================================================= */

window.pdfUniversalDocxGridModel =
    pdfUniversalDocxGridModel;


