/* =========================================================
   STEP 53 — INTELLIGENT DOCX GRID SIMPLIFICATION
   ========================================================= */

const simplifyGridModel =
    window.pdfUniversalDocxGridModel;

const simplifyTextModel =
    window.pdfUniversalDocxTextVerificationModel;

const simplifyBorderModel =
    window.pdfUniversalDocxBorderVerificationModel;


if (
    !simplifyGridModel ||
    !simplifyTextModel ||
    !simplifyBorderModel
) {

    console.error(
        "STEP 53 ERROR: Required models are missing."
    );

    throw new Error(
        "Step 53 cannot continue."
    );
}


/* =========================================================
   TOLERANCE
   ========================================================= */

const GRID_SIMPLIFY_TOLERANCE =
    8;


/* =========================================================
   HELPER — ADD UNIQUE POSITION
   ========================================================= */

function addSimplifiedPosition(
    array,
    value
) {

    const number =
        Number(value);

    if (!Number.isFinite(number)) {
        return;
    }

    const existing =
        array.find(
            item =>
                Math.abs(item - number) <=
                GRID_SIMPLIFY_TOLERANCE
        );

    if (existing === undefined) {

        array.push(number);

    }

}


/* =========================================================
   STRUCTURAL X POSITIONS
   ========================================================= */

const simplifiedXPositions = [];


/* ---------- PAGE EDGES ---------- */

addSimplifiedPosition(
    simplifiedXPositions,
    0
);

addSimplifiedPosition(
    simplifiedXPositions,
    simplifyGridModel.page.widthTwips
);


/* ---------- VERTICAL BORDERS ---------- */

(
    simplifyBorderModel.vertical.elements || []
).forEach(item => {

    addSimplifiedPosition(
        simplifiedXPositions,
        item.xTwips
    );

});


/* ---------- HORIZONTAL BORDER START/END ---------- */

(
    simplifyBorderModel.horizontal.elements || []
).forEach(item => {

    addSimplifiedPosition(
        simplifiedXPositions,
        item.x1Twips
    );

    addSimplifiedPosition(
        simplifiedXPositions,
        item.x2Twips
    );

});


/* =========================================================
   STRUCTURAL TEXT POSITIONS
   ========================================================= */

(
    simplifyTextModel.elements || []
).forEach(item => {

    addSimplifiedPosition(
        simplifiedXPositions,
        item.xTwips
    );

});


/* =========================================================
   SORT X
   ========================================================= */

simplifiedXPositions.sort(
    (a, b) => a - b
);


/* =========================================================
   STRUCTURAL Y POSITIONS
   ========================================================= */

const simplifiedYPositions = [];


/* ---------- PAGE EDGES ---------- */

addSimplifiedPosition(
    simplifiedYPositions,
    0
);

addSimplifiedPosition(
    simplifiedYPositions,
    simplifyGridModel.page.heightTwips
);


/* ---------- HORIZONTAL BORDERS ---------- */

(
    simplifyBorderModel.horizontal.elements || []
).forEach(item => {

    addSimplifiedPosition(
        simplifiedYPositions,
        item.yTwips
    );

});


/* ---------- VERTICAL BORDER ENDPOINTS ---------- */

(
    simplifyBorderModel.vertical.elements || []
).forEach(item => {

    addSimplifiedPosition(
        simplifiedYPositions,
        item.y1Twips
    );

    addSimplifiedPosition(
        simplifiedYPositions,
        item.y2Twips
    );

});


/* =========================================================
   TEXT Y POSITIONS
   ========================================================= */

(
    simplifyTextModel.elements || []
).forEach(item => {

    addSimplifiedPosition(
        simplifiedYPositions,
        item.yTwips
    );

    addSimplifiedPosition(
        simplifiedYPositions,
        Number(item.yTwips) +
        Number(item.heightTwips)

    );

});


/* =========================================================
   SORT Y
   ========================================================= */

simplifiedYPositions.sort(
    (a, b) => a - b
);


/* =========================================================
   BUILD SIMPLIFIED COLUMNS
   ========================================================= */

const simplifiedColumns = [];

for (
    let i = 0;
    i < simplifiedXPositions.length - 1;
    i++
) {

    const left =
        simplifiedXPositions[i];

    const right =
        simplifiedXPositions[i + 1];

    if (
        right - left <=
        GRID_SIMPLIFY_TOLERANCE
    ) {
        continue;
    }

    simplifiedColumns.push({

        index:
            simplifiedColumns.length + 1,

        leftTwips:
            left,

        rightTwips:
            right,

        widthTwips:
            right - left

    });

}


/* =========================================================
   BUILD SIMPLIFIED ROWS
   ========================================================= */

const simplifiedRows = [];

for (
    let i = 0;
    i < simplifiedYPositions.length - 1;
    i++
) {

    const top =
        simplifiedYPositions[i];

    const bottom =
        simplifiedYPositions[i + 1];

    if (
        bottom - top <=
        GRID_SIMPLIFY_TOLERANCE
    ) {
        continue;
    }

    simplifiedRows.push({

        index:
            simplifiedRows.length + 1,

        topTwips:
            top,

        bottomTwips:
            bottom,

        heightTwips:
            bottom - top

    });

}


/* =========================================================
   FINAL SIMPLIFIED MODEL
   ========================================================= */

const pdfUniversalSimplifiedGridModel = {

    version:
        "1.0",

    coordinateUnit:
        "twips",

    tolerance:
        GRID_SIMPLIFY_TOLERANCE,

    page:
        simplifyGridModel.page,

    columns:
        simplifiedColumns,

    rows:
        simplifiedRows,

    sourceGrid:
        {

            originalColumns:
                simplifyGridModel.columns.length,

            originalRows:
                simplifyGridModel.rows.length

        },

    sourceElements:
        {

            text:
                simplifyTextModel.elements.length,

            horizontalBorders:
                simplifyBorderModel.horizontal.elements.length,

            verticalBorders:
                simplifyBorderModel.vertical.elements.length

        }

};


/* =========================================================
   SAVE
   ========================================================= */

window.pdfUniversalSimplifiedGridModel =
    pdfUniversalSimplifiedGridModel;


