/* =========================================================
   STEP 54 — BORDER-DRIVEN STRUCTURAL GRID
   ========================================================= */

const structuralGridSource =
    window.pdfUniversalDocxBorderPlacementModel;

const structuralPage =
    structuralGridSource.page;


/* =========================================================
   TOLERANCE
   ========================================================= */

const STRUCTURAL_TOLERANCE = 8;


/* =========================================================
   HELPER
   ========================================================= */

function addStructuralPosition(array, value) {

    const n = Number(value);

    if (!Number.isFinite(n)) {
        return;
    }

    const found = array.some(
        existing =>
            Math.abs(existing - n) <=
            STRUCTURAL_TOLERANCE
    );

    if (!found) {
        array.push(n);
    }
}


/* =========================================================
   X POSITIONS
   ONLY PAGE EDGES + VERTICAL BORDERS
   ========================================================= */

const structuralX = [];


/* Page edges */

addStructuralPosition(
    structuralX,
    0
);

addStructuralPosition(
    structuralX,
    structuralPage.widthTwips
);


/* Vertical borders */

(
    structuralGridSource.vertical || []
).forEach(border => {

    addStructuralPosition(
        structuralX,
        border.docx.x1Twips
    );

});


/* Sort */

structuralX.sort(
    (a, b) => a - b
);


/* =========================================================
   Y POSITIONS
   ONLY PAGE EDGES + HORIZONTAL BORDERS
   ========================================================= */

const structuralY = [];


/* Page edges */

addStructuralPosition(
    structuralY,
    0
);

addStructuralPosition(
    structuralY,
    structuralPage.heightTwips
);


/* Horizontal borders */

(
    structuralGridSource.horizontal || []
).forEach(border => {

    addStructuralPosition(
        structuralY,
        border.docx.yTwips
    );

});


/* Sort */

structuralY.sort(
    (a, b) => a - b
);


/* =========================================================
   BUILD COLUMNS
   ========================================================= */

const structuralColumns = [];

for (
    let i = 0;
    i < structuralX.length - 1;
    i++
) {

    const left =
        structuralX[i];

    const right =
        structuralX[i + 1];

    if (
        right - left <=
        STRUCTURAL_TOLERANCE
    ) {
        continue;
    }

    structuralColumns.push({

        index:
            structuralColumns.length + 1,

        leftTwips:
            left,

        rightTwips:
            right,

        widthTwips:
            right - left

    });

}


/* =========================================================
   BUILD ROWS
   ========================================================= */

const structuralRows = [];

for (
    let i = 0;
    i < structuralY.length - 1;
    i++
) {

    const top =
        structuralY[i];

    const bottom =
        structuralY[i + 1];

    if (
        bottom - top <=
        STRUCTURAL_TOLERANCE
    ) {
        continue;
    }

    structuralRows.push({

        index:
            structuralRows.length + 1,

        topTwips:
            top,

        bottomTwips:
            bottom,

        heightTwips:
            bottom - top

    });

}


/* =========================================================
   MODEL
   ========================================================= */

const pdfUniversalStructuralGridModel = {

    version:
        "1.0",

    coordinateUnit:
        "twips",

    tolerance:
        STRUCTURAL_TOLERANCE,

    page:
        structuralPage,

    columns:
        structuralColumns,

    rows:
        structuralRows,

    source:
        {

            verticalBorders:
                (structuralGridSource.vertical || []).length,

            horizontalBorders:
                (structuralGridSource.horizontal || []).length

        }

};


