/* =========================================================
   STEP 55 — TEXT → STRUCTURAL CELL MAPPING
   ========================================================= */

const step55Grid =
    window.pdfUniversalStructuralGridModel;

const step55Text =
    window.pdfUniversalDocxTextVerificationModel;

if (!step55Grid || !step55Text) {

    console.error(
        "STEP 55 ERROR: Required models are missing."
    );

    throw new Error(
        "Step 55 cannot continue."
    );
}


/* =========================================================
   HELPER — OVERLAP
   ========================================================= */

function step55Overlap(
    startA,
    endA,
    startB,
    endB
) {

    const start =
        Math.max(startA, startB);

    const end =
        Math.min(endA, endB);

    return Math.max(
        0,
        end - start
    );
}


/* =========================================================
   MAP ONE TEXT ELEMENT
   ========================================================= */

function step55FindBestCell(text) {

    const textLeft =
        Number(text.xTwips);

    const textRight =
        textLeft +
        Number(text.widthTwips);

    const textTop =
        Number(text.yTwips);

    const textBottom =
        textTop +
        Number(text.heightTwips);

    const textWidth =
        Math.max(
            1,
            textRight - textLeft
        );

    const textHeight =
        Math.max(
            1,
            textBottom - textTop
        );

    let bestCell = null;

    let bestScore = -Infinity;


    /* =====================================================
       CHECK EVERY STRUCTURAL CELL
       ===================================================== */

    for (
        let rowIndex = 0;
        rowIndex < step55Grid.rows.length;
        rowIndex++
    ) {

        const row =
            step55Grid.rows[rowIndex];

        const verticalOverlap =
            step55Overlap(
                textTop,
                textBottom,
                row.topTwips,
                row.bottomTwips
            );

        if (verticalOverlap <= 0) {
            continue;
        }


        for (
            let colIndex = 0;
            colIndex < step55Grid.columns.length;
            colIndex++
        ) {

            const column =
                step55Grid.columns[colIndex];

            const horizontalOverlap =
                step55Overlap(
                    textLeft,
                    textRight,
                    column.leftTwips,
                    column.rightTwips
                );

            if (horizontalOverlap <= 0) {
                continue;
            }


            /* =============================================
               OVERLAP RATIO
               ============================================= */

            const overlapArea =
                horizontalOverlap *
                verticalOverlap;

            const textArea =
                textWidth *
                textHeight;

            const overlapRatio =
                overlapArea /
                textArea;


            /* =============================================
               CENTER DISTANCE
               ============================================= */

            const textCenterX =
                (textLeft + textRight) / 2;

            const textCenterY =
                (textTop + textBottom) / 2;

            const cellCenterX =
                (
                    column.leftTwips +
                    column.rightTwips
                ) / 2;

            const cellCenterY =
                (
                    row.topTwips +
                    row.bottomTwips
                ) / 2;

            const dx =
                Math.abs(
                    textCenterX -
                    cellCenterX
                );

            const dy =
                Math.abs(
                    textCenterY -
                    cellCenterY
                );

            const cellWidth =
                Math.max(
                    1,
                    column.widthTwips
                );

            const cellHeight =
                Math.max(
                    1,
                    row.heightTwips
                );

            const centerPenalty =
                (
                    dx / cellWidth
                ) +
                (
                    dy / cellHeight
                );


            /* =============================================
               FINAL SCORE
               ============================================= */

            const score =
                (
                    overlapRatio * 100
                ) -
                (
                    centerPenalty * 10
                );


            if (
                score >
                bestScore
            ) {

                bestScore =
                    score;

                bestCell = {

                    rowIndex:
                        rowIndex,

                    columnIndex:
                        colIndex,

                    rowNumber:
                        row.index,

                    columnNumber:
                        column.index,

                    score:
                        score,

                    overlapRatio:
                        overlapRatio

                };

            }

        }

    }

    return bestCell;
}


/* =========================================================
   MAP ALL TEXT
   ========================================================= */

const step55MappedText = [];

let step55Unmapped = 0;


(
    step55Text.elements || []
).forEach((text, index) => {

    const cell =
        step55FindBestCell(text);

    if (!cell) {

        step55Unmapped++;

        step55MappedText.push({

            textIndex:
                index,

            sourceIndex:
                text.sourceIndex,

            text:
                text.text,

            xTwips:
                text.xTwips,

            yTwips:
                text.yTwips,

            widthTwips:
                text.widthTwips,

            heightTwips:
                text.heightTwips,

            mapped:
                false

        });

        return;
    }


    step55MappedText.push({

        textIndex:
            index,

        sourceIndex:
            text.sourceIndex,

        text:
            text.text,

        xTwips:
            text.xTwips,

        yTwips:
            text.yTwips,

        widthTwips:
            text.widthTwips,

        heightTwips:
            text.heightTwips,

        mapped:
            true,

        rowIndex:
            cell.rowIndex,

        columnIndex:
            cell.columnIndex,

        rowNumber:
            cell.rowNumber,

        columnNumber:
            cell.columnNumber,

        score:
            Number(
                cell.score.toFixed(3)
            ),

        overlapRatio:
            Number(
                cell.overlapRatio.toFixed(3)
            )

    });

});


/* =========================================================
   CELL GROUPS
   ========================================================= */

const step55CellGroups = {};


step55MappedText.forEach(item => {

    if (!item.mapped) {
        return;
    }

    const key =
        item.rowNumber +
        ":" +
        item.columnNumber;

    if (
        !step55CellGroups[key]
    ) {

        step55CellGroups[key] = {

            rowNumber:
                item.rowNumber,

            columnNumber:
                item.columnNumber,

            texts:
                []

        };

    }

    step55CellGroups[key]
        .texts
        .push(item);

});


/* =========================================================
   MODEL
   ========================================================= */

const pdfUniversalTextCellMappingModel = {

    version:
        "1.0",

    coordinateUnit:
        "twips",

    page:
        step55Grid.page,

    grid:
        {

            columns:
                step55Grid.columns.length,

            rows:
                step55Grid.rows.length

        },

    text:

        {

            total:
                step55MappedText.length,

            mapped:
                step55MappedText
                    .filter(item => item.mapped)
                    .length,

            unmapped:
                step55Unmapped

        },

    elements:
        step55MappedText,

    cells:
        step55CellGroups

};


/* =========================================================
   SAVE
   ========================================================= */

window.pdfUniversalTextCellMappingModel =
    pdfUniversalTextCellMappingModel;


/* =========================================================
   RESULT
   ========================================================= */

