/* =========================================================
   STEP 57 — UNIFIED DOCX CELL MODEL
   ========================================================= */

const step57Grid =
    window.pdfUniversalStructuralGridModel;

const step57TextMap =
    window.pdfUniversalTextCellMappingModel;

const step57BorderMap =
    window.pdfUniversalBorderCellMappingModel;


if (
    !step57Grid ||
    !step57TextMap ||
    !step57BorderMap
) {

    console.error(
        "STEP 57 ERROR: Required models are missing."
    );

    throw new Error(
        "Step 57 cannot continue."
    );
}


/* =========================================================
   CREATE EMPTY CELL MATRIX
   ========================================================= */

const step57Cells = [];

for (
    let rowIndex = 0;
    rowIndex < step57Grid.rows.length;
    rowIndex++
) {

    const row =
        step57Grid.rows[rowIndex];

    const cellRow = [];

    for (
        let colIndex = 0;
        colIndex < step57Grid.columns.length;
        colIndex++
    ) {

        const column =
            step57Grid.columns[colIndex];

        cellRow.push({

            rowNumber:
                row.index,

            columnNumber:
                column.index,

            topTwips:
                row.topTwips,

            bottomTwips:
                row.bottomTwips,

            leftTwips:
                column.leftTwips,

            rightTwips:
                column.rightTwips,

            widthTwips:
                column.widthTwips,

            heightTwips:
                row.heightTwips,

            texts: [],

            borders: {

                top: false,
                bottom: false,
                left: false,
                right: false

            }

        });

    }

    step57Cells.push(
        cellRow
    );

}


/* =========================================================
   ADD TEXT TO CELLS
   ========================================================= */

(
    step57TextMap.elements || []
).forEach(text => {

    if (!text.mapped) {
        return;
    }

    const rowIndex =
        Number(text.rowIndex);

    const columnIndex =
        Number(text.columnIndex);

    if (
        !step57Cells[rowIndex] ||
        !step57Cells[rowIndex][columnIndex]
    ) {
        return;
    }

    step57Cells[rowIndex][columnIndex]
        .texts
        .push({

            textIndex:
                text.textIndex,

            sourceIndex:
                text.sourceIndex,

            text:
                text.text,

            xTwips:
                text.xTwips,

            yTwips:
                text.yTwips,

            widthTwips:
                text.widthTwips,

            heightTwips:
                text.heightTwips,

            score:
                text.score,

            overlapRatio:
                text.overlapRatio

        });

});


/* =========================================================
   HORIZONTAL BORDER → CELL SIDES
   ========================================================= */

(
    step57BorderMap.horizontalElements || []
).forEach(border => {

    if (!border.mapped) {
        return;
    }

    const rowNumber =
        Number(border.rowNumber);

    const rowIndex =
        rowNumber - 1;

    if (
        !step57Cells[rowIndex]
    ) {
        return;
    }


    (
        border.touchedColumns || []
    ).forEach(columnInfo => {

        const columnNumber =
            Number(
                columnInfo.columnNumber
            );

        const columnIndex =
            columnNumber - 1;

        const cell =
            step57Cells[rowIndex]
                [columnIndex];

        if (!cell) {
            return;
        }


        /* Find whether border is
           top or bottom of this row */

        const row =
            step57Grid.rows[rowIndex];

        const distanceTop =
            Math.abs(
                border.yTwips -
                row.topTwips
            );

        const distanceBottom =
            Math.abs(
                border.yTwips -
                row.bottomTwips
            );


        if (
            distanceTop <=
            distanceBottom
        ) {

            cell.borders.top = true;

        } else {

            cell.borders.bottom = true;

        }

    });

});


/* =========================================================
   VERTICAL BORDER → CELL SIDES
   ========================================================= */

(
    step57BorderMap.verticalElements || []
).forEach(border => {

    if (!border.mapped) {
        return;
    }

    const columnNumber =
        Number(border.columnNumber);

    const columnIndex =
        columnNumber - 1;


    (
        border.touchedRows || []
    ).forEach(rowInfo => {

        const rowNumber =
            Number(
                rowInfo.rowNumber
            );

        const rowIndex =
            rowNumber - 1;

        const cell =
            step57Cells[rowIndex]
                ? step57Cells[rowIndex]
                    [columnIndex]
                : null;

        if (!cell) {
            return;
        }


        const column =
            step57Grid.columns[
                columnIndex
            ];

        const distanceLeft =
            Math.abs(
                border.xTwips -
                column.leftTwips
            );

        const distanceRight =
            Math.abs(
                border.xTwips -
                column.rightTwips
            );


        if (
            distanceLeft <=
            distanceRight
        ) {

            cell.borders.left = true;

        } else {

            cell.borders.right = true;

        }

    });

});


/* =========================================================
   CELL STATISTICS
   ========================================================= */

let step57CellsWithText = 0;
let step57CellsWithBorders = 0;
let step57TotalText = 0;

const step57UsedCells = [];


step57Cells.forEach(row => {

    row.forEach(cell => {

        if (
            cell.texts.length > 0
        ) {

            step57CellsWithText++;

            step57TotalText +=
                cell.texts.length;

            step57UsedCells.push(
                {
                    row:
                        cell.rowNumber,

                    column:
                        cell.columnNumber,

                    textCount:
                        cell.texts.length
                }
            );

        }


        const hasBorder =
            cell.borders.top ||
            cell.borders.bottom ||
            cell.borders.left ||
            cell.borders.right;

        if (hasBorder) {

            step57CellsWithBorders++;

        }

    });

});


/* =========================================================
   FINAL MODEL
   ========================================================= */

const pdfUniversalUnifiedDocxCellModel = {

    version:
        "1.0",

    coordinateUnit:
        "twips",

    page:
        step57Grid.page,

    grid:
        {

            columns:
                step57Grid.columns.length,

            rows:
                step57Grid.rows.length,

            totalCells:
                step57Grid.columns.length *
                step57Grid.rows.length

        },

    statistics:
        {

            cellsWithText:
                step57CellsWithText,

            cellsWithBorders:
                step57CellsWithBorders,

            totalText:
                step57TotalText

        },

    cells:
        step57Cells,

    usedCells:
        step57UsedCells

};


/* =========================================================
   SAVE
   ========================================================= */

window.pdfUniversalUnifiedDocxCellModel =
    pdfUniversalUnifiedDocxCellModel;


/* =========================================================
   RESULT
   ========================================================= */

