const step59CellModel =
    window.pdfUniversalUnifiedDocxCellModel;

const step59VerifyModel =
    window.pdfUniversalUnifiedCellVerificationModel;

if (!step59CellModel) {
    throw new Error(
        "STEP 59 ERROR: Unified Cell Model not found."
    );
}

if (!step59VerifyModel || !step59VerifyModel.passed) {
    throw new Error(
        "STEP 59 ERROR: Step 58 verification has not passed."
    );
}


/* =========================================================
   DOCX LIBRARY CHECK
   ========================================================= */

if (
    typeof Document === "undefined" ||
    typeof Packer === "undefined" ||
    typeof Table === "undefined" ||
    typeof TableRow === "undefined" ||
    typeof TableCell === "undefined" ||
    typeof Paragraph === "undefined" ||
    typeof TextRun === "undefined"
) {
    throw new Error(
        "STEP 59 ERROR: DOCX library is not loaded."
    );
}


/* =========================================================
   PAGE SIZE
   ========================================================= */

const step59PageWidth =
    Number(
        step59CellModel.page.widthTwips
    );

const step59PageHeight =
    Number(
        step59CellModel.page.heightTwips
    );


/* =========================================================
   GRID
   ========================================================= */

const step59Rows =
    step59CellModel.grid.rows;

const step59Columns =
    step59CellModel.grid.columns;

const step59Cells =
    step59CellModel.cells;


/* =========================================================
   BORDER HELPER
   ========================================================= */

function step59Border(enabled) {

    if (enabled) {

        return {
            style: BorderStyle.SINGLE,
            size: 4,
            color: "000000"
        };

    }

    return {
        style: BorderStyle.NONE,
        size: 0,
        color: "FFFFFF"
    };

}


/* =========================================================
   TEXT PARAGRAPH
   ========================================================= */

function step59CreateTextParagraph(textObject) {

    const text =
        String(
            textObject.text || ""
        );

    if (!text) {

        return new Paragraph({
            children: []
        });

    }


    /* -----------------------------------------
       Approximate font size
       ----------------------------------------- */

    let fontSize =
        Number(
            textObject.fontSize ||
            textObject.heightTwips / 20 ||
            10
        );


    /*
       PDF text height is not always the same
       as actual font size.

       Keep the first renderer conservative.
    */

    if (!Number.isFinite(fontSize)) {
        fontSize = 10;
    }

    fontSize =
        Math.max(
            7,
            Math.min(
                18,
                fontSize
            )
        );


    return new Paragraph({

        spacing: {
            before: 0,
            after: 0,
            line: 240
        },

        children: [

            new TextRun({

                text: text,

                font: "Arial",

                size:
                    Math.round(
                        fontSize * 2
                    )

            })

        ]

    });

}


/* =========================================================
   CELL TEXT
   ========================================================= */

function step59CreateCellChildren(cell) {

    const texts =
        Array.isArray(cell.texts)
            ? cell.texts
            : [];


    /*
       Preserve source order.
    */

    texts.sort(
        (a, b) =>
            Number(a.textIndex || 0) -
            Number(b.textIndex || 0)
    );


    if (texts.length === 0) {

        return [

            new Paragraph({
                spacing: {
                    before: 0,
                    after: 0
                },
                children: []
            })

        ];

    }


    return texts.map(
        textObject =>
            step59CreateTextParagraph(
                textObject
            )
    );

}


/* =========================================================
   CELL CREATION
   ========================================================= */

function step59CreateCell(cell) {

    const children =
        step59CreateCellChildren(
            cell
        );


    return new TableCell({

        width: {
            size:
                Number(
                    cell.widthTwips
                ),
            type: WidthType.DXA
        },


        verticalAlign:
            VerticalAlign.CENTER,


        margins: {

            top: 40,
            bottom: 40,
            left: 60,
            right: 60

        },


        borders: {

            top:
                step59Border(
                    Boolean(
                        cell.borders?.top
                    )
                ),

            bottom:
                step59Border(
                    Boolean(
                        cell.borders?.bottom
                    )
                ),

            left:
                step59Border(
                    Boolean(
                        cell.borders?.left
                    )
                ),

            right:
                step59Border(
                    Boolean(
                        cell.borders?.right
                    )
                )

        },


        children:
            children

    });

}


/* =========================================================
   ROW CREATION
   ========================================================= */

function step59CreateRow(rowCells) {

    const cells =
        rowCells.map(
            cell =>
                step59CreateCell(
                    cell
                )
        );


    return new TableRow({

        children: cells

    });

}


/* =========================================================
   CREATE DOCX ROWS
   ========================================================= */

const step59DocxRows = [];


for (
    let rowIndex = 0;
    rowIndex < step59Rows;
    rowIndex++
) {

    const sourceRow =
        step59Cells[rowIndex];


    if (
        !Array.isArray(sourceRow)
    ) {

        throw new Error(
            "STEP 59 ERROR: Invalid row " +
            rowIndex
        );

    }


    const row =
        step59CreateRow(
            sourceRow
        );


    step59DocxRows.push(
        row
    );

}


/* =========================================================
   COLUMN WIDTHS
   ========================================================= */

const step59ColumnWidths = [];


for (
    let columnIndex = 0;
    columnIndex < step59Columns;
    columnIndex++
) {

    let width = 0;


    for (
        let rowIndex = 0;
        rowIndex < step59Rows;
        rowIndex++
    ) {

        const cell =
            step59Cells[rowIndex]
                [columnIndex];


        if (cell) {

            width =
                Math.max(
                    width,
                    Number(
                        cell.widthTwips || 0
                    )
                );

        }

    }


    step59ColumnWidths.push(
        width
    );

}


/* =========================================================
   CREATE TABLE
   ========================================================= */

const step59Table =
    new Table({

        width: {

            size:
                step59PageWidth,

            type:
                WidthType.DXA

        },


        layout:
            "fixed",


        columnWidths:
            step59ColumnWidths,


        rows:
            step59DocxRows

    });


/* =========================================================
   CREATE DOCUMENT
   ========================================================= */

const step59Document =
    new Document({

        sections: [

            {

                properties: {

                    page: {

                        width:
                            step59PageWidth,

                        height:
                            step59PageHeight,

                        margin: {

                            top: 0,

                            bottom: 0,

                            left: 0,

                            right: 0

                        }

                    }

                },


                children: [

                    step59Table

                ]

            }

        ]

    });


/* =========================================================
   STORE RENDER MODEL
   ========================================================= */

window.pdfUniversalFirstDocxRenderModel = {

    version:
        "1.0",

    page: {

        widthTwips:
            step59PageWidth,

        heightTwips:
            step59PageHeight

    },

    grid: {

        rows:
            step59Rows,

        columns:
            step59Columns,

        cells:
            step59Rows *
            step59Columns

    },

    textElements:
        34,

    renderer:
        "universal-structural-table",

    status:
        "ready"

};


