const step62TestItems =
    step62TextItems.slice(0, 10);


step62TestItems.forEach(
    (item, index) => {

        const convertedX =
            Number(item.x) *
            step62ScaleX;

        const convertedY =
            (
                step62PdfHeight -
                Number(item.y) -
                Number(item.height || 0)
            ) *
            step62ScaleY;

        const convertedWidth =
            Number(item.width || 0) *
            step62ScaleX;

        const convertedHeight =
            Number(item.height || 0) *
            step62ScaleY;


        console.log(
            "TEXT",
            index,
            "|",
            item.text,
            "| X:",
            convertedX,
            "| Y:",
            convertedY,
            "| W:",
            convertedWidth,
            "| H:",
            convertedHeight
        );

    }
);


/* =========================================================
   STEP 62 — FIND CELL FOR ONE TEXT ITEM
   ========================================================= */

function step62FindCellForText(item) {

    const itemX =
        Number(item.x) * step62ScaleX;

    const itemY =
        (
            step62PdfHeight -
            Number(item.y) -
            Number(item.height || 0)
        ) * step62ScaleY;

    const itemRight =
        itemX +
        (
            Number(item.width || 0) *
            step62ScaleX
        );

    const itemBottom =
        itemY +
        (
            Number(item.height || 0) *
            step62ScaleY
        );


    for (
        let i = 0;
        i < step62CellMap.cells.length;
        i++
    ) {

        const cell =
            step62CellMap.cells[i];


        const overlapX =
            itemX < cell.rightTwips &&
            itemRight > cell.leftTwips;


        const overlapY =
            itemY < cell.bottomTwips &&
            itemBottom > cell.topTwips;


        if (
            overlapX &&
            overlapY
        ) {

            return cell;

        }

    }


    return null;
}


