/* =========================================================
   STEP 62 — STEP 9
   GROUP TEXT ITEMS BY GRID CELL
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 9 START");
console.log("GROUP TEXT ITEMS BY CELL");
console.log("=================================");

const step62CellContentMap = {};

step62MappedItems.forEach(item => {

    const row = item.cellRow;
    const column = item.cellColumn;

    if (row === null || column === null) {
        return;
    }

    const cellKey = `R${row}C${column}`;

    if (!step62CellContentMap[cellKey]) {

        step62CellContentMap[cellKey] = {
            row: row,
            column: column,
            items: [],
            text: ""
        };

    }

    step62CellContentMap[cellKey].items.push(item);

});


/* =========================================================
   SORT ITEMS INSIDE EACH CELL
   ========================================================= */

Object.values(step62CellContentMap).forEach(cell => {

    cell.items.sort((a, b) => {

        // PDF Y coordinate:
        // Higher Y = higher on page
        if (a.y !== b.y) {
            return b.y - a.y;
        }

        // Same line → left to right
        return a.x - b.x;

    });

});


/* =========================================================
   JOIN TEXT FRAGMENTS
   ========================================================= */

Object.values(step62CellContentMap).forEach(cell => {

    cell.text =
        cell.items
            .map(item => item.text)
            .join(" ");

});


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalCellContentMap = {

    version: "1.0",

    totalCells:
        Object.keys(step62CellContentMap).length,

    cells:
        step62CellContentMap,

    status: "ready"

};


