const step62RowAnalysis = [];

for (
    let row = 1;
    row <= window.pdfUniversalCompleteCellModel.cells
        .reduce(
            (max, cell) =>
                Math.max(max, cell.row),
            0
        );
    row++
) {

    const rowCells =
        window.pdfUniversalCompleteCellModel.cells
            .filter(cell => cell.row === row);

    const contentCells =
        rowCells.filter(
            cell => cell.text !== ""
        );

    step62RowAnalysis.push({

        row: row,

        totalCells:
            rowCells.length,

        contentCells:
            contentCells.length,

        hasContent:
            contentCells.length > 0,

        texts:
            contentCells.map(
                cell => cell.text
            )

    });

}


