console.log("CELL SPAN ANALYSIS");
console.log("=================================");

const step62SpanAnalysis = [];

window.pdfUniversalCompleteCellModel.cells.forEach(cell => {

    const content =
        window.pdfUniversalCellContentMap
            .cells[`R${cell.row}C${cell.column}`];

    step62SpanAnalysis.push({

        row:
            cell.row,

        column:
            cell.column,

        widthTwips:
            cell.widthTwips,

        heightTwips:
            cell.heightTwips,

        text:
            cell.text,

        itemCount:
            cell.itemCount,

        hasContent:
            cell.text !== ""

    });

});


/* =========================================================
   FIND CELLS WITH CONTENT
   ========================================================= */

const step62ContentCells =
    step62SpanAnalysis.filter(
        cell => cell.hasContent
    );


/* =========================================================
   WIDTH GROUP ANALYSIS
   ========================================================= */

const step62WidthGroups = {};

step62ContentCells.forEach(cell => {

    const width =
        cell.widthTwips;

    if (!step62WidthGroups[width]) {
        step62WidthGroups[width] = 0;
    }

    step62WidthGroups[width]++;

});


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalCellSpanAnalysis = {

    version: "1.0",

    totalCells:
        step62SpanAnalysis.length,

    contentCells:
        step62ContentCells.length,

    widthGroups:
        step62WidthGroups,

    cells:
        step62SpanAnalysis,

    status: "ready"

};


