const step62BoundaryAnalysis = [];


window.pdfUniversalCompleteCellModel.cells
    .filter(cell => cell.text !== "")
    .forEach(cell => {

        const cellKey =
            `R${cell.row}C${cell.column}`;

        const content =
            window.pdfUniversalCellContentMap
                .cells[cellKey];

        if (!content || !content.items.length) {
            return;
        }


        const items =
            content.items;


        /* -------------------------------------------------
           TEXT BOUNDARIES
           ------------------------------------------------- */

        const textLeft =
            Math.min(
                ...items.map(
                    item =>
                        Number(item.x) *
                        20
                )
            );

        const textRight =
            Math.max(
                ...items.map(
                    item =>
                        (
                            Number(item.x) +
                            Number(item.width || 0)
                        ) * 20
                )
            );


        const textTop =
            Math.min(
                ...items.map(
                    item =>
                        (
                            816.5 -
                            Number(item.y) -
                            Number(item.height || 0)
                        ) * 20
                )
            );

        const textBottom =
            Math.max(
                ...items.map(
                    item =>
                        (
                            816.5 -
                            Number(item.y)
                        ) * 20
                )
            );


        /* -------------------------------------------------
           STORE COMPARISON
           ------------------------------------------------- */

        step62BoundaryAnalysis.push({

            cell:
                cellKey,

            text:
                cell.text,

            cellLeft:
                cell.leftTwips,

            cellRight:
                cell.rightTwips,

            cellTop:
                cell.topTwips,

            cellBottom:
                cell.bottomTwips,

            textLeft:
                Math.round(textLeft),

            textRight:
                Math.round(textRight),

            textTop:
                Math.round(textTop),

            textBottom:
                Math.round(textBottom)

        });

    });


