console.log("TEXT POSITION → GRID ANALYSIS");
console.log("=================================");


const step17DLayout =
    window.pdfLayoutAnalysis;

const step17DGrid =
    window.pdfUniversalActualGridBoundaries;


const step17DPage =
    step17DLayout?.pages?.[0];

const step17DItems =
    step17DPage?.textItems || [];

const step17DX =
    step17DGrid?.xBoundaries || [];

const step17DY =
    step17DGrid?.yBoundaries || [];


/* =========================================================
   FIND COLUMN
   ========================================================= */

function step17DFindColumn(x) {

    for (
        let i = 0;
        i < step17DX.length - 1;
        i++
    ) {

        if (
            x >= step17DX[i] &&
            x < step17DX[i + 1]
        ) {

            return i + 1;

        }

    }

    return null;

}


/* =========================================================
   FIND ROW
   ========================================================= */

function step17DFindRow(y) {

    for (
        let i = 0;
        i < step17DY.length - 1;
        i++
    ) {

        if (
            y >= step17DY[i] &&
            y < step17DY[i + 1]
        ) {

            return i + 1;

        }

    }

    return null;

}


/* =========================================================
   ANALYZE TEXT ITEMS
   ========================================================= */

const step17DResults =
    step17DItems.map(item => {

        const x =
            Number(item.x) * 20;

        const y =
            (
                Number(step17DPage.height) -
                Number(item.y) -
                Number(item.height || 0)
            ) * 20;

        return {

            index:
                item.index,

            text:
                item.text,

            x:
                Math.round(x),

            y:
                Math.round(y),

            column:
                step17DFindColumn(x),

            row:
                step17DFindRow(y)

        };

    });


/* =========================================================
   STORE RESULT
   ========================================================= */

window.pdfUniversalTextGridPositionAnalysis = {

    version:
        "1.0",

    totalItems:
        step17DResults.length,

    items:
        step17DResults,

    status:
        "ready"

};


