/* =========================================================
   STEP 62 — STEP 17E
   TEXT LINE GROUPING
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17E START");
console.log("TEXT LINE GROUPING");
console.log("=================================");


const step17EAnalysis =
    window.pdfUniversalTextGridPositionAnalysis;

const step17EItems =
    step17EAnalysis?.items || [];


/* =========================================================
   GROUP BY ROW + COLUMN
   ========================================================= */

const step17ELines = {};


step17EItems.forEach(item => {

    if (
        item.row === null ||
        item.column === null
    ) {
        return;
    }


    const key =
        `R${item.row}C${item.column}`;


    if (!step17ELines[key]) {

        step17ELines[key] = {

            row:
                item.row,

            column:
                item.column,

            items:
                []

        };

    }


    step17ELines[key].items.push(item);

});


/* =========================================================
   SORT ITEMS INSIDE EACH CELL
   ========================================================= */

Object.values(step17ELines)
    .forEach(group => {

        group.items.sort(
            (a, b) => {

                if (a.y !== b.y) {
                    return a.y - b.y;
                }

                return a.x - b.x;

            }
        );

    });


/* =========================================================
   CREATE LINE TEXT
   ========================================================= */

Object.values(step17ELines)
    .forEach(group => {

        group.text =
            group.items
                .map(item => item.text)
                .join(" ");

    });


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalTextLineModel = {

    version:
        "1.0",

    totalGroups:
        Object.keys(step17ELines).length,

    groups:
        step17ELines,

    status:
        "ready"

};


/* =========================================================
   RESULT
   ========================================================= */

console.log(
    "Total Text Groups:",
    Object.keys(step17ELines).length
);


Object.values(step17ELines)
    .slice(0, 10)
    .forEach(group => {

        console.log(
            `R${group.row}C${group.column}`,
            "|",
            group.text,
            "| ITEMS:",
            group.items.length
        );

    });


