/* =========================================================
   STEP 62 — STEP 17F
   TEXT ALIGNMENT ANALYSIS
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17F START");
console.log("TEXT ALIGNMENT ANALYSIS");
console.log("=================================");


const step17FModel =
    window.pdfUniversalTextLineModel;

const step17FCellMap =
    window.pdfUniversalCompleteCellModel;


const step17FGroups =
    step17FModel?.groups || {};


/* =========================================================
   ALIGNMENT FUNCTION
   ========================================================= */

function step17FGetAlignment(
    textLeft,
    textRight,
    cellLeft,
    cellRight
) {

    const cellCenter =
        (cellLeft + cellRight) / 2;

    const textCenter =
        (textLeft + textRight) / 2;

    const tolerance =
        100;


    if (
        Math.abs(
            textCenter - cellCenter
        ) <= tolerance
    ) {

        return "center";

    }


    if (
        Math.abs(
            textLeft - cellLeft
        ) <= tolerance
    ) {

        return "left";

    }


    if (
        Math.abs(
            textRight - cellRight
        ) <= tolerance
    ) {

        return "right";

    }


    return "positioned";

}


/* =========================================================
   ANALYZE GROUPS
   ========================================================= */

const step17FResults = [];


Object.values(step17FGroups)
    .forEach(group => {

        if (
            !group.items ||
            group.items.length === 0
        ) {
            return;
        }


        const firstItem =
            group.items[0];

        const lastItem =
            group.items[
                group.items.length - 1
            ];


        const textLeft =
            Math.min(
                ...group.items.map(
                    item => item.x
                )
            );


        const textRight =
            Math.max(
                ...group.items.map(
                    item =>
                        item.x
                )
            );


        const cell =
            step17FCellMap.cells.find(
                item =>
                    item.row === group.row &&
                    item.column === group.column
            );


        if (!cell) {
            return;
        }


        const alignment =
            step17FGetAlignment(
                textLeft,
                textRight,
                cell.leftTwips,
                cell.rightTwips
            );


        step17FResults.push({

            row:
                group.row,

            column:
                group.column,

            text:
                group.text,

            textLeft:
                Math.round(textLeft),

            textRight:
                Math.round(textRight),

            cellLeft:
                cell.leftTwips,

            cellRight:
                cell.rightTwips,

            alignment:
                alignment

        });

    });


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalTextAlignmentModel = {

    version:
        "1.0",

    totalGroups:
        step17FResults.length,

    groups:
        step17FResults,

    status:
        "ready"

};


/* =========================================================
   RESULT
   ========================================================= */

console.log(
    "Total Groups:",
    step17FResults.length
);


step17FResults
    .slice(0, 15)
    .forEach(group => {

        console.log(
            `R${group.row}C${group.column}`,
            "|",
            group.alignment,
            "| LEFT:",
            group.textLeft,
            "| RIGHT:",
            group.textRight,
            "|",
            group.text
        );

    });


console.log(
    "TEXT ALIGNMENT MODEL:",
    window.pdfUniversalTextAlignmentModel
);


console.log("=================================");
console.log("STEP 62 — STEP 17F COMPLETE");
console.log("=================================");




/* =========================================================
   STEP 62 — STEP 17F-2
   CORRECT TEXT BOUNDARY ANALYSIS
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17F-2 START");
console.log("CORRECT TEXT BOUNDARIES");
console.log("=================================");


const step17F2Model =
    window.pdfUniversalTextLineModel;

const step17F2CellModel =
    window.pdfUniversalCompleteCellModel;

const step17F2Groups =
    step17F2Model?.groups || {};


/* =========================================================
   ANALYZE GROUPS
   ========================================================= */

const step17F2Results = [];


Object.values(step17F2Groups)
    .forEach(group => {

        if (
            !group.items ||
            group.items.length === 0
        ) {
            return;
        }


        const textLeft =
            Math.min(
                ...group.items.map(
                    item => Number(item.x)
                )
            );


        const textRight =
            Math.max(
                ...group.items.map(
                    item =>
                        Number(item.x) +
                        Number(item.width || 0)
                )
            );


        const cell =
            step17F2CellModel.cells.find(
                item =>
                    item.row === group.row &&
                    item.column === group.column
            );


        if (!cell) {
            return;
        }


        const cellCenter =
            (
                Number(cell.leftTwips) +
                Number(cell.rightTwips)
            ) / 2;


        const textCenter =
            (
                textLeft +
                textRight
            ) / 2;


        const cellLeft =
            Number(cell.leftTwips);

        const cellRight =
            Number(cell.rightTwips);


        let alignment =
            "positioned";


        const tolerance =
            100;


        if (
            Math.abs(
                textCenter - cellCenter
            ) <= tolerance
        ) {

            alignment =
                "center";

        }
        else if (
            Math.abs(
                textLeft - cellLeft
            ) <= tolerance
        ) {

            alignment =
                "left";

        }
        else if (
            Math.abs(
                textRight - cellRight
            ) <= tolerance
        ) {

            alignment =
                "right";

        }


        step17F2Results.push({

            row:
                group.row,

            column:
                group.column,

            text:
                group.text,

            textLeft:
                Math.round(textLeft),

            textRight:
                Math.round(textRight),

            textWidth:
                Math.round(
                    textRight - textLeft
                ),

            cellLeft:
                cellLeft,

            cellRight:
                cellRight,

            alignment:
                alignment

        });

    });


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalCorrectTextBoundaryModel = {

    version:
        "1.0",

    totalGroups:
        step17F2Results.length,

    groups:
        step17F2Results,

    status:
        "ready"

};


