/* =========================================================
   STEP 62 — STEP 17K
   VERTICAL ANCHOR ANALYSIS
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17K START");
console.log("VERTICAL ANCHOR ANALYSIS");
console.log("=================================");


const step17KTextModel =
    window.pdfUniversalTextDimensionModel;

const step17KCellModel =
    window.pdfUniversalCompleteCellModel;


const step17KItems =
    step17KTextModel?.items || [];


/* =========================================================
   ANALYZE VERTICAL CENTER
   ========================================================= */

const step17KResults =
    step17KItems.map(item => {

        const cell =
            step17KCellModel.cells.find(
                cell =>
                    cell.row === item.row &&
                    cell.column === item.column
            );


        if (!cell) {
            return null;
        }


        const textTop =
            Number(item.y);

        const textHeight =
            Number(item.height || 0);


        const textCenter =
            textTop +
            (textHeight / 2);


        const cellTop =
            Number(cell.topTwips);

        const cellBottom =
            Number(cell.bottomTwips);


        const cellCenter =
            (
                cellTop +
                cellBottom
            ) / 2;


        const centerOffset =
            textCenter -
            cellCenter;


        let anchor =
            "middle";


        const tolerance =
            100;


        if (
            centerOffset <
            -tolerance
        ) {

            anchor =
                "upper";

        }
        else if (
            centerOffset >
            tolerance
        ) {

            anchor =
                "lower";

        }


        return {

            index:
                item.index,

            text:
                item.text,

            row:
                item.row,

            column:
                item.column,

            textCenter:
                Math.round(
                    textCenter
                ),

            cellCenter:
                Math.round(
                    cellCenter
                ),

            centerOffset:
                Math.round(
                    centerOffset
                ),

            anchor:
                anchor

        };

    })
    .filter(Boolean);


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalVerticalAnchorModel = {

    version:
        "1.0",

    totalItems:
        step17KResults.length,

    items:
        step17KResults,

    status:
        "ready"

};


