/* =========================================================
   STEP 62 — STEP 17Q
   TEXT RUN SPACING ANALYSIS
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17Q START");
console.log("TEXT RUN SPACING ANALYSIS");
console.log("=================================");


const step17QModel =
    window.pdfUniversalTextRunModel;


if (!step17QModel) {

    throw new Error(
        "STEP 17Q ERROR: Text Run Model not found."
    );

}


const step17QRuns =
    step17QModel.runs || [];


/* =========================================================
   GROUP RUNS BY ROW + COLUMN
   ========================================================= */

const step17QGroups = {};


step17QRuns.forEach(run => {

    const key =
        `R${run.row}C${run.column}`;


    if (!step17QGroups[key]) {

        step17QGroups[key] = {

            row:
                run.row,

            column:
                run.column,

            runs:
                []

        };

    }


    step17QGroups[key].runs.push(
        run
    );

});


/* =========================================================
   SORT + CALCULATE SPACING
   ========================================================= */

Object.values(step17QGroups)
    .forEach(group => {

        group.runs.sort(
            (a, b) => a.x - b.x
        );


        group.runs.forEach(
            (run, index) => {

                if (index === 0) {

                    run.gapFromPrevious =
                        null;

                    return;

                }


                const previous =
                    group.runs[index - 1];


                const previousRight =
                    previous.x +
                    previous.width;


                run.gapFromPrevious =
                    Math.round(
                        run.x -
                        previousRight
                    );

            }
        );

    });


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalTextRunSpacingModel = {

    version:
        "1.0",

    totalGroups:
        Object.keys(step17QGroups).length,

    groups:
        step17QGroups,

    status:
        "ready"

};


/* =========================================================
   RESULT
   ========================================================= */

console.log(
    "TOTAL RUN GROUPS:",
    Object.keys(step17QGroups).length
);


[
    "R2C2",
    "R3C2",
    "R6C2",
    "R6C3"
]
.forEach(key => {

    const group =
        step17QGroups[key];


    if (!group) return;


    console.log(
        "---------------------------------"
    );

    console.log(
        "GROUP:",
        key
    );


    group.runs.forEach(run => {

        console.log(
            "RUN:",
            run.text,
            "| X:",
            run.x,
            "| W:",
            run.width,
            "| GAP:",
            run.gapFromPrevious
        );

    });

});


console.log(
    "TEXT RUN SPACING MODEL:",
    window.pdfUniversalTextRunSpacingModel
);


console.log("=================================");
console.log("STEP 62 — STEP 17Q COMPLETE");
console.log("=================================");



