/* =========================================================
   STEP 62 — STEP 17V
   GRAPHICS PATH GEOMETRY ANALYSIS
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17V START");
console.log("GRAPHICS PATH GEOMETRY ANALYSIS");
console.log("=================================");


const step17VGraphics =
    window.pdfLayoutAnalysis
        ?.pages?.[0]
        ?.graphics || [];


if (
    !Array.isArray(step17VGraphics)
) {

    throw new Error(
        "STEP 17V ERROR: Graphics data not found."
    );

}


/* =========================================================
   ANALYZE PATHS
   ========================================================= */

const step17VPaths = [];


step17VGraphics.forEach(
    (graphic, index) => {

        if (
            graphic.type !== "path"
        ) {

            return;

        }


        const args =
            graphic.args || [];


        const geometry =
            args[2];


        if (
            !Array.isArray(geometry) ||
            geometry.length < 4
        ) {

            return;

        }


        const x1 =
            Number(geometry[0]);

        const y1 =
            Number(geometry[1]);

        const x2 =
            Number(geometry[2]);

        const y2 =
            Number(geometry[3]);


        const width =
            Math.abs(x2 - x1);

        const height =
            Math.abs(y2 - y1);


        let orientation =
            "other";


        const tolerance =
            0.01;


        if (
            height <= tolerance &&
            width > tolerance
        ) {

            orientation =
                "horizontal";

        }
        else if (
            width <= tolerance &&
            height > tolerance
        ) {

            orientation =
                "vertical";

        }
        else if (
            width > tolerance &&
            height > tolerance
        ) {

            orientation =
                "diagonal-or-rectangle";

        }


        step17VPaths.push({

            graphicIndex:
                index,

            pdfIndex:
                graphic.index,

            x1:
                x1,

            y1:
                y1,

            x2:
                x2,

            y2:
                y2,

            width:
                width,

            height:
                height,

            orientation:
                orientation

        });

    }
);


/* =========================================================
   STORE MODEL
   ========================================================= */

window.pdfUniversalPathGeometryModel = {

    version:
        "1.0",

    totalPaths:
        step17VPaths.length,

    paths:
        step17VPaths,

    status:
        "ready"

};


/* =========================================================
   SUMMARY
   ========================================================= */

const horizontalCount =
    step17VPaths.filter(
        path =>
            path.orientation ===
            "horizontal"
    ).length;


const verticalCount =
    step17VPaths.filter(
        path =>
            path.orientation ===
            "vertical"
    ).length;


const otherCount =
    step17VPaths.filter(
        path =>
            path.orientation ===
            "other"
    ).length;


const diagonalOrRectangleCount =
    step17VPaths.filter(
        path =>
            path.orientation ===
            "diagonal-or-rectangle"
    ).length;


console.log(
    "TOTAL PATHS:",
    step17VPaths.length
);

