console.log("STEP 62 — STEP 17W START");
console.log("REAL BORDER GEOMETRY ANALYSIS");
console.log("=================================");

const step17WGraphics =
    window.pdfLayoutAnalysis
        ?.pages?.[0]
        ?.graphics || [];

if (!Array.isArray(step17WGraphics)) {
    throw new Error(
        "STEP 17W ERROR: Graphics data not found."
    );
}


/* =========================================================
   COLLECT PATH BOUNDING BOXES
   ========================================================= */

const step17WPaths = [];

step17WGraphics.forEach((graphic, index) => {

    if (graphic.type !== "path") {
        return;
    }

    const args = graphic.args || [];

    if (!Array.isArray(args)) {
        return;
    }

    const geometry = args[2];

    if (
        !Array.isArray(geometry) ||
        geometry.length < 4
    ) {
        return;
    }

    const x =
        Number(geometry[0]);

    const y =
        Number(geometry[1]);

    const width =
        Math.abs(Number(geometry[2]));

    const height =
        Math.abs(Number(geometry[3]));

    let type = "other";


    /*
     * Thin horizontal rectangle
     */

    if (
        width > 20 &&
        height <= 3
    ) {

        type = "horizontal-border";

    }


    /*
     * Thin vertical rectangle
     */

    else if (
        height > 20 &&
        width <= 3
    ) {

        type = "vertical-border";

    }


    /*
     * Small corner / connector
     */

    else if (
        width <= 3 &&
        height <= 3
    ) {

        type = "small-connector";

    }


    /*
     * Normal rectangle / filled area
     */

    else {

        type = "rectangle-or-filled-area";

    }


    step17WPaths.push({

        graphicIndex:
            index,

        pdfIndex:
            graphic.index,

        x:
            x,

        y:
            y,

        width:
            width,

        height:
            height,

        type:
            type

    });

});


/* =========================================================
   COUNTS
   ========================================================= */

const horizontalBorders =
    step17WPaths.filter(
        path =>
            path.type ===
            "horizontal-border"
    );

const verticalBorders =
    step17WPaths.filter(
        path =>
            path.type ===
            "vertical-border"
    );

const smallConnectors =
    step17WPaths.filter(
        path =>
            path.type ===
            "small-connector"
    );

const rectangles =
    step17WPaths.filter(
        path =>
            path.type ===
            "rectangle-or-filled-area"
    );


/* =========================================================
   MODEL
   ========================================================= */

window.pdfUniversalRealBorderModel = {

    version:
        "1.0",

    totalPaths:
        step17WPaths.length,

    horizontalBorders:
        horizontalBorders,

    verticalBorders:
        verticalBorders,

    smallConnectors:
        smallConnectors,

    rectangles:
        rectangles,

    status:
        "ready"

};


/* =========================================================
   SUMMARY
   ========================================================= */

console.log(
    "TOTAL PATHS:",
    step17WPaths.length
);

console.log(
    "HORIZONTAL BORDERS:",
    horizontalBorders.length
);

console.log(
    "VERTICAL BORDERS:",
    verticalBorders.length
);

console.log(
    "SMALL CONNECTORS:",
    smallConnectors.length
);

