console.log("=================================");


const step17YModel =
    window.pdfUniversalCorrectGraphicsModel;


if (!step17YModel) {

    throw new Error(
        "STEP 17Y ERROR: Correct graphics model not found."
    );

}


/* =========================================================
   GET BORDERS
   ========================================================= */

const horizontal =
    Array.isArray(
        step17YModel.horizontalBorders
    )
        ? step17YModel.horizontalBorders
        : [];


const vertical =
    Array.isArray(
        step17YModel.verticalBorders
    )
        ? step17YModel.verticalBorders
        : [];


/* =========================================================
   UNIQUE HORIZONTAL Y POSITIONS
   ========================================================= */

const horizontalY = [];


horizontal.forEach(
    border => {

        const y =
            Number(border.y);

        if (
            Number.isFinite(y)
        ) {

            horizontalY.push(y);

        }

    }
);


const uniqueHorizontalY = [
    ...new Set(
        horizontalY.map(
            y =>
                Number(
                    y.toFixed(2)
                )
        )
    )
].sort(
    (a, b) => a - b
);


/* =========================================================
   UNIQUE VERTICAL X POSITIONS
   ========================================================= */

const verticalX = [];


vertical.forEach(
    border => {

        const x =
            Number(border.x);

        if (
            Number.isFinite(x)
        ) {

            verticalX.push(x);

        }

    }
);


const uniqueVerticalX = [
    ...new Set(
        verticalX.map(
            x =>
                Number(
                    x.toFixed(2)
                )
        )
    )
].sort(
    (a, b) => a - b
);


/* =========================================================
   COUNT OCCURRENCES
   ========================================================= */

const horizontalGroups =
    uniqueHorizontalY.map(
        y => {

            const matches =
                horizontal.filter(
                    border =>
                        Math.abs(
                            Number(border.y) - y
                        ) < 0.05
                );

            return {

                y:
                    y,

                count:
                    matches.length

            };

        }
    );


const verticalGroups =
    uniqueVerticalX.map(
        x => {

            const matches =
                vertical.filter(
                    border =>
                        Math.abs(
                            Number(border.x) - x
                        ) < 0.05
                );

            return {

                x:
                    x,

                count:
                    matches.length

            };

        }
    );


