    // =================================

    function getBorderBounds17AD(cell) {

        return {

            left: Number(
                cell.x || 0
            ),

            right:
                Number(cell.x || 0) +
                Number(cell.width || 0),

            top: Number(
                cell.y || 0
            ),

            bottom:
                Number(cell.y || 0) +
                Number(cell.height || 0),

            width: Number(
                cell.width || 0
            ),

            height: Number(
                cell.height || 0
            )

        };

    }


