/* =========================================================
   STEP 62 — STEP 17AI-C
   CORRECTED BORDER DEDUPLICATION
   & EXACT STRUCTURAL EDGE MAPPING
   ========================================================= */

console.log("=================================");
console.log("STEP 62 — STEP 17AI-C START");
console.log("CORRECTED BORDER EDGE MAPPING");
console.log("=================================");


/* ---------------------------------------------------------
   REQUIRED MODELS
   --------------------------------------------------------- */

const step17AICBorderModel =
    window.pdfUniversalBorderSegmentModel || null;

const step17AICCellMap =
    window.pdfUniversalDocxCellMap || null;

const step17AICTransform =
    window.pdfUniversalCoordinateTransform17AF || null;

const step17AICLayout =
    window.pdfLayoutAnalysis || null;


console.log(
    "BORDER MODEL FOUND:",
    !!step17AICBorderModel
);

console.log(
    "CELL MAP FOUND:",
    !!step17AICCellMap
);

console.log(
    "TRANSFORM MODEL FOUND:",
    !!step17AICTransform
);

console.log(
    "LAYOUT MODEL FOUND:",
    !!step17AICLayout
);


/* ---------------------------------------------------------
   VALIDATION
   --------------------------------------------------------- */

if (!step17AICBorderModel) {
    throw new Error(
        "STEP 17AI-C: BORDER MODEL NOT FOUND"
    );
}

if (!step17AICCellMap) {
    throw new Error(
        "STEP 17AI-C: CELL MAP NOT FOUND"
    );
}

if (!step17AICTransform) {
    throw new Error(
        "STEP 17AI-C: TRANSFORM MODEL NOT FOUND"
    );
}


/* ---------------------------------------------------------
   GET STRUCTURAL CELLS
   --------------------------------------------------------- */

let step17AICCells = [];

if (
    Array.isArray(step17AICCellMap)
) {

    step17AICCells =
        step17AICCellMap;

} else if (
    Array.isArray(step17AICCellMap.cells)
) {

    step17AICCells =
        step17AICCellMap.cells;

}


console.log(
    "STRUCTURAL CELLS:",
    step17AICCells.length
);


/* ---------------------------------------------------------
   SCALE
   --------------------------------------------------------- */

const step17AICScaleX = 20;
const step17AICScaleY = 20;


/* ---------------------------------------------------------
   TOLERANCES
   --------------------------------------------------------- */

const step17AICPositionTolerance =
    35;

const step17AICOverlapTolerance =
    20;


/* ---------------------------------------------------------
   NUMBER HELPER
   --------------------------------------------------------- */

function step17AICNumber(value) {

    const number =
        Number(value);

    return Number.isFinite(number)
        ? number
        : null;

}


/* ---------------------------------------------------------
   NORMALIZE CELLS
   --------------------------------------------------------- */

const step17AICNormalizedCells =
    step17AICCells
        .map(
            (cell, index) => {

                const left =
                    step17AICNumber(
                        cell?.leftTwips ??
                        cell?.xTwips ??
                        cell?.x ??
                        cell?.left
                    );

                const top =
                    step17AICNumber(
                        cell?.topTwips ??
                        cell?.yTwips ??
                        cell?.y ??
                        cell?.top
                    );

                const width =
                    step17AICNumber(
                        cell?.widthTwips ??
                        cell?.width
                    );

                const height =
                    step17AICNumber(
                        cell?.heightTwips ??
                        cell?.height
                    );

                const right =
                    step17AICNumber(
                        cell?.rightTwips ??
                        cell?.right
                    ) ??
                    (
                        left !== null &&
                        width !== null
                            ? left + width
                            : null
                    );

                const bottom =
                    step17AICNumber(
                        cell?.bottomTwips ??
                        cell?.bottom
                    ) ??
                    (
                        top !== null &&
                        height !== null
                            ? top + height
                            : null
                    );

                return {

                    cellIndex:
                        index,

                    row:
                        cell?.row ??
                        null,

                    column:
                        cell?.column ??
                        cell?.col ??
                        null,

                    left,
                    top,
                    right,
                    bottom

                };

            }
        )
        .filter(
            cell =>
                cell.left !== null &&
                cell.top !== null &&
                cell.right !== null &&
                cell.bottom !== null
        );


/* ---------------------------------------------------------
   SOURCE SEGMENTS
   --------------------------------------------------------- */

const step17AICHorizontalSource =
    Array.isArray(
        step17AICBorderModel.horizontal
    )
        ? step17AICBorderModel.horizontal
        : [];

const step17AICVerticalSource =
    Array.isArray(
        step17AICBorderModel.vertical
    )
        ? step17AICBorderModel.vertical
        : [];


console.log(
    "RAW HORIZONTAL:",
    step17AICHorizontalSource.length
);

console.log(
    "RAW VERTICAL:",
    step17AICVerticalSource.length
);


/* =========================================================
   HORIZONTAL BORDER DEDUPLICATION
   ========================================================= */

const step17AICHMap =
    new Map();


step17AICHorizontalSource
    .forEach(
        (segment, index) => {

            const x =
                step17AICNumber(
                    segment?.x
                );

            const y =
                step17AICNumber(
                    segment?.y
                );

            const width =
                step17AICNumber(
                    segment?.width
                );

            const x2 =
                step17AICNumber(
                    segment?.x2
                ) ??
                (
                    x !== null &&
                    width !== null
                        ? x + width
                        : null
                );


            if (
                x === null ||
                y === null ||
                x2 === null
            ) {
                return;
            }


            /*
             * 0.75 height lines are treated
             * as text underline candidates.
             */

            const height =
                step17AICNumber(
                    segment?.height
                );


            if (
                height !== null &&
                height < 1.5
            ) {

                return;

            }


            const key =
                [
                    Math.round(x * 100),
                    Math.round(x2 * 100),
                    Math.round(y * 100)
                ].join("|");


            if (
                !step17AICHMap.has(key)
            ) {

                step17AICHMap.set(
                    key,
                    {

                        sourceIndex:
                            index,

                        pdfX:
                            x,

                        pdfX2:
                            x2,

                        pdfY:
                            y,

                        pdfWidth:
                            x2 - x,

                        pdfHeight:
                            height

                    }
                );

            }

        }
    );


const step17AICHorizontalUnique =
    Array.from(
        step17AICHMap.values()
    );


console.log(
    "HORIZONTAL AFTER DEDUP:",
    step17AICHorizontalUnique.length
);


/* =========================================================
   VERTICAL BORDER DEDUPLICATION
   ========================================================= */

const step17AICVMap =
    new Map();


step17AICVerticalSource
    .forEach(
        (segment, index) => {

            const x =
                step17AICNumber(
                    segment?.x
                );

            const y =
                step17AICNumber(
                    segment?.y
                );

            const height =
                step17AICNumber(
                    segment?.height
                );

            const y2 =
                step17AICNumber(
                    segment?.y2
                ) ??
                (
                    y !== null &&
                    height !== null
                        ? y + height
                        : null
                );


            if (
                x === null ||
                y === null ||
                y2 === null
            ) {
                return;
            }


            /*
             * Duplicate graphics frequently
             * represent the same PDF border.
             */

            const key =
                [
                    Math.round(x * 100),
                    Math.round(y * 100),
                    Math.round(y2 * 100)
                ].join("|");


            if (
                !step17AICVMap.has(key)
            ) {

                step17AICVMap.set(
                    key,
                    {

                        sourceIndex:
                            index,

                        pdfX:
                            x,

                        pdfY:
                            y,

                        pdfY2:
                            y2,

                        pdfHeight:
                            y2 - y

                    }
                );

            }

        }
    );


const step17AICVerticalUnique =
    Array.from(
        step17AICVMap.values()
    );


console.log(
    "VERTICAL AFTER DEDUP:",
    step17AICVerticalUnique.length
);


/* =========================================================
   PDF → DOCX COORDINATES
   ========================================================= */

const step17AICHorizontalDOCX =
    step17AICHorizontalUnique
        .map(
            border => ({

                ...border,

                docxX:
                    border.pdfX *
                    step17AICScaleX,

                docxX2:
                    border.pdfX2 *
                    step17AICScaleX,

                docxY:
                    border.pdfY *
                    step17AICScaleY

            })
        );


const step17AICVerticalDOCX =
    step17AICVerticalUnique
        .map(
            border => ({

                ...border,

                docxX:
                    border.pdfX *
                    step17AICScaleX,

                docxY:
                    border.pdfY *
                    step17AICScaleY,

                docxY2:
                    border.pdfY2 *
                    step17AICScaleY

            })
        );


/* =========================================================
   CREATE CELL EDGE MODEL
   ========================================================= */

const step17AICCellEdges =
    step17AICNormalizedCells
        .map(
            cell => ({

                cellIndex:
                    cell.cellIndex,

                row:
                    cell.row,

                column:
                    cell.column,

                left:
                    cell.left,

                top:
                    cell.top,

                right:
                    cell.right,

                bottom:
                    cell.bottom,

                borders: {

                    top: false,
                    bottom: false,
                    left: false,
                    right: false

                },

                matched: {

                    top: [],
                    bottom: [],
                    left: [],
                    right: []

                }

            })
        );


/* =========================================================
   HORIZONTAL EXACT EDGE MAPPING
   ========================================================= */

step17AICHorizontalDOCX
    .forEach(
        border => {

            let bestTop = null;
            let bestBottom = null;


            step17AICCellEdges
                .forEach(
                    cell => {

                        const overlap =
                            Math.min(
                                border.docxX2,
                                cell.right
                            ) -
                            Math.max(
                                border.docxX,
                                cell.left
                            );


                        if (
                            overlap <=
                            step17AICOverlapTolerance
                        ) {
                            return;
                        }


                        const topDistance =
                            Math.abs(
                                border.docxY -
                                cell.top
                            );

                        const bottomDistance =
                            Math.abs(
                                border.docxY -
                                cell.bottom
                            );


                        if (
                            topDistance <=
                            step17AICPositionTolerance
                        ) {

                            if (
                                !bestTop ||
                                topDistance <
                                bestTop.distance
                            ) {

                                bestTop = {

                                    cell,
                                    distance:
                                        topDistance,
                                    overlap

                                };

                            }

                        }


                        if (
                            bottomDistance <=
                            step17AICPositionTolerance
                        ) {

                            if (
                                !bestBottom ||
                                bottomDistance <
                                bestBottom.distance
                            ) {

                                bestBottom = {

                                    cell,
                                    distance:
                                        bottomDistance,
                                    overlap

                                };

                            }

                        }

                    }
                );


            if (bestTop) {

                const cell =
                    bestTop.cell;

                cell.borders.top =
                    true;

                cell.matched.top.push({

                    sourceIndex:
                        border.sourceIndex,

                    distance:
                        bestTop.distance,

                    overlap:
                        bestTop.overlap

                });

            }


            if (bestBottom) {

                const cell =
                    bestBottom.cell;

                cell.borders.bottom =
                    true;

                cell.matched.bottom.push({

                    sourceIndex:
                        border.sourceIndex,

                    distance:
                        bestBottom.distance,

                    overlap:
                        bestBottom.overlap

                });

            }

        }
    );


/* =========================================================
   VERTICAL EXACT EDGE MAPPING
   ========================================================= */

step17AICVerticalDOCX
    .forEach(
        border => {

            let bestLeft = null;
            let bestRight = null;


            step17AICCellEdges
                .forEach(
                    cell => {

                        const overlap =
                            Math.min(
                                border.docxY2,
                                cell.bottom
                            ) -
                            Math.max(
                                border.docxY,
                                cell.top
                            );


                        if (
                            overlap <=
                            step17AICOverlapTolerance
                        ) {
                            return;
                        }


                        const leftDistance =
                            Math.abs(
                                border.docxX -
                                cell.left
                            );

                        const rightDistance =
                            Math.abs(
                                border.docxX -
                                cell.right
                            );


                        if (
                            leftDistance <=
                            step17AICPositionTolerance
                        ) {

                            if (
                                !bestLeft ||
                                leftDistance <
                                bestLeft.distance
                            ) {

                                bestLeft = {

                                    cell,
                                    distance:
                                        leftDistance,
                                    overlap

                                };

                            }

                        }


                        if (
                            rightDistance <=
                            step17AICPositionTolerance
                        ) {

                            if (
                                !bestRight ||
                                rightDistance <
                                bestRight.distance
                            ) {

                                bestRight = {

                                    cell,
                                    distance:
                                        rightDistance,
                                    overlap

                                };

                            }

                        }

                    }
                );


            if (bestLeft) {

                const cell =
                    bestLeft.cell;

                cell.borders.left =
                    true;

                cell.matched.left.push({

                    sourceIndex:
                        border.sourceIndex,

                    distance:
                        bestLeft.distance,

                    overlap:
                        bestLeft.overlap

                });

            }


            if (bestRight) {

                const cell =
                    bestRight.cell;

                cell.borders.right =
                    true;

                cell.matched.right.push({

                    sourceIndex:
                        border.sourceIndex,

                    distance:
                        bestRight.distance,

                    overlap:
                        bestRight.overlap

                });

            }

        }
    );


/* =========================================================
   COUNT EDGES
   ========================================================= */

const step17AICTopCount =
    step17AICCellEdges
        .filter(
            cell =>
                cell.borders.top
        )
        .length;


const step17AICBottomCount =
    step17AICCellEdges
        .filter(
            cell =>
                cell.borders.bottom
        )
        .length;


const step17AICLeftCount =
    step17AICCellEdges
        .filter(
            cell =>
                cell.borders.left
        )
        .length;


const step17AICRightCount =
    step17AICCellEdges
        .filter(
            cell =>
                cell.borders.right
        )
        .length;


/* =========================================================
   SAVE MODEL
   ========================================================= */

window.pdfUniversalCorrectedBorderEdgeModel = {

    version:
        "1.0",

    source:
        "STEP 17AI-C",

    rawHorizontal:
        step17AICHorizontalSource.length,

    rawVertical:
        step17AICVerticalSource.length,

    uniqueHorizontal:
        step17AICHorizontalUnique.length,

    uniqueVertical:
        step17AICVerticalUnique.length,

    horizontalBorders:
        step17AICHorizontalDOCX,

    verticalBorders:
        step17AICVerticalDOCX,

    cells:
        step17AICCellEdges,

    topEdges:
        step17AICTopCount,

    bottomEdges:
        step17AICBottomCount,

    leftEdges:
        step17AICLeftCount,

    rightEdges:
        step17AICRightCount,

    totalActiveEdges:
        step17AICTopCount +
        step17AICBottomCount +
        step17AICLeftCount +
        step17AICRightCount,

    status:
        "ready"

};


