if (!step17AJSource) {

    throw new Error(
        "STEP 17AJ: CORRECTED BORDER MODEL NOT FOUND"
    );

}

if (!step17AJCells) {

    throw new Error(
        "STEP 17AJ: DOCX CELL MAP NOT FOUND"
    );

}


/* ---------------------------------------------------------
   GET CELLS
   --------------------------------------------------------- */

let step17AJCellArray = [];

if (
    Array.isArray(step17AJCells)
) {

    step17AJCellArray =
        step17AJCells;

} else if (
    Array.isArray(step17AJCells.cells)
) {

    step17AJCellArray =
        step17AJCells.cells;

}


console.log(
    "STRUCTURAL CELLS:",
    step17AJCellArray.length
);


/* ---------------------------------------------------------
   NORMALIZE CELL EDGES
   --------------------------------------------------------- */

function step17AJNumber(value) {

    const number =
        Number(value);

    return Number.isFinite(number)
        ? number
        : null;

}


const step17AJNormalizedCells =
    step17AJCellArray
        .map(
            (cell, index) => {

                const left =
                    step17AJNumber(
                        cell?.leftTwips ??
                        cell?.xTwips ??
                        cell?.x ??
                        cell?.left
                    );

                const top =
                    step17AJNumber(
                        cell?.topTwips ??
                        cell?.yTwips ??
                        cell?.y ??
                        cell?.top
                    );

                const width =
                    step17AJNumber(
                        cell?.widthTwips ??
                        cell?.width
                    );

                const height =
                    step17AJNumber(
                        cell?.heightTwips ??
                        cell?.height
                    );

                const right =
                    step17AJNumber(
                        cell?.rightTwips ??
                        cell?.right
                    ) ??
                    (
                        left !== null &&
                        width !== null
                            ? left + width
                            : null
                    );

                const bottom =
                    step17AJNumber(
                        cell?.bottomTwips ??
                        cell?.bottom
                    ) ??
                    (
                        top !== null &&
                        height !== null
                            ? top + height
                            : null
                    );

                return {

                    cellIndex:
                        index,

                    row:
                        cell?.row ??
                        null,

                    column:
                        cell?.column ??
                        cell?.col ??
                        null,

                    left,
                    top,
                    right,
                    bottom

                };

            }
        )
        .filter(
            cell =>
                cell.left !== null &&
                cell.top !== null &&
                cell.right !== null &&
                cell.bottom !== null
        );


/* ---------------------------------------------------------
   CREATE EXACT CELL EDGE STATE
   --------------------------------------------------------- */

const step17AJFinalCells =
    step17AJNormalizedCells
        .map(
            cell => ({

                cellIndex:
                    cell.cellIndex,

                row:
                    cell.row,

                column:
                    cell.column,

                left:
                    cell.left,

                top:
                    cell.top,

                right:
                    cell.right,

                bottom:
                    cell.bottom,

                borders: {

                    top: false,

                    bottom: false,

                    left: false,

                    right: false

                }

            })
        );


/* =========================================================
   BUILD UNIQUE VERTICAL STRUCTURAL EDGES
   ========================================================= */

const step17AJVerticalEdges =
    new Map();


step17AJFinalCells
    .forEach(
        cell => {

            const leftKey =
                Math.round(
                    cell.left
                );

            const rightKey =
                Math.round(
                    cell.right
                );


            if (
                !step17AJVerticalEdges.has(
                    leftKey
                )
            ) {

                step17AJVerticalEdges.set(
                    leftKey,
                    {

                        x:
                            cell.left,

                        segments: []

                    }
                );

            }


            step17AJVerticalEdges
                .get(leftKey)
                .segments
                .push({

                    cellIndex:
                        cell.cellIndex,

                    row:
                        cell.row,

                    column:
                        cell.column,

                    y1:
                        cell.top,

                    y2:
                        cell.bottom,

                    side:
                        "left"

                });


            if (
                !step17AJVerticalEdges.has(
                    rightKey
                )
            ) {

                step17AJVerticalEdges.set(
                    rightKey,
                    {

                        x:
                            cell.right,

                        segments: []

                    }
                );

            }


            step17AJVerticalEdges
                .get(rightKey)
                .segments
                .push({

                    cellIndex:
                        cell.cellIndex,

                    row:
                        cell.row,

                    column:
                        cell.column,

                    y1:
                        cell.top,

                    y2:
                        cell.bottom,

                    side:
                        "right"

                });

        }
    );


/* =========================================================
   SOURCE VERTICAL BORDER LOCATIONS
   ========================================================= */

const step17AJSourceVertical =
    Array.isArray(
        step17AJSource.verticalBorders
    )
        ? step17AJSource.verticalBorders
        : [];


/* ---------------------------------------------------------
   VERTICAL STRUCTURAL X POSITIONS
   --------------------------------------------------------- */

const step17AJVerticalX =
    [
        ...new Set(
            step17AJSourceVertical
                .map(
                    border =>
                        Math.round(
                            Number(
                                border.docxX
                            )
                        )
                )
                .filter(
                    value =>
                        Number.isFinite(value)
                )
        )
    ]
    .sort(
        (a, b) =>
            a - b
    );


console.log(
    "SOURCE VERTICAL X POSITIONS:",
    step17AJVerticalX
);


/* =========================================================
   MATCH VERTICAL EDGES
   ========================================================= */

const step17AJVerticalMatches = [];


step17AJVerticalX
    .forEach(
        sourceX => {

            step17AJVerticalEdges
                .forEach(
                    (edge, edgeX) => {

                        const distance =
                            Math.abs(
                                sourceX -
                                Number(edgeX)
                            );


                        if (
                            distance <= 35
                        ) {

                            step17AJVerticalMatches
                                .push({

                                    sourceX,

                                    structuralX:
                                        Number(
                                            edgeX
                                        ),

                                    distance,

                                    segments:
                                        edge.segments

                                });

                        }

                    }
                );

        }
    );


/* =========================================================
   APPLY VERTICAL EDGES
   ========================================================= */

step17AJVerticalMatches
    .forEach(
        match => {

            match.segments
                .forEach(
                    segment => {

                        const cell =
                            step17AJFinalCells[
                                segment.cellIndex
                            ];


                        if (!cell) {
                            return;
                        }


                        if (
                            segment.side ===
                            "left"
                        ) {

                            cell.borders.left =
                                true;

                        }


                        if (
                            segment.side ===
                            "right"
                        ) {

                            cell.borders.right =
                                true;

                        }

                    }
                );

        }
    );


/* =========================================================
   HORIZONTAL STRUCTURAL EDGES
   ========================================================= */

const step17AJHorizontalEdges =
    new Map();


step17AJFinalCells
    .forEach(
        cell => {

            const topKey =
                Math.round(
                    cell.top
                );

            const bottomKey =
                Math.round(
                    cell.bottom
                );


            if (
                !step17AJHorizontalEdges.has(
                    topKey
                )
            ) {

                step17AJHorizontalEdges.set(
                    topKey,
                    {

                        y:
                            cell.top,

                        segments: []

                    }
                );

            }


            step17AJHorizontalEdges
                .get(topKey)
                .segments
                .push({

                    cellIndex:
                        cell.cellIndex,

                    row:
                        cell.row,

                    column:
                        cell.column,

                    x1:
                        cell.left,

                    x2:
                        cell.right,

                    side:
                        "top"

                });


            if (
                !step17AJHorizontalEdges.has(
                    bottomKey
                )
            ) {

                step17AJHorizontalEdges.set(
                    bottomKey,
                    {

                        y:
                            cell.bottom,

                        segments: []

                    }
                );

            }


            step17AJHorizontalEdges
                .get(bottomKey)
                .segments
                .push({

                    cellIndex:
                        cell.cellIndex,

                    row:
                        cell.row,

                    column:
                        cell.column,

                    x1:
                        cell.left,

                    x2:
                        cell.right,

                    side:
                        "bottom"

                });

        }
    );


/* ---------------------------------------------------------
   SOURCE HORIZONTAL BORDER LOCATIONS
   --------------------------------------------------------- */

const step17AJSourceHorizontal =
    Array.isArray(
        step17AJSource.horizontalBorders
    )
        ? step17AJSource.horizontalBorders
        : [];


const step17AJHorizontalY =
    [
        ...new Set(
            step17AJSourceHorizontal
                .map(
                    border =>
                        Math.round(
                            Number(
                                border.docxY
                            )
                        )
                )
                .filter(
                    value =>
                        Number.isFinite(value)
                )
        )
    ]
    .sort(
        (a, b) =>
            a - b
    );


console.log(
    "SOURCE HORIZONTAL Y POSITIONS:",
    step17AJHorizontalY
);


/* =========================================================
   MATCH HORIZONTAL EDGES
   ========================================================= */

const step17AJHorizontalMatches = [];


step17AJHorizontalY
    .forEach(
        sourceY => {

            step17AJHorizontalEdges
                .forEach(
                    (edge, edgeY) => {

                        const distance =
                            Math.abs(
                                sourceY -
                                Number(edgeY)
                            );


                        if (
                            distance <= 35
                        ) {

                            step17AJHorizontalMatches
                                .push({

                                    sourceY,

                                    structuralY:
                                        Number(
                                            edgeY
                                        ),

                                    distance,

                                    segments:
                                        edge.segments

                                });

                        }

                    }
                );

        }
    );


/* =========================================================
   APPLY HORIZONTAL EDGES
   ========================================================= */

step17AJHorizontalMatches
    .forEach(
        match => {

            match.segments
                .forEach(
                    segment => {

                        const cell =
                            step17AJFinalCells[
                                segment.cellIndex
                            ];


                        if (!cell) {
                            return;
                        }


                        if (
                            segment.side ===
                            "top"
                        ) {

                            cell.borders.top =
                                true;

                        }


                        if (
                            segment.side ===
                            "bottom"
                        ) {

                            cell.borders.bottom =
                                true;

                        }

                    }
                );

        }
    );


/* =========================================================
   CONSOLIDATED EDGE COUNTS
   ========================================================= */

const step17AJTop =
    step17AJFinalCells
        .filter(
            cell =>
                cell.borders.top
        )
        .length;


const step17AJBottom =
    step17AJFinalCells
        .filter(
            cell =>
                cell.borders.bottom
        )
        .length;


const step17AJLeft =
    step17AJFinalCells
        .filter(
            cell =>
                cell.borders.left
        )
        .length;


const step17AJRight =
    step17AJFinalCells
        .filter(
            cell =>
                cell.borders.right
        )
        .length;


/* =========================================================
   CREATE CONSOLIDATED MODEL
   ========================================================= */

window.pdfUniversalConsolidatedBorderModel = {

    version:
        "1.0",

    source:
        "STEP 17AJ",

    cells:
        step17AJFinalCells,

    verticalMatches:
        step17AJVerticalMatches,

    horizontalMatches:
        step17AJHorizontalMatches,

    sourceVerticalX:
        step17AJVerticalX,

    sourceHorizontalY:
        step17AJHorizontalY,

    topEdges:
        step17AJTop,

    bottomEdges:
        step17AJBottom,

    leftEdges:
        step17AJLeft,

    rightEdges:
        step17AJRight,

    totalActiveEdges:
        step17AJTop +
        step17AJBottom +
        step17AJLeft +
        step17AJRight,

    status:
        "ready"

};


/* =========================================================
   OUTPUT
   ========================================================= */

