console.log("=================================");
console.log("STEP 62 — STEP 17AK START");
console.log("EXACT BORDER SEGMENT → CELL EDGE MAPPING");
console.log("=================================");

const step17AKBorderModel =
    window.pdfUniversalBorderSegmentModel;

const step17AKCellMap =
    window.pdfUniversalDocxCellMap;

const step17AKTransform =
    window.pdfUniversalCoordinateTransform17AF;

if (!step17AKBorderModel) {
    console.error("STEP 17AK ERROR: BORDER MODEL NOT FOUND");
    throw new Error("STEP 17AK BORDER MODEL NOT FOUND");
}

if (!step17AKCellMap) {
    console.error("STEP 17AK ERROR: CELL MAP NOT FOUND");
    throw new Error("STEP 17AK CELL MAP NOT FOUND");
}

if (!step17AKTransform) {
    console.error("STEP 17AK ERROR: TRANSFORM MODEL NOT FOUND");
    throw new Error("STEP 17AK TRANSFORM MODEL NOT FOUND");
}

console.log(
    "BORDER MODEL FOUND:",
    !!step17AKBorderModel
);

console.log(
    "CELL MAP FOUND:",
    !!step17AKCellMap
);

console.log(
    "TRANSFORM MODEL FOUND:",
    !!step17AKTransform
);


/* ---------------------------------
   BASIC SETTINGS
--------------------------------- */

const STEP17AK_TOLERANCE = 35;


/* ---------------------------------
   SOURCE SEGMENTS
--------------------------------- */

const step17AKHorizontal =
    Array.isArray(step17AKBorderModel.horizontal)
        ? step17AKBorderModel.horizontal
        : [];

const step17AKVertical =
    Array.isArray(step17AKBorderModel.vertical)
        ? step17AKBorderModel.vertical
        : [];

console.log(
    "SOURCE HORIZONTAL SEGMENTS:",
    step17AKHorizontal.length
);

console.log(
    "SOURCE VERTICAL SEGMENTS:",
    step17AKVertical.length
);


/* ---------------------------------
   STRUCTURAL CELLS
--------------------------------- */

const step17AKCells =
    Array.isArray(step17AKCellMap)
        ? step17AKCellMap
        : Array.isArray(step17AKCellMap.cells)
            ? step17AKCellMap.cells
            : [];

console.log(
    "STRUCTURAL CELLS:",
    step17AKCells.length
);


/* ---------------------------------
   HELPERS
--------------------------------- */

function step17AKNear(a, b, tolerance) {
    return Math.abs(Number(a) - Number(b)) <= tolerance;
}

function step17AKOverlap(
    start1,
    end1,
    start2,
    end2,
    tolerance
) {

    const left =
        Math.max(
            Number(start1),
            Number(start2)
        );

    const right =
        Math.min(
            Number(end1),
            Number(end2)
        );

    return (
        right >= left - tolerance
    );
}


/* ---------------------------------
   NORMALIZE CELLS
--------------------------------- */

const step17AKNormalizedCells =
    step17AKCells.map((cell, index) => {

        const row =
            Number(
                cell.row ??
                cell.rowNumber ??
                cell.r ??
                0
            );

        const col =
            Number(
                cell.col ??
                cell.column ??
                cell.c ??
                0
            );

        const left =
            Number(
                cell.leftTwips ??
                cell.x ??
                0
            );

        const top =
            Number(
                cell.topTwips ??
                cell.y ??
                0
            );

        const right =
            Number(
                cell.rightTwips ??
                (
                    left +
                    Number(
                        cell.widthTwips ??
                        cell.width ??
                        0
                    )
                )
            );

        const bottom =
            Number(
                cell.bottomTwips ??
                (
                    top +
                    Number(
                        cell.heightTwips ??
                        cell.height ??
                        0
                    )
                )
            );

        return {
            index,
            row,
            col,
            left,
            top,
            right,
            bottom
        };
    });


/* ---------------------------------
   RESULT CELL MODEL
--------------------------------- */

const step17AKResultCells =
    step17AKNormalizedCells.map(cell => {

        return {
            index: cell.index,
            row: cell.row,
            col: cell.col,

            top: false,
            bottom: false,
            left: false,
            right: false,

            borderSources: {
                top: [],
                bottom: [],
                left: [],
                right: []
            }
        };

    });


/* ---------------------------------
   TRANSFORM PDF → DOCX
--------------------------------- */

function step17AKPdfToDocxX(pdfX) {

    return Number(pdfX) *
        Number(step17AKTransform.scaleX);
}

function step17AKPdfToDocxY(pdfY) {

    return Number(pdfY) *
        Number(step17AKTransform.scaleY);
}


/* ---------------------------------
   HORIZONTAL BORDER MAPPING
--------------------------------- */

let step17AKHorizontalMapped = 0;

for (
    let i = 0;
    i < step17AKHorizontal.length;
    i++
) {

    const segment =
        step17AKHorizontal[i];

    const pdfX1 =
        Number(segment.x);

    const pdfX2 =
        Number(
            segment.x2 ??
            (
                Number(segment.x) +
                Number(segment.width || 0)
            )
        );

    const pdfY =
        Number(segment.y);

    const docxX1 =
        step17AKPdfToDocxX(pdfX1);

    const docxX2 =
        step17AKPdfToDocxX(pdfX2);

    const docxY =
        step17AKPdfToDocxY(pdfY);


    for (
        let c = 0;
        c < step17AKNormalizedCells.length;
        c++
    ) {

        const cell =
            step17AKNormalizedCells[c];

        const horizontalOverlap =
            step17AKOverlap(
                docxX1,
                docxX2,
                cell.left,
                cell.right,
                STEP17AK_TOLERANCE
            );

        if (!horizontalOverlap) {
            continue;
        }


        /* TOP EDGE */

        if (
            step17AKNear(
                docxY,
                cell.top,
                STEP17AK_TOLERANCE
            )
        ) {

            step17AKResultCells[c].top = true;

            step17AKResultCells[c]
                .borderSources
                .top
                .push(i);

            step17AKHorizontalMapped++;

            continue;
        }


        /* BOTTOM EDGE */

        if (
            step17AKNear(
                docxY,
                cell.bottom,
                STEP17AK_TOLERANCE
            )
        ) {

            step17AKResultCells[c].bottom = true;

            step17AKResultCells[c]
                .borderSources
                .bottom
                .push(i);

            step17AKHorizontalMapped++;

        }

    }

}


/* ---------------------------------
   VERTICAL BORDER MAPPING
--------------------------------- */

let step17AKVerticalMapped = 0;

for (
    let i = 0;
    i < step17AKVertical.length;
    i++
) {

    const segment =
        step17AKVertical[i];

    const pdfX =
        Number(segment.x);

    const pdfY1 =
        Number(segment.y);

    const pdfY2 =
        Number(
            segment.y2 ??
            (
                Number(segment.y) +
                Number(segment.height || 0)
            )
        );

    const docxX =
        step17AKPdfToDocxX(pdfX);

    const docxY1 =
        step17AKPdfToDocxY(pdfY1);

    const docxY2 =
        step17AKPdfToDocxY(pdfY2);


    for (
        let c = 0;
        c < step17AKNormalizedCells.length;
        c++
    ) {

        const cell =
            step17AKNormalizedCells[c];

        const verticalOverlap =
            step17AKOverlap(
                docxY1,
                docxY2,
                cell.top,
                cell.bottom,
                STEP17AK_TOLERANCE
            );

        if (!verticalOverlap) {
            continue;
        }


        /* LEFT EDGE */

        if (
            step17AKNear(
                docxX,
                cell.left,
                STEP17AK_TOLERANCE
            )
        ) {

            step17AKResultCells[c].left = true;

            step17AKResultCells[c]
                .borderSources
                .left
                .push(i);

            step17AKVerticalMapped++;

            continue;
        }


        /* RIGHT EDGE */

        if (
            step17AKNear(
                docxX,
                cell.right,
                STEP17AK_TOLERANCE
            )
        ) {

            step17AKResultCells[c].right = true;

            step17AKResultCells[c]
                .borderSources
                .right
                .push(i);

            step17AKVerticalMapped++;

        }

    }

}


/* ---------------------------------
   COUNT ACTIVE EDGES
--------------------------------- */

let step17AKTop = 0;
let step17AKBottom = 0;
let step17AKLeft = 0;
let step17AKRight = 0;

for (
    const cell of step17AKResultCells
) {

    if (cell.top) {
        step17AKTop++;
    }

    if (cell.bottom) {
        step17AKBottom++;
    }

    if (cell.left) {
        step17AKLeft++;
    }

    if (cell.right) {
        step17AKRight++;
    }

}


/* ---------------------------------
   FINAL MODEL
--------------------------------- */

window.pdfUniversalExactBorderEdgeModel = {

    version: "1.0",

    source:
        "STEP 17AK exact segment mapping",

    cells:
        step17AKResultCells,

    sourceHorizontalSegments:
        step17AKHorizontal.length,

    sourceVerticalSegments:
        step17AKVertical.length,

    horizontalMapped:
        step17AKHorizontalMapped,

    verticalMapped:
        step17AKVerticalMapped,

    topEdges:
        step17AKTop,

    bottomEdges:
        step17AKBottom,

    leftEdges:
        step17AKLeft,

    rightEdges:
        step17AKRight,

    totalActiveEdges:
        step17AKTop +
        step17AKBottom +
        step17AKLeft +
        step17AKRight,

    status:
        "ready"
};


/* ---------------------------------
   RESULT
--------------------------------- */

console.log("---------------------------------");
console.log("STEP 17AK EXACT MAPPING RESULT");
console.log("---------------------------------");

console.log(
    "SOURCE HORIZONTAL SEGMENTS:",
    step17AKHorizontal.length
);

console.log(
    "SOURCE VERTICAL SEGMENTS:",
    step17AKVertical.length
);

console.log(
    "HORIZONTAL MAPPED:",
    step17AKHorizontalMapped
);

console.log(
    "VERTICAL MAPPED:",
    step17AKVerticalMapped
);

console.log(
    "TOP EDGES:",
    step17AKTop
);

console.log(
    "BOTTOM EDGES:",
    step17AKBottom
);

console.log(
    "LEFT EDGES:",
    step17AKLeft
);

console.log(
    "RIGHT EDGES:",
    step17AKRight
);

console.log(
    "TOTAL ACTIVE EDGES:",
    step17AKTop +
    step17AKBottom +
    step17AKLeft +
    step17AKRight
);


