    step17ALLayout.pages &&
    step17ALLayout.pages[0];

if (!step17ALPage) {
    throw new Error(
        "STEP 17AL: PAGE DATA NOT FOUND"
    );
}

const step17ALPdfWidth =
    Number(step17ALPage.width);

const step17ALPdfHeight =
    Number(step17ALPage.height);

const step17ALScaleX = 20;
const step17ALScaleY = 20;

console.log(
    "PDF WIDTH:",
    step17ALPdfWidth
);

console.log(
    "PDF HEIGHT:",
    step17ALPdfHeight
);

console.log(
    "SCALE X:",
    step17ALScaleX
);

console.log(
    "SCALE Y:",
    step17ALScaleY
);


/* ---------------------------------
   CELL MAP
--------------------------------- */

const step17ALCells =
    Array.isArray(step17ALCellMap)
        ? step17ALCellMap
        : Array.isArray(step17ALCellMap.cells)
            ? step17ALCellMap.cells
            : [];

console.log(
    "STRUCTURAL CELLS:",
    step17ALCells.length
);


/* ---------------------------------
   NORMALIZE CELLS
--------------------------------- */

const step17ALNormalizedCells =
    step17ALCells.map((cell, index) => {

        const left =
            Number(
                cell.leftTwips ??
                cell.x ??
                0
            );

        const top =
            Number(
                cell.topTwips ??
                cell.y ??
                0
            );

        const width =
            Number(
                cell.widthTwips ??
                cell.width ??
                0
            );

        const height =
            Number(
                cell.heightTwips ??
                cell.height ??
                0
            );

        return {

            index,

            row:
                Number(
                    cell.row ??
                    cell.rowNumber ??
                    0
                ),

            col:
                Number(
                    cell.col ??
                    cell.column ??
                    0
                ),

            left,

            top,

            right:
                Number(
                    cell.rightTwips ??
                    (left + width)
                ),

            bottom:
                Number(
                    cell.bottomTwips ??
                    (top + height)
                )
        };

    });


/* ---------------------------------
   PDF → DOCX TRANSFORM
--------------------------------- */

function step17ALX(pdfX) {

    return Number(pdfX) *
        step17ALScaleX;

}


/*
   PDF coordinate system:

   Y = bottom based

   DOCX structural grid:

   Y = top based
*/

function step17ALY(pdfY) {

    return (
        step17ALPdfHeight -
        Number(pdfY)
    ) * step17ALScaleY;

}


