console.log("EXACT BORDER → STRUCTURAL CELL MAPPING");
console.log("=================================");

const step17AMBorderModel =
    window.pdfUniversalCorrectedBorderCoordinateModel;

const step17AMCellMap =
    window.pdfUniversalDocxCellMap;

if (!step17AMBorderModel) {
    throw new Error(
        "STEP 17AM: CORRECTED BORDER MODEL NOT FOUND"
    );
}

if (!step17AMCellMap) {
    throw new Error(
        "STEP 17AM: CELL MAP NOT FOUND"
    );
}

console.log(
    "CORRECTED BORDER MODEL FOUND:",
    true
);

console.log(
    "CELL MAP FOUND:",
    true
);


/* ---------------------------------
   CELLS
--------------------------------- */

const step17AMRawCells =
    Array.isArray(step17AMCellMap)
        ? step17AMCellMap
        : Array.isArray(step17AMCellMap.cells)
            ? step17AMCellMap.cells
            : [];

console.log(
    "STRUCTURAL CELLS:",
    step17AMRawCells.length
);


/* ---------------------------------
   NORMALIZE CELLS
--------------------------------- */

const step17AMCells =
    step17AMRawCells.map(
        (cell, index) => {

            const left =
                Number(
                    cell.leftTwips ??
                    cell.x ??
                    0
                );

            const top =
                Number(
                    cell.topTwips ??
                    cell.y ??
                    0
                );

            const width =
                Number(
                    cell.widthTwips ??
                    cell.width ??
                    0
                );

            const height =
                Number(
                    cell.heightTwips ??
                    cell.height ??
                    0
                );

            return {

                index,

                row:
                    Number(
                        cell.row ??
                        cell.rowNumber ??
                        0
                    ),

                col:
                    Number(
                        cell.col ??
                        cell.column ??
                        0
                    ),

                left,

                right:
                    Number(
                        cell.rightTwips ??
                        (left + width)
                    ),

                top,

                bottom:
                    Number(
                        cell.bottomTwips ??
                        (top + height)
                    )

            };

        }
    );


/* ---------------------------------
   RESULT CELLS
--------------------------------- */

const step17AMResultCells =
    step17AMCells.map(
        cell => ({

            index:
                cell.index,

            row:
                cell.row,

            col:
                cell.col,

            top: false,

            bottom: false,

            left: false,

            right: false,

            sources: {

                top: [],

                bottom: [],

                left: [],

                right: []

            }

        })
    );


/* ---------------------------------
   TOLERANCE
--------------------------------- */

const STEP17AM_TOLERANCE = 35;


/* ---------------------------------
   RANGE OVERLAP
--------------------------------- */

function step17AMOverlap(
    startA,
    endA,
    startB,
    endB
) {

    const a1 =
        Math.min(
            Number(startA),
            Number(endA)
        );

    const a2 =
        Math.max(
            Number(startA),
            Number(endA)
        );

    const b1 =
        Math.min(
            Number(startB),
            Number(endB)
        );

    const b2 =
        Math.max(
            Number(startB),
            Number(endB)
        );

    return (
        Math.min(a2, b2) >=
        Math.max(a1, b1) -
        STEP17AM_TOLERANCE
    );

}


/* ---------------------------------
   POINT MATCH
--------------------------------- */

function step17AMNear(
    valueA,
    valueB
) {

    return (
        Math.abs(
            Number(valueA) -
            Number(valueB)
        ) <=
        STEP17AM_TOLERANCE
    );

}


/* ---------------------------------
   HORIZONTAL BORDER MAPPING
--------------------------------- */

const step17AMHorizontal =
    Array.isArray(
        step17AMBorderModel.horizontal
    )
        ? step17AMBorderModel.horizontal
        : [];

let step17AMHorizontalMapped = 0;


/*
   Each horizontal PDF border becomes:

   X1 -------------------- X2
               Y

   It can only activate a cell whose:

   TOP    ≈ Y
   OR
   BOTTOM ≈ Y

   AND whose X range overlaps
   the border segment.
*/

for (
    let i = 0;
    i < step17AMHorizontal.length;
    i++
) {

    const segment =
        step17AMHorizontal[i];

    const x1 =
        Number(segment.docxX1);

    const x2 =
        Number(segment.docxX2);

    const y =
        Number(segment.docxY);


    for (
        let c = 0;
        c < step17AMCells.length;
        c++
    ) {

        const cell =
            step17AMCells[c];


        /*
           Check horizontal overlap.
        */

        if (
            !step17AMOverlap(
                x1,
                x2,
                cell.left,
                cell.right
            )
        ) {

            continue;

        }


        /*
           TOP
        */

        if (
            step17AMNear(
                y,
                cell.top
            )
        ) {

            if (
                !step17AMResultCells[c].top
            ) {

                step17AMResultCells[c].top =
                    true;

                step17AMHorizontalMapped++;

            }

            step17AMResultCells[c]
                .sources
                .top
                .push(i);

            continue;

        }


        /*
           BOTTOM
        */

        if (
            step17AMNear(
                y,
                cell.bottom
            )
        ) {

            if (
                !step17AMResultCells[c].bottom
            ) {

                step17AMResultCells[c].bottom =
                    true;

                step17AMHorizontalMapped++;

            }

            step17AMResultCells[c]
                .sources
                .bottom
                .push(i);

        }

    }

}


/* ---------------------------------
   VERTICAL BORDER MAPPING
--------------------------------- */

const step17AMVertical =
    Array.isArray(
        step17AMBorderModel.vertical
    )
        ? step17AMBorderModel.vertical
        : [];

let step17AMVerticalMapped = 0;


/*
   Each vertical border becomes:

             Y1
              |
              |
              |
             Y2

   It can only activate a cell whose:

   LEFT  ≈ X
   OR
   RIGHT ≈ X

   AND whose Y range overlaps
   the border segment.
*/

for (
    let i = 0;
    i < step17AMVertical.length;
    i++
) {

    const segment =
        step17AMVertical[i];

    const x =
        Number(segment.docxX);

    const y1 =
        Number(segment.docxY1);

    const y2 =
        Number(segment.docxY2);


    for (
        let c = 0;
        c < step17AMCells.length;
        c++
    ) {

        const cell =
            step17AMCells[c];


        /*
           Check vertical overlap.
        */

        if (
            !step17AMOverlap(
                y1,
                y2,
                cell.top,
                cell.bottom
            )
        ) {

            continue;

        }


        /*
           LEFT
        */

        if (
            step17AMNear(
                x,
                cell.left
            )
        ) {

            if (
                !step17AMResultCells[c].left
            ) {

                step17AMResultCells[c].left =
                    true;

                step17AMVerticalMapped++;

            }

            step17AMResultCells[c]
                .sources
                .left
                .push(i);

            continue;

        }


        /*
           RIGHT
        */

        if (
            step17AMNear(
                x,
                cell.right
            )
        ) {

            if (
                !step17AMResultCells[c].right
            ) {

                step17AMResultCells[c].right =
                    true;

                step17AMVerticalMapped++;

            }

            step17AMResultCells[c]
                .sources
                .right
                .push(i);

        }

    }

}


/* ---------------------------------
   COUNTS
--------------------------------- */

let step17AMTop = 0;
let step17AMBottom = 0;
let step17AMLeft = 0;
let step17AMRight = 0;


for (
    const cell of step17AMResultCells
) {

    if (cell.top) {
        step17AMTop++;
    }

    if (cell.bottom) {
        step17AMBottom++;
    }

    if (cell.left) {
        step17AMLeft++;
    }

    if (cell.right) {
        step17AMRight++;
    }

}


/* ---------------------------------
   FINAL MODEL
--------------------------------- */

window.pdfUniversalExactBorderCellModel = {

    version:
        "1.0",

    source:
        "STEP 17AM",

    cells:
        step17AMResultCells,

    horizontalSegments:
        step17AMHorizontal.length,

    verticalSegments:
        step17AMVertical.length,

    horizontalMapped:
        step17AMHorizontalMapped,

    verticalMapped:
        step17AMVerticalMapped,

    topEdges:
        step17AMTop,

    bottomEdges:
        step17AMBottom,

    leftEdges:
        step17AMLeft,

    rightEdges:
        step17AMRight,

    totalActiveEdges:
        step17AMTop +
        step17AMBottom +
        step17AMLeft +
        step17AMRight,

    status:
        "ready"

};


