console.log("EXACT VISUAL ZONE → STRUCTURAL CELL MAPPING");
console.log("=================================");


/* ---------------------------------
   SOURCE MODELS
--------------------------------- */

const step17ARZoneModel =
    window.pdfUniversalExactVisualZoneModel;

const step17ARCellMap =
    window.pdfUniversalDocxCellMap;

const step17ARLayout =
    window.pdfLayoutAnalysis;


if (!step17ARZoneModel) {
    throw new Error(
        "STEP 17AR: EXACT VISUAL ZONE MODEL NOT FOUND"
    );
}

if (!step17ARCellMap) {
    throw new Error(
        "STEP 17AR: DOCX CELL MAP NOT FOUND"
    );
}

if (!step17ARLayout) {
    throw new Error(
        "STEP 17AR: PDF LAYOUT ANALYSIS NOT FOUND"
    );
}


/* ---------------------------------
   PAGE INFORMATION
--------------------------------- */

const step17ARPage =
    Array.isArray(step17ARLayout.pages)
        ? step17ARLayout.pages[0]
        : null;

if (!step17ARPage) {
    throw new Error(
        "STEP 17AR: PAGE DATA NOT FOUND"
    );
}


const step17ARPageWidth =
    Number(step17ARPage.width);

const step17ARPageHeight =
    Number(step17ARPage.height);


/* ---------------------------------
   STRUCTURAL CELLS
--------------------------------- */

const step17ARStructuralCells =
    Array.isArray(step17ARCellMap.cells)
        ? step17ARCellMap.cells
        : Array.isArray(step17ARCellMap)
            ? step17ARCellMap
            : [];


if (!step17ARStructuralCells.length) {
    throw new Error(
        "STEP 17AR: STRUCTURAL CELLS NOT FOUND"
    );
}


/* ---------------------------------
   PDF → DOCX SCALE
--------------------------------- */

const step17ARScaleX =
    12620 / step17ARPageWidth;

const step17ARScaleY =
    16330 / step17ARPageHeight;


/* ---------------------------------
   PDF → DOCX TRANSFORM
--------------------------------- */

function step17ARX(pdfX) {

    return (
        Number(pdfX) *
        step17ARScaleX
    );

}


function step17ARY(pdfY) {

    return (
        Number(pdfY) *
        step17ARScaleY
    );

}


/* ---------------------------------
   TEXT ZONE → STRUCTURAL CELL
--------------------------------- */

function step17ARFindCell(
    item
) {

    const x =
        step17ARX(
            Number(item.x)
        );

    const right =
        step17ARX(
            Number(item.right)
        );

    const top =
        step17ARY(
            Number(item.top)
        );

    const bottom =
        step17ARY(
            Number(item.bottom)
        );

    const centerX =
        (
            x +
            right
        ) / 2;

    const centerY =
        (
            top +
            bottom
        ) / 2;


    let bestCell =
        null;

    let bestScore =
        Infinity;


    step17ARStructuralCells.forEach(
        cell => {

            const cellLeft =
                Number(
                    cell.leftTwips ??
                    cell.x ??
                    0
                );

            const cellRight =
                Number(
                    cell.rightTwips ??
                    (
                        Number(
                            cell.x ??
                            0
                        ) +
                        Number(
                            cell.widthTwips ??
                            cell.width ??
                            0
                        )
                    )
                );

            const cellTop =
                Number(
                    cell.topTwips ??
                    cell.y ??
                    0
                );

            const cellBottom =
                Number(
                    cell.bottomTwips ??
                    (
                        Number(
                            cell.y ??
                            0
                        ) +
                        Number(
                            cell.heightTwips ??
                            cell.height ??
                            0
                        )
                    )
                );


            const overlapX =
                Math.max(
                    0,
                    Math.min(
                        right,
                        cellRight
                    ) -
                    Math.max(
                        x,
                        cellLeft
                    )
                );


            const overlapY =
                Math.max(
                    0,
                    Math.min(
                        bottom,
                        cellBottom
                    ) -
                    Math.max(
                        top,
                        cellTop
                    )
                );


            const itemWidth =
                Math.max(
                    1,
                    right - x
                );

            const itemHeight =
                Math.max(
                    1,
                    bottom - top
                );


            const overlapRatioX =
                overlapX /
                itemWidth;

            const overlapRatioY =
                overlapY /
                itemHeight;


            const insideX =
                centerX >= cellLeft &&
                centerX <= cellRight;

            const insideY =
                centerY >= cellTop &&
                centerY <= cellBottom;


            /*
             * Strong score for actual
             * geometric containment.
             */

            let score =
                100000;


            if (
                insideX &&
                insideY
            ) {

                score -= 50000;

            }


            score -=
                overlapRatioX *
                25000;

            score -=
                overlapRatioY *
                25000;


            const distanceX =
                centerX <
                cellLeft
                    ? cellLeft -
                      centerX
                    : centerX >
                      cellRight
                        ? centerX -
                          cellRight
                        : 0;


            const distanceY =
                centerY <
                cellTop
                    ? cellTop -
                      centerY
                    : centerY >
                      cellBottom
                        ? centerY -
                          cellBottom
                        : 0;


            score +=
                distanceX;

            score +=
                distanceY;


            if (
                score <
                bestScore
            ) {

                bestScore =
                    score;

                bestCell =
                    cell;

            }

        }
    );


    return {

        cell:
            bestCell,

        x,
        right,
        top,
        bottom,
        centerX,
        centerY

    };

}


/* ---------------------------------
   MAP ALL TEXT ITEMS
--------------------------------- */

const step17ARTextMappings =
    [];


step17ARZoneModel.zones.forEach(
    zone => {

        zone.textItems.forEach(
            item => {

                const result =
                    step17ARFindCell(
                        item
                    );


                if (
                    !result.cell
                ) {
                    return;
                }


                const cell =
                    result.cell;


                step17ARTextMappings.push({

                    textIndex:
                        item.index,

                    text:
                        item.text,

                    zoneIndex:
                        zone.index,

                    cellIndex:
                        Number(
                            cell.index ??
                            0
                        ),

                    row:
                        Number(
                            cell.row ??
                            cell.rowNumber ??
                            0
                        ),

                    column:
                        Number(
                            cell.column ??
                            cell.col ??
                            cell.columnNumber ??
                            0
                        ),

                    pdfPosition: {

                        x:
                            item.x,

                        right:
                            item.right,

                        top:
                            item.top,

                        bottom:
                            item.bottom

                    },

                    docxPosition: {

                        x:
                            result.x,

                        right:
                            result.right,

                        top:
                            result.top,

                        bottom:
                            result.bottom,

                        centerX:
                            result.centerX,

                        centerY:
                            result.centerY

                    },

                    mappingStatus:
                        "mapped"

                });

            }
        );

    }
);


/* ---------------------------------
   GROUP BY STRUCTURAL CELL
--------------------------------- */

const step17ARCellGroups =
    new Map();


step17ARTextMappings.forEach(
    mapping => {

        const key =
            mapping.cellIndex;


        if (
            !step17ARCellGroups.has(
                key
            )
        ) {

            step17ARCellGroups.set(
                key,
                []
            );

        }


        step17ARCellGroups
            .get(key)
            .push(mapping);

    }
);


/* ---------------------------------
   CELL CONTENT SUMMARY
--------------------------------- */

const step17ARCellContent =
    [];


step17ARCellGroups.forEach(
    (
        items,
        cellIndex
    ) => {

        items.sort(
            (
                a,
                b
            ) =>
                a.docxPosition.top -
                b.docxPosition.top ||
                a.docxPosition.x -
                b.docxPosition.x
        );


        step17ARCellContent.push({

            cellIndex:
                Number(cellIndex),

            row:
                items[0].row,

            column:
                items[0].column,

            textCount:
                items.length,

            text:
                items
                    .map(
                        item =>
                            item.text
                    )
                    .join(" "),

            items

        });

    }
);


/* ---------------------------------
   SORT CELLS
--------------------------------- */

step17ARCellContent.sort(
    (
        a,
        b
    ) =>
        a.row -
        b.row ||
        a.column -
        b.column
);


/* ---------------------------------
   ZONE SUMMARY
--------------------------------- */

const step17ARZoneSummary =
    step17ARZoneModel.zones.map(
        zone => {

            const mappings =
                step17ARTextMappings.filter(
                    item =>
                        item.zoneIndex ===
                        zone.index
                );


            const cells =
                [
                    ...new Set(
                        mappings.map(
                            item =>
                                item.cellIndex
                        )
                    )
                ];


            return {

                zoneIndex:
                    zone.index,

                topY:
                    zone.topY,

                bottomY:
                    zone.bottomY,

                height:
                    zone.height,

                textCount:
                    mappings.length,

                structuralCells:
                    cells,

                cellCount:
                    cells.length,

                preview:
                    mappings
                        .slice(
                            0,
                            10
                        )
                        .map(
                            item =>
                                item.text
                        )
                        .join(" ")

            };

        }
    );


/* ---------------------------------
   FINAL MODEL
--------------------------------- */

window.pdfUniversalExactZoneCellMap = {

    version:
        "1.0",

    page: {

        width:
            step17ARPageWidth,

        height:
            step17ARPageHeight

    },

    scale: {

        x:
            step17ARScaleX,

        y:
            step17ARScaleY

    },

    textMappings:
        step17ARTextMappings,

    cellContent:
        step17ARCellContent,

    zoneSummary:
        step17ARZoneSummary,

    totalTextItems:
        step17ARTextMappings.length,

    mappedTextItems:
        step17ARTextMappings.length,

    unmappedTextItems:
        step17ARZoneModel.totalTextItems -
        step17ARTextMappings.length,

    populatedCells:
        step17ARCellContent.length,

    totalStructuralCells:
        step17ARStructuralCells.length,

    status:
        "analysis-ready"

};


/* ---------------------------------
   RESULT
--------------------------------- */

