/* ---------------------------------
   SOURCE MODELS
--------------------------------- */

const step17ATZoneModel =
    window.pdfUniversalExactVisualZoneModel;

const step17ATCellMap =
    window.pdfUniversalDocxCellMap;


if (!step17ATZoneModel) {
    throw new Error(
        "STEP 17AT: EXACT VISUAL ZONE MODEL NOT FOUND"
    );
}

if (!step17ATCellMap) {
    throw new Error(
        "STEP 17AT: DOCX CELL MAP NOT FOUND"
    );
}


/* ---------------------------------
   STRUCTURAL CELLS
--------------------------------- */

const step17ATCells =
    Array.isArray(step17ATCellMap.cells)
        ? step17ATCellMap.cells
        : Array.isArray(step17ATCellMap)
            ? step17ATCellMap
            : [];


if (!step17ATCells.length) {
    throw new Error(
        "STEP 17AT: STRUCTURAL CELLS NOT FOUND"
    );
}


/* ---------------------------------
   PAGE / SCALE
--------------------------------- */

const step17ATPageWidth = 631;
const step17ATPageHeight = 816.5;

const step17ATDocxWidth = 12620;
const step17ATDocxHeight = 16330;


const step17ATScaleX =
    step17ATDocxWidth /
    step17ATPageWidth;

const step17ATScaleY =
    step17ATDocxHeight /
    step17ATPageHeight;


/* ---------------------------------
   NORMALIZE STRUCTURAL CELLS
--------------------------------- */

const step17ATNormalizedCells =
    step17ATCells.map(
        (
            cell,
            index
        ) => {

            const left =
                Number(
                    cell.leftTwips ??
                    cell.x ??
                    0
                );

            const top =
                Number(
                    cell.topTwips ??
                    cell.y ??
                    0
                );

            const width =
                Number(
                    cell.widthTwips ??
                    cell.width ??
                    0
                );

            const height =
                Number(
                    cell.heightTwips ??
                    cell.height ??
                    0
                );

            const right =
                Number(
                    cell.rightTwips ??
                    left + width
                );

            const bottom =
                Number(
                    cell.bottomTwips ??
                    top + height
                );

            return {

                index,

                row:
                    Number(
                        cell.row ??
                        cell.rowNumber ??
                        0
                    ),

                column:
                    Number(
                        cell.column ??
                        cell.col ??
                        cell.columnNumber ??
                        0
                    ),

                left,
                right,
                top,
                bottom,

                width:
                    right - left,

                height:
                    bottom - top

            };

        }
    );


/* ---------------------------------
   STRUCTURAL BOUNDARIES
--------------------------------- */

const step17ATXBoundaries =
    [
        ...new Set(
            step17ATNormalizedCells
                .flatMap(
                    cell => [
                        cell.left,
                        cell.right
                    ]
                )
        )
    ].sort(
        (
            a,
            b
        ) =>
            a - b
    );


const step17ATYBoundaries =
    [
        ...new Set(
            step17ATNormalizedCells
                .flatMap(
                    cell => [
                        cell.top,
                        cell.bottom
                    ]
                )
        )
    ].sort(
        (
            a,
            b
        ) =>
            a - b
    );


/* ---------------------------------
   NEAREST BOUNDARY
--------------------------------- */

function step17ATNearest(
    value,
    boundaries
) {

    let nearest = null;
    let distance = Infinity;

    boundaries.forEach(
        boundary => {

            const currentDistance =
                Math.abs(
                    Number(value) -
                    Number(boundary)
                );

            if (
                currentDistance <
                distance
            ) {

                distance =
                    currentDistance;

                nearest =
                    Number(
                        boundary
                    );

            }

        }
    );

    return {

        value:
            Number(value),

        nearest,

        distance

    };

}


/* ---------------------------------
   CORRECT TEXT POSITION
--------------------------------- */

const step17ATTextDiagnostics =
    step17ATZoneModel.textItems.map(
        item => {

            /*
             * 17AQ already contains
             * TOP-ORIGIN visual coordinates.
             *
             * Do NOT invert Y again.
             */

            const left =
                Number(item.x) *
                step17ATScaleX;

            const right =
                Number(item.right) *
                step17ATScaleX;

            const top =
                Number(item.top) *
                step17ATScaleY;

            const bottom =
                Number(item.bottom) *
                step17ATScaleY;


            const centerX =
                (
                    left +
                    right
                ) / 2;

            const centerY =
                (
                    top +
                    bottom
                ) / 2;


            const nearestX =
                step17ATNearest(
                    centerX,
                    step17ATXBoundaries
                );

            const nearestY =
                step17ATNearest(
                    centerY,
                    step17ATYBoundaries
                );


            const candidateCells =
                step17ATNormalizedCells
                    .filter(
                        cell =>
                            centerX >=
                                cell.left &&
                            centerX <=
                                cell.right &&
                            centerY >=
                                cell.top &&
                            centerY <=
                                cell.bottom
                    )
                    .map(
                        cell => ({

                            index:
                                cell.index,

                            row:
                                cell.row,

                            column:
                                cell.column

                        })
                    );


            const zone =
                step17ATZoneModel.zones.find(
                    currentZone =>
                        currentZone.textItems.some(
                            zoneItem =>
                                Number(
                                    zoneItem.index
                                ) ===
                                Number(
                                    item.index
                                )
                        )
                );


            return {

                textIndex:
                    Number(
                        item.index
                    ),

                text:
                    item.text,

                zone:
                    zone
                        ? zone.index
                        : -1,

                pdfVisual: {

                    x:
                        Number(item.x),

                    right:
                        Number(item.right),

                    top:
                        Number(item.top),

                    bottom:
                        Number(item.bottom)

                },

                docxVisual: {

                    left,
                    right,
                    top,
                    bottom,
                    centerX,
                    centerY

                },

                nearestBoundary: {

                    x:
                        nearestX,

                    y:
                        nearestY

                },

                candidateCells,

                candidateCellCount:
                    candidateCells.length

            };

        }
    );


/* ---------------------------------
   CELL GROUPS
--------------------------------- */

const step17ATCellGroups =
    new Map();


step17ATTextDiagnostics.forEach(
    item => {

        if (
            item.candidateCellCount !== 1
        ) {
            return;
        }

        const cell =
            item.candidateCells[0];

        const key =
            cell.index;


        if (
            !step17ATCellGroups.has(
                key
            )
        ) {

            step17ATCellGroups.set(
                key,
                []
            );

        }


        step17ATCellGroups
            .get(key)
            .push(item);

    }
);


/* ---------------------------------
   CELL CONTENT
--------------------------------- */

const step17ATCellContent =
    [];


step17ATCellGroups.forEach(
    (
        items,
        cellIndex
    ) => {

        items.sort(
            (
                a,
                b
            ) =>
                a.docxVisual.top -
                b.docxVisual.top ||
                a.docxVisual.left -
                b.docxVisual.left
        );


        const first =
            items[0];


        step17ATCellContent.push({

            cellIndex:
                Number(cellIndex),

            row:
                first.candidateCells[0].row,

            column:
                first.candidateCells[0].column,

            textCount:
                items.length,

            text:
                items
                    .map(
                        item =>
                            item.text
                    )
                    .join(" ")

        });

    }
);


step17ATCellContent.sort(
    (
        a,
        b
    ) =>
        a.row -
        b.row ||
        a.column -
        b.column
);


/* ---------------------------------
   ZONE SUMMARY
--------------------------------- */

const step17ATZoneSummary =
    step17ATZoneModel.zones.map(
        zone => {

            const items =
                step17ATTextDiagnostics.filter(
                    item =>
                        item.zone ===
                        zone.index
                );


            const cells =
                [
                    ...new Set(
                        items
                            .flatMap(
                                item =>
                                    item.candidateCells
                                        .map(
                                            cell =>
                                                cell.index
                                        )
                            )
                    )
                ];


            return {

                zone:
                    zone.index,

                top:
                    zone.topY,

                bottom:
                    zone.bottomY,

                textCount:
                    items.length,

                candidateCells:
                    cells,

                candidateCellCount:
                    cells.length,

                preview:
                    items
                        .slice(
                            0,
                            10
                        )
                        .map(
                            item =>
                                item.text
                        )
                        .join(" ")

            };

        }
    );
    /* ---------------------------------
   FINAL MODEL
--------------------------------- */

window.pdfUniversalCorrectedTextStructuralDiagnostic =
{

    version:
        "1.0",

    coordinateSystem:
        "top-origin",

    page: {

        width:
            step17ATPageWidth,

        height:
            step17ATPageHeight

    },

    docx: {

        width:
            step17ATDocxWidth,

        height:
            step17ATDocxHeight

    },

    scale: {

        x:
            step17ATScaleX,

        y:
            step17ATScaleY

    },

    structuralCells:
        step17ATNormalizedCells,

    xBoundaries:
        step17ATXBoundaries,

    yBoundaries:
        step17ATYBoundaries,

    textDiagnostics:
        step17ATTextDiagnostics,

    zoneSummary:
        step17ATZoneSummary,

    cellContent:
        step17ATCellContent,

    totalTextItems:
        step17ATTextDiagnostics.length,

    singleCandidateText:
        step17ATTextDiagnostics.filter(
            item =>
                item.candidateCellCount === 1
        ).length,

    ambiguousText:
        step17ATTextDiagnostics.filter(
            item =>
                item.candidateCellCount !== 1
        ).length,

    populatedCells:
        step17ATCellContent.length,

    status:
        "diagnostic-ready"

};


/* ---------------------------------
   RESULT
--------------------------------- */

