console.log("STEP 17AV — START");
console.log("CELL TEXT → EXACT POSITION MODEL");
console.log("=================================");


/* ---------------------------------
   SOURCE MODEL
--------------------------------- */

const step17AVModel =
    window.pdfUniversalStep17AUModel;


/* ---------------------------------
   VALIDATION
--------------------------------- */

if (!step17AVModel) {

    console.error(
        "STEP 17AV ERROR: Step 17AU model not found."
    );

} else {

    console.log(
        "STEP 17AV SOURCE MODEL FOUND"
    );

    console.log(
        "TOTAL CELLS:",
        step17AVModel.totalCells
    );

    console.log(
        "TOTAL TEXT ITEMS:",
        step17AVModel.totalTextItems
    );

    console.log(
        "POPULATED CELLS:",
        step17AVModel.populatedCells
    );


    /* ---------------------------------
       CREATE POSITION MODEL
    --------------------------------- */

    const step17AVPositionItems = [];


    /* ---------------------------------
       PROCESS CELLS
    --------------------------------- */

    step17AVModel.cells.forEach(
        function(step17AVCell) {

            if (
                !Array.isArray(
                    step17AVCell.textItems
                )
            ) {
                return;
            }


            if (
                step17AVCell.textItems.length === 0
            ) {
                return;
            }


            /* -----------------------------
               CELL TEXT ITEMS
            ----------------------------- */

            step17AVCell.textItems.forEach(
                function(step17AVItem) {

                    const step17AVPdfX =
                        Number(step17AVItem.pdfX) || 0;

                    const step17AVPdfY =
                        Number(step17AVItem.pdfY) || 0;

                    const step17AVDocxX =
                        Number(step17AVItem.docxX) || 0;

                    const step17AVDocxY =
                        Number(step17AVItem.docxY) || 0;


                    /* -------------------------
                       CELL RELATIVE POSITION
                    ------------------------- */

                    const step17AVRelativeX =
                        step17AVDocxX -
                        step17AVCell.x;

                    const step17AVRelativeY =
                        step17AVDocxY -
                        step17AVCell.y;


                    /* -------------------------
                       SAVE POSITION ITEM
                    ------------------------- */

                    step17AVPositionItems.push({

                        cell:
                            step17AVCell.index,

                        row:
                            step17AVCell.row,

                        column:
                            step17AVCell.column,

                        text:
                            step17AVItem.text,

                        textIndex:
                            step17AVItem.textIndex,

                        pdfX:
                            step17AVPdfX,

                        pdfY:
                            step17AVPdfY,

                        docxX:
                            step17AVDocxX,

                        docxY:
                            step17AVDocxY,

                        relativeX:
                            step17AVRelativeX,

                        relativeY:
                            step17AVRelativeY,

                        cellX:
                            step17AVCell.x,

                        cellY:
                            step17AVCell.y,

                        cellWidth:
                            step17AVCell.width,

                        cellHeight:
                            step17AVCell.height

                    });
                }
            );
        }
    );


    /* ---------------------------------
       SORT BY CELL → TEXT INDEX
    --------------------------------- */

    step17AVPositionItems.sort(
        function(a, b) {

            if (a.cell !== b.cell) {
                return a.cell - b.cell;
            }

            return a.textIndex - b.textIndex;
        }
    );


    /* ---------------------------------
       CREATE FINAL MODEL
    --------------------------------- */

    window.pdfUniversalStep17AVModel = {

        version:
            "1.0",

        coordinateUnit:
            "twips",

        totalPositionItems:
            step17AVPositionItems.length,

        sourceCells:
            step17AVModel.totalCells,

        sourceTextItems:
            step17AVModel.totalTextItems,

        items:
            step17AVPositionItems
    };


    /* ---------------------------------
       FINAL SUMMARY
    --------------------------------- */

    console.log("=================================");
    console.log("STEP 17AV — COMPLETE");
    console.log("=================================");

    console.log(
        "POSITION ITEMS:",
        step17AVPositionItems.length
    );

    console.log(
        "SOURCE TEXT ITEMS:",
        step17AVModel.totalTextItems
    );

    console.log(
        "SOURCE POPULATED CELLS:",
        step17AVModel.populatedCells
    );


    /* ---------------------------------
       POSITION TABLE
    --------------------------------- */

    console.table(

        step17AVPositionItems.map(
            function(step17AVItem) {

                return {

                    cell:
                        step17AVItem.cell,

                    row:
                        step17AVItem.row,

                    column:
                        step17AVItem.column,

                    text:
                        step17AVItem.text,

                    pdfX:
                        Number(
                            step17AVItem.pdfX
                        ).toFixed(2),

                    pdfY:
                        Number(
                            step17AVItem.pdfY
                        ).toFixed(2),

                    docxX:
                        Number(
                            step17AVItem.docxX
                        ).toFixed(2),

                    docxY:
                        Number(
                            step17AVItem.docxY
                        ).toFixed(2),

                    relativeX:
                        Number(
                            step17AVItem.relativeX
                        ).toFixed(2),

                    relativeY:
                        Number(
                            step17AVItem.relativeY
                        ).toFixed(2)
                };
            }
        )
    );


    /* ---------------------------------
       FIRST CELL DETAIL
    --------------------------------- */

    const step17AVFirstCell =
        step17AVModel.cells.find(
            function(step17AVCell) {

                return (
                    Array.isArray(
                        step17AVCell.textItems
                    ) &&
                    step17AVCell.textItems.length > 0
                );
            }
        );


    if (step17AVFirstCell) {

        console.log(
            "================================="
        );

        console.log(
            "STEP 17AV FIRST POPULATED CELL"
        );

        console.log(
            "CELL:",
            step17AVFirstCell.index
        );

        console.log(
            "ROW:",
            step17AVFirstCell.row
        );

        console.log(
            "COLUMN:",
            step17AVFirstCell.column
        );

        console.log(
            "CELL X:",
            step17AVFirstCell.x
        );

        console.log(
            "CELL Y:",
            step17AVFirstCell.y
        );

        console.log(
            "CELL WIDTH:",
            step17AVFirstCell.width
        );

        console.log(
            "CELL HEIGHT:",
            step17AVFirstCell.height
        );

        console.table(
            step17AVPositionItems.filter(
                function(step17AVItem) {

                    return (
                        step17AVItem.cell ===
                        step17AVFirstCell.index
                    );
                }
            )
        );
    }


    /* ---------------------------------
       MODEL REFERENCE
    --------------------------------- */

    console.log(
        "FINAL MODEL:",
        window.pdfUniversalStep17AVModel
    );
}




