        if (!source17BI) {

            throw new Error(
                "pdfUniversalFinalTextPlacementModel NOT FOUND"
            );

        }


        /* ---------------------------------
           GET TEXT ITEMS
        --------------------------------- */

        let items17BI = [];

        if (Array.isArray(source17BI.items)) {

            items17BI = source17BI.items;

        } else if (
            source17BI.result &&
            Array.isArray(source17BI.result)
        ) {

            items17BI = source17BI.result;

        } else if (
            source17BI.text &&
            Array.isArray(source17BI.text)
        ) {

            items17BI = source17BI.text;

        } else {

            throw new Error(
                "TEXT ITEMS ARRAY NOT FOUND"
            );

        }


        console.log(
            "TEXT ITEMS FOUND:",
            items17BI.length
        );


        if (items17BI.length !== 82) {

            console.warn(
                "WARNING: Expected 82 text items but found:",
                items17BI.length
            );

        }


        /* ---------------------------------
           NORMALIZE TEXT ITEMS
        --------------------------------- */

        const normalized17BI =
            items17BI.map(function (item, index) {

                const x =
                    Number(item.docxX);

                const y =
                    Number(item.docxY);

                const width =
                    Number(item.docxWidth);

                const height =
                    Number(item.docxHeight);

                const fontSize =
                    Number(item.fontSize);


                if (!Number.isFinite(x)) {

                    throw new Error(
                        "Invalid docxX at item " + index
                    );

                }

                if (!Number.isFinite(y)) {

                    throw new Error(
                        "Invalid docxY at item " + index
                    );

                }

                if (
                    !Number.isFinite(width) ||
                    width <= 0
                ) {

                    throw new Error(
                        "Invalid docxWidth at item " + index
                    );

                }

                if (
                    !Number.isFinite(height) ||
                    height <= 0
                ) {

                    throw new Error(
                        "Invalid docxHeight at item " + index
                    );

                }

                if (
                    !Number.isFinite(fontSize) ||
                    fontSize <= 0
                ) {

                    throw new Error(
                        "Invalid fontSize at item " + index
                    );

                }


                return {

                    index: index,

                    text:
                        String(
                            item.text ?? ""
                        ),

                    x: x,
                    y: y,

                    width: width,
                    height: height,

                    fontSize: fontSize,

                    row:
                        item.row ?? null,

                    column:
                        item.column ?? null,

                    cell:
                        item.cell ?? null,

                    pdfX:
                        Number(item.pdfX),

                    pdfY:
                        Number(item.pdfY),

                    pdfWidth:
                        Number(item.pdfWidth),

                    pdfHeight:
                        Number(item.pdfHeight)

                };

            });


        /* ---------------------------------
           SORT BY PDF VISUAL ORDER
        --------------------------------- */

        normalized17BI.sort(function (a, b) {

            if (
                Number.isFinite(a.pdfY) &&
                Number.isFinite(b.pdfY)
            ) {

                if (a.pdfY !== b.pdfY) {

                    return a.pdfY - b.pdfY;

                }

            }

            return a.x - b.x;

        });


