/* ==========================================
   STEP 25 - UNIVERSAL DOCX RENDERER
   ========================================== */

import {
    Document,
    Packer,
    Paragraph,
    TextRun,
    Table,
    TableRow,
    TableCell,
    WidthType,
    BorderStyle,
    VerticalAlign
} from "https://cdn.jsdelivr.net/npm/docx@9.5.1/+esm";


console.log("");
console.log("=================================");
console.log("STEP 25 - DOCX RENDERER LOADED");
console.log("=================================");


/* ==========================================
   PDF POINTS → TWIPS
   ========================================== */

function pointsToTwips(points) {

    return Math.round(
        points * 20
    );

}


/* ==========================================
   CREATE CELL BORDERS
   ========================================== */

function createCellBorders(
    borderInfo
) {

    const BORDER_SIZE = 6;

    return {

        top: {

            style:
                borderInfo.top
                    ? BorderStyle.SINGLE
                    : BorderStyle.NONE,

            size: BORDER_SIZE,

            color: "000000"

        },

        bottom: {

            style:
                borderInfo.bottom
                    ? BorderStyle.SINGLE
                    : BorderStyle.NONE,

            size: BORDER_SIZE,

            color: "000000"

        },

        left: {

            style:
                borderInfo.left
                    ? BorderStyle.SINGLE
                    : BorderStyle.NONE,

            size: BORDER_SIZE,

            color: "000000"

        },

        right: {

            style:
                borderInfo.right
                    ? BorderStyle.SINGLE
                    : BorderStyle.NONE,

            size: BORDER_SIZE,

            color: "000000"

        }

    };

}


/* ==========================================
   CREATE TEXT PARAGRAPH
   ========================================== */

function createTextParagraph(
    text
) {

    if (!text) {

        return new Paragraph({
            children: []
        });

    }


    return new Paragraph({

        children: [

            new TextRun({

                text: text,

                size: 20

            })

        ],

        spacing: {

            before: 0,

            after: 0,

            line: 240

        }

    });

}


/* ==========================================
   CREATE DOCX CELL
   ========================================== */

function createDocxCell(
    cell
) {

    const cellOptions = {

        children: [

            createTextParagraph(
                cell.text || ""
            )

        ],

        borders:
            createCellBorders(
                cell.borders
            ),

        verticalAlign:
            VerticalAlign.CENTER,

        width: {

            size:
                pointsToTwips(
                    cell.width
                ),

            type:
                WidthType.DXA

        },

        margins: {

            top: 60,

            bottom: 60,

            left: 80,

            right: 80

        }

    };


    /* --------------------------------------
       COLUMN SPAN
       -------------------------------------- */

    if (
        cell.columnSpan &&
        cell.columnSpan > 1
    ) {

        cellOptions.columnSpan =
            cell.columnSpan;

    }


    return new TableCell(
        cellOptions
    );

}


/* ==========================================
   CREATE DOCX ROW
   ========================================== */

function createDocxRow(
    row
) {

    const cells =
        row.cells
            .filter(
                cell =>
                    !cell.isMergedChild
            )
            .map(
                cell =>
                    createDocxCell(
                        cell
                    )
            );


    return new TableRow({

        children: cells,

        height: {

            value:
                pointsToTwips(
                    row.height
                ),

            rule: "atLeast"

        }

    });

}


/* ==========================================
   GENERATE WORD DOCUMENT
   ========================================== */

async function generateUniversalDocx() {

    console.log("");
    console.log(
        "---------------------------------"
    );

    console.log(
        "STEP 25 - GENERATING DOCX"
    );

    console.log(
        "---------------------------------"
    );


    /* --------------------------------------
       GET FINAL LAYOUT MODEL
       -------------------------------------- */

    const layoutModel =
        window.pdfFinalLayoutModel;


    if (!layoutModel) {

        console.error(
            "Final layout model not found."
        );

        throw new Error(
            "PDF layout model is not ready."
        );

    }


    console.log(
        "Layout model loaded."
    );


    console.log(
        "Rows:",
        layoutModel.statistics.rows
    );

    console.log(
        "Columns:",
        layoutModel.statistics.columns
    );

    console.log(
        "Cells:",
        layoutModel.statistics.cells
    );

    console.log(
        "Text Cells:",
        layoutModel.statistics.textCells
    );

    console.log(
        "Merged Cells:",
        layoutModel.statistics.mergedCells
    );


    /* --------------------------------------
       CREATE DOCX ROWS
       -------------------------------------- */

    const docxRows =
        layoutModel.rows.map(
            row =>
                createDocxRow(
                    row
                )
        );


    console.log(
        "DOCX rows created:",
        docxRows.length
    );


    /* --------------------------------------
       CREATE TABLE
       -------------------------------------- */

    const docxTable =
        new Table({

            rows: docxRows,

            width: {

                size: 100,

                type:
                    WidthType.PERCENTAGE

            },

            layout: "fixed"

        });


    console.log(
        "DOCX table created."
    );


    /* --------------------------------------
       CREATE DOCUMENT
       -------------------------------------- */

    const docxDocument =
        new Document({

            sections: [

                {

                    properties: {

                        page: {

                            margin: {

                                top: 0,

                                bottom: 0,

                                left: 0,

                                right: 0

                            }

                        }

                    },

                    children: [

                        docxTable

                    ]

                }

            ]

        });


    console.log(
        "DOCX document created."
    );


    /* --------------------------------------
       GENERATE BLOB
       -------------------------------------- */

    console.log(
        "Generating DOCX file..."
    );


    const blob =
        await Packer.toBlob(
            docxDocument
        );


    console.log(
        "DOCX blob generated."
    );


    /* --------------------------------------
       DOWNLOAD
       -------------------------------------- */

    const downloadUrl =
        URL.createObjectURL(
            blob
        );


    const downloadLink =
        document.createElement(
            "a"
        );


    downloadLink.href =
        downloadUrl;


    downloadLink.download =
        "PDF-to-Word-Test.docx";


    document.body.appendChild(
        downloadLink
    );


    downloadLink.click();


    downloadLink.remove();


    setTimeout(
        () => {

            URL.revokeObjectURL(
                downloadUrl
            );

        },
        5000
    );


    console.log("");
    console.log(
        "================================="
    );

    console.log(
        "STEP 25 COMPLETE"
    );

    console.log(
        "================================="
    );

    console.log(
        "DOCX generated successfully."
    );

}


